    @Override
    protected void onCreate(Bundle savedInstanceState) {
        Checkout.preload(getApplicationContext());
        super.onCreate(savedInstanceState);
        getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);
        polishSystemBars();
        setContentView(splashScreen());
        refreshHandler.postDelayed(this::startAfterSplash, SPLASH_DELAY_MS);
    }

    @Override
    public void setContentView(View view) {
        super.setContentView(view);
        applySafeDrawingInsets(view);
    }

    private void applySafeDrawingInsets(View root) {
        if (root == null) return;
        final int initialLeft = root.getPaddingLeft();
        final int initialTop = root.getPaddingTop();
        final int initialRight = root.getPaddingRight();
        final int initialBottom = root.getPaddingBottom();
        ViewCompat.setOnApplyWindowInsetsListener(root, (view, windowInsets) -> {
            Insets safe = windowInsets.getInsets(
                    WindowInsetsCompat.Type.systemBars() | WindowInsetsCompat.Type.displayCutout()
            );
            view.setPadding(
                    initialLeft + safe.left,
                    initialTop + safe.top,
                    initialRight + safe.right,
                    initialBottom + safe.bottom
            );
            return windowInsets;
        });
        ViewCompat.requestApplyInsets(root);
    }

    private void startAfterSplash() {
        if (isFinishing()) {
            return;
        }
        prefs = securePartnerPrefs();
        capturePartnerPushIntent(getIntent());
        firebaseAuth = FirebaseAuth.getInstance();
        googleSignInClient = buildGoogleSignInClient();
        firestore = FirebaseFirestore.getInstance("default");
        realtimeDatabase = FirebaseDatabase.getInstance("https://apna-servo-default-rtdb.firebaseio.com");
        firebaseStorage = FirebaseStorage.getInstance();
        backendClient = new BackendClient(this);
        appControlRepository = new AppControlRepository(this, backendClient);
        applyPartnerRemoteTheme(appControlRepository.current());
        backendClient.warmUp();
        backendSocketClient = new BackendSocketClient(backendClient);
        locationManager = (LocationManager) getSystemService(LOCATION_SERVICE);
        fusedLocationClient = LocationServices.getFusedLocationProviderClient(this);
        appInForeground = true;
        selectedSkill = normalizeSkill(prefs.getString(KEY_SKILL, ""));
        selectedSkills = skillsFromPrefs();
        selectedSkill = firstPartnerSkill();
        online = prefs.getBoolean("online", true);
        bookings = new ArrayList<>();
        loadState();
        if (applyAppControlBlockingGate()) {
            // Cached control state is authoritative even while the device is offline.
        } else if (!hasActiveInternetTransport()) {
            showNoInternetScreen();
        } else if (prefs.getBoolean(KEY_LOGGED_IN, false)) {
            signInFirebase();
            if (isStaffSession() || isPartnerApproved()) {
                setContentView(appShell());
                restorePersistedNavigation();
                if (!isStaffSession()) showApprovalPopupIfNeeded();
            } else {
                setContentView(verificationStatusScreen());
            }
            refreshHandler.postDelayed(this::startPartnerBackgroundSync, 120);
            refreshHandler.postDelayed(this::applyPendingPartnerDeepLink, 900);
        } else {
            setContentView(loginScreen());
        }
        registerBackHandler();
        registerNetworkSync();
        refreshAppControl();
    }

    private SharedPreferences securePartnerPrefs() {
        try {
            String keyAlias = MasterKeys.getOrCreate(MasterKeys.AES256_GCM_SPEC);
            return EncryptedSharedPreferences.create(
                    PREFS,
                    keyAlias,
                    this,
                    EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
                    EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
            );
        } catch (Exception ignored) {
            return getSharedPreferences(PREFS, MODE_PRIVATE);
        }
    }

    private void startPartnerBackgroundSync() {
        ensureBookingNotificationChannel();
        if (isStaffSession()) {
            requestNotificationPermission();
            refreshFcmToken();
            startStaffBackgroundSync();
            return;
        }
        boolean locationPromptStarted = requestInitialPartnerLocationPermission();
        if (!locationPromptStarted) {
            ensurePartnerLocationReady(false);
            requestNotificationPermission();
            syncCurrentPartnerLocation();
        }
        signInFirebase();
        refreshFcmToken();
        refreshPartnerApprovalStatus();
            syncPartnerAvailabilityFromServerThenStartRealtime();
            flushQueuedPartnerSupportMessages();
            flushQueuedBookingChatMessages();
    }

    @Override
    protected void onDestroy() {
        activityDestroyed = true;
        stopOtpSmsAutoFill();
        clearCurrentResumedActivity();
        dismissActiveWindowDialogs();
        refreshHandler.removeCallbacksAndMessages(null);
        if (refreshRunnable != null) {
            refreshHandler.removeCallbacks(refreshRunnable);
        }
        stopApprovalStatusPolling();
        if (bookingListener != null) {
            bookingListener.remove();
        }
        if (realtimeBookingsRef != null && realtimeBookingListener != null) {
            realtimeBookingsRef.removeEventListener(realtimeBookingListener);
        }
        stopRealtimeRestPolling();
        if (backendSocketClient != null) {
            backendSocketClient.disconnect();
        }
        if (appControlRepository != null) appControlRepository.dispose();
        stopJobLocationTracking();
        stopAvailabilityLocationTracking();
        unregisterNetworkSync();
        stopIncomingRequestAlert();
        releaseStartServiceVoicePlayer();
        removePartnerSupportInputDock();
        supportStatusViews.clear();
        supportChatMessages = null;
        super.onDestroy();
    }

    @Override
    protected void onPause() {
        activityResumed = false;
        appInForeground = false;
        restoreAddStaffDialogOnResume = prefs != null
                && prefs.getBoolean(KEY_ADD_STAFF_DRAFT_ACTIVE, false)
                && ((activeAddLaundryStaffDialog != null && activeAddLaundryStaffDialog.isShowing())
                || (currentNavState != null && "add_laundry_staff".equals(currentNavState.screen)));
        clearCurrentResumedActivity();
        dismissActiveWindowDialogs();
        stopApprovalStatusPolling();
        stopIncomingRequestAlert();
        stopBellAnimation();
        stopAvailabilityLocationTracking();
        super.onPause();
    }

    @Override
    protected void onStop() {
        activityStarted = false;
        appInForeground = false;
        stopIncomingRequestAlert();
        stopBellAnimation();
        // Keep the authenticated booking socket alive while this Activity is only
        // backgrounded. FCM remains the killed/suspended-process fallback, while
        // the socket preserves immediate delivery whenever Android keeps us alive.
        super.onStop();
    }

    @Override
    protected void onResume() {
        super.onResume();
        activityStarted = true;
        activityResumed = true;
        currentResumedActivity = new WeakReference<>(this);
        appInForeground = true;
        if (partnerLocationWaitingForSettings) {
            partnerLocationWaitingForSettings = false;
            refreshHandler.postDelayed(() -> ensurePartnerLocationReady(false), 350);
        }
        // Cached maintenance/mandatory-update state must take effect before any
        // operational UI or socket work resumes.
        if (applyAppControlBlockingGate()) {
            refreshAppControl();
            return;
        }
        if (prefs != null && prefs.getBoolean(KEY_LOGGED_IN, false)) {
            refreshAppControl();
            applyPendingPartnerDeepLink();
            refreshPartnerApprovalStatus();
            if (!isPartnerApproved()) {
                startApprovalStatusPolling();
            }
            refreshHandler.post(this::connectBackendSocketAndFetch);
            if (!isStaffSession() && online) {
                refreshHandler.post(this::startAvailabilityLocationTracking);
            }
            refreshHandler.postDelayed(this::showPendingRequestIfAvailable, 450);
            flushQueuedPartnerSupportMessages();
            flushQueuedBookingChatMessages();
            if (activeJobRequiresGps(activeMapBooking)) {
                startJobLocationTracking(activeMapBooking);
            } else if (activeJobRequiresGps(activeDetailBooking)) {
                startJobLocationTracking(activeDetailBooking);
            }
            if (restoreAddStaffDialogOnResume
                    && prefs.getBoolean(KEY_ADD_STAFF_DRAFT_ACTIVE, false)) {
                restoreAddStaffDialogOnResume = false;
                refreshHandler.postDelayed(() -> {
                    if (activityResumed && !activityDestroyed
                            && (activeAddLaundryStaffDialog == null
                            || !activeAddLaundryStaffDialog.isShowing())) {
                        showAddLaundryStaffDialog();
                    }
                }, 180L);
            }
        }
    }

    @Override
    protected void onStart() {
        super.onStart();
        activityStarted = true;
    }

    private void clearCurrentResumedActivity() {
        MainActivity current = currentResumedActivity.get();
        if (current == this) {
            currentResumedActivity.clear();
        }
    }

    private boolean canPresentWindowUi() {
        if (Looper.myLooper() != Looper.getMainLooper() || activityDestroyed || isFinishing()
                || !activityStarted || !activityResumed || !appInForeground
                || currentResumedActivity.get() != this) {
            return false;
        }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN_MR1 && isDestroyed()) {
            return false;
        }
        Window window = getWindow();
        if (window == null) {
            return false;
        }
        View decor = window.peekDecorView();
        return decor != null && decor.isAttachedToWindow() && decor.getWindowToken() != null;
    }

    private boolean showDialogSafely(Dialog dialog) {
        if (dialog == null) {
            return false;
        }
        if (Looper.myLooper() != Looper.getMainLooper()) {
            refreshHandler.post(() -> showDialogSafely(dialog));
            return false;
        }
        if (!canPresentWindowUi() || dialog.isShowing()) {
            return false;
        }
        // Lifecycle transitions and Dialog.show() both run on the main thread, so
        // the validated window token cannot become stale between this gate and show().
        try {
            dialog.show();
            activeWindowDialogs.add(new WeakReference<>(dialog));
            return true;
        } catch (RuntimeException ignored) {
            return false;
        }
    }

    private void dismissActiveWindowDialogs() {
        for (WeakReference<Dialog> reference : new ArrayList<>(activeWindowDialogs)) {
            Dialog dialog = reference.get();
            if (dialog != null && dialog.isShowing()) {
                try {
                    dialog.dismiss();
                } catch (RuntimeException ignored) {
                }
            }
        }
        activeWindowDialogs.clear();
        if (incomingRequestDialog != null && incomingRequestDialog.isShowing()) {
            dismissIncomingBookingPopup();
        }
    }

    @Override
    public void onTrimMemory(int level) {
        super.onTrimMemory(level);
        if (level >= TRIM_MEMORY_RUNNING_LOW) {
            bookingAlternatePhoneCache.clear();
            bookingLocationChangeStateCache.clear();
            bookingLocationVersionCache.clear();
            bookingChatRendered.clear();
        }
        if (level >= TRIM_MEMORY_UI_HIDDEN) {
            stopIncomingRequestAlert();
            releaseStartServiceVoicePlayer();
        }
    }

    @Override
    public void onLowMemory() {
        super.onLowMemory();
        bookingAlternatePhoneCache.clear();
        bookingLocationChangeStateCache.clear();
        bookingLocationVersionCache.clear();
        bookingChatRendered.clear();
        stopIncomingRequestAlert();
        releaseStartServiceVoicePlayer();
    }

    @Override
    protected void onNewIntent(Intent intent) {
        super.onNewIntent(intent);
        setIntent(intent);
        capturePartnerPushIntent(intent);
        applyPendingPartnerDeepLink();
    }

    private void registerNetworkSync() {
        connectivityManager = (ConnectivityManager) getSystemService(CONNECTIVITY_SERVICE);
        if (connectivityManager == null || networkCallback != null) {
            return;
        }
        networkCallback = new ConnectivityManager.NetworkCallback() {
            @Override
            public void onAvailable(Network network) {
                refreshHandler.post(MainActivity.this::restoreAfterInternetReturns);
                refreshHandler.post(MainActivity.this::flushQueuedPartnerSupportMessages);
                refreshHandler.post(MainActivity.this::flushQueuedBookingChatMessages);
                refreshHandler.postDelayed(MainActivity.this::connectBackendSocketAndFetch, 250);
            }

            @Override
            public void onCapabilitiesChanged(Network network, NetworkCapabilities capabilities) {
                if (capabilities != null
                        && capabilities.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)) {
                    refreshHandler.post(MainActivity.this::restoreAfterInternetReturns);
                    refreshHandler.post(MainActivity.this::flushQueuedPartnerSupportMessages);
                    refreshHandler.post(MainActivity.this::flushQueuedBookingChatMessages);
                    refreshHandler.postDelayed(MainActivity.this::connectBackendSocketAndFetch, 250);
                }
            }

            @Override
            public void onLost(Network network) {
                // Debounce handovers between Wi-Fi and mobile data. A slow/temporarily
                // unvalidated connection must never replace the partner's current page.
                refreshHandler.postDelayed(() -> {
                    if (!hasActiveInternetTransport()) showNoInternetScreen();
                }, 900);
            }
        };
        try {
            NetworkRequest request = new NetworkRequest.Builder()
                    .addCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)
                    .build();
            connectivityManager.registerNetworkCallback(request, networkCallback);
        } catch (Exception ignored) {
        }
    }

    private void unregisterNetworkSync() {
        if (connectivityManager == null || networkCallback == null) {
            return;
        }
        try {
            connectivityManager.unregisterNetworkCallback(networkCallback);
        } catch (Exception ignored) {
        }
        networkCallback = null;
    }

    private boolean isNetworkOnline() {
        return hasActiveInternetTransport();
    }

    private boolean hasActiveInternetTransport() {
        if (connectivityManager == null) {
            connectivityManager = (ConnectivityManager) getSystemService(CONNECTIVITY_SERVICE);
        }
        if (connectivityManager == null) {
            return true;
        }
        try {
            Network network = connectivityManager.getActiveNetwork();
            if (network == null) {
                return false;
            }
            NetworkCapabilities caps = connectivityManager.getNetworkCapabilities(network);
            return caps != null
                    && caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)
                    && (caps.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)
                    || caps.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR)
                    || caps.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET)
                    || caps.hasTransport(NetworkCapabilities.TRANSPORT_VPN));
        } catch (Exception ignored) {
            return true;
        }
    }

    private void refreshAppControl() {
        if (appControlRepository == null) return;
        appControlRepository.refresh((config, fromNetwork) -> {
            if (activityDestroyed || isFinishing()) return;
            applyPartnerRemoteTheme(config);
            if (applyAppControlBlockingGate()) return;
            appControlBlockingScreen = false;
            lastAppControlGate = "";
            if (fromNetwork) {
                maybeShowSoftUpdate(config);
            }
            if (fromNetwork && prefs != null && prefs.getBoolean(KEY_LOGGED_IN, false)) {
                maybeShowActiveAnnouncement(config);
                rebuildShellForAppControl();
            }
        });
    }

    private void applyPartnerRemoteTheme(AppControlRepository.AppConfig config) {
        try {
            int primary = Color.parseColor(config == null ? "#ef4d70" : config.primaryColor);
            ROSE = primary;
            ROSE_DARK = Color.rgb(Math.round(Color.red(primary) * 0.61f), Math.round(Color.green(primary) * 0.61f), Math.round(Color.blue(primary) * 0.61f));
            ROSE_SOFT = Color.rgb(255 - Math.round((255 - Color.red(primary)) * 0.14f), 255 - Math.round((255 - Color.green(primary)) * 0.14f), 255 - Math.round((255 - Color.blue(primary)) * 0.14f));
        } catch (Exception ignored) {
            ROSE = Color.rgb(239, 77, 112); ROSE_DARK = Color.rgb(145, 18, 67); ROSE_SOFT = Color.rgb(255, 233, 237);
        }
    }

    private boolean applyAppControlBlockingGate() {
        if (appControlRepository == null) return false;
        AppControlRepository.AppConfig config = appControlRepository.current();
        boolean force = config.forceUpdate(BuildConfig.VERSION_NAME, BuildConfig.VERSION_CODE);
        if (!force && !config.maintenance()) return false;
        String gate = force ? "update:" + config.configVersion : "status:" + config.configVersion + ":" + config.status;
        if (!gate.equals(lastAppControlGate) || !appControlBlockingScreen) {
            lastAppControlGate = gate;
            appControlBlockingScreen = true;
            setContentView(appControlBlockingView(config, force));
        }
        return true;
    }

    private View appControlBlockingView(AppControlRepository.AppConfig config, boolean forceUpdate) {
        FrameLayout overlay = new FrameLayout(this);
        overlay.setBackgroundColor(Color.argb(188, 18, 18, 22));
        LinearLayout card = vertical();
        card.setGravity(Gravity.CENTER_HORIZONTAL);
        card.setPadding(dp(24), dp(28), dp(24), dp(24));
        card.setBackground(round(Color.WHITE, dp(28)));
        card.setElevation(dp(22));

        if (!forceUpdate) {
            ImageView illustration = new ImageView(this);
            illustration.setImageResource(R.drawable.app_status_maintenance);
            illustration.setScaleType(ImageView.ScaleType.CENTER_INSIDE);
            illustration.setContentDescription("Maintenance in progress");
            card.addView(illustration, new LinearLayout.LayoutParams(dp(220), dp(176)));
        } else {
            TextView updateIcon = text("↑", 34, Color.WHITE, true);
            updateIcon.setGravity(Gravity.CENTER);
            updateIcon.setContentDescription("Update required");
            updateIcon.setBackground(round(ROSE, dp(22)));
            card.addView(updateIcon, centered(dp(58), dp(58), 0, 0, 0, 18));
        }
        TextView title = text(forceUpdate ? "Update Required" : "ApnaServo is\nUnder Maintenance",
                forceUpdate ? 22 : 27, BLACK, true);
        title.setGravity(Gravity.CENTER);
        title.setLineSpacing(dp(2), 0.95f);
        card.addView(title, margin(-1, -2, 0, 0, 0, 14));

        View divider = new View(this);
        divider.setBackgroundColor(Color.rgb(250, 183, 196));
        card.addView(divider, centered(dp(150), dp(2), 0, 0, 0, 16));

        String primary = forceUpdate
                ? "You must update to continue using the ApnaServo Partner app."
                : "We are currently performing some maintenance to improve your experience.";
        TextView message = text(primary, 15, Color.rgb(77, 76, 84), false);
        message.setGravity(Gravity.CENTER);
        message.setLineSpacing(dp(4), 1f);
        card.addView(message, margin(-1, -2, 2, 0, 2, forceUpdate ? 22 : 10));
        if (!forceUpdate) {
            TextView secondary = text("Please try again after some time.", 15, Color.rgb(77, 76, 84), false);
            secondary.setGravity(Gravity.CENTER);
            card.addView(secondary, margin(-1, -2, 0, 0, 0, 24));
        }
        TextView action = roseButton(forceUpdate ? "Update Now" : "Okay, Got It");
        action.setTextSize(17);
        action.setOnClickListener(view -> {
            if (forceUpdate) {
                openAppControlStore(config.storeUrl);
            } else {
                // Dismissing acknowledgement never changes or bypasses published maintenance.
                appControlRepository.refresh((latest, network) -> applyAppControlBlockingGate());
            }
        });
        card.addView(action, new LinearLayout.LayoutParams(-1, dp(54)));
        FrameLayout.LayoutParams cardParams = new FrameLayout.LayoutParams(-1, -2, Gravity.CENTER);
        cardParams.setMargins(dp(24), dp(20), dp(24), dp(20));
        overlay.addView(card, cardParams);
        return overlay;
    }

    private void restoreAfterAppControlGate() {
        appControlBlockingScreen = false;
        lastAppControlGate = "";
        if (prefs != null && prefs.getBoolean(KEY_LOGGED_IN, false)) {
            if (isStaffSession() || isPartnerApproved()) {
                setContentView(appShell());
                restorePersistedNavigation();
            } else setContentView(verificationStatusScreen());
        } else setContentView(loginScreen());
    }

    private void openAppControlStore(String url) {
        // Never trust a shared/admin store URL here: it can point at the customer app.
        // The package-scoped market URI also opens the correct Play Store listing directly.
        String packageId = getPackageName();
        Intent market = new Intent(Intent.ACTION_VIEW, Uri.parse("market://details?id=" + packageId));
        market.setPackage("com.android.vending");
        try {
            startActivity(market);
        } catch (Exception noPlayStore) {
            try {
                startActivity(new Intent(Intent.ACTION_VIEW,
                        Uri.parse("https://play.google.com/store/apps/details?id=" + packageId)));
            } catch (Exception ignored) {
                Toast.makeText(this, "Store is currently unavailable", Toast.LENGTH_LONG).show();
            }
        }
    }

    private boolean featureEnabled(String featureId) {
        return appControlRepository == null || appControlRepository.current().featureEnabled(featureId);
    }

    private boolean allowOperationalAction() {
        if (appControlRepository == null) return true;
        AppControlRepository.AppConfig config = appControlRepository.current();
        if (!config.maintenance() && !config.forceUpdate(BuildConfig.VERSION_NAME, BuildConfig.VERSION_CODE)) return true;
        applyAppControlBlockingGate();
        Toast.makeText(this, "Operations are temporarily unavailable.", Toast.LENGTH_SHORT).show();
        return false;
    }

    private boolean requireFeature(String featureId, String title) {
        if (featureEnabled(featureId)) return true;
        if (appRoot != null && content != null) {
            enterScreen("feature_unavailable", featureId);
            activeTab = "feature_unavailable";
            clearContentForScreen("feature_unavailable");
            content.addView(partnerPageHeader(title, "Temporarily unavailable", false, false));
            LinearLayout unavailable = card(20);
            TextView body = text("This feature is temporarily unavailable. Your account and active booking data remain safe. Please try again later.", 14, MUTED, false);
            body.setGravity(Gravity.CENTER);
            unavailable.addView(body);
            TextView home = roseButton("partner_dashboard".equals(featureId) ? "Check Again" : "Back to Home");
            home.setOnClickListener(v -> {
                if ("partner_dashboard".equals(featureId)) refreshAppControl(); else showDashboard();
            });
            unavailable.addView(home, margin(-1, 50, 0, 18, 0, 0));
            content.addView(unavailable, margin(-1, -2, 0, 20, 0, 0));
        } else Toast.makeText(this, title + " is temporarily unavailable", Toast.LENGTH_LONG).show();
        return false;
    }

    private void rebuildShellForAppControl() {
        if (appControlBlockingScreen || appRoot == null || prefs == null || !prefs.getBoolean(KEY_LOGGED_IN, false)) return;
        if ("booking_chat".equals(activeTab) || "map".equals(activeTab) || "detail".equals(activeTab)) return;
        NavState state = currentNavState == null ? persistedNavigation() : currentNavState;
        setContentView(appShell());
        renderNavigationWithoutHistory(state);
    }

    private void maybeShowSoftUpdate(AppControlRepository.AppConfig config) {
        if (config == null || !config.softUpdate(BuildConfig.VERSION_NAME, BuildConfig.VERSION_CODE) || !canPresentWindowUi()
                || (appControlUpdateDialog != null && appControlUpdateDialog.isShowing())) return;
        String promptKey = "partner_soft_update_dismissed_" + config.latestVersion;
        if (prefs != null && prefs.getBoolean(promptKey, false)) return;
        Dialog dialog = new Dialog(this);
        dialog.setCancelable(true);
        dialog.setCanceledOnTouchOutside(true);
        LinearLayout card = vertical();
        card.setGravity(Gravity.CENTER_HORIZONTAL);
        card.setPadding(dp(22), dp(22), dp(22), dp(18));
        card.setBackground(round(Color.WHITE, dp(20)));
        TextView icon = text("↑", 28, Color.WHITE, true);
        icon.setGravity(Gravity.CENTER);
        icon.setContentDescription("New version available");
        icon.setBackground(round(ROSE, dp(16)));
        card.addView(icon, centered(dp(48), dp(48), 0, 0, 0, 14));
        TextView title = text("A new version is available!", 18, BLACK, true);
        title.setGravity(Gravity.CENTER);
        card.addView(title, margin(-1, -2, 0, 0, 0, 10));
        TextView body = text("We've improved performance, fixed bugs, and added exciting new features. Please update now to get the best experience.", 12, MUTED, false);
        body.setGravity(Gravity.CENTER);
        body.setLineSpacing(dp(3), 1f);
        card.addView(body, margin(-1, -2, 0, 0, 0, 16));
        TextView update = roseButton("Update Now");
        update.setOnClickListener(view -> {
            if (prefs != null) prefs.edit().putBoolean(promptKey, true).apply();
            dialog.dismiss();
            openAppControlStore(config.storeUrl);
        });
        card.addView(update, new LinearLayout.LayoutParams(-1, dp(48)));
        TextView later = text("Not Now", 12, ROSE, true);
        later.setGravity(Gravity.CENTER);
        later.setContentDescription("Not now");
        later.setOnClickListener(view -> {
            if (prefs != null) prefs.edit().putBoolean(promptKey, true).apply();
            dialog.dismiss();
        });
        card.addView(later, margin(-1, 38, 0, 8, 0, 0));
        dialog.setContentView(card);
        dialog.setOnCancelListener(ignored -> {
            if (prefs != null) prefs.edit().putBoolean(promptKey, true).apply();
        });
        dialog.setOnDismissListener(ignored -> {
            if (appControlUpdateDialog == dialog) appControlUpdateDialog = null;
        });
        appControlUpdateDialog = dialog;
        if (showDialogSafely(dialog) && dialog.getWindow() != null) {
            dialog.getWindow().setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));
            dialog.getWindow().setLayout((int) (getResources().getDisplayMetrics().widthPixels * 0.84f), WindowManager.LayoutParams.WRAP_CONTENT);
        }
    }

    private void maybeShowActiveAnnouncement(AppControlRepository.AppConfig config) {
        if (config == null || !canPresentWindowUi() || config.announcements.isEmpty()) return;
        long now = System.currentTimeMillis();
        for (JSONObject item : config.announcements) {
            if (!item.optBoolean("enabled", item.optBoolean("active", true))) continue;
            long start = appControlTime(item, "startAt", "startsAt", "startDate", "scheduledAt");
            long end = appControlTime(item, "endAt", "endsAt", "endDate", "expiresAt");
            if ((start > 0 && now < start) || (end > 0 && now > end)) continue;
            String id = item.optString("id", item.optString("announcementId", String.valueOf(item.toString().hashCode())));
            String seenKey = "app_control_announcement_" + config.configVersion + "_" + id;
            if (prefs.getBoolean(seenKey, false)) continue;
            String title = item.optString("title", "ApnaServo Update");
            String message = item.optString("message", item.optString("body", ""));
            if (TextUtils.isEmpty(message)) continue;
            AlertDialog dialog = new AlertDialog.Builder(this)
                    .setTitle(title)
                    .setMessage(message)
                    .setPositiveButton(item.optString("buttonText", "Got it"),
                            (d, which) -> prefs.edit().putBoolean(seenKey, true).apply())
                    .create();
            showDialogSafely(dialog);
            return;
        }
    }

    private long appControlTime(JSONObject item, String... keys) {
        for (String key : keys) {
            Object raw = item.opt(key);
            if (raw instanceof Number) {
                long value = ((Number) raw).longValue();
                return value > 0 && value < 100000000000L ? value * 1000L : value;
            }
            if (raw instanceof String && !TextUtils.isEmpty((String) raw)) {
                String value = (String) raw;
                try {
                    long numeric = Long.parseLong(value);
                    return numeric < 100000000000L ? numeric * 1000L : numeric;
                } catch (Exception ignored) {}
                String[] patterns = {"yyyy-MM-dd'T'HH:mm:ss.SSSX", "yyyy-MM-dd'T'HH:mm:ssX", "yyyy-MM-dd HH:mm:ss", "yyyy-MM-dd"};
                for (String pattern : patterns) try {
                    SimpleDateFormat format = new SimpleDateFormat(pattern, Locale.US);
                    Date parsed = format.parse(value);
                    if (parsed != null) return parsed.getTime();
                } catch (Exception ignored) {}
            }
        }
        return 0L;
    }

    private void showNoInternetScreen() {
        if (isFinishing() || activityDestroyed || offlineScreenVisible) return;
        offlineScreenVisible = true;
        offlineRetryInProgress = false;
        dismissActiveWindowDialogs();
        LinearLayout root = vertical();
        root.setGravity(Gravity.CENTER_HORIZONTAL);
        root.setPadding(dp(28), dp(28), dp(28), dp(28));
        root.setBackgroundColor(Color.WHITE);

        View top = new View(this);
        root.addView(top, new LinearLayout.LayoutParams(1, 0, 1));
        ImageView illustration = new ImageView(this);
        illustration.setImageResource(R.drawable.ic_partner_no_internet);
        illustration.setScaleType(ImageView.ScaleType.FIT_CENTER);
        root.addView(illustration, new LinearLayout.LayoutParams(dp(270), dp(270)));
        TextView title = text("No Internet Connection", 28, Color.BLACK, true);
        title.setGravity(Gravity.CENTER);
        root.addView(title, margin(-1, -2, 0, 18, 0, 12));
        TextView message = text("Could not connect to the internet.\nPlease check Wi-Fi or mobile data.", 16, Color.rgb(74, 74, 74), false);
        message.setGravity(Gravity.CENTER);
        message.setLineSpacing(dp(5), 1f);
        root.addView(message, margin(-1, -2, 0, 8, 0, 22));

        TextView retry = text("↻  Try Again", 17, Color.WHITE, true);
        retry.setGravity(Gravity.CENTER);
        retry.setContentDescription("Try internet connection again");
        retry.setBackground(gradient(Color.rgb(22, 178, 71), Color.rgb(0, 142, 54), dp(17)));
        retry.setElevation(dp(7));
        retry.setOnClickListener(view -> retryInternetConnection(retry));
        addPressAnimation(retry);
        root.addView(retry, new LinearLayout.LayoutParams(dp(230), dp(58)));
        TextView hint = text("This page appears only when Wi-Fi and mobile data are unavailable.", 11, Color.rgb(125, 125, 125), false);
        hint.setGravity(Gravity.CENTER);
        root.addView(hint, margin(-1, -2, 0, 18, 0, 0));
        View bottom = new View(this);
        root.addView(bottom, new LinearLayout.LayoutParams(1, 0, 1));
        setContentView(root);
    }

    private void retryInternetConnection(TextView retry) {
        if (offlineRetryInProgress) return;
        offlineRetryInProgress = true;
        retry.setEnabled(false);
        retry.setAlpha(0.78f);
        retry.setText("Checking connection…");
        refreshHandler.postDelayed(() -> {
            offlineRetryInProgress = false;
            if (hasActiveInternetTransport()) {
                retry.setText("✓  Connected");
                retry.setAlpha(1f);
                refreshHandler.postDelayed(this::restoreAfterInternetReturns, 350);
            } else {
                retry.setEnabled(true);
                retry.setAlpha(1f);
                retry.setText("↻  Try Again");
                retry.animate().translationX(dp(7)).setDuration(70).withEndAction(() ->
                        retry.animate().translationX(0).setDuration(90).start()).start();
                Toast.makeText(this, "Still offline. Turn on Wi-Fi or mobile data and try again.", Toast.LENGTH_SHORT).show();
            }
        }, 700);
    }

    private void restoreAfterInternetReturns() {
        if (!offlineScreenVisible || !hasActiveInternetTransport() || prefs == null) return;
        offlineScreenVisible = false;
        offlineRetryInProgress = false;
        if (prefs.getBoolean(KEY_LOGGED_IN, false)) {
            if (isStaffSession() || isPartnerApproved()) {
                setContentView(appShell());
                restorePersistedNavigation();
            } else {
                setContentView(verificationStatusScreen());
            }
            refreshHandler.postDelayed(this::startPartnerBackgroundSync, 120);
        } else {
            setContentView(loginScreen());
        }
    }

    @Override
    protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        super.onActivityResult(requestCode, resultCode, data);
        if (requestCode == GOOGLE_SIGN_IN_REQUEST) {
            Task<GoogleSignInAccount> task = GoogleSignIn.getSignedInAccountFromIntent(data);
            try {
                firebaseAuthWithGoogle(task.getResult(ApiException.class));
            } catch (ApiException error) {
                showGoogleSignInError(error);
            }
            return;
        }
        if (requestCode == REQ_CASHFREE_CHECKOUT) {
            String orderId = data == null ? pendingCashfreeOrderId
                    : data.getStringExtra(CashfreeCheckoutActivity.RESULT_ORDER_ID);
            if (TextUtils.isEmpty(orderId)) orderId = pendingCashfreeOrderId;
            if (resultCode == RESULT_OK && !TextUtils.isEmpty(orderId)) {
                verifyCashfreeSubscription(orderId);
            } else {
                // Even on a cancelled/unknown result the payment may have gone
                // through; a silent re-verify confirms the backend truth.
                if (!TextUtils.isEmpty(orderId)) verifyCashfreeSubscription(orderId);
                else Toast.makeText(this, "Payment was not completed. You can try again.", Toast.LENGTH_LONG).show();
            }
            pendingCashfreeOrderId = "";
            return;
        }
        if (resultCode != RESULT_OK) {
            return;
        }
        if (requestCode == REQ_DOC_FILE) {
            if (data != null && data.getData() != null) {
                Uri saved = copyDocumentFileToInternalStorage(pendingDocumentUploadTitle, data.getData());
                if (saved != null && isRegistrationDocumentSelectionMode()) {
                    submitDocumentVerification(pendingDocumentUploadTitle, saved);
                    pendingDocumentUploadTitle = "";
                } else {
                    persistDocumentUpload(pendingDocumentUploadTitle, saved);
                }
            }
            return;
        }
        if (requestCode == REQ_LAUNDRY_STAFF_PHOTO) {
            if (data != null && data.getData() != null) {
                String displayName = documentSourceDisplayName(data.getData());
                if (TextUtils.isEmpty(displayName)) displayName = "Staff_Photo.jpg";
                pendingLaundryStaffPhotoUri = copyLaundryStaffPhotoToInternalStorage(data.getData());
                if (pendingLaundryStaffPhotoUri != null) {
                    prefs.edit().putBoolean(KEY_ADD_STAFF_DRAFT_ACTIVE, true)
                            .putString(KEY_ADD_STAFF_DRAFT_PHOTO_PATH, pendingLaundryStaffPhotoUri.getPath())
                            .putString(KEY_ADD_STAFF_DRAFT_PHOTO_NAME, displayName).apply();
                    updateLaundryStaffPhotoSelection(displayName);
                }
            }
            return;
        }
        if (requestCode == REQ_LAUNDRY_STAFF_ID) {
            if (data != null && data.getData() != null) {
                String displayName = documentSourceDisplayName(data.getData());
                if (TextUtils.isEmpty(displayName)) displayName = "Government_ID";
                pendingLaundryStaffIdUri = copyDocumentFileToInternalStorage("Laundry Staff Government ID", data.getData());
                if (pendingLaundryStaffIdUri != null) {
                    prefs.edit().putBoolean(KEY_ADD_STAFF_DRAFT_ACTIVE, true)
                            .putString(KEY_ADD_STAFF_DRAFT_ID_PATH, pendingLaundryStaffIdUri.getPath())
                            .putString(KEY_ADD_STAFF_DRAFT_ID_NAME, displayName).apply();
                    updateLaundryStaffIdSelection(displayName);
                }
            }
            return;
        }
        if (requestCode == SUPPORT_CAMERA_REQUEST) {
            handlePartnerSupportCameraResult(data);
            return;
        }
        if (requestCode == REQ_DOC_CAMERA) {
            if (data != null && data.getExtras() != null) {
                Object bitmap = data.getExtras().get("data");
                if (bitmap instanceof Bitmap) {
                    Uri saved = saveDocumentCameraBitmap(pendingDocumentUploadTitle, (Bitmap) bitmap);
                    String capturedTitle = pendingDocumentUploadTitle;
                    if (saved != null && isRegistrationDocumentSelectionMode()) {
                        submitDocumentVerification(capturedTitle, saved);
                        pendingDocumentUploadTitle = "";
                    } else {
                        persistDocumentUpload(capturedTitle, saved);
                    }
                }
            }
            return;
        }
        if (requestCode == REQ_CAMERA) {
            handleProfilePhotoCameraResult(data);
            return;
        }
        if (data == null) {
            return;
        }
    }

    private void registerBackHandler() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            getOnBackInvokedDispatcher().registerOnBackInvokedCallback(
                    OnBackInvokedDispatcher.PRIORITY_DEFAULT,
                    this::handleBackNavigation
            );
        }
    }

    private void handleBackNavigation() {
        if (appControlBlockingScreen) return;
        if (!prefs.getBoolean(KEY_LOGGED_IN, false)) {
            finish();
            return;
        }
        if ("arrival_estimate".equals(activeTab) && currentNavState != null) {
            arrivalDialogBookingIds.remove(currentNavState.primary);
        }
        navigateBack();
    }

    private void navigateBack() {
        if (sideDrawerOverlay != null) {
            closeSideDrawer(true);
            return;
        }
        if (!navHistory.isEmpty()) {
            NavState previous = navHistory.remove(navHistory.size() - 1);
            restoringNavigation = true;
            renderNavState(previous);
            restoringNavigation = false;
            return;
        }
        if ("home".equals(activeTab) || currentNavState == null || "home".equals(currentNavState.screen)) {
            finish();
            return;
        }
        showDashboard();
    }

    private void enterScreen(String screen) {
        enterScreen(screen, "", "");
    }

    private void enterScreen(String screen, String primary) {
        enterScreen(screen, primary, "");
    }

    private void enterScreen(String screen, String primary, String secondary) {
        if (!"support_chat".equals(screen) && !"booking_chat".equals(screen)) {
            removePartnerSupportInputDock();
        }
        NavState next = new NavState(screen, primary, secondary);
        if (!restoringNavigation && currentNavState != null && !currentNavState.sameAs(next)) {
            navHistory.add(currentNavState);
            if (navHistory.size() > 30) {
                navHistory.remove(0);
            }
        }
        currentNavState = next;
        if (prefs != null && prefs.getBoolean(KEY_LOGGED_IN, false)) {
            prefs.edit()
                    .putString(KEY_NAV_SCREEN, next.screen)
                    .putString(KEY_NAV_PRIMARY, next.primary)
                    .putString(KEY_NAV_SECONDARY, next.secondary)
                    .apply();
        }
    }

    private NavState persistedNavigation() {
        if (prefs == null) return new NavState("home", "", "");
        return new NavState(
                prefs.getString(KEY_NAV_SCREEN, "home"),
                prefs.getString(KEY_NAV_PRIMARY, ""),
                prefs.getString(KEY_NAV_SECONDARY, "")
        );
    }

    private void restorePersistedNavigation() {
        renderNavigationWithoutHistory(persistedNavigation());
    }

    private void renderNavigationWithoutHistory(NavState state) {
        restoringNavigation = true;
        try {
            renderNavState(state);
        } finally {
            restoringNavigation = false;
        }
    }

    private void renderNavState(NavState state) {
        if (state == null) {
            showDashboard();
            return;
        }
        switch (state.screen) {
            case "bookings":
                showBookings();
                return;
            case "earnings":
                showEarnings();
                return;
            case "profile":
                showProfile();
                return;
            case "menu":
                showSideMenu();
                return;
            case "request": {
                PartnerBooking booking = findBookingById(state.primary);
                if (booking != null) {
                    showNewRequest(booking);
                } else {
                    showBookings();
                }
                return;
            }
            case "arrival_estimate": {
                PartnerBooking booking = findBookingById(state.primary);
                if (booking != null) {
                    showArrivalEstimateDialog(booking);
                } else {
                    showBookings();
                }
                return;
            }
            case "detail": {
                PartnerBooking booking = findBookingById(state.primary);
                if (booking != null) {
                    showOrderDetail(booking);
                } else {
                    showBookings();
                }
                return;
            }
            case "map": {
                PartnerBooking booking = findBookingById(state.primary);
                if (booking != null) {
                    showInAppMap(booking);
                } else {
                    showBookings();
                }
                return;
            }
            case "personal":
                showPersonalInformationTool();
                return;
            case "documents":
                showDocumentsTool();
                return;
            case "services":
                showMyServicesTool();
                return;
            case "support":
                showSupportTool();
                return;
            case "legal_info":
                showPartnerLegalInformationTool();
                return;
            case "support_chat":
                showPartnerSupportChat(state.primary, state.secondary);
                return;
            case "booking_chat": {
                PartnerBooking booking = findBookingById(state.primary);
                if (booking != null) {
                    showCustomerBookingChat(booking);
                } else {
                    showBookings();
                }
                return;
            }
            case "settings":
                showSettingsTool();
                return;
            case "referral":
                showReferralTool();
                return;
            case "notifications":
                showNotifications();
                return;
            case "add_laundry_staff":
                showDashboard();
                refreshHandler.postDelayed(this::showAddLaundryStaffDialog, 120);
                return;
            case "laundry_partners":
                showLaundryPartnersDirectory();
                return;
            case "profile_tool":
                showProfileTool(state.primary, state.secondary);
                return;
            default:
                showDashboard();
        }
    }

    @SuppressLint("GestureBackNavigation")
    @Override
    public void onBackPressed() {
        handleBackNavigation();
    }

    private void loadState() {
        clearLegacyBookingStateOnce();
        acceptedIds = new HashSet<>(prefs.getStringSet(KEY_ACCEPTED, new HashSet<>()));
        completedIds = new HashSet<>(prefs.getStringSet(KEY_COMPLETED, new HashSet<>()));
        cancelledIds = new HashSet<>(prefs.getStringSet(KEY_CANCELLED, new HashSet<>()));
        paidIds = new HashSet<>(prefs.getStringSet(KEY_PAID, new HashSet<>()));
        alertedPendingIds = new HashSet<>(prefs.getStringSet(KEY_ALERTED_PENDING, new HashSet<>()));
        if (isPartnerApproved()) {
            ensureApprovalBookingBaseline();
            bookings = loadCachedPartnerBookings();
        } else {
            bookings = new ArrayList<>();
            prefs.edit().remove(KEY_BOOKING_CACHE).apply();
        }
        hydrateLocalStateFromCachedBookings(bookings);
    }

    private void clearLegacyBookingStateOnce() {
        if (prefs.getBoolean(KEY_BOOKING_STATE_RESET, false)) {
            return;
        }
        SharedPreferences.Editor editor = prefs.edit()
                .remove(KEY_ACCEPTED)
                .remove(KEY_COMPLETED)
                .remove(KEY_CANCELLED)
                .remove(KEY_PAID)
                .putBoolean(KEY_BOOKING_STATE_RESET, true);
        for (String key : prefs.getAll().keySet()) {
            if (key != null && key.startsWith("amount_")) {
                editor.remove(key);
            }
        }
        editor.apply();
    }

