    private void installFixedAuthCardKeyboardLift(View root, View card) {
        root.getViewTreeObserver().addOnGlobalLayoutListener(() -> {
            if (!root.isAttachedToWindow() || activityDestroyed) return;
            Rect frame = new Rect();
            root.getWindowVisibleDisplayFrame(frame);
            int keyboardHeight = root.getRootView().getHeight() - frame.bottom;
            boolean open = keyboardHeight > dp(140);
            float target = open ? -Math.max(dp(72), Math.min(dp(210), keyboardHeight * 0.58f)) : 0f;
            if (Math.abs(card.getTranslationY() - target) > 1f) {
                card.animate().translationY(target).setDuration(180).setInterpolator(new DecelerateInterpolator()).start();
            }
        });
    }

    private void authenticatePartnerWithEmail(EditText emailInput, EditText passwordInput, View submitButton) {
        String email = emailInput.getText().toString().trim().toLowerCase(Locale.US);
        String password = passwordInput.getText().toString();
        if (!email.contains("@") || !email.contains(".")) {
            showSupportInfoDialog("Email Required", "Enter a valid registered email address.");
            return;
        }
        if (password.length() < 6) {
            showSupportInfoDialog("Password Required", "Enter your password. It must contain at least 6 characters.");
            return;
        }
        if (firebaseAuth == null) firebaseAuth = FirebaseAuth.getInstance();
        submitButton.setEnabled(false);
        firebaseAuth.signInWithEmailAndPassword(email, password)
                .addOnSuccessListener(result -> {
                    prefs.edit().putString(KEY_EMAIL, email).apply();
                    submitButton.setEnabled(true);
                    startAuthenticatedStaffLookup();
                })
                .addOnFailureListener(error -> {
                    submitButton.setEnabled(true);
                    showSupportInfoDialog("Login Failed", partnerEmailAuthError(error));
                });
    }

    private void showStaffPhoneLoginDialog() {
        EditText phone = registrationInput("Registered staff mobile number", InputType.TYPE_CLASS_PHONE);
        phone.setFilters(new InputFilter[]{new InputFilter.LengthFilter(10)});
        AlertDialog dialog = new AlertDialog.Builder(this)
                .setTitle("Company Staff Login")
                .setMessage("Enter the same mobile number that your company owner added for you.")
                .setView(phone)
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Send OTP", (selectedDialog, which) -> beginPhoneAuthentication(phone, false))
                .create();
        showDialogSafely(dialog);
    }

    private void sendPartnerPasswordReset(EditText emailInput) {
        String email = emailInput.getText().toString().trim().toLowerCase(Locale.US);
        if (!email.contains("@") || !email.contains(".")) {
            showSupportInfoDialog("Email Required", "Enter your registered email address first.");
            return;
        }
        if (firebaseAuth == null) firebaseAuth = FirebaseAuth.getInstance();
        firebaseAuth.sendPasswordResetEmail(email)
                .addOnSuccessListener(result -> showSupportInfoDialog("Email Sent", "A password reset link has been sent to " + email + "."))
                .addOnFailureListener(error -> showSupportInfoDialog("Reset Failed", partnerEmailAuthError(error)));
    }

    private String partnerEmailAuthError(Exception error) {
        String message = error == null || error.getMessage() == null ? "Email login failed" : error.getMessage();
        String normalized = message.toLowerCase(Locale.US);
        if (normalized.contains("password is invalid") || normalized.contains("invalid credential")) {
            return "Incorrect email or password.";
        }
        if (normalized.contains("no user record") || normalized.contains("user may have been deleted")) {
            return "No partner account was found for this email.";
        }
        if (normalized.contains("network")) {
            return "Network unavailable. Please try again.";
        }
        return message.length() > 140 ? message.substring(0, 140) : message;
    }

