    private void beginPhoneAuthentication(EditText phoneInput, boolean registration) {
        String phone = normalizePhone(phoneInput == null ? "" : phoneInput.getText().toString());
        if (!PHONE_PATTERN.matcher(phone).matches()) {
            if (phoneInput != null) phoneInput.setError("Enter a valid 10-digit mobile number");
            return;
        }
        pendingPhoneNumber = phone;
        pendingPhoneRegistration = registration;
        prefs.edit().putString(KEY_PHONE, phone).apply();
        pendingOtpRequestId = "";
        pendingPhoneVerificationId = "";
        phoneResendToken = null;
        otpExpiresAtMillis = 0L;
        otpResendAvailableAtMillis = 0L;
        showPhoneOtpScreen();
        requestPartnerOtp(false);
    }

