    private EditText otpDigitInput() {
        EditText input = new EditText(this);
        input.setGravity(Gravity.CENTER);
        input.setTextSize(20);
        input.setTypeface(Typeface.DEFAULT_BOLD);
        input.setTextColor(BLACK);
        input.setHintTextColor(Color.rgb(190, 184, 186));
        input.setSingleLine(true);
        input.setInputType(InputType.TYPE_CLASS_NUMBER);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            input.setAutofillHints("smsOTPCode");
        }
        input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(1)});
        input.setBackground(stroke(Color.WHITE, Color.rgb(220, 216, 217), dp(12)));
        input.setPadding(0, 0, 0, 0);
        return input;
    }

    private String readOtpCode(EditText[] boxes) {
        StringBuilder builder = new StringBuilder();
        if (boxes == null) return "";
        for (EditText box : boxes) {
            builder.append(box == null ? "" : box.getText().toString().trim());
        }
        return builder.toString();
    }

    /**
     * Uses Google Play services' SMS Retriever. It never requests READ_SMS;
     * Android delivers only an OTP SMS addressed to this signed application.
     */
    private void startOtpSmsAutoFill() {
        EditText[] boxes = activeOtpBoxes;
        stopOtpSmsAutoFill();
        activeOtpBoxes = boxes;
        if (activeOtpBoxes == null || activeOtpBoxes.length != 6) return;
        otpSmsReceiver = new BroadcastReceiver() {
            @Override public void onReceive(Context context, Intent intent) {
                if (!SmsRetriever.SMS_RETRIEVED_ACTION.equals(intent.getAction())) return;
                Status status = intent.getParcelableExtra(SmsRetriever.EXTRA_STATUS);
                if (status == null || status.getStatusCode() != CommonStatusCodes.SUCCESS) return;
                String message = intent.getStringExtra(SmsRetriever.EXTRA_SMS_MESSAGE);
                String code = extractSixDigitOtp(message);
                if (!TextUtils.isEmpty(code)) {
                    fillOtpBoxes(code);
                    Toast.makeText(MainActivity.this, "OTP filled automatically", Toast.LENGTH_SHORT).show();
                }
                stopOtpSmsAutoFill();
            }
        };
        IntentFilter filter = new IntentFilter(SmsRetriever.SMS_RETRIEVED_ACTION);
        ContextCompat.registerReceiver(
                this,
                otpSmsReceiver,
                filter,
                SmsRetriever.SEND_PERMISSION,
                null,
                ContextCompat.RECEIVER_EXPORTED
        );
        otpSmsReceiverRegistered = true;
        SmsRetriever.getClient(this).startSmsRetriever();
    }

    private void stopOtpSmsAutoFill() {
        if (otpSmsReceiverRegistered && otpSmsReceiver != null) {
            try { unregisterReceiver(otpSmsReceiver); } catch (IllegalArgumentException ignored) { }
        }
        otpSmsReceiverRegistered = false;
        otpSmsReceiver = null;
        activeOtpBoxes = null;
    }

    private String extractSixDigitOtp(String message) {
        if (TextUtils.isEmpty(message)) return "";
        java.util.regex.Matcher matcher = Pattern.compile("(?<!\\d)(\\d{6})(?!\\d)").matcher(message);
        return matcher.find() ? matcher.group(1) : "";
    }

    private void fillOtpBoxes(String code) {
        if (activeOtpBoxes == null || code == null || code.length() != activeOtpBoxes.length) return;
        for (int index = 0; index < activeOtpBoxes.length; index++) {
            activeOtpBoxes[index].setText(String.valueOf(code.charAt(index)));
        }
        activeOtpBoxes[activeOtpBoxes.length - 1].requestFocus();
    }

    private String maskPartnerPhone(String phone) {
        String clean = normalizePhone(phone);
        if (clean.length() < 4) return clean;
        return clean.substring(0, Math.min(2, clean.length())) + "XXXXXX" + clean.substring(clean.length() - 2);
    }

    private void resendPhoneOtp() {
        if (TextUtils.isEmpty(pendingPhoneNumber)) {
            Toast.makeText(this, "Request a new verification code", Toast.LENGTH_SHORT).show();
            setContentView(loginScreen());
            return;
        }
        if (otpSendInFlight) {
            Toast.makeText(this, "OTP request is already in progress", Toast.LENGTH_SHORT).show();
            return;
        }
        long remaining = otpResendAvailableAtMillis - android.os.SystemClock.elapsedRealtime();
        if (remaining > 0L) {
            Toast.makeText(this, "Resend available in " + Math.max(1L, (remaining + 999L) / 1000L) + " seconds", Toast.LENGTH_SHORT).show();
            return;
        }
        requestPartnerOtp(true);
    }

    private void requestPartnerOtp(boolean resend) {
        if (backendClient == null || TextUtils.isEmpty(pendingPhoneNumber) || otpSendInFlight) return;
        otpSendInFlight = true;
        final long generation = ++otpRequestGeneration;
        Toast.makeText(this, resend ? "Sending a new verification code..." : "Sending verification code...", Toast.LENGTH_SHORT).show();
        backendClient.sendOtp(pendingPhoneNumber, "partner", new BackendClient.JsonCallback() {
            @Override
            public void onSuccess(JSONObject object) {
                if (generation != otpRequestGeneration || isFinishing() || isDestroyed()) return;
                otpSendInFlight = false;
                String requestId = object.optString("requestId", "").trim();
                if (TextUtils.isEmpty(requestId)) {
                    Toast.makeText(MainActivity.this, "OTP service did not return a valid request. Please resend.", Toast.LENGTH_LONG).show();
                    return;
                }
                pendingOtpRequestId = requestId;
                pendingPhoneVerificationId = requestId;
                long now = android.os.SystemClock.elapsedRealtime();
                long expiresIn = Math.max(120L, object.optLong("expiresInSeconds", 300L));
                // Use monotonic elapsed time so device clock changes cannot make
                // a fresh OTP appear expired before its server-provided duration.
                otpExpiresAtMillis = now + expiresIn * 1000L;
                otpResendAvailableAtMillis = now + 30_000L;
                String devOtp = object.optString("devOtp", "");
                Toast.makeText(MainActivity.this,
                        TextUtils.isEmpty(devOtp) ? "Verification code sent" : "Development OTP: " + devOtp,
                        Toast.LENGTH_LONG).show();
            }

            @Override
            public void onError(String message) {
                if (generation != otpRequestGeneration || isFinishing() || isDestroyed()) return;
                otpSendInFlight = false;
                Toast.makeText(MainActivity.this, otpUserError(message), Toast.LENGTH_LONG).show();
            }
        });
    }

    private void cancelOtpUiSession() {
        stopOtpSmsAutoFill();
        otpRequestGeneration++;
        otpSendInFlight = false;
        if (otpTimerRunnable != null) {
            refreshHandler.removeCallbacks(otpTimerRunnable);
            otpTimerRunnable = null;
        }
    }

    private void startOtpTimer(TextView timer, TextView resend) {
        if (otpTimerRunnable != null) refreshHandler.removeCallbacks(otpTimerRunnable);
        otpTimerRunnable = new Runnable() {
            @Override public void run() {
                if (timer == null || resend == null || isFinishing() || isDestroyed()) return;
                long now = android.os.SystemClock.elapsedRealtime();
                long remainingMs = otpExpiresAtMillis - now;
                boolean canResend = !otpSendInFlight && now >= otpResendAvailableAtMillis;
                resend.setEnabled(canResend);
                resend.setAlpha(canResend ? 1f : 0.55f);
                if (otpSendInFlight || TextUtils.isEmpty(pendingOtpRequestId)) {
                    timer.setText("Sending OTP…");
                } else if (remainingMs <= 0L) {
                    timer.setText("OTP expired — request a new code");
                } else {
                    long seconds = (remainingMs + 999L) / 1000L;
                    timer.setText(String.format(Locale.US, "OTP valid for %02d:%02d", seconds / 60L, seconds % 60L));
                }
                refreshHandler.postDelayed(this, 1000L);
            }
        };
        refreshHandler.post(otpTimerRunnable);
    }

    private void verifyBackendPhoneOtp(String code, TextView verifyButton) {
        if (TextUtils.isEmpty(pendingPhoneNumber) || TextUtils.isEmpty(pendingOtpRequestId)) {
            resetOtpVerifyButton(verifyButton);
            showSupportInfoDialog("Verification Failed", "Please request a new OTP.");
            return;
        }
        if (otpExpiresAtMillis > 0L && android.os.SystemClock.elapsedRealtime() >= otpExpiresAtMillis) {
            resetOtpVerifyButton(verifyButton);
            showSupportInfoDialog("OTP Expired", "This OTP has completed its validity period. Please request a new code.");
            return;
        }
        backendClient.verifyOtp(pendingPhoneNumber, "partner", pendingOtpRequestId, code, new BackendClient.JsonCallback() {
            @Override
            public void onSuccess(JSONObject object) {
                String customToken = object.optString("customToken", "");
                if (TextUtils.isEmpty(customToken)) {
                    resetOtpVerifyButton(verifyButton);
                    showSupportInfoDialog("Verification Failed", "The OTP server did not return a Firebase session.");
                    return;
                }
                if (firebaseAuth == null) firebaseAuth = FirebaseAuth.getInstance();
                firebaseAuth.signInWithCustomToken(customToken)
                        .addOnSuccessListener(result -> handleVerifiedPhoneSession())
                        .addOnFailureListener(error -> {
                            resetOtpVerifyButton(verifyButton);
                            showSupportInfoDialog("Verification Failed",
                                    otpUserError(error == null ? "Firebase login failed" : error.getMessage()));
                        });
            }

            @Override
            public void onError(String message) {
                resetOtpVerifyButton(verifyButton);
                showSupportInfoDialog("Verification Failed", otpUserError(message));
            }
        });
    }

    private void resetOtpVerifyButton(TextView button) {
        if (button == null) return;
        button.setEnabled(true);
        button.setAlpha(1f);
        button.setText(onboardingRegistrationOtp ? "Verify & Continue" : "Verify & Login");
    }

    private void authenticateWithPhoneCredential(PhoneAuthCredential credential) {
        if (firebaseAuth == null) firebaseAuth = FirebaseAuth.getInstance();
        firebaseAuth.signInWithCredential(credential)
                .addOnSuccessListener(result -> handleVerifiedPhoneSession())
                .addOnFailureListener(error -> {
                    String message = error instanceof FirebaseAuthInvalidCredentialsException
                            ? "The verification code is invalid or expired."
                            : safeUserError(error == null ? "Phone verification failed" : error.getMessage());
                    showSupportInfoDialog("Verification Failed", message);
                });
    }

    private void handleVerifiedPhoneSession() {
        if (onboardingRegistrationOtp && registrationDraftActive) {
            onboardingRegistrationOtp = false;
            authMode = "Register";
            EditText name = hiddenInput(draftRegName, InputType.TYPE_CLASS_TEXT);
            EditText phone = hiddenInput(draftRegPhone, InputType.TYPE_CLASS_PHONE);
            EditText email = hiddenInput(draftRegEmail, InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);
            EditText dob = hiddenInput(draftRegDob, InputType.TYPE_CLASS_TEXT);
            EditText gender = hiddenInput(draftRegGender, InputType.TYPE_CLASS_TEXT);
            EditText city = hiddenInput(draftRegCity, InputType.TYPE_CLASS_TEXT);
            EditText state = hiddenInput(draftRegState, InputType.TYPE_CLASS_TEXT);
            EditText pin = hiddenInput(draftRegPin, InputType.TYPE_CLASS_NUMBER);
            EditText address = hiddenInput(savedOrGeneratedAddress(draftRegCity, draftRegState, draftRegPin), InputType.TYPE_CLASS_TEXT);
            EditText emergency = hiddenInput(draftRegPhone, InputType.TYPE_CLASS_PHONE);
            EditText experience = hiddenInput(TextUtils.isEmpty(draftRegExperience) ? "0" : draftRegExperience, InputType.TYPE_CLASS_NUMBER);
            EditText areas = hiddenInput(draftRegAreas, InputType.TYPE_CLASS_TEXT);
            EditText languages = hiddenInput(draftRegLanguages, InputType.TYPE_CLASS_TEXT);
            finishAuth(name, phone, email, dob, gender, address, city, state, pin, emergency, experience, areas, languages);
            return;
        }
        if (pendingPhoneRegistration) {
            prefs.edit()
                    .putString(KEY_PHONE, pendingPhoneNumber)
                    .putString(KEY_SESSION_ROLE, SESSION_OWNER)
                    .apply();
            showAuthForm("Register");
            return;
        }
        startAuthenticatedStaffLookup();
    }

    private void startAuthenticatedStaffLookup() {
        backendClient.startLaundryStaffSession(fcmToken(), true, new BackendClient.JsonCallback() {
            @Override
            public void onSuccess(JSONObject object) {
                persistStaffSession(object);
            }

            @Override
            public void onError(String staffError) {
                backendClient.fetchPartnerProfile(new BackendClient.JsonCallback() {
                    @Override
                    public void onSuccess(JSONObject object) {
                        JSONObject partner = object == null ? null : object.optJSONObject("partner");
                        if (partner != null && !TextUtils.isEmpty(partner.optString("_id", ""))) {
                            persistOwnerSession(partner);
                            return;
                        }
                        showSupportInfoDialog(
                                "Account Not Found",
                                "This number is not linked to a Partner or company staff account. Ask the company owner to add this exact number, or register as a new partner."
                        );
                    }

                    @Override
                    public void onError(String ignored) {
                        showSupportInfoDialog("Login Failed", safeUserError(staffError));
                    }
                });
            }
        });
    }

    private void persistStaffSession(JSONObject response) {
        JSONObject staff = response == null ? null : response.optJSONObject("staff");
        if (staff == null) {
            showSupportInfoDialog("Login Failed", "Staff profile was not returned by the server.");
            return;
        }
        online = staff.optBoolean("isOnline", true);
        Set<String> staffServices = categoriesFromPartnerJson(staff.optJSONArray("serviceCategory"));
        selectedSkills = staffServices;
        selectedSkill = staffServices.isEmpty() ? "" : firstPartnerSkill();
        String authoritativeServiceId = canonicalAccountServiceId(staff, staffServices);
        String companyName = staffCompanyNameFromJson(staff);
        prefs.edit()
                .putBoolean(KEY_LOGGED_IN, true)
                .putString(KEY_SESSION_ROLE, SESSION_STAFF)
                .putString(KEY_NAME, staff.optString("name", "Service Staff"))
                .putString(KEY_PHONE, normalizePhone(staff.optString("phone", pendingPhoneNumber)))
                .putString(KEY_EMAIL, staffEmailValue(staff))
                .putString(KEY_PHOTO, staffPhotoValue(staff))
                .putString(KEY_STAFF_PROFILE_JSON, staff.toString())
                .putString(KEY_STAFF_SHOP_NAME, companyName)
                .putString(KEY_STAFF_OWNER_ID, staff.optString("ownerPartnerId", ""))
                .putString(KEY_SKILL, staffServices.isEmpty() ? "" : skillsCsv(staffServices))
                .putString(KEY_SERVICE_ID, authoritativeServiceId)
                .putBoolean("online", online)
                .apply();
        setContentView(appShell());
        applyLiveBookings(parseBackendBookings(response), false);
        showDashboard();
        refreshAppControl();
        startStaffBackgroundSync();
    }

    private void persistOwnerSession(JSONObject partner) {
        Set<String> ownerServices = categoriesFromPartnerJson(partner.optJSONArray("serviceCategory"));
        selectedSkills = ownerServices;
        selectedSkill = ownerServices.isEmpty() ? "" : firstPartnerSkill();
        String authoritativeServiceId = canonicalAccountServiceId(partner, ownerServices);
        prefs.edit()
                .putBoolean(KEY_LOGGED_IN, true)
                .putString(KEY_SESSION_ROLE, SESSION_OWNER)
                .putString(KEY_NAME, partner.optString("name", prefs.getString(KEY_NAME, "ApnaServo Partner")))
                .putString(KEY_PHONE, normalizePhone(partner.optString("phone", pendingPhoneNumber)))
                .putString(KEY_EMAIL, partner.optString("email", prefs.getString(KEY_EMAIL, "")))
                .putString(KEY_PHOTO, partner.optString("profilePhotoUrl", prefs.getString(KEY_PHOTO, "")))
                .putString(KEY_PUBLIC_ID, partner.optString("publicId", partner.optString("partnerCode", "")))
                .putString(KEY_SKILL, skillsCsv(ownerServices))
                .putString(KEY_SERVICE_ID, authoritativeServiceId)
                .apply();
        updateApprovalFromPartner(partner);
        if (isPartnerApproved()) {
            setContentView(appShell());
            showDashboard();
        } else {
            setContentView(verificationStatusScreen());
        }
        refreshAppControl();
        startPartnerBackgroundSync();
    }

