    private void showPartnerRegistrationStepOne() {
        authMode = "Register";
        ScrollView scroll = new ScrollView(this);
        scroll.setFillViewport(true);
        scroll.setSmoothScrollingEnabled(true);
        scroll.setOverScrollMode(View.OVER_SCROLL_NEVER);
        scroll.setVerticalScrollBarEnabled(false);
        scroll.setClipToPadding(false);
        scroll.setBackgroundColor(Color.rgb(255, 249, 248));

        LinearLayout page = vertical();
        page.setPadding(dp(22), dp(38), dp(22), dp(22));
        page.setGravity(Gravity.CENTER_HORIZONTAL);
        scroll.addView(page, new ScrollView.LayoutParams(-1, -2));

        FrameLayout header = registrationHeader(
                "Choose Your Services",
                "Select the services you provide to get started on ApnaServo",
                () -> setContentView(loginScreen())
        );
        page.addView(header, margin(-1, 142, 0, 0, 0, 18));

        String[][] services = new String[][]{
                {"AC Repair", "ac", "service_logo_ac", "AC"},
                {"Plumber", "plumbing", "service_logo_plumbing", "PL"},
                {"Electrician", "electrician", "service_logo_electrician", "EL"},
                {"Carpenter", "carpenter", "service_home_carpenter", "CP"},
                {"Painting", "painting", "service_home_painting", "PT"},
                {"Cleaning", "cleaning", "service_logo_cleaning", "CL"},
                {"Interior Design", "interior", "service_home_interior", "IN"},
                {"Pest Control", "pest", "ic_service_pest_logo", "PC"},
                {"Laundry", "laundry", "laundry_service_logo", "LW"},
                {"RO Service", "ro", "ro_service_logo", "RO"},
                {"Appliances Repair", "appliances", "service_logo_appliances", "AP"},
                {"Roadside\nAssistance", "roadside", "service_home_roadside", "RA"}
        };
        Map<String, LinearLayout> serviceCards = new HashMap<>();
        for (int rowIndex = 0; rowIndex < services.length; rowIndex += 3) {
            LinearLayout row = horizontal();
            row.setGravity(Gravity.CENTER);
            for (int column = 0; column < 3; column++) {
                String[] service = services[rowIndex + column];
                int iconResource = TextUtils.isEmpty(service[2]) ? 0
                        : getResources().getIdentifier(service[2], "drawable", getPackageName());
                LinearLayout option = registrationServiceCard(
                        service[0], iconResource, service[3], selectedSkills.contains(service[1]));
                option.setTag(service[1]);
                option.setOnClickListener(view -> {
                    String skill = String.valueOf(view.getTag());
                    if (selectedSkills.contains(skill)) {
                        selectedSkills.remove(skill);
                    } else {
                        // One profile is one service. This keeps all matching,
                        // bookings and staff workspaces fully separated.
                        selectedSkills.clear();
                        selectedSkills.add(skill);
                    }
                    selectedSkill = selectedSkills.isEmpty() ? "" : firstPartnerSkill();
                    for (Map.Entry<String, LinearLayout> entry : serviceCards.entrySet()) {
                        styleRegistrationServiceCard(entry.getValue(), selectedSkills.contains(entry.getKey()));
                    }
                });
                addPressAnimation(option);
                serviceCards.put(service[1], option);
                LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(0, dp(118), 1);
                if (column > 0) params.setMargins(dp(1), 0, 0, 0);
                row.addView(option, params);
            }
            page.addView(row, margin(-1, 118, 0, 0, 0, rowIndex + 3 < services.length ? 1 : 22));
        }

        TextView next = roseButton("Continue");
        next.setTextSize(16);
        next.setGravity(Gravity.CENTER);
        next.setOnClickListener(view -> {
            if (selectedSkills.isEmpty()) {
                Toast.makeText(this, "Select at least one service to continue", Toast.LENGTH_SHORT).show();
                return;
            }
            selectedSkill = firstPartnerSkill();
            if (selectedSkills.contains("laundry")) {
                showLaundryServiceDetailsRegistration();
            } else {
                showStandardPartnerRegistration();
            }
        });
        next.setBackground(gradient(Color.rgb(255, 63, 111), Color.rgb(241, 45, 91), dp(8)));
        page.addView(next, margin(-1, 56, 0, 0, 0, 0));
        setContentView(scroll);
    }

    private FrameLayout registrationHeader(String titleValue, String subtitleValue, Runnable backAction) {
        FrameLayout header = new FrameLayout(this);
        ImageView back = new ImageView(this);
        back.setImageResource(R.drawable.ic_partner_info_back);
        back.setColorFilter(BLACK);
        back.setPadding(dp(10), dp(10), dp(10), dp(10));
        back.setBackground(stroke(Color.rgb(255, 246, 247), Color.rgb(252, 228, 233), dp(14)));
        back.setOnClickListener(view -> backAction.run());
        addPressAnimation(back);
        FrameLayout.LayoutParams backParams = new FrameLayout.LayoutParams(dp(44), dp(44), Gravity.LEFT | Gravity.TOP);
        backParams.setMargins(0, dp(4), 0, 0);
        header.addView(back, backParams);

        LinearLayout copy = vertical();
        copy.setGravity(Gravity.CENTER_HORIZONTAL);
        TextView title = text(titleValue, 27, BLACK, true);
        title.setGravity(Gravity.CENTER);
        title.setLetterSpacing(0f);
        title.setMaxLines(1);
        title.setEllipsize(TextUtils.TruncateAt.END);
        copy.addView(title);
        TextView subtitle = text(subtitleValue, 16, MUTED, false);
        subtitle.setGravity(Gravity.CENTER);
        subtitle.setMaxLines(2);
        subtitle.setLineSpacing(dp(2), 1f);
        copy.addView(subtitle, margin(-1, -2, 0, 9, 0, 0));
        FrameLayout.LayoutParams copyParams = new FrameLayout.LayoutParams(-1, -2, Gravity.TOP | Gravity.CENTER_HORIZONTAL);
        copyParams.setMargins(dp(48), 0, dp(48), 0);
        header.addView(copy, copyParams);
        return header;
    }

    private LinearLayout registrationServiceCard(String label, int iconResource, String fallback, boolean selected) {
        LinearLayout card = vertical();
        card.setGravity(Gravity.CENTER);
        card.setPadding(dp(5), dp(6), dp(5), dp(6));
        TextView indicator = text(selected ? "\u2713" : "", 12, selected ? Color.WHITE : ROSE, true);
        indicator.setGravity(Gravity.CENTER);
        indicator.setTag("indicator");
        LinearLayout indicatorRow = horizontal();
        indicatorRow.setGravity(Gravity.RIGHT);
        indicatorRow.addView(indicator, new LinearLayout.LayoutParams(dp(22), dp(22)));
        card.addView(indicatorRow, new LinearLayout.LayoutParams(-1, dp(22)));
        if (iconResource != 0) {
            ImageView icon = new ImageView(this);
            icon.setImageResource(iconResource);
            icon.setScaleType(ImageView.ScaleType.FIT_CENTER);
            icon.setAdjustViewBounds(true);
            icon.setTag("icon");
            card.addView(icon, margin(62, 50, 0, 0, 0, 4));
        } else {
            TextView icon = text(fallback, 24, selected ? ROSE_DARK : Color.rgb(83, 92, 105), true);
            icon.setTag("icon");
            icon.setGravity(Gravity.CENTER);
            card.addView(icon, margin(-1, 50, 0, 0, 0, 4));
        }
        TextView title = text(label, 14, BLACK, false);
        title.setTag("title");
        title.setGravity(Gravity.CENTER);
        title.setMaxLines(2);
        title.setIncludeFontPadding(false);
        card.addView(title, new LinearLayout.LayoutParams(-1, dp(32)));
        styleRegistrationServiceCard(card, selected);
        return card;
    }

    private void styleRegistrationServiceCard(LinearLayout card, boolean selected) {
        card.setBackground(stroke(selected ? Color.rgb(255, 248, 250) : Color.WHITE,
                selected ? ROSE : Color.rgb(242, 232, 234), dp(1)));
        card.setElevation(0);
        LinearLayout indicatorRow = (LinearLayout) card.getChildAt(0);
        TextView indicator = (TextView) indicatorRow.getChildAt(0);
        indicator.setText(selected ? "\u2713" : "");
        indicator.setTextColor(selected ? Color.WHITE : ROSE);
        indicator.setBackground(stroke(selected ? ROSE : Color.TRANSPARENT, ROSE, dp(11)));
    }

