    private String laundryDocumentMetadata(String title, String fallback) {
        if (!documentUploaded(title)) return fallback;
        String source = prefs.getString(documentPrefKey(title), "");
        if (TextUtils.isEmpty(source)) return "File added | Ready to submit";
        String fileName = laundryDocumentFileName(source);
        long bytes = -1L;
        try {
            Uri uri = Uri.parse(source);
            if ("file".equalsIgnoreCase(uri.getScheme()) && uri.getPath() != null) {
                bytes = new File(uri.getPath()).length();
            } else {
                try (android.content.res.AssetFileDescriptor descriptor =
                             getContentResolver().openAssetFileDescriptor(uri, "r")) {
                    if (descriptor != null) bytes = descriptor.getLength();
                }
            }
        } catch (Exception ignored) {
        }
        if (bytes > 0L) {
            return String.format(Locale.US, "%s | %.2f MB | Ready to submit",
                    fileName, bytes / (1024d * 1024d));
        }
        return fileName + " | Ready to submit";
    }

    private String laundryDocumentFileName(String source) {
        String fallback = "Selected file";
        try {
            Uri uri = Uri.parse(source);
            if ("content".equalsIgnoreCase(uri.getScheme())) {
                try (android.database.Cursor cursor = getContentResolver().query(
                        uri,
                        new String[]{android.provider.OpenableColumns.DISPLAY_NAME},
                        null,
                        null,
                        null
                )) {
                    if (cursor != null && cursor.moveToFirst()) {
                        int column = cursor.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME);
                        if (column >= 0 && !TextUtils.isEmpty(cursor.getString(column))) {
                            return cursor.getString(column);
                        }
                    }
                }
            }
            if (uri.getPath() != null) {
                String name = new File(uri.getPath()).getName();
                if (!TextUtils.isEmpty(name)) return name;
            }
        } catch (Exception ignored) {
        }
        return fallback;
    }

    private void addLaundryStaffForm() {
        if (laundryStaffContainer == null) return;
        if (laundryStaffForms.size() >= 20) {
            Toast.makeText(this, "You can add up to 20 staff members", Toast.LENGTH_SHORT).show();
            return;
        }
        int sequence = laundryStaffSequence++;
        String documentTitle = "Laundry Staff " + sequence + " ID Proof";
        LinearLayout root = vertical();
        root.setPadding(dp(10), dp(10), dp(10), dp(12));
        root.setBackground(stroke(Color.rgb(255, 251, 252), Color.rgb(247, 222, 228), dp(14)));

        LinearLayout heading = horizontal();
        heading.setGravity(Gravity.CENTER_VERTICAL);
        TextView count = text(String.format(Locale.US, "%02d", sequence), 12, ROSE, true);
        count.setGravity(Gravity.CENTER);
        count.setBackground(round(ROSE_SOFT, dp(18)));
        heading.addView(count, new LinearLayout.LayoutParams(dp(38), dp(38)));
        TextView memberTitle = text("Staff Member", 14, BLACK, true);
        LinearLayout.LayoutParams memberTitleParams = new LinearLayout.LayoutParams(0, -2, 1);
        memberTitleParams.setMargins(dp(10), 0, dp(8), 0);
        heading.addView(memberTitle, memberTitleParams);
        TextView remove = text("Remove", 11, ROSE, true);
        remove.setGravity(Gravity.CENTER);
        heading.addView(remove, new LinearLayout.LayoutParams(dp(66), dp(38)));
        ImageView removeIcon = new ImageView(this);
        removeIcon.setImageResource(R.drawable.ic_partner_delete);
        removeIcon.setPadding(dp(6), dp(6), dp(6), dp(6));
        heading.addView(removeIcon, new LinearLayout.LayoutParams(dp(34), dp(38)));
        root.addView(heading, margin(-1, -2, 0, 0, 0, 10));

        EditText name = registrationInput("Staff Name", InputType.TYPE_CLASS_TEXT);
        EditText phone = registrationInput("Staff Phone Number", InputType.TYPE_CLASS_PHONE);
        phone.setFilters(new InputFilter[]{new InputFilter.LengthFilter(10)});
        EditText email = registrationInput("Staff Email Address", InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);
        EditText idType = registrationInput("Select ID Type", InputType.TYPE_CLASS_TEXT);
        idType.setFocusable(false);
        idType.setText("Aadhaar");

        String photoTitle = "Laundry Staff " + sequence + " Profile Picture";
        root.addView(text("Staff Profile Picture", 12, Color.rgb(98, 96, 101), false), margin(-1, -2, 0, 2, 0, 6));
        root.addView(laundryRegistrationUploadRow(photoTitle, "Upload Profile Picture",
                "Clear photo of staff member", R.drawable.ic_partner_reg_camera_rose), margin(-1, -2, 0, 0, 0, 10));

        root.addView(laundryFieldRow(R.drawable.ic_partner_info_user, "Staff Name", name, false), margin(-1, -2, 0, 0, 0, 8));
        root.addView(laundryFieldRow(R.drawable.ic_partner_info_phone, "Staff Phone Number", phone, false), margin(-1, -2, 0, 0, 0, 8));
        root.addView(laundryFieldRow(R.drawable.ic_partner_reg_mail, "Staff Email Address", email, false), margin(-1, -2, 0, 0, 0, 8));

        View idTypeRow = laundryFieldRow(R.drawable.ic_partner_info_id, "ID Type", idType, true);
        View.OnClickListener chooseId = view -> {
            String[] labels = {"Aadhaar", "PAN", "Driving Licence", "Voter ID", "Passport"};
            int selected = 0;
            for (int index = 0; index < labels.length; index++) {
                if (labels[index].equalsIgnoreCase(value(idType))) selected = index;
            }
            showChoiceSheet("Staff ID Type", "Select the uploaded identity proof type.", labels, selected,
                    which -> idType.setText(labels[which]));
        };
        idTypeRow.setOnClickListener(chooseId);
        idType.setOnClickListener(chooseId);
        root.addView(idTypeRow, margin(-1, -2, 0, 0, 0, 8));
        root.addView(text("Staff Document", 12, Color.rgb(98, 96, 101), false), margin(-1, -2, 0, 2, 0, 6));
        root.addView(laundryRegistrationUploadRow(documentTitle, "Upload Staff Document",
                "Upload Aadhaar, ID card or any official document", R.drawable.ic_partner_doc_upload),
                margin(-1, -2, 0, 0, 0, 8));
        LaundryStaffForm form = new LaundryStaffForm(sequence, root, name, phone, email, idType, documentTitle);
        View.OnClickListener removeAction = view -> {
            if (laundryStaffForms.size() == 1) {
                Toast.makeText(this, "At least one staff member is required", Toast.LENGTH_SHORT).show();
                return;
            }
            laundryStaffForms.remove(form);
            laundryStaffContainer.removeView(root);
        };
        remove.setOnClickListener(removeAction);
        removeIcon.setOnClickListener(removeAction);
        laundryStaffForms.add(form);
        laundryStaffContainer.addView(root, margin(-1, -2, 0, 0, 0, 10));
    }

    private void submitLaundryRegistration(EditText shopNameView, EditText shopLicenseView,
                                           EditText shopLocationView, EditText ownerNameView,
                                           EditText ownerPhoneView) {
        if (laundryRegistrationSubmitting) return;
        String shopName = value(shopNameView);
        String shopLicense = value(shopLicenseView);
        String shopLocation = value(shopLocationView);
        String ownerName = value(ownerNameView);
        String ownerPhone = value(ownerPhoneView).replaceAll("\\D", "");
        String savedPhone = prefs.getString(KEY_PHONE, "").replaceAll("\\D", "");
        if (!isValidIndianPhone(ownerPhone) && isValidIndianPhone(savedPhone)) ownerPhone = savedPhone;
        if (!isValidIndianPhone(ownerPhone)) {
            ownerPhoneView.setError("Enter a valid 10-digit Indian mobile number");
            ownerPhoneView.requestFocus();
            Toast.makeText(this, "Valid laundry owner mobile number required", Toast.LENGTH_LONG).show();
            return;
        }
        if (TextUtils.isEmpty(ownerName)) {
            ownerName = prefs.getString(KEY_NAME, "Laundry Owner").trim();
        }
        if (!isValidPartnerName(ownerName)) ownerName = "Laundry Owner";
        if (TextUtils.isEmpty(shopName)) shopName = ownerName + " Laundry";
        if (TextUtils.isEmpty(shopLicense)) shopLicense = "Not provided";
        if (TextUtils.isEmpty(shopLocation)) shopLocation = serviceAreaLabel();

        JSONArray staffMembers = new JSONArray();
        List<String> staffDocumentTitles = new ArrayList<>();
        for (LaundryStaffForm form : laundryStaffForms) {
            String staffName = value(form.name);
            String staffPhone = value(form.phone).replaceAll("\\D", "");
            String staffEmail = value(form.email).trim().toLowerCase(Locale.US);
            String idType = value(form.idType);
            boolean completeStaff = isValidPartnerName(staffName)
                    && (isValidIndianPhone(staffPhone) || isValidEmail(staffEmail))
                    && !TextUtils.isEmpty(idType);
            if (!completeStaff) continue;
            JSONObject staff = new JSONObject();
            try {
                staff.put("sequence", form.sequence);
                staff.put("name", staffName);
                staff.put("phone", staffPhone);
                staff.put("email", staffEmail);
                staff.put("idType", idType);
                staff.put("documentType", documentTypeForTitle(form.documentTitle));
                staff.put("documentTitle", form.documentTitle);
                staffMembers.put(staff);
                staffDocumentTitles.add(form.documentTitle);
            } catch (Exception ignored) {
            }
        }

        JSONObject laundryBusiness = new JSONObject();
        JSONObject profile = new JSONObject();
        try {
            laundryBusiness.put("shopName", shopName);
            laundryBusiness.put("shopLicenseNumber", shopLicense);
            laundryBusiness.put("shopLocation", shopLocation);
            laundryBusiness.put("ownerName", ownerName);
            laundryBusiness.put("ownerPhone", ownerPhone);
            laundryBusiness.put("staffMembers", staffMembers);
            profile.put("businessType", "laundry");
            profile.put("laundryBusiness", laundryBusiness);
            profile.put("residentialAddress", shopLocation);
            profile.put("city", prefs.getString(KEY_CITY, "Guwahati"));
            profile.put("state", prefs.getString(KEY_STATE, "Assam"));
            profile.put("pinCode", prefs.getString(KEY_PIN_CODE, ""));
            profile.put("emergencyContactNumber", ownerPhone);
            profile.put("yearsOfExperience", 0);
            profile.put("workingAreas", shopLocation);
            profile.put("languagesKnown", prefs.getString(KEY_LANGUAGES, "Hindi, English"));
            addRegistrationTermsToProfile(profile);
        } catch (Exception ignored) {
        }

        selectedSkills.add("laundry");
        selectedSkill = "laundry";
        prefs.edit()
                .remove(documentPrefKey("Laundry Shop License"))
                .remove(documentPrefKey("Laundry Shop License") + "_name")
                .remove(documentPrefKey("Laundry Shop License") + "_size")
                .putBoolean(KEY_LAUNDRY_REGISTRATION, true)
                .putString(KEY_LAUNDRY_SHOP_NAME, shopName)
                .putString(KEY_LAUNDRY_SHOP_LICENSE, shopLicense)
                .putString(KEY_LAUNDRY_SHOP_LOCATION, shopLocation)
                .putString(KEY_LAUNDRY_OWNER_NAME, ownerName)
                .putString(KEY_LAUNDRY_OWNER_PHONE, ownerPhone)
                .putInt(KEY_LAUNDRY_STAFF_COUNT, staffMembers.length())
                .putString(KEY_LAUNDRY_STAFF_DOCUMENTS, TextUtils.join("|", staffDocumentTitles))
                .putString(KEY_LAUNDRY_STAFF_JSON, staffMembers.toString())
                .apply();
        setLaundryRegistrationSubmitting(true);
        String email = !TextUtils.isEmpty(pendingGoogleEmail) ? pendingGoogleEmail : prefs.getString(KEY_EMAIL, "");
        String photo = !TextUtils.isEmpty(pendingGooglePhoto) ? pendingGooglePhoto : prefs.getString(KEY_PHOTO, "");
        finishPartnerLogin(ownerName, ownerPhone, email, photo, profile);
    }

    private void setLaundryRegistrationSubmitting(boolean submitting) {
        laundryRegistrationSubmitting = submitting;
        if (laundryRegistrationSubmitButton == null) return;
        laundryRegistrationSubmitButton.setEnabled(!submitting);
        laundryRegistrationSubmitButton.setAlpha(submitting ? 0.72f : 1f);
        laundryRegistrationSubmitButton.setText(submitting
                ? "Submitting securely..."
                : "Request for Verification");
    }

