    private void installDateSlashFormatter(EditText input) {
        input.addTextChangedListener(new TextWatcher() {
            boolean changing;
            @Override public void beforeTextChanged(CharSequence s, int start, int count, int after) {}
            @Override public void onTextChanged(CharSequence s, int start, int before, int count) {}
            @Override public void afterTextChanged(Editable editable) {
                if (changing) return;
                String digits = editable.toString().replaceAll("\\D", "");
                if (digits.length() > 8) digits = digits.substring(0, 8);
                StringBuilder formatted = new StringBuilder();
                for (int i = 0; i < digits.length(); i++) {
                    if (i == 2 || i == 4) formatted.append('/');
                    formatted.append(digits.charAt(i));
                }
                if (!formatted.toString().equals(editable.toString())) {
                    changing = true;
                    input.setText(formatted.toString());
                    input.setSelection(formatted.length());
                    changing = false;
                }
            }
        });
    }

    private void installKeyboardLift(ScrollView scroll, EditText... fields) {
        if (scroll == null || fields == null) return;
        for (EditText field : fields) {
            if (field == null) continue;
            field.setOnFocusChangeListener((view, focused) -> {
                if (!focused) return;
                scroll.postDelayed(() -> {
                    int target = Math.max(0, view.getTop() - dp(110));
                    ViewParent parent = view.getParent();
                    while (parent instanceof View && parent != scroll) {
                        target += ((View) parent).getTop();
                        parent = parent.getParent();
                    }
                    scroll.smoothScrollTo(0, target);
                }, 220L);
            });
        }
    }

