    private int registrationIconResource(String icon) {
        if ("P".equals(icon)) return R.drawable.ic_partner_info_user;
        if ("T".equals(icon)) return R.drawable.ic_partner_info_phone;
        if ("@".equals(icon)) return R.drawable.ic_partner_reg_mail;
        if ("D".equals(icon)) return R.drawable.ic_partner_reg_calendar;
        if ("G".equals(icon)) return R.drawable.ic_partner_reg_gender;
        if ("L".equals(icon)) return R.drawable.ic_partner_reg_pin;
        if ("B".equals(icon)) return R.drawable.ic_partner_reg_building;
        if ("#".equals(icon)) return R.drawable.ic_partner_reg_pin;
        if ("W".equals(icon)) return R.drawable.ic_partner_stat_briefcase;
        if ("A".equals(icon)) return R.drawable.ic_partner_service_location;
        if ("O".equals(icon)) return R.drawable.ic_partner_doc_certificate;
        return 0;
    }

    private String savedOrGeneratedAddress(String city, String state, String pin) {
        String saved = prefs.getString(KEY_ADDRESS, "");
        if (!TextUtils.isEmpty(saved)) {
            return saved;
        }
        StringBuilder builder = new StringBuilder();
        if (!TextUtils.isEmpty(city)) {
            builder.append(city.trim());
        }
        if (!TextUtils.isEmpty(state)) {
            if (builder.length() > 0) builder.append(", ");
            builder.append(state.trim());
        }
        if (!TextUtils.isEmpty(pin)) {
            if (builder.length() > 0) builder.append(" - ");
            builder.append(pin.trim());
        }
        return builder.toString();
    }

    private String serviceDisplayName(String skill) {
        String normalized = normalizeSkill(skill);
        if ("plumbing".equals(normalized)) return "Plumber";
        if ("electrician".equals(normalized)) return "Electrician";
        if ("ac".equals(normalized)) return "AC";
        if ("cleaning".equals(normalized)) return "Cleaning";
        if ("painting".equals(normalized)) return "Painting";
        if ("carpenter".equals(normalized)) return "Carpenter";
        if ("appliances".equals(normalized)) return "Appliance";
        if ("roadside".equals(normalized)) return "Roadside";
        if ("interior".equals(normalized)) return "Interior";
        if ("pest".equals(normalized)) return "Pest";
        if ("laundry".equals(normalized)) return "Laundry";
        if ("ro".equals(normalized)) return "RO";
        return "Service";
    }

    private String value(EditText editText) {
        return editText == null ? "" : editText.getText().toString().trim();
    }

    private void openCamera() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M
                && checkSelfPermission(Manifest.permission.CAMERA) != PackageManager.PERMISSION_GRANTED) {
            requestPermissions(new String[]{Manifest.permission.CAMERA}, CAMERA_PERMISSION_REQUEST);
            return;
        }
        launchCameraIntent();
    }

    private void launchCameraIntent() {
        Intent intent = new Intent(MediaStore.ACTION_IMAGE_CAPTURE);
        if (intent.resolveActivity(getPackageManager()) == null) {
            Toast.makeText(this, "Camera app is not available on this device.", Toast.LENGTH_LONG).show();
            return;
        }
        try {
            startActivityForResult(intent, REQ_CAMERA);
        } catch (Exception exception) {
            Toast.makeText(this, "Unable to open the camera.", Toast.LENGTH_LONG).show();
        }
    }

    private void handleProfilePhotoCameraResult(Intent data) {
        if (data == null || data.getExtras() == null) {
            Toast.makeText(this, "Profile photo was not captured. Please try again.", Toast.LENGTH_SHORT).show();
            return;
        }
        Object value = data.getExtras().get("data");
        if (!(value instanceof Bitmap)) {
            Toast.makeText(this, "Profile photo was not captured. Please try again.", Toast.LENGTH_SHORT).show();
            return;
        }
        Uri saved = saveCameraBitmap((Bitmap) value);
        if (saved == null) {
            Toast.makeText(this, "Unable to save profile photo.", Toast.LENGTH_SHORT).show();
            return;
        }
        authPhotoUri = saved;
        if (authPhotoView != null) {
            setImageUriSafely(authPhotoView, authPhotoUri);
        }
        if (faceStatusView != null) {
            faceStatusView.setText("Profile photo added");
            faceStatusView.setTextColor(GREEN);
        }
        if (faceActionView != null) {
            faceActionView.setText("Retake Profile Photo");
        }
    }

    @Override
    public void onRequestPermissionsResult(int requestCode, String[] permissions, int[] grantResults) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults);
        if (requestCode == CAMERA_PERMISSION_REQUEST) {
            boolean granted = grantResults.length > 0 && grantResults[0] == PackageManager.PERMISSION_GRANTED;
            if (granted) {
                launchCameraIntent();
            } else {
                Toast.makeText(this, "Camera permission is required to add a profile photo.", Toast.LENGTH_LONG).show();
            }
        } else if (requestCode == DOCUMENT_CAMERA_PERMISSION_REQUEST) {
            boolean granted = grantResults.length > 0 && grantResults[0] == PackageManager.PERMISSION_GRANTED;
            if (granted) {
                launchDocumentCameraIntent();
            } else {
                Toast.makeText(this, "Camera permission required for document upload.", Toast.LENGTH_LONG).show();
            }
        } else if (requestCode == SUPPORT_CAMERA_PERMISSION_REQUEST) {
            boolean granted = grantResults.length > 0 && grantResults[0] == PackageManager.PERMISSION_GRANTED;
            if (granted) {
                launchPartnerSupportCamera();
            } else {
                Toast.makeText(this, "Camera permission required for support photo.", Toast.LENGTH_LONG).show();
            }
        } else if (requestCode == LOCATION_PERMISSION_REQUEST) {
            boolean granted = false;
            for (int result : grantResults) {
                if (result == PackageManager.PERMISSION_GRANTED) {
                    granted = true;
                    break;
                }
            }
            if (granted) {
                syncCurrentPartnerLocation();
                PartnerBooking booking = activeMapBooking != null ? activeMapBooking : activeDetailBooking;
                if (booking != null) {
                    startJobLocationTracking(booking);
                    Toast.makeText(this, "GPS enabled for active job", Toast.LENGTH_SHORT).show();
                } else {
                    Toast.makeText(this, "Location access enabled", Toast.LENGTH_SHORT).show();
                }
            } else {
                Toast.makeText(this, "Location access is required for nearby bookings and active-job tracking.", Toast.LENGTH_LONG).show();
            }
            refreshHandler.postDelayed(this::requestNotificationPermission, 450L);
        }
    }

    private void finishAuth(EditText name, EditText phone, EditText emailView, EditText dobView, EditText genderView, EditText addressView, EditText cityView, EditText stateView, EditText pinView, EditText emergencyView, EditText experienceView, EditText areasView, EditText languagesView) {
        String partnerName = name.getText().toString().trim();
        if (!isValidPartnerName(partnerName)) {
            Toast.makeText(this, "Valid partner name required", Toast.LENGTH_SHORT).show();
            return;
        }
        String partnerPhone = phone.getText().toString().replaceAll("\\D", "");
        if (!isValidIndianPhone(partnerPhone)) {
            Toast.makeText(this, "10 digit Indian mobile number required", Toast.LENGTH_SHORT).show();
            return;
        }
        String email = emailView.getText().toString().trim();
        if (!TextUtils.isEmpty(email) && !isValidEmail(email)) {
            Toast.makeText(this, "Valid email required", Toast.LENGTH_SHORT).show();
            return;
        }
        String dob = dobView.getText().toString().trim();
        String gender = genderView.getText().toString().trim();
        String address = addressView.getText().toString().trim();
        String city = cityView.getText().toString().trim();
        String state = stateView.getText().toString().trim();
        String pin = pinView.getText().toString().replaceAll("\\D", "");
        String emergency = emergencyView.getText().toString().replaceAll("\\D", "");
        String experience = experienceView.getText().toString().replaceAll("\\D", "");
        String areas = areasView.getText().toString().trim();
        String languages = languagesView.getText().toString().trim();
        if ("Register".equalsIgnoreCase(authMode)) {
            if (TextUtils.isEmpty(address)) {
                address = savedOrGeneratedAddress(city, state, pin);
            }
            if (TextUtils.isEmpty(address)) {
                address = "Guwahati, Assam - " + (TextUtils.isEmpty(pin) ? "781001" : pin);
            }
            if (TextUtils.isEmpty(emergency)) {
                emergency = partnerPhone;
            }
            if (TextUtils.isEmpty(experience)) {
                experience = "0";
            }
            if (TextUtils.isEmpty(areas)) {
                areas = serviceAreaLabel();
            }
            if (TextUtils.isEmpty(languages)) {
                languages = "Hindi, English";
            }
        }
        if ("Register".equalsIgnoreCase(authMode)) {
            if (TextUtils.isEmpty(dob) || TextUtils.isEmpty(gender) || TextUtils.isEmpty(address) || TextUtils.isEmpty(city) || TextUtils.isEmpty(state) || pin.length() != 6 || !isValidIndianPhone(emergency) || TextUtils.isEmpty(experience) || TextUtils.isEmpty(areas) || TextUtils.isEmpty(languages)) {
                Toast.makeText(this, "Complete professional profile details required", Toast.LENGTH_LONG).show();
                return;
            }
        }
        if (selectedSkills == null || selectedSkills.isEmpty()) {
            Toast.makeText(this, "At least one service required", Toast.LENGTH_SHORT).show();
            return;
        }
        if ("Register".equalsIgnoreCase(authMode) && authPhotoUri == null) {
            Toast.makeText(this, "Take a profile photo before registration", Toast.LENGTH_SHORT).show();
            return;
        }
        if ("Register".equalsIgnoreCase(authMode) && missingRequiredRegistrationDocuments()) {
            Toast.makeText(this, "Upload at least one identity document before registration.", Toast.LENGTH_LONG).show();
            return;
        }
        String photo = authPhotoUri == null ? "" : authPhotoUri.toString();
        JSONObject profile = new JSONObject();
        try {
            profile.put("dateOfBirth", dob);
            profile.put("gender", gender);
            profile.put("residentialAddress", address);
            profile.put("city", TextUtils.isEmpty(city) ? "Guwahati" : city);
            profile.put("state", TextUtils.isEmpty(state) ? "Assam" : state);
            profile.put("pinCode", pin);
            profile.put("emergencyContactNumber", emergency);
            profile.put("yearsOfExperience", TextUtils.isEmpty(experience) ? 0 : Integer.parseInt(experience));
            profile.put("workingAreas", areas);
            profile.put("languagesKnown", languages);
            if ("Register".equalsIgnoreCase(authMode)) addRegistrationTermsToProfile(profile);
        } catch (Exception ignored) {
        }
        finishPartnerLogin(partnerName, partnerPhone, email, photo, profile);
    }

    private void finishPartnerLogin(String partnerName, String partnerPhone, String partnerEmail, String photoUri) {
        finishPartnerLogin(partnerName, partnerPhone, partnerEmail, photoUri, null);
    }

    private void finishPartnerLogin(String partnerName, String partnerPhone, String partnerEmail, String photoUri, JSONObject profile) {
        if (selectedSkills == null || selectedSkills.isEmpty()) {
            selectedSkills = skillsFromPrefs();
        }
        if (backendClient == null) {
            setLaundryRegistrationSubmitting(false);
            Toast.makeText(this, "Partner service is still starting. Please try again.", Toast.LENGTH_LONG).show();
            return;
        }
        Toast.makeText(this, "Saving partner profile...", Toast.LENGTH_SHORT).show();
        String backendPhoto = networkSafeImageUrl(photoUri) ? photoUri : "";
        double regLat = Double.NaN, regLng = Double.NaN;
        if (lastTrustedLocation != null) {
            regLat = lastTrustedLocation.getLatitude();
            regLng = lastTrustedLocation.getLongitude();
        }
        backendClient.upsertPartnerProfile(
                partnerName,
                partnerPhone,
                partnerEmail,
                selectedSkills,
                online,
                serviceRadiusKm(),
                serviceAreaLabel(),
                fcmToken(),
                backendPhoto,
                profile,
                regLat,
                regLng,
                new BackendClient.JsonCallback() {
                    @Override
                    public void onSuccess(JSONObject object) {
                        JSONObject partnerObject = object.optJSONObject("partner");
                        updateApprovalFromPartner(partnerObject);
                        // Optimistic navigation: the authoritative pending status is visible
                        // immediately while media synchronizes in the background.
                        persistPartnerSessionAndEnter(partnerName, partnerPhone, partnerEmail, photoUri, profile);
                        uploadProfilePhotoAfterProfileSave(photoUri, partnerObject, () ->
                                uploadRegistrationDocumentsAfterProfileSave((documentsUploaded, failedTitle, uploadError) -> {
                                    if (!documentsUploaded) {
                                        String detail = TextUtils.isEmpty(uploadError)
                                                ? "Choose a valid JPG, PNG, or PDF up to 5 MB, then retry."
                                                : safeUserError(uploadError);
                                        Toast.makeText(MainActivity.this,
                                                failedTitle + " upload failed. " + detail,
                                                Toast.LENGTH_LONG).show();
                                    }
                                    refreshPartnerApprovalStatus();
                                }));
                    }

                    @Override
                    public void onError(String message) {
                        setLaundryRegistrationSubmitting(false);
                        Toast.makeText(MainActivity.this, "Partner registration failed: " + safeUserError(message), Toast.LENGTH_LONG).show();
                    }
                }
        );
    }

    private void uploadProfilePhotoAfterProfileSave(String photoUri, JSONObject partnerObject, Runnable done) {
        if (backendClient == null || TextUtils.isEmpty(photoUri) || networkSafeImageUrl(photoUri)) {
            done.run();
            return;
        }
        Uri uri = Uri.parse(photoUri);
        File file = fileFromLocalUri(uri);
        if (file == null || !file.exists()) {
            done.run();
            return;
        }
        backendClient.uploadPartnerProfilePhoto(file, new BackendClient.JsonCallback() {
            @Override
            public void onSuccess(JSONObject object) {
                if (partnerObject != null) {
                    try {
                        partnerObject.put("photoUrl", object.optString("photoUrl", ""));
                    } catch (Exception ignored) {
                    }
                }
                done.run();
            }

            @Override
            public void onError(String message) {
                Toast.makeText(MainActivity.this, "Profile photo upload pending. Try again if admin cannot see it.", Toast.LENGTH_LONG).show();
                done.run();
            }
        });
    }

    private void uploadRegistrationDocumentsAfterProfileSave(RegistrationUploadCallback done) {
        if (!"Register".equalsIgnoreCase(authMode)) {
            done.onComplete(true, "", "");
            return;
        }
        uploadRegistrationDocumentAtIndex(0, done);
    }

    private void uploadRegistrationDocumentAtIndex(int index, RegistrationUploadCallback done) {
        String[] registrationDocuments = registrationUploadDocumentTitles();
        if (index >= registrationDocuments.length) {
            done.onComplete(true, "", "");
            return;
        }
        String title = registrationDocuments[index];
        String uriText = prefs.getString(documentPrefKey(title), "");
        if (TextUtils.isEmpty(uriText)) {
            uploadRegistrationDocumentAtIndex(index + 1, done);
            return;
        }
        uploadDocumentForRegistration(
                title,
                Uri.parse(uriText),
                prefs.getString(documentPrefKey(title) + "_aadhaar_last4", ""),
                (success, errorMessage) -> {
                    if (!success) {
                        done.onComplete(false, title, errorMessage);
                        return;
                    }
                    uploadRegistrationDocumentAtIndex(index + 1, done);
                }
        );
    }

    private String[] registrationUploadDocumentTitles() {
        if (prefs.getBoolean(KEY_LAUNDRY_REGISTRATION, false)) {
            List<String> laundryTitles = new ArrayList<>();
            laundryTitles.add("Laundry Shop License");
            try {
                JSONArray staff = new JSONArray(prefs.getString(KEY_LAUNDRY_STAFF_JSON, "[]"));
                for (int index = 0; index < staff.length(); index++) {
                    int sequence = staff.optJSONObject(index) == null ? index + 1
                            : staff.optJSONObject(index).optInt("sequence", index + 1);
                    laundryTitles.add("Laundry Staff " + sequence + " Profile Picture");
                    laundryTitles.add("Laundry Staff " + sequence + " ID Proof");
                }
            } catch (Exception ignored) {
            }
            return laundryTitles.toArray(new String[0]);
        }
        List<String> titles = new ArrayList<>(Arrays.asList(
                "Identity Document",
                "Aadhaar Card Front",
                "Aadhaar Card Back",
                "PAN Card",
                "Selfie Verification",
                "Other Supporting Document",
                "Experience Certificate",
                "Skill Certificate",
                "Training Certificate",
                "Government License",
                "Trade License"
        ));
        return titles.toArray(new String[0]);
    }

    private boolean missingRequiredRegistrationDocuments() {
        if ("Register".equalsIgnoreCase(authMode)) {
            for (String title : registrationUploadDocumentTitles()) {
                if (!TextUtils.isEmpty(prefs.getString(documentPrefKey(title), ""))) {
                    return false;
                }
            }
            return true;
        }
        for (String title : REQUIRED_REGISTRATION_DOCUMENTS) {
            if (TextUtils.isEmpty(prefs.getString(documentPrefKey(title), ""))) {
                return true;
            }
        }
        return false;
    }

    private File fileFromLocalUri(Uri uri) {
        if (uri == null) {
            return null;
        }
        if ("file".equalsIgnoreCase(uri.getScheme()) || TextUtils.isEmpty(uri.getScheme())) {
            return new File(uri.getPath());
        }
        return null;
    }

    private void persistPartnerSessionAndEnter(String partnerName, String partnerPhone, String partnerEmail, String photoUri) {
        persistPartnerSessionAndEnter(partnerName, partnerPhone, partnerEmail, photoUri, null);
    }

    private void persistPartnerSessionAndEnter(String partnerName, String partnerPhone, String partnerEmail, String photoUri, JSONObject profile) {
        SharedPreferences.Editor editor = prefs.edit()
                .putBoolean(KEY_LOGGED_IN, true)
                .putString(KEY_NAME, TextUtils.isEmpty(partnerName) ? "ApnaServo Partner" : partnerName)
                .putString(KEY_PHONE, partnerPhone == null ? "" : partnerPhone)
                .putString(KEY_EMAIL, partnerEmail == null ? "" : partnerEmail)
                .putString(KEY_SKILL, skillsCsv(selectedSkills))
                .putString(KEY_SERVICE_ID, ServiceRouting.canonicalServiceId(firstPartnerSkill()))
                .putString(KEY_PHOTO, photoUri == null ? "" : photoUri);
        if (profile != null) {
            editor
                    .putString(KEY_DOB, profile.optString("dateOfBirth", ""))
                    .putString(KEY_GENDER, profile.optString("gender", ""))
                    .putString(KEY_ADDRESS, profile.optString("residentialAddress", ""))
                    .putString(KEY_CITY, profile.optString("city", "Guwahati"))
                    .putString(KEY_STATE, profile.optString("state", "Assam"))
                    .putString(KEY_PIN_CODE, profile.optString("pinCode", ""))
                    .putString(KEY_EMERGENCY_PHONE, profile.optString("emergencyContactNumber", ""))
                    .putString(KEY_EXPERIENCE_YEARS, profile.optString("yearsOfExperience", ""))
                    .putString(KEY_WORKING_AREAS, profile.optString("workingAreas", ""))
                    .putString(KEY_LANGUAGES, profile.optString("languagesKnown", ""));
        }
        editor.apply();
        pendingGoogleName = "";
        pendingGoogleEmail = "";
        pendingGooglePhoto = "";
        if (isPartnerApproved()) {
            setContentView(appShell());
            showDashboard();
            showApprovalPopupIfNeeded();
        } else {
            setContentView(verificationStatusScreen());
        }
        refreshHandler.postDelayed(this::startPartnerBackgroundSync, 120);
        refreshHandler.postDelayed(this::applyPendingPartnerDeepLink, 400);
    }

    private boolean isValidPartnerName(String value) {
        return value != null && PARTNER_NAME_PATTERN.matcher(value.trim()).matches();
    }

    private boolean isValidIndianPhone(String value) {
        return value != null && PHONE_PATTERN.matcher(value.trim()).matches();
    }

    private boolean isValidEmail(String value) {
        return value != null && EMAIL_PATTERN.matcher(value.trim()).matches();
    }

    private boolean isGoogleSignedInPartner() {
        return firebaseAuth != null
                && firebaseAuth.getCurrentUser() != null
                && !firebaseAuth.getCurrentUser().isAnonymous()
                && !TextUtils.isEmpty(pendingGoogleEmail);
    }

    private boolean networkSafeImageUrl(String value) {
        return value != null && (value.startsWith("https://") || value.startsWith("http://"));
    }

    private String otpUserError(String message) {
        if (message == null || message.trim().isEmpty()) {
            return "OTP verification failed. Please try again.";
        }
        String normalized = message.toLowerCase(Locale.US);
        if (normalized.contains("route not found") || normalized.contains("/otp/send") || normalized.contains("/otp/verify")) {
            return "OTP service is not deployed yet. Please redeploy the backend and try again.";
        }
        if (normalized.contains("authenticationfailure") || normalized.contains("authentication failure")
                || normalized.contains("unauthorized") || message.contains("401") || message.contains("403")) {
            return "MSG91 rejected the OTP Widget credential. Copy this widget's Token into MSG91_TOKEN_AUTH on Render, then redeploy.";
        }
        if (normalized.contains("otp provider is not configured")) {
            return "OTP service is not configured. Set MSG91_WIDGET_ID and MSG91_TOKEN_AUTH on the backend, then redeploy.";
        }
        if (normalized.contains("invalid request") || normalized.contains("msg91")
                || normalized.contains("authkey") || normalized.contains("widget") || normalized.contains("provider")) {
            return "OTP provider rejected the request. Check MSG91 auth key, widget ID, and mobile integration settings.";
        }
        if (normalized.contains("invalid otp") || normalized.contains("invalid verification") || normalized.contains("incorrect otp")) {
            return "Invalid OTP. Please check the code and try again.";
        }
        if (normalized.contains("otp expired") || normalized.contains("expired otp")) {
            return "OTP expired. Please request a new OTP.";
        }
        if (normalized.contains("firebase") || normalized.contains("custom token") || normalized.contains("session was not created")) {
            return "OTP verified, but Firebase login could not be completed. Check FIREBASE_PROJECT_ID and FIREBASE_SERVICE_ACCOUNT_JSON on the backend.";
        }
        if (normalized.contains("timeout") || normalized.contains("timed out")
                || normalized.contains("network temporarily unavailable") || normalized.contains("failed to connect")) {
            return "Server is waking up or the connection is slow. Please try again.";
        }
        return message.length() > 140 ? message.substring(0, 140) : message;
    }

    private String safeUserError(String message) {
        if (message == null) {
            return "Please try again";
        }
        if (message.contains("409")) {
            return "This phone/email is already registered";
        }
        if (message.contains("401") || message.toLowerCase(Locale.US).contains("auth_session_missing")) {
            return "Login session expired. Please reopen the app and sign in again.";
        }
        String normalized = message.toLowerCase(Locale.US);
        if (message.contains("422")) {
            int separator = message.indexOf(':');
            String reason = separator >= 0 && separator + 1 < message.length()
                    ? message.substring(separator + 1).trim()
                    : "Location verification failed. Refresh GPS and try again.";
            if (!TextUtils.isEmpty(reason) && !"Request failed.".equalsIgnoreCase(reason)) {
                return reason;
            }
            return "Location verification failed. Refresh GPS and try again.";
        }
        if (normalized.contains("timeout")
                || normalized.contains("timed out")
                || normalized.contains("network temporarily unavailable")
                || normalized.contains("failed to connect")) {
            return "Server is waking up or the connection is slow. Please try again.";
        }
        if (message.length() > 120) {
            return message.substring(0, 120);
        }
        return message;
    }

    private GoogleSignInClient buildGoogleSignInClient() {
        String webClientId = googleWebClientId();
        GoogleSignInOptions.Builder builder = new GoogleSignInOptions.Builder(GoogleSignInOptions.DEFAULT_SIGN_IN)
                .requestEmail()
                .requestProfile();
        if (!TextUtils.isEmpty(webClientId)) {
            builder.requestIdToken(webClientId);
        }
        return GoogleSignIn.getClient(this, builder.build());
    }

    private String googleWebClientId() {
        // Direct reference keeps the generated Google Services value reachable in
        // minified/resource-shrunk release builds. Dynamic getIdentifier() lookup
        // can be removed by the shrinker and previously showed a false setup error.
        return getString(R.string.default_web_client_id).trim();
    }

    private void startGoogleSignIn(boolean registrationRequested) {
        googleRegistrationRequested = registrationRequested;
        if (googleSignInClient == null) {
            googleSignInClient = buildGoogleSignInClient();
        }
        if (TextUtils.isEmpty(googleWebClientId())) {
            googleRegistrationRequested = false;
            showSupportInfoDialog("Google Sign-In Setup",
                    "Enable the Google sign-in provider in Firebase, add SHA-1/SHA-256 fingerprints, and replace the partner app google-services.json.");
            return;
        }
        googleSignInClient.signOut().addOnCompleteListener(task ->
                startActivityForResult(googleSignInClient.getSignInIntent(), GOOGLE_SIGN_IN_REQUEST));
    }

    private void firebaseAuthWithGoogle(GoogleSignInAccount account) {
        if (account == null || TextUtils.isEmpty(account.getIdToken())) {
            Toast.makeText(this, "Google account token missing", Toast.LENGTH_SHORT).show();
            return;
        }
        AuthCredential credential = GoogleAuthProvider.getCredential(account.getIdToken(), null);
        firebaseAuth.signInWithCredential(credential)
                .addOnSuccessListener(result -> {
                    String displayName = account.getDisplayName();
                    if (TextUtils.isEmpty(displayName)) {
                        displayName = account.getEmail();
                    }
                    String email = account.getEmail() == null ? "" : account.getEmail();
                    String photo = account.getPhotoUrl() == null ? "" : account.getPhotoUrl().toString();
                    handleGooglePartnerProfile(TextUtils.isEmpty(displayName) ? "ApnaServo Partner" : displayName, email, photo);
                })
                .addOnFailureListener(error -> {
                    googleRegistrationRequested = false;
                    String message = error == null ? "" : error.getMessage();
                    showSupportInfoDialog(
                            "Google Sign-In Failed",
                            TextUtils.isEmpty(message)
                                    ? "Google authentication could not be completed. Check the internet connection and try again."
                                    : safeUserError(message)
                    );
                });
    }

    private void showGoogleSignInError(ApiException error) {
        int statusCode = error == null ? -1 : error.getStatusCode();
        if (statusCode == 12501) {
            googleRegistrationRequested = false;
            Toast.makeText(this, "Google sign-in cancelled", Toast.LENGTH_SHORT).show();
            return;
        }
        if (statusCode == 10) {
            showSupportInfoDialog(
                    "Google Sign-In Configuration",
                    "This app build is not registered in Firebase. Add this build's SHA-1 and SHA-256 fingerprints, download the updated google-services.json, and rebuild the partner app."
            );
            return;
        }
        if (statusCode == 7) {
            Toast.makeText(this, "Google sign-in needs an internet connection", Toast.LENGTH_LONG).show();
            return;
        }
        showSupportInfoDialog(
                "Google Sign-In Failed",
                "Google returned error " + statusCode + ". Please try again or choose a different Google account."
        );
    }

    private void handleGooglePartnerProfile(String displayName, String email, String photo) {
        pendingGoogleName = displayName;
        pendingGoogleEmail = email == null ? "" : email;
        pendingGooglePhoto = photo == null ? "" : photo;
        if (backendClient == null) {
            if (googleRegistrationRequested) {
                googleRegistrationRequested = false;
                Toast.makeText(this, "Complete registration to continue", Toast.LENGTH_SHORT).show();
                showAuthForm("Register");
            } else {
                showSupportInfoDialog("Partner Service Unavailable", "The partner service is still starting. Please try signing in again.");
            }
            return;
        }
        // A verified Google email can belong either to a company owner or to
        // staff invited by that owner. The staff session endpoint resolves the
        // invitation first and startAuthenticatedStaffLookup falls back to the
        // regular owner profile when no staff invitation exists.
        if (!googleRegistrationRequested) {
            startAuthenticatedStaffLookup();
            return;
        }
        backendClient.fetchPartnerProfile(new BackendClient.JsonCallback() {
            @Override
            public void onSuccess(JSONObject object) {
                JSONObject partner = object.optJSONObject("partner");
                if (isRegisteredPartnerProfile(partner)) {
                    googleRegistrationRequested = false;
                    completeExistingGooglePartner(partner);
                    Toast.makeText(MainActivity.this, "Google sign-in successful", Toast.LENGTH_SHORT).show();
                } else if (googleRegistrationRequested) {
                    googleRegistrationRequested = false;
                    Toast.makeText(MainActivity.this, "Google account verified. Complete your partner registration.", Toast.LENGTH_SHORT).show();
                    showAuthForm("Register");
                } else {
                    googleRegistrationRequested = false;
                    showSupportInfoDialog(
                            "Partner Account Not Found",
                            "No approved or submitted partner profile is linked to this Google account. Tap Register as Partner to create one."
                    );
                }
            }

            @Override
            public void onError(String message) {
                googleRegistrationRequested = false;
                showSupportInfoDialog(
                        "Unable to Check Partner Account",
                        safeUserError(message) + " Your account was not changed. Please retry Google sign-in."
                );
            }
        });
    }

    private boolean isRegisteredPartnerProfile(JSONObject partner) {
        if (partner == null) {
            return false;
        }
        boolean hasIdentity = !TextUtils.isEmpty(partner.optString("phone", ""))
                || !TextUtils.isEmpty(partner.optString("email", ""));
        JSONArray categories = partner.optJSONArray("serviceCategory");
        boolean hasServices = categories != null && categories.length() > 0;
        return hasIdentity && hasServices;
    }

    private void completeExistingGooglePartner(JSONObject partner) {
        Set<String> services = categoriesFromPartnerJson(partner.optJSONArray("serviceCategory"));
        if (!services.isEmpty()) {
            selectedSkills = services;
            selectedSkill = firstPartnerSkill();
        }
        String name = partner.optString("name", pendingGoogleName);
        String phone = partner.optString("phone", partnerPhone());
        String email = partner.optString("email", pendingGoogleEmail);
        String photo = partner.optString("photoUrl", pendingGooglePhoto);
        finishPartnerLogin(name, phone, email, photo);
    }

    private Set<String> categoriesFromPartnerJson(JSONArray array) {
        Set<String> services = new LinkedHashSet<>();
        if (array == null) {
            return services;
        }
        for (int i = 0; i < array.length(); i++) {
            String normalized = normalizeSkill(array.optString(i, ""));
            if (!TextUtils.isEmpty(normalized)) {
                services.add(normalized);
                // Company and staff accounts are single-service. Old cached
                // multi-service values are normalized by the backend as well.
                break;
            }
        }
        return services;
    }

