    private Uri saveCameraBitmap(Bitmap bitmap) {
        try {
            File file = new File(getFilesDir(), "partner_photo.jpg");
            writeCompressedProfilePhoto(bitmap, file);
            return Uri.fromFile(file);
        } catch (Exception exception) {
            Toast.makeText(this, "Could not save verification thumbnail", Toast.LENGTH_SHORT).show();
            return null;
        }
    }

    private void writeCompressedProfilePhoto(Bitmap bitmap, File file) throws Exception {
        Bitmap source = bitmap;
        int maxSide = 1200;
        int largestSide = Math.max(bitmap.getWidth(), bitmap.getHeight());
        if (largestSide > maxSide) {
            float scale = maxSide / (float) largestSide;
            int width = Math.max(1, Math.round(bitmap.getWidth() * scale));
            int height = Math.max(1, Math.round(bitmap.getHeight() * scale));
            source = Bitmap.createScaledBitmap(bitmap, width, height, true);
        }

        int quality = 86;
        byte[] encoded = encodeJpeg(source, quality);
        while (encoded.length > 700 * 1024 && quality > 58) {
            quality -= 7;
            encoded = encodeJpeg(source, quality);
        }
        try (FileOutputStream output = new FileOutputStream(file)) {
            output.write(encoded);
        }
        if (source != bitmap) {
            source.recycle();
        }
    }

    private void pickDocumentFile(String title) {
        pendingDocumentUploadTitle = title;
        Intent intent = new Intent(Intent.ACTION_OPEN_DOCUMENT);
        intent.addCategory(Intent.CATEGORY_OPENABLE);
        intent.setType("*/*");
        intent.putExtra(Intent.EXTRA_MIME_TYPES, new String[]{"image/*", "application/pdf"});
        startActivityForResult(intent, REQ_DOC_FILE);
    }

    private void openDocumentCamera(String title) {
        pendingDocumentUploadTitle = title;
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M
                && checkSelfPermission(Manifest.permission.CAMERA) != PackageManager.PERMISSION_GRANTED) {
            requestPermissions(new String[]{Manifest.permission.CAMERA}, DOCUMENT_CAMERA_PERMISSION_REQUEST);
            return;
        }
        launchDocumentCameraIntent();
    }

    private void launchDocumentCameraIntent() {
        Intent intent = new Intent(MediaStore.ACTION_IMAGE_CAPTURE);
        if (intent.resolveActivity(getPackageManager()) == null) {
            Toast.makeText(this, "No camera app is available.", Toast.LENGTH_LONG).show();
            return;
        }
        try {
            startActivityForResult(intent, REQ_DOC_CAMERA);
        } catch (Exception exception) {
            Toast.makeText(this, "Unable to open the camera.", Toast.LENGTH_LONG).show();
        }
    }

    private Uri copyDocumentFileToInternalStorage(String title, Uri source) {
        File file = null;
        try {
            String originalName = documentSourceDisplayName(source);
            String extension = documentFileExtension(source, originalName);
            long declaredSize = documentSourceSize(source);
            if (declaredSize > MAX_DOCUMENT_BYTES) {
                Toast.makeText(this, "Your document size is above 5 MB. Please choose a smaller file.", Toast.LENGTH_LONG).show();
                return null;
            }
            file = new File(getFilesDir(), documentFileName(title, "upload") + extension);
            try (InputStream input = getContentResolver().openInputStream(source);
                 OutputStream output = new FileOutputStream(file)) {
                if (input == null) {
                    throw new IllegalStateException("Document unavailable");
                }
                byte[] buffer = new byte[8192];
                int read;
                while ((read = input.read(buffer)) != -1) {
                    output.write(buffer, 0, read);
                    if (file.length() > MAX_DOCUMENT_BYTES) {
                        throw new IllegalArgumentException("Your document size is above 5 MB. Please choose a smaller file.");
                    }
                }
            }
            if (!isUploadableDocumentImage(file)) {
                file.delete();
                Toast.makeText(this, "Choose a valid JPG, PNG or PDF file up to 5 MB.", Toast.LENGTH_LONG).show();
                return null;
            }
            prefs.edit()
                    .putString(documentPrefKey(title) + "_name", TextUtils.isEmpty(originalName) ? file.getName() : originalName)
                    .putLong(documentPrefKey(title) + "_size", file.length())
                    .apply();
            return Uri.fromFile(file);
        } catch (Exception exception) {
            if (file != null && file.exists()) file.delete();
            Toast.makeText(this, exception instanceof IllegalArgumentException
                    ? exception.getMessage()
                    : "Unable to read this document. Choose another file.", Toast.LENGTH_LONG).show();
            return null;
        }
    }

    private String documentFileExtension(Uri source) {
        return documentFileExtension(source, documentSourceDisplayName(source));
    }

    private String documentFileExtension(Uri source, String displayName) {
        String mimeType = "";
        try {
            mimeType = getContentResolver().getType(source);
        } catch (Exception ignored) {
        }
        if ("application/pdf".equalsIgnoreCase(mimeType) || "application/x-pdf".equalsIgnoreCase(mimeType)) {
            return ".pdf";
        }
        if ("image/png".equalsIgnoreCase(mimeType)) {
            return ".png";
        }
        String lowerName = displayName == null ? "" : displayName.toLowerCase(Locale.US);
        if (lowerName.endsWith(".pdf")) return ".pdf";
        if (lowerName.endsWith(".png")) return ".png";
        if (lowerName.endsWith(".jpeg")) return ".jpeg";
        return ".jpg";
    }

    private String documentSourceDisplayName(Uri source) {
        if (source == null) return "";
        if ("content".equalsIgnoreCase(source.getScheme())) {
            try (Cursor cursor = getContentResolver().query(source, new String[]{OpenableColumns.DISPLAY_NAME}, null, null, null)) {
                if (cursor != null && cursor.moveToFirst()) {
                    int index = cursor.getColumnIndex(OpenableColumns.DISPLAY_NAME);
                    if (index >= 0) return cursor.getString(index);
                }
            } catch (Exception ignored) {
            }
        }
        return source.getLastPathSegment() == null ? "document" : source.getLastPathSegment();
    }

    private long documentSourceSize(Uri source) {
        if (source == null || !"content".equalsIgnoreCase(source.getScheme())) return -1L;
        try (Cursor cursor = getContentResolver().query(source, new String[]{OpenableColumns.SIZE}, null, null, null)) {
            if (cursor != null && cursor.moveToFirst()) {
                int index = cursor.getColumnIndex(OpenableColumns.SIZE);
                if (index >= 0 && !cursor.isNull(index)) return cursor.getLong(index);
            }
        } catch (Exception ignored) {
        }
        return -1L;
    }

    private Uri saveDocumentCameraBitmap(String title, Bitmap bitmap) {
        try {
            File file = new File(getFilesDir(), documentFileName(title, "camera") + ".jpg");
            writeCompressedDocumentBitmap(bitmap, file);
            prefs.edit()
                    .putString(documentPrefKey(title) + "_name", title.replaceAll("[^A-Za-z0-9]+", "_") + ".jpg")
                    .putLong(documentPrefKey(title) + "_size", file.length())
                    .apply();
            return Uri.fromFile(file);
        } catch (Exception exception) {
            Toast.makeText(this, "Unable to save the camera document.", Toast.LENGTH_SHORT).show();
            return null;
        }
    }

    private void writeCompressedDocumentBitmap(Bitmap bitmap, File file) throws Exception {
        Bitmap source = bitmap;
        int maxSide = 1600;
        int largestSide = Math.max(bitmap.getWidth(), bitmap.getHeight());
        if (largestSide > maxSide) {
            float scale = maxSide / (float) largestSide;
            int width = Math.max(1, Math.round(bitmap.getWidth() * scale));
            int height = Math.max(1, Math.round(bitmap.getHeight() * scale));
            source = Bitmap.createScaledBitmap(bitmap, width, height, true);
        }

        int quality = 82;
        byte[] encoded = encodeJpeg(source, quality);
        while (encoded.length > 900 * 1024 && quality > 62) {
            quality -= 6;
            encoded = encodeJpeg(source, quality);
        }
        try (FileOutputStream output = new FileOutputStream(file)) {
            output.write(encoded);
        }
        if (source != bitmap) {
            source.recycle();
        }
    }

    private byte[] encodeJpeg(Bitmap bitmap, int quality) {
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        bitmap.compress(Bitmap.CompressFormat.JPEG, quality, output);
        return output.toByteArray();
    }

    private String documentFileName(String title, String source) {
        return KEY_DOC_PREFIX + documentSlug(title) + "_" + source + "_" + System.currentTimeMillis();
    }

    private String documentSlug(String title) {
        String value = title == null ? "document" : title.toLowerCase(Locale.US).replaceAll("[^a-z0-9]+", "_");
        value = value.replaceAll("^_+|_+$", "");
        return TextUtils.isEmpty(value) ? "document" : value;
    }

    private String documentPrefKey(String title) {
        return KEY_DOC_PREFIX + documentSlug(title);
    }

    private void persistDocumentUpload(String title, Uri uri) {
        if (uri == null || TextUtils.isEmpty(title)) {
            return;
        }
        showDocumentPreviewBeforeSubmit(title, uri);
        pendingDocumentUploadTitle = "";
    }

    private void showDocumentPreviewBeforeSubmit(String title, Uri uri) {
        AlertDialog dialog = new AlertDialog.Builder(this).create();
        LinearLayout sheet = vertical();
        sheet.setPadding(dp(18), dp(18), dp(18), dp(16));
        sheet.setBackground(stroke(Color.WHITE, Color.rgb(250, 216, 225), dp(22)));
        sheet.addView(text("Preview " + title, 18, BLACK, true), margin(-1, -2, 0, 0, 0, 12));
        File previewFile = fileFromDocumentUri(title, uri);
        boolean pdf = previewFile != null && previewFile.getName().toLowerCase(Locale.US).endsWith(".pdf");
        if (pdf) {
            TextView pdfPreview = text("PDF\n" + registrationDocumentDisplayName(title), 14, ROSE, true);
            pdfPreview.setGravity(Gravity.CENTER);
            pdfPreview.setBackground(stroke(Color.rgb(255, 247, 249), Color.rgb(248, 226, 232), dp(14)));
            sheet.addView(pdfPreview, margin(-1, 150, 0, 0, 0, 14));
        } else {
            ImageView preview = new ImageView(this);
            preview.setScaleType(ImageView.ScaleType.CENTER_CROP);
            setImageUriSafely(preview, uri);
            preview.setBackground(round(Color.rgb(255, 247, 249), dp(14)));
            sheet.addView(preview, margin(-1, 220, 0, 0, 0, 14));
        }
        LinearLayout actions = horizontal();
        TextView retake = outlineButton("Retake");
        retake.setOnClickListener(view -> {
            dialog.dismiss();
            openDocumentCamera(title);
        });
        actions.addView(retake, new LinearLayout.LayoutParams(0, dp(48), 1));
        TextView submit = roseButton("Submit");
        submit.setOnClickListener(view -> {
            dialog.dismiss();
            submitDocumentVerification(title, uri);
        });
        LinearLayout.LayoutParams submitParams = new LinearLayout.LayoutParams(0, dp(48), 1);
        submitParams.setMargins(dp(10), 0, 0, 0);
        actions.addView(submit, submitParams);
        sheet.addView(actions);
        dialog.setView(sheet);
        dialog.setOnShowListener(d -> {
            Window window = dialog.getWindow();
            if (window != null) {
                window.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));
            }
        });
        showDialogSafely(dialog);
    }

    private void submitDocumentVerification(String title, Uri uri) {
        if (TextUtils.isEmpty(title) || uri == null) {
            return;
        }
        if (isRegistrationDocumentSelectionMode() && "Identity Document".equalsIgnoreCase(title)) {
            saveDocumentUploadState(title, uri, "Selected");
            Toast.makeText(this, "Document selected. It will be uploaded securely on submission.", Toast.LENGTH_SHORT).show();
            return;
        }
        String lower = title.toLowerCase(Locale.US);
        if (lower.contains("aadhaar")) {
            showAadhaarLast4Dialog(title, uri);
            return;
        }
        if (isRegistrationDocumentSelectionMode()) {
            saveDocumentUploadState(title, uri, "Selected");
            Toast.makeText(this, "Document selected. It will be uploaded securely on submission.", Toast.LENGTH_SHORT).show();
            return;
        }
        if (backendClient == null) {
            Toast.makeText(this, "Document service is temporarily unavailable. Please try again.", Toast.LENGTH_LONG).show();
            return;
        }
        uploadDocumentForValidation(title, uri, "");
    }

    private boolean isRegistrationDocumentSelectionMode() {
        return "Register".equalsIgnoreCase(authMode) && !prefs.getBoolean(KEY_LOGGED_IN, false);
    }

    private void uploadDocumentForValidation(String title, Uri uri, String aadhaarLast4) {
        File file = fileFromDocumentUri(uri);
        if (file == null || !file.exists()) {
            Toast.makeText(this, "Document file missing. Retake photo.", Toast.LENGTH_SHORT).show();
            return;
        }
        if (!isUploadableDocumentImage(file)) {
            Toast.makeText(this, "Clear JPG/PNG photo required. Retake document photo.", Toast.LENGTH_LONG).show();
            return;
        }
        String documentType = documentTypeForTitle(title);
        long originalSize = file.length();
        Toast.makeText(this, "Checking document clarity...", Toast.LENGTH_SHORT).show();
        backendClient.uploadPartnerDocument(documentType, file, aadhaarLast4, true, originalSize, new BackendClient.JsonCallback() {
            @Override
            public void onSuccess(JSONObject object) {
                JSONObject document = object.optJSONObject("document");
                String status = document == null ? "Review" : document.optString("validationStatus", "review");
                saveDocumentUploadState(title, uri, "accepted".equals(status) ? "Uploaded" : "Review");
                Toast.makeText(MainActivity.this, "Document accepted for verification", Toast.LENGTH_SHORT).show();
                if (currentNavState != null && "documents".equals(currentNavState.screen)) {
                    showDocumentsTool();
                }
            }

            @Override
            public void onError(String message) {
                String userMessage = message != null && message.contains("422")
                        ? "The document is unclear. Upload a clear JPG, PNG, or PDF file."
                        : "Document upload failed. Try again.";
                Toast.makeText(MainActivity.this, userMessage, Toast.LENGTH_LONG).show();
            }
        });
    }

    private void uploadDocumentForRegistration(String title, Uri uri, String aadhaarLast4, DocumentUploadCallback done) {
        File file = fileFromDocumentUri(title, uri);
        if (file == null || !file.exists() || !isUploadableDocumentImage(file)) {
            saveDocumentUploadState(title, uri, "Upload pending");
            done.onComplete(false, "Select a valid JPG, PNG, or PDF file up to 5 MB.");
            return;
        }
        backendClient.uploadPartnerDocument(documentTypeForTitle(title), file, aadhaarLast4, true, file.length(), new BackendClient.JsonCallback() {
            @Override
            public void onSuccess(JSONObject object) {
                JSONObject document = object.optJSONObject("document");
                String status = document == null ? "review" : document.optString("validationStatus", "review");
                saveDocumentUploadState(title, uri, "accepted".equals(status) ? "Uploaded" : "Review");
                done.onComplete(true, "");
            }

            @Override
            public void onError(String message) {
                saveDocumentUploadState(title, uri, "Upload pending");
                done.onComplete(false, message == null ? "Document upload failed." : message);
            }
        });
    }

    private File fileFromDocumentUri(String title, Uri uri) {
        if (uri == null) return null;
        if ("file".equalsIgnoreCase(uri.getScheme()) || TextUtils.isEmpty(uri.getScheme())) {
            return new File(uri.getPath());
        }
        Uri copied = copyDocumentFileToInternalStorage(title, uri);
        return copied == null ? null : new File(copied.getPath());
    }

    private File fileFromDocumentUri(Uri uri) {
        if (uri == null) {
            return null;
        }
        if ("file".equalsIgnoreCase(uri.getScheme()) || TextUtils.isEmpty(uri.getScheme())) {
            return new File(uri.getPath());
        }
        Uri copied = copyDocumentFileToInternalStorage(pendingDocumentUploadTitle, uri);
        return copied == null ? null : new File(copied.getPath());
    }

    private boolean isUploadableDocumentImage(File file) {
        if (file == null || !file.exists()) {
            return false;
        }
        long size = file.length();
        if (size < MIN_DOCUMENT_BYTES || size > MAX_DOCUMENT_BYTES) {
            return false;
        }
        try (InputStream input = new java.io.FileInputStream(file)) {
            byte[] header = new byte[12];
            int read = input.read(header);
            if (read < 8) {
                return false;
            }
            boolean jpeg = (header[0] & 0xff) == 0xff && (header[1] & 0xff) == 0xd8;
            boolean png = (header[0] & 0xff) == 0x89
                    && header[1] == 0x50
                    && header[2] == 0x4e
                    && header[3] == 0x47
                    && header[4] == 0x0d
                    && header[5] == 0x0a
                    && header[6] == 0x1a
                    && header[7] == 0x0a;
            boolean pdf = header[0] == 0x25
                    && header[1] == 0x50
                    && header[2] == 0x44
                    && header[3] == 0x46;
            return jpeg || png || pdf;
        } catch (Exception ignored) {
            return false;
        }
    }

    private String documentTypeForTitle(String title) {
        String value = title == null ? "" : title.toLowerCase(Locale.US);
        if (value.contains("laundry") && value.contains("shop")) return "laundry_shop_license";
        if (value.contains("laundry") && value.contains("staff")) {
            String sequence = value.replaceFirst("^.*?laundry\\s+staff\\s+(\\d+).*$", "$1");
            if (sequence.matches("\\d+") && value.contains("profile")) return "laundry_staff_" + sequence + "_profile";
            if (sequence.matches("\\d+")) return "laundry_staff_" + sequence + "_identity";
            return "laundry_staff_identity";
        }
        if (value.contains("aadhaar") && value.contains("front")) return "aadhaar_front";
        if (value.contains("identity document")) return "id_proof";
        if (value.contains("aadhaar") && value.contains("back")) return "aadhaar_back";
        if (value.contains("pan")) return "pan_card";
        if (value.contains("selfie") || value.contains("face")) return "selfie_photo";
        if (value.contains("experience")) return "experience_certificate";
        if (value.contains("skill")) return "skill_certificate";
        if (value.contains("training")) return "training_certificate";
        if (value.contains("government")) return "government_license";
        if (value.contains("trade")) return "trade_license";
        if (value.contains("address")) return "address_proof";
        return "other_supporting_document";
    }

    private void saveDocumentUploadState(String title, Uri uri, String status) {
        prefs.edit()
                .putString(documentPrefKey(title), uri.toString())
                .putString(documentPrefKey(title) + "_status", TextUtils.isEmpty(status) ? "Review" : status)
                .putLong(documentPrefKey(title) + "_updated", System.currentTimeMillis())
                .apply();
        updateLaundryDocumentSelection(title);
        refreshRegistrationDocumentsIfNeeded();
    }

    private String registrationDocumentDisplayName(String title) {
        String name = prefs.getString(documentPrefKey(title) + "_name", "");
        if (!TextUtils.isEmpty(name)) return name;
        String uriText = prefs.getString(documentPrefKey(title), "");
        if (!TextUtils.isEmpty(uriText)) {
            Uri uri = Uri.parse(uriText);
            String segment = uri.getLastPathSegment();
            if (!TextUtils.isEmpty(segment)) return segment;
        }
        return "Uploaded document";
    }

    private String registrationDocumentSizeLabel(String title) {
        long size = prefs.getLong(documentPrefKey(title) + "_size", 0L);
        if (size <= 0L) {
            File file = fileFromDocumentUri(title, Uri.parse(prefs.getString(documentPrefKey(title), "")));
            size = file == null ? 0L : file.length();
        }
        if (size >= 1024L * 1024L) return String.format(Locale.US, "%.1f MB", size / (1024f * 1024f));
        if (size >= 1024L) return String.format(Locale.US, "%.0f KB", size / 1024f);
        return size > 0L ? size + " bytes" : "Ready to submit";
    }

    private boolean documentIsPdf(String title) {
        return registrationDocumentDisplayName(title).toLowerCase(Locale.US).endsWith(".pdf");
    }

    private void removeRegistrationDocument(String title) {
        String uriText = prefs.getString(documentPrefKey(title), "");
        if (!TextUtils.isEmpty(uriText)) {
            try {
                Uri uri = Uri.parse(uriText);
                if ("file".equalsIgnoreCase(uri.getScheme()) && uri.getPath() != null) {
                    new File(uri.getPath()).delete();
                }
            } catch (Exception ignored) {
            }
        }
        prefs.edit()
                .remove(documentPrefKey(title))
                .remove(documentPrefKey(title) + "_status")
                .remove(documentPrefKey(title) + "_updated")
                .remove(documentPrefKey(title) + "_aadhaar_last4")
                .remove(documentPrefKey(title) + "_name")
                .remove(documentPrefKey(title) + "_size")
                .apply();
        refreshRegistrationDocumentsIfNeeded();
        Toast.makeText(this, "Document removed", Toast.LENGTH_SHORT).show();
    }

    private void saveDocumentUploadState(String title, Uri uri, String status, String aadhaarLast4) {
        prefs.edit()
                .putString(documentPrefKey(title), uri.toString())
                .putString(documentPrefKey(title) + "_status", TextUtils.isEmpty(status) ? "Review" : status)
                .putString(documentPrefKey(title) + "_aadhaar_last4", aadhaarLast4 == null ? "" : aadhaarLast4)
                .putLong(documentPrefKey(title) + "_updated", System.currentTimeMillis())
                .apply();
        updateLaundryDocumentSelection(title);
        refreshRegistrationDocumentsIfNeeded();
    }

    private void refreshRegistrationDocumentsIfNeeded() {
        if (registrationDraftActive && "Register".equalsIgnoreCase(authMode) && !onboardingRegistrationOtp) {
            new Handler(Looper.getMainLooper()).post(() -> showPartnerRegistrationStepTwo(
                    draftRegName, draftRegPhone, draftRegEmail, draftRegDob, draftRegGender,
                    "", "", draftRegCity, draftRegState, draftRegPin));
        }
    }

    private void updateLaundryDocumentSelection(String title) {
        TextView titleView = laundryDocumentTitleViews.get(title);
        if (titleView != null) {
            titleView.setText(registrationDocumentDisplayName(title));
            titleView.setTextColor(BLACK);
        }
        TextView subtitleView = laundryDocumentSubtitleViews.get(title);
        if (subtitleView != null) {
            subtitleView.setText(registrationDocumentSizeLabel(title) + " • Uploaded");
            subtitleView.setTextColor(GREEN);
        }
        TextView actionView = laundryDocumentActionViews.get(title);
        if (actionView != null) {
            actionView.setText("✓");
            actionView.setTextColor(GREEN);
            actionView.setTextSize(18);
        }
        LinearLayout uploadBox = laundryRegistrationUploadBoxes.get(title);
        if (uploadBox != null) {
            uploadBox.setBackground(stroke(Color.rgb(241, 253, 246),
                    Color.rgb(177, 234, 201), dp(14)));
        }
    }

    private void showAadhaarLast4Dialog(String title, Uri uri) {
        AlertDialog dialog = new AlertDialog.Builder(this).create();
        LinearLayout sheet = vertical();
        sheet.setPadding(dp(20), dp(18), dp(20), dp(18));
        sheet.setBackground(stroke(Color.WHITE, Color.rgb(250, 216, 225), dp(22)));
        sheet.addView(text("Aadhaar Verification", 18, BLACK, true), margin(-1, -2, 0, 0, 0, 6));
        sheet.addView(text("Enter the last 4 digits of Aadhaar. The full Aadhaar number is not stored in the app.", 12, MUTED, false), margin(-1, -2, 0, 0, 0, 14));
        EditText aadhaar = input("Last 4 digits", InputType.TYPE_CLASS_NUMBER);
        aadhaar.setFilters(new InputFilter[]{new InputFilter.LengthFilter(4)});
        sheet.addView(aadhaar, margin(-1, 52, 0, 0, 0, 14));
        LinearLayout actions = horizontal();
        TextView cancel = outlineButton("Skip");
        cancel.setOnClickListener(view -> dialog.dismiss());
        actions.addView(cancel, new LinearLayout.LayoutParams(0, dp(48), 1));
        TextView submit = roseButton("Submit");
        submit.setOnClickListener(view -> {
            String last4 = aadhaar.getText().toString().replaceAll("\\D", "");
            if (last4.length() != 4) {
                Toast.makeText(this, "Aadhaar last 4 digits required", Toast.LENGTH_SHORT).show();
                return;
            }
            if (isRegistrationDocumentSelectionMode()) {
                saveDocumentUploadState(title, uri, "Selected", last4);
                Toast.makeText(this, "File uploaded successfully and is ready to submit", Toast.LENGTH_SHORT).show();
            } else {
                uploadDocumentForValidation(title, uri, last4);
            }
            dialog.dismiss();
        });
        LinearLayout.LayoutParams submitParams = new LinearLayout.LayoutParams(0, dp(48), 1);
        submitParams.setMargins(dp(10), 0, 0, 0);
        actions.addView(submit, submitParams);
        sheet.addView(actions);
        dialog.setView(sheet);
        dialog.setOnShowListener(d -> {
            Window window = dialog.getWindow();
            if (window != null) {
                window.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));
            }
        });
        showDialogSafely(dialog);
    }

    private void setImageUriSafely(ImageView image, Uri uri) {
        loadImageUriSafely(image, uri, true);
    }

    private void loadImageUriSafely(ImageView image, Uri uri, boolean showDefaultOnFailure) {
        if (image == null) return;
        if (uri == null) {
            if (showDefaultOnFailure) image.setImageResource(android.R.drawable.sym_def_app_icon);
            return;
        }
        com.bumptech.glide.RequestBuilder<Drawable> request = Glide.with(this)
                .load(uri)
                .override(dp(360), dp(360));
        if (showDefaultOnFailure) {
            request = request.error(android.R.drawable.sym_def_app_icon);
        }
        request.into(image);
    }

    private void setSampledResourceImage(ImageView image, int resourceId, int targetWidth, int targetHeight) {
        if (image == null) return;
        try {
            BitmapFactory.Options bounds = new BitmapFactory.Options();
            bounds.inJustDecodeBounds = true;
            BitmapFactory.decodeResource(getResources(), resourceId, bounds);
            BitmapFactory.Options options = new BitmapFactory.Options();
            options.inPreferredConfig = Bitmap.Config.RGB_565;
            options.inSampleSize = bitmapSampleSize(bounds.outWidth, bounds.outHeight, targetWidth, targetHeight);
            Bitmap bitmap = BitmapFactory.decodeResource(getResources(), resourceId, options);
            if (bitmap != null) {
                image.setImageBitmap(bitmap);
                return;
            }
        } catch (RuntimeException ignored) {
        }
        image.setImageResource(resourceId);
    }

    private int bitmapSampleSize(int width, int height, int targetWidth, int targetHeight) {
        int safeWidth = Math.max(1, targetWidth);
        int safeHeight = Math.max(1, targetHeight);
        int sample = 1;
        while (width / (sample * 2) >= safeWidth && height / (sample * 2) >= safeHeight) {
            sample *= 2;
        }
        return sample;
    }

    private void polishSystemBars() {
        Window window = getWindow();
        WindowCompat.getInsetsController(window, window.getDecorView()).setAppearanceLightStatusBars(true);
        WindowCompat.getInsetsController(window, window.getDecorView()).setAppearanceLightNavigationBars(true);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            window.setNavigationBarContrastEnforced(false);
            window.setStatusBarContrastEnforced(false);
        }
    }

    private View splashScreen() {
        FrameLayout root = new FrameLayout(this);
        root.setBackgroundColor(BG);

        ImageView logo = new ImageView(this);
        // The brand mark contains transparency. RGB_565 drops its alpha channel and
        // renders a white rectangle around the logo on the warm dashboard surface.
        logo.setImageResource(R.drawable.apna_servo_logo);
        logo.setScaleType(ImageView.ScaleType.FIT_CENTER);
        logo.setAdjustViewBounds(true);
        logo.setAlpha(0f);
        logo.setScaleX(0.985f);
        logo.setScaleY(0.985f);
        FrameLayout.LayoutParams logoParams = new FrameLayout.LayoutParams(dp(270), dp(96), Gravity.CENTER);
        root.addView(logo, logoParams);

        logo.animate()
                .alpha(1f)
                .scaleX(1f)
                .scaleY(1f)
                .setDuration(520)
                .setInterpolator(new AccelerateDecelerateInterpolator())
                .start();
        return root;
    }

