    private JSONObject staffProfile() {
        try {
            return new JSONObject(prefs.getString(KEY_STAFF_PROFILE_JSON, "{}"));
        } catch (Exception ignored) {
            return new JSONObject();
        }
    }

    private void startStaffBackgroundSync() {
        if (!isStaffSession() || backendClient == null) return;
        if (refreshRunnable != null) refreshHandler.removeCallbacks(refreshRunnable);
        refreshRunnable = new Runnable() {
            @Override
            public void run() {
                if (!isStaffSession() || isFinishing()) return;
                fetchStaffBookings();
                refreshHandler.postDelayed(this, REFRESH_MS);
            }
        };
        fetchStaffBookings();
        refreshHandler.postDelayed(refreshRunnable, REFRESH_MS);
    }

    private void fetchStaffBookings() {
        if (!isStaffSession() || backendClient == null || loadingBookings) return;
        loadingBookings = true;
        backendClient.fetchLaundryStaffBookings(new BackendClient.JsonCallback() {
            @Override
            public void onSuccess(JSONObject object) {
                loadingBookings = false;
                backendConnected = true;
                JSONObject staff = object.optJSONObject("staff");
                if (staff != null) {
                    online = staff.optBoolean("isOnline", online);
                    Set<String> authoritativeServices = categoriesFromPartnerJson(staff.optJSONArray("serviceCategory"));
                    String authoritativeServiceId = canonicalAccountServiceId(staff, authoritativeServices);
                    String companyName = staffCompanyNameFromJson(staff);
                    if (!authoritativeServices.isEmpty()) {
                        selectedSkills = authoritativeServices;
                        selectedSkill = firstPartnerSkill();
                    }
                    prefs.edit()
                            .putString(KEY_NAME, staff.optString("name", prefs.getString(KEY_NAME, "Service Staff")))
                            .putString(KEY_EMAIL, staffEmailValue(staff))
                            .putString(KEY_PHOTO, staffPhotoValue(staff))
                            .putString(KEY_STAFF_PROFILE_JSON, staff.toString())
                            .putString(KEY_STAFF_SHOP_NAME, TextUtils.isEmpty(companyName) ? prefs.getString(KEY_STAFF_SHOP_NAME, "") : companyName)
                            .putString(KEY_SKILL, skillsCsv(authoritativeServices))
                            .putString(KEY_SERVICE_ID, authoritativeServiceId)
                            .putBoolean("online", online)
                            .apply();
                }
                applyLiveBookings(parseBackendBookings(object), false);
            }

            @Override
            public void onError(String message) {
                loadingBookings = false;
                backendConnected = false;
                refreshCurrent();
            }
        });
    }

