        LinearLayout row = horizontal();
        row.setGravity(Gravity.CENTER_VERTICAL);
        row.setPadding(dp(10), dp(11), dp(10), dp(11));
        row.setBackground(stroke(Color.rgb(255, 253, 253), Color.rgb(247, 222, 227), dp(15)));
