    private View laundryRecentRequests() {
        LinearLayout card = card(10);
        card.setBackground(stroke(Color.WHITE, Color.rgb(247, 222, 228), dp(18)));
        LinearLayout heading = horizontal();
        heading.setGravity(Gravity.CENTER_VERTICAL);
        heading.addView(text("Recent Requests", 17, BLACK, true), new LinearLayout.LayoutParams(0, -2, 1));
        int pendingCount = 0;
        for (PartnerBooking item : bookings) if (isPending(item) && !cancelledIds.contains(item.id)) pendingCount++;
        heading.addView(pill(pendingCount + " New Requests", ROSE, ROSE_SOFT), new LinearLayout.LayoutParams(dp(118), dp(30)));
        card.addView(heading, margin(-1, -2, 0, 0, 0, 8));
        int shown = 0;
        for (PartnerBooking booking : bookings) {
            if (!isPending(booking) || cancelledIds.contains(booking.id) || shown >= 2) continue;
            LinearLayout row = vertical();
            row.setPadding(dp(10), dp(9), dp(10), dp(9));
            row.setBackground(stroke(Color.rgb(255, 253, 253), Color.rgb(247, 226, 231), dp(12)));
            LinearLayout title = horizontal();
            title.addView(text(laundryOrderCode(booking) + "  •  " + customerNameOnly(booking), 12, BLACK, true), new LinearLayout.LayoutParams(0, -2, 1));
            title.addView(text(finalAmount(booking) > 0 ? moneyLabel(finalAmount(booking)) : "New", 12, ROSE, true));
            row.addView(title);
            row.addView(text((TextUtils.isEmpty(booking.issue) ? "Laundry order" : booking.issue) + "\nPickup: " + laundryPickupLabel(booking), 10, MUTED, false), margin(-1, -2, 0, 5, 0, 7));
            LinearLayout buttons = horizontal();
            TextView reject = outlineButton("Reject");
            reject.setOnClickListener(view -> cancelBooking(booking));
            TextView accept = roseButton("Accept");
            accept.setOnClickListener(view -> acceptBooking(booking));
            buttons.addView(reject, new LinearLayout.LayoutParams(0, dp(38), 1));
            LinearLayout.LayoutParams acceptParams = new LinearLayout.LayoutParams(0, dp(38), 1);
            acceptParams.setMargins(dp(10), 0, 0, 0);
            buttons.addView(accept, acceptParams);
            row.addView(buttons);
            card.addView(row, margin(-1, -2, 0, 0, 0, 7));
            shown++;
        }
        if (shown == 0) {
            TextView empty = text("No new laundry requests right now.", 12, MUTED, false);
            empty.setGravity(Gravity.CENTER);
            empty.setPadding(0, dp(18), 0, dp(14));
            card.addView(empty);
        }
        return card;
    }

