        LinearLayout right = vertical();
        right.setGravity(Gravity.RIGHT);
        TextView status = text(laundryStatusLabel(booking), 9, laundryStatusColor(booking), true);
        status.setGravity(Gravity.CENTER);
        status.setBackground(round(laundryStatusSoftColor(booking), dp(11)));
