    private void renderLaundryPartnersList(LinearLayout list, String query) {
        list.removeAllViews();
        String needle = query == null ? "" : query.trim().toLowerCase(Locale.US);
        JSONArray staff = laundryStaffMembers();
        int shown = 0;
        for (int index = 0; index < staff.length(); index++) {
            JSONObject member = staff.optJSONObject(index);
            if (member == null) continue;
            String haystack = (member.optString("name", "") + " " + member.optString("phone", "")
                    + " " + member.optString("email", "")).toLowerCase(Locale.US);
            if (!needle.isEmpty() && !haystack.contains(needle)) continue;
            list.addView(laundryPartnerDirectoryCard(member), margin(-1, -2, 0, 0, 0, 10));
            shown++;
        }
        if (shown == 0) {
            TextView empty = text(needle.isEmpty() ? "No laundry partners added yet." : "No matching laundry partner found.", 13, MUTED, false);
            empty.setGravity(Gravity.CENTER);
            empty.setPadding(dp(16), dp(36), dp(16), dp(36));
            empty.setBackground(stroke(Color.WHITE, Color.rgb(247, 220, 227), dp(16)));
            list.addView(empty, margin(-1, -2, 0, 0, 0, 12));
        }
    }

