    private String staffJoinedDate(JSONObject member) {
        String raw = member.optString("joinedAt", member.optString("createdAt", ""));
        if (TextUtils.isEmpty(raw)) return "Not available";
        try {
            String normalized = raw.length() >= 10 ? raw.substring(0, 10) : raw;
            Date date = new SimpleDateFormat("yyyy-MM-dd", Locale.US).parse(normalized);
            return date == null ? "Not available" : new SimpleDateFormat("dd MMM yyyy", Locale.US).format(date);
        } catch (Exception ignored) { return "Not available"; }
    }

    private void showLaundryPartnerActions(JSONObject member) {
        String name = member.optString("name", "this partner");
        new AlertDialog.Builder(this)
                .setTitle(name)
                .setItems(new String[]{"Permanently Remove Partner"}, (dialog, which) -> confirmPermanentLaundryPartnerRemoval(member))
                .setNegativeButton("Cancel", null)
                .show();
    }

    private void confirmPermanentLaundryPartnerRemoval(JSONObject member) {
        String name = member.optString("name", "this partner");
        new AlertDialog.Builder(this)
                .setTitle("Permanently remove " + name + "?")
                .setMessage("This removes only this Laundry staff record. Historical order records remain safe. This action cannot be undone.")
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Remove Permanently", (dialog, which) -> removeLaundryPartnerPermanently(member))
                .show();
    }

    private void removeLaundryPartnerPermanently(JSONObject member) {
        String staffId = member.optString("id", String.valueOf(member.optInt("sequence", 0)));
        if (TextUtils.isEmpty(staffId) || "0".equals(staffId)) {
            Toast.makeText(this, "Staff record ID is unavailable. Refresh and try again.", Toast.LENGTH_LONG).show();
            return;
        }
        backendClient.removeServiceStaff("laundry", staffId, new BackendClient.JsonCallback() {
            @Override public void onSuccess(JSONObject object) {
                JSONArray current = laundryStaffMembers();
                JSONArray kept = new JSONArray();
                for (int i = 0; i < current.length(); i++) {
                    JSONObject item = current.optJSONObject(i);
                    if (item == null) continue;
                    String itemId = item.optString("id", String.valueOf(item.optInt("sequence", 0)));
                    if (!staffId.equals(itemId)) kept.put(item);
                }
                prefs.edit().putString(KEY_LAUNDRY_STAFF_JSON, kept.toString())
                        .putInt(KEY_LAUNDRY_STAFF_COUNT, kept.length()).apply();
                Toast.makeText(MainActivity.this, "Laundry partner permanently removed", Toast.LENGTH_SHORT).show();
                showLaundryPartnersDirectory();
            }

            @Override public void onError(String message) {
                showSupportInfoDialog("Partner Not Removed", safeUserError(message));
            }
        });
    }

