    private Uri copyLaundryStaffPhotoToInternalStorage(Uri source) {
        File file = null;
        try {
            long declaredSize = documentSourceSize(source);
            if (declaredSize > MAX_DOCUMENT_BYTES) {
                Toast.makeText(this, "Staff photo size is above 5 MB. Choose a smaller image.", Toast.LENGTH_LONG).show();
                return null;
            }
            String extension = documentFileExtension(source);
            if (!".jpg".equalsIgnoreCase(extension) && !".jpeg".equalsIgnoreCase(extension) && !".png".equalsIgnoreCase(extension)) {
                Toast.makeText(this, "Choose a valid JPG or PNG staff photo.", Toast.LENGTH_LONG).show();
                return null;
            }
            file = new File(getFilesDir(), "laundry_staff_photo_" + System.currentTimeMillis() + extension);
            try (InputStream input = getContentResolver().openInputStream(source);
                 OutputStream output = new FileOutputStream(file)) {
                if (input == null) throw new IllegalStateException("Photo unavailable");
                byte[] buffer = new byte[8192];
                int read;
                long total = 0L;
                while ((read = input.read(buffer)) != -1) {
                    total += read;
                    if (total > MAX_DOCUMENT_BYTES) throw new IllegalArgumentException("Staff photo size is above 5 MB. Choose a smaller image.");
                    output.write(buffer, 0, read);
                }
            }
            return Uri.fromFile(file);
        } catch (Exception error) {
            if (file != null && file.exists()) file.delete();
            Toast.makeText(this, error instanceof IllegalArgumentException ? error.getMessage() : "Unable to save the staff photo", Toast.LENGTH_LONG).show();
            return null;
        }
    }

    private JSONArray mergeLaundryStaffPhoto(JSONArray serverMembers, String name, String phone, String email, String photoUrl) {
        JSONArray members = serverMembers == null ? laundryStaffMembers() : serverMembers;
        boolean updated = false;
        for (int i = 0; i < members.length(); i++) {
            JSONObject member = members.optJSONObject(i);
            if (member == null) continue;
            boolean samePhone = !TextUtils.isEmpty(phone) && phone.equals(normalizePhone(member.optString("phone", "")));
            boolean sameEmail = !TextUtils.isEmpty(email) && email.equalsIgnoreCase(member.optString("email", ""));
            boolean sameName = name.equalsIgnoreCase(member.optString("name", ""));
            if (samePhone || sameEmail || sameName) {
                try { member.put("photoUrl", photoUrl); } catch (Exception ignored) {}
                updated = true;
                break;
            }
        }
        if (!updated) {
            JSONObject member = new JSONObject();
            try {
                member.put("name", name);
                member.put("phone", phone);
                member.put("email", email);
                member.put("role", "Laundry Staff");
                member.put("photoUrl", photoUrl);
                members.put(member);
            } catch (Exception ignored) {}
        }
        return members;
    }

