    private void showLaundryOrderPicker(JSONObject member) {
        List<PartnerBooking> open = new ArrayList<>();
        for (PartnerBooking booking : bookings) {
            if (!isFinishedForPartner(booking) && !cancelledIds.contains(booking.id)) open.add(booking);
        }
        if (open.isEmpty()) {
            Toast.makeText(this, "No open laundry orders available", Toast.LENGTH_SHORT).show();
            return;
        }
        String[] labels = new String[open.size()];
        for (int i = 0; i < open.size(); i++) labels[i] = laundryOrderCode(open.get(i)) + " - " + customerNameOnly(open.get(i));
        String staffName = member.optString("name", "Service Staff");
        int staffSequence = member.optInt("sequence", 0);
        AlertDialog dialog = new AlertDialog.Builder(this)
                .setTitle("Assign order to " + staffName)
                .setItems(labels, (selectedDialog, which) -> {
                    PartnerBooking booking = open.get(which);
                    assignLaundryOrderToStaff(booking, staffSequence, staffName, "pickup");
                })
                .setNegativeButton("Cancel", null)
                .create();
        showDialogSafely(dialog);
    }

    private void assignLaundryOrderToStaff(PartnerBooking booking, int staffSequence, String staffName) {
        assignLaundryOrderToStaff(booking, staffSequence, staffName, "pickup");
    }

    private void assignLaundryOrderToStaff(PartnerBooking booking, int staffSequence, String staffName, String assignmentType) {
        if (booking == null || staffSequence <= 0) {
            Toast.makeText(this, "Select a valid staff member", Toast.LENGTH_SHORT).show();
            return;
        }
        backendClient.assignLaundryStaff(booking.id, staffSequence, assignmentType, new BackendClient.JsonCallback() {
            @Override
            public void onSuccess(JSONObject object) {
                prefs.edit()
                        .putString(KEY_LAUNDRY_ASSIGNMENT_PREFIX + booking.id, staffName)
                        .putString(KEY_LAUNDRY_ASSIGNMENT_PREFIX + assignmentType + "_" + booking.id, staffName)
                        .putString(KEY_LAUNDRY_TASK_STATUS_PREFIX + booking.id, "assigned")
                        .apply();
                Toast.makeText(MainActivity.this, staffName + " assigned for " + assignmentType, Toast.LENGTH_SHORT).show();
                fetchBackendBookings();
                showDashboard();
            }

            @Override
            public void onError(String message) {
                Toast.makeText(MainActivity.this, safeUserError(message), Toast.LENGTH_LONG).show();
            }
        });
    }

    private void showNewRequest(PartnerBooking booking) {
        if (!requireFeature("partner_booking_management", "Booking Management")) return;
        if (!isPartnerApproved()) {
            setContentView(verificationStatusScreen());
            return;
        }
        stopIncomingRequestAlert();
        if (booking != null) arrivalDialogBookingIds.remove(booking.id);
        enterScreen("request", booking == null ? "" : booking.id);
        activeTab = "request";
        updateNav();
        clearContentForScreen("request");
        content.setBackgroundColor(Color.rgb(255, 253, 253));
        content.addView(newRequestHeader(booking, false), margin(-1, -2, 0, 0, 0, 20));
        content.addView(requestAvailabilityNotice(), margin(-1, -2, 0, 0, 0, 16));
        content.addView(thinDivider(), new LinearLayout.LayoutParams(-1, dp(1)));
        content.addView(newRequestServiceRow(booking));
        content.addView(thinDivider(), new LinearLayout.LayoutParams(-1, dp(1)));
        content.addView(newRequestInfoRow(R.drawable.ic_partner_info_user, "Customer", booking.customer, true, booking));
        content.addView(thinDivider(), new LinearLayout.LayoutParams(-1, dp(1)));
        content.addView(newRequestInfoRow(R.drawable.ic_partner_service_location, "Address", booking.address, false, booking));
        content.addView(thinDivider(), new LinearLayout.LayoutParams(-1, dp(1)));
        content.addView(newRequestInfoRow(R.drawable.ic_partner_earn_clipboard, "Issue",
                TextUtils.isEmpty(booking.issue) ? "Customer requested " + bookingTitle(booking) + " inspection" : booking.issue,
                false, booking));
        content.addView(thinDivider(), new LinearLayout.LayoutParams(-1, dp(1)));
        content.addView(newRequestInfoRow(R.drawable.ic_partner_earn_wallet, "Amount", "Partner enters after work", false, booking));
        content.addView(thinDivider(), new LinearLayout.LayoutParams(-1, dp(1)));
        content.addView(newRequestInfoRow(R.drawable.ic_partner_stat_calendar, "Detail", "Partner enters after work", false, booking));

        LinearLayout actions = horizontal();
        actions.setPadding(0, dp(12), 0, dp(8));
        TextView reject = outlineButton("\u2715  Reject");
        reject.setOnClickListener(view -> cancelBooking(booking));
        boolean alreadyAccepting = booking != null && acceptingIds.contains(booking.id);
        boolean alreadyAccepted = booking != null && acceptedIds.contains(booking.id);
        TextView accept = roseButton(alreadyAccepted ? "Accepted" : alreadyAccepting ? "Accepting..." : "\u2713  Accept");
        accept.setEnabled(!alreadyAccepted && !alreadyAccepting);
        accept.setAlpha((alreadyAccepted || alreadyAccepting) ? 0.72f : 1f);
        accept.setOnClickListener(view -> acceptBooking(booking));
        actions.addView(reject, new LinearLayout.LayoutParams(0, dp(54), 1));
        LinearLayout.LayoutParams acceptParams = new LinearLayout.LayoutParams(0, dp(54), 1);
        acceptParams.setMargins(dp(12), 0, 0, 0);
        actions.addView(accept, acceptParams);
        content.addView(actions, margin(-1, -2, 0, 0, 0, 8));
    }

    private void showOrderDetail(PartnerBooking booking) {
        if (!isPartnerApproved()) {
            setContentView(verificationStatusScreen());
            return;
        }
        stopIncomingRequestAlert();
        if (isFinishedForPartner(booking)) {
            showFinishedBookingList(booking);
            return;
        }
        String workflowStatus = normalizedStatus(booking);
        if ("pending".equals(workflowStatus) || "sent_to_partner".equals(workflowStatus)) {
            showNewRequest(booking);
            return;
        }
        if (isReadOnlyLaundryOwnerFor(booking)) {
            showCompanyBookingLiveDetail(booking);
            return;
        }
        if ("on_the_way".equals(workflowStatus)
                || "arrived".equals(workflowStatus)
                || "started".equals(workflowStatus)
                || "amount_pending".equals(workflowStatus)
                || "customer_no_response".equals(workflowStatus)) {
            showInAppMap(booking);
            return;
        }
        enterScreen("detail", booking == null ? "" : booking.id);
        activeDetailBooking = booking;
        activeTab = "detail";
        updateNav();
        clearContentForScreen("detail");
        content.addView(bookingDetailHeader(), margin(-1, -2, 0, 0, 0, 12));
        if ("pending_partner_ack".equals(bookingLocationChangeStateCache.get(booking.id))) {
            content.addView(partnerLocationChangeCard(booking), margin(-1, -2, 0, 0, 0, 12));
        }
        content.addView(bookingDetailPanel(booking), margin(-1, -2, 0, 0, 0, 10));
        if (isCleaningOwnerBooking(booking)) {
            content.addView(cleaningHelperCard(booking, true), margin(-1, -2, 0, 0, 0, 12));
        }
        content.addView(bookingAcceptedBanner(), margin(-1, 46, 0, 0, 0, 14));
        resetMainScroll();
    }

    private void showCompanyBookingLiveDetail(PartnerBooking booking) {
        if (booking == null) {
            showBookings();
            return;
        }
        enterScreen("company_booking", booking.id);
        activeDetailBooking = booking;
        activeTab = "company_booking";
        updateNav();
        clearContentForScreen("company_booking");
        content.setBackgroundColor(Color.rgb(255, 251, 251));
        content.addView(mapHeader(booking), margin(-1, -2, 0, 0, 0, 12));
        if ("pending_partner_ack".equals(bookingLocationChangeStateCache.get(booking.id))) {
            content.addView(partnerLocationChangeCard(booking), margin(-1, -2, 0, 0, 0, 12));
        }
        content.addView(mapCustomerCard(booking), margin(-1, -2, 0, 0, 0, 12));
        content.addView(companyReadOnlyStatusCard(booking), margin(-1, -2, 0, 0, 0, 12));
        content.addView(mapStatusActions(booking), margin(-1, -2, 0, 0, 0, 14));
        removeServiceStatusActionDock();
        setDefaultScrollPadding();
        resetMainScroll();
    }

