    private String companyPaymentPill(PartnerBooking booking) {
        String status = normalizedStatus(booking);
        if ("completed".equals(status)) return "Payment complete";
        if (paymentSubmittedByCustomer(booking)) return "Payment marked";
        if ("amount_pending".equals(status)) return "Awaiting payment";
        return "Amount after job";
    }

    private String companyPaymentDetail(PartnerBooking booking) {
        String status = normalizedStatus(booking);
        if ("completed".equals(status)) return "Customer payment verified successfully.";
        if (paymentSubmittedByCustomer(booking)) return "Customer marked payment; staff verification pending.";
        if ("amount_pending".equals(status)) return "Waiting for the customer to confirm payment.";
        return "Staff will enter the final amount after service completion.";
    }

