    private void showLocationChangeRejectionReasons(PartnerBooking booking) {
        String[] reasons = {
                "Updated location is outside my service area",
                "Updated location is too far away",
                "I cannot reach the updated location on time",
                "Service location was changed and I cannot accept the new location"
        };
        new AlertDialog.Builder(this)
                .setTitle("Why can't you accept the new location?")
                .setItems(reasons, (dialog, which) -> submitLocationChangeResponse(booking, "reject", reasons[which]))
                .setNegativeButton("Cancel", null)
                .show();
    }

    private void submitLocationChangeResponse(PartnerBooking booking, String action, String reason) {
        if (!allowOperationalAction()) return;
        if (backendClient == null || booking == null) return;
        backendClient.respondToLocationChange(booking.id, action, reason, new BackendClient.JsonCallback() {
            @Override public void onSuccess(JSONObject object) {
                bookingLocationChangeStateCache.put(booking.id, "accept".equals(action) ? "accepted" : "rejected");
                Toast.makeText(MainActivity.this, "accept".equals(action) ? "Updated location accepted" : "Assignment released for reassignment", Toast.LENGTH_LONG).show();
                fetchBackendBookings();
            }
            @Override public void onError(String message) {
                Toast.makeText(MainActivity.this, "Location response failed: " + message, Toast.LENGTH_LONG).show();
            }
        });
    }

