    private String customerNameOnly(PartnerBooking booking) {
        String value = booking == null ? "" : booking.customer;
        if (TextUtils.isEmpty(value)) {
            return "Customer";
        }
        String[] parts = value.split("\\n");
        String name = parts.length == 0 ? value : parts[0];
        return TextUtils.isEmpty(name.trim()) ? "Customer" : name.trim();
    }

    private String customerShortPhone(PartnerBooking booking) {
        if (booking == null || TextUtils.isEmpty(booking.customerPhone)) {
            return "+----";
        }
        String digits = booking.customerPhone.replaceAll("\\D", "");
        if (digits.length() < 4) {
            return "+----";
        }
        return "+" + digits.substring(Math.max(0, digits.length() - 4));
    }

    private String bookingDetailDateTitle(PartnerBooking booking) {
        String date = extractBookingDate(booking);
        if (TextUtils.isEmpty(date)) {
            return "Today";
        }
        String today = new SimpleDateFormat("d MMM yyyy", Locale.US).format(new Date());
        if (date.equalsIgnoreCase(today)) {
            return "Today";
        }
        return date;
    }

    private String bookingDetailDay(PartnerBooking booking) {
        String slot = booking == null || booking.time == null ? "" : booking.time.trim();
        String lower = slot.toLowerCase(Locale.US);
        if (lower.startsWith("mon")) return "Monday";
        if (lower.startsWith("tue")) return "Tuesday";
        if (lower.startsWith("wed")) return "Wednesday";
        if (lower.startsWith("thu")) return "Thursday";
        if (lower.startsWith("fri")) return "Friday";
        if (lower.startsWith("sat")) return "Saturday";
        if (lower.startsWith("sun")) return "Sunday";
        return new SimpleDateFormat("EEEE", Locale.US).format(new Date());
    }

    private String bookingDetailTimeTitle(PartnerBooking booking) {
        String slot = booking == null || booking.time == null ? "" : booking.time.trim();
        if (TextUtils.isEmpty(slot)) {
            return bookingSlot(booking);
        }
        return slot.replaceAll("\\s+", " ");
    }

    private String bookingDurationLabel(PartnerBooking booking) {
        String slot = booking == null || booking.time == null ? "" : booking.time.trim();
        java.util.regex.Matcher matcher = Pattern.compile("(\\d{1,2}:\\d{2})\\s*([AP]M)\\s*-\\s*(\\d{1,2}:\\d{2})\\s*([AP]M)", Pattern.CASE_INSENSITIVE).matcher(slot);
        if (matcher.find()) {
            try {
                SimpleDateFormat format = new SimpleDateFormat("hh:mm a", Locale.US);
                Date start = format.parse(matcher.group(1) + " " + matcher.group(2).toUpperCase(Locale.US));
                Date end = format.parse(matcher.group(3) + " " + matcher.group(4).toUpperCase(Locale.US));
                if (start != null && end != null) {
                    long diff = Math.max(0, end.getTime() - start.getTime());
                    long hours = diff / (60 * 60 * 1000);
                    long minutes = (diff / (60 * 1000)) % 60;
                    if (hours > 0 && minutes > 0) return hours + " hr " + minutes + " min";
                    if (hours > 0) return hours + (hours == 1 ? " hr" : " hrs");
                    if (minutes > 0) return minutes + " min";
                }
            } catch (Exception ignored) {
            }
        }
        return "2 hrs";
    }

    private String extractBookingDate(PartnerBooking booking) {
        String slot = booking == null || booking.time == null ? "" : booking.time.trim();
        java.util.regex.Matcher matcher = Pattern.compile("(\\d{1,2}\\s+[A-Za-z]{3,9}\\s+\\d{4})").matcher(slot);
        if (matcher.find()) {
            return matcher.group(1);
        }
        String date = bookingDate(booking);
        return TextUtils.isEmpty(date) ? "" : date;
    }

