    private void showBookings() {
        if (!requireFeature("partner_booking_management", "Booking Management")) return;
        if (isStaffSession()) {
            showLaundryStaffJobs();
            return;
        }
        if (!isPartnerApproved()) {
            setContentView(verificationStatusScreen());
            return;
        }
        if ("laundry".equals(currentServiceId())) {
            showLaundryOrders();
            return;
        }
        enterScreen("bookings");
        activeTab = "bookings";
        updateNav();
        clearContentForScreen("bookings");
        content.addView(partnerPageHeader("My Bookings", "Manage and track your all bookings", false, false), margin(-1, -2, 0, 0, 0, 12));
        content.addView(bookingFilterTabs(), margin(-1, -2, 0, 0, 0, 14));
        content.addView(section("Upcoming & Ongoing", "View All"), margin(-1, -2, 0, 0, 0, 8));
        LinearLayout list = vertical();
        int shown = 0;
        for (PartnerBooking booking : bookings) {
            if (matchesBookingFilter(booking)) {
                list.addView(premiumBookingCard(booking), margin(-1, -2, 0, 0, 0, 12));
                shown++;
            }
        }
        if (shown == 0) {
            list.addView(emptyBookingsCard(), margin(-1, -2, 0, 0, 0, 12));
        }
        content.addView(list);
    }

    private void showLaundryOrders() {
        enterScreen("bookings");
        activeTab = "bookings";
        updateNav();
        clearContentForScreen("bookings");
        content.setBackgroundColor(Color.rgb(255, 251, 250));
        content.addView(partnerPageHeader("Laundry Orders", "Manage pickup and delivery orders", false, false), margin(-1, -2, 0, 0, 0, 12));
        LinearLayout tabs = horizontal();
        tabs.setGravity(Gravity.CENTER_VERTICAL);
        tabs.setBackground(stroke(Color.WHITE, Color.rgb(247, 226, 231), dp(16)));
        tabs.addView(laundryOrderTab("all", "All Orders (" + laundryVisibleCount("all") + ")"), new LinearLayout.LayoutParams(0, dp(48), 1));
        tabs.addView(laundryOrderTab("pickup", "Pickup (" + laundryVisibleCount("pickup") + ")"), new LinearLayout.LayoutParams(0, dp(48), 1));
        tabs.addView(laundryOrderTab("delivery", "Delivery (" + laundryVisibleCount("delivery") + ")"), new LinearLayout.LayoutParams(0, dp(48), 1));
        content.addView(tabs, margin(-1, -2, 0, 0, 0, 8));
        LinearLayout list = vertical();
        list.setPadding(dp(4), 0, dp(4), 0);
        int shown = 0;
        for (PartnerBooking booking : bookings) {
            if (!laundryOrderMatchesTab(booking, bookingFilter)) continue;
            list.addView(laundryCompactOrderRow(booking));
            shown++;
        }
        if (shown == 0) list.addView(emptyBookingsCard(), margin(-1, -2, 0, 8, 0, 8));
        LinearLayout shell = card(0);
        shell.setBackground(stroke(Color.WHITE, Color.rgb(247, 226, 231), dp(16)));
        shell.addView(list);
        content.addView(shell);
    }

    private TextView laundryOrderTab(String key, String label) {
        boolean selected = key.equals(bookingFilter) || ("all".equals(key) && !"pickup".equals(bookingFilter) && !"delivery".equals(bookingFilter));
        TextView view = text(label, 11, selected ? ROSE : Color.rgb(70, 68, 68), selected);
        view.setGravity(Gravity.CENTER);
        if (selected) view.setBackground(stroke(Color.WHITE, ROSE, 0));
        view.setOnClickListener(v -> { bookingFilter = key; showLaundryOrders(); });
        return view;
    }

    private int laundryVisibleCount(String key) {
        int count = 0;
        for (PartnerBooking booking : bookings) if (laundryOrderMatchesTab(booking, key)) count++;
        return count;
    }

    private boolean laundryOrderMatchesTab(PartnerBooking booking, String key) {
        if (!isBookingHistoryVisible(booking)) return false;
        String status = normalizedStatus(booking);
        if ("pickup".equals(key)) return "accepted".equals(status) || "pickup_scheduled".equals(status) || "on_the_way".equals(status) || "arrived".equals(status);
        if ("delivery".equals(key)) return "ready_for_delivery".equals(status) || "out_for_delivery".equals(status) || "completed".equals(status);
        return true;
    }

