    // Plain-language "how it works" card, tailored to the partner's model.
    private View partnerPlanExplainerCard() {
        LinearLayout card = vertical();
        card.setPadding(dp(18), dp(16), dp(18), dp(16));
        card.setBackground(stroke(Color.WHITE, Color.rgb(235, 215, 220), dp(18)));
        card.addView(text("How your plan works", 16, BLACK, true));

        if (partnerBillingStatus == null) {
            card.addView(text(partnerBillingLoading ? "Loading your plan..." : "Plan details unavailable right now.", 12, MUTED, false), margin(-1, -2, 0, 8, 0, 0));
            return card;
        }

        String model = partnerBillingStatus.optString("billingModel",
                partnerBillingStatus.optString("kind", "subscription"));
        boolean withinTrial = partnerBillingStatus.optBoolean("withinTrial", false);
        int trialDaysLeft = partnerBillingStatus.optInt("trialDaysRemaining", 0);
        int freeTrialDays = partnerBillingStatus.optInt("freeTrialDays", 10);

        if ("commission".equals(model)) {
            int percent = partnerBillingStatus.optInt("cleaningCommissionPercent",
                    (int) Math.round(partnerBillingStatus.optDouble("cleaningCommissionRate", 0.25) * 100));
            card.addView(planBullet("No monthly subscription", "As a cleaning partner you never pay a subscription fee."));
            card.addView(planBullet("Commission per job", "The platform keeps " + percent + "% of each completed job. The rest is yours."));
            card.addView(planBullet("First " + freeTrialDays + " days free", withinTrial
                    ? ("You are in the free launch period — 0% fee. " + trialDaysLeft + (trialDaysLeft == 1 ? " day left." : " days left."))
                    : ("The free launch period is over, so the " + percent + "% fee now applies.")));
            card.addView(planBullet("You always get bookings", "Cleaning partners keep receiving booking requests regardless of billing."));
        } else {
            double subscriptionAmount = partnerBillingStatus.optDouble("subscriptionAmount",
                    partnerBillingStatus.optDouble("amount", 299));
            card.addView(planBullet("Monthly subscription", "Pay " + money(subscriptionAmount) + " per month to keep receiving booking requests. It is a flat fee — it does not depend on how many bookings you get."));
            card.addView(planBullet("First " + freeTrialDays + " days free", withinTrial
                    ? ("You are in the free launch period — you receive bookings free. " + trialDaysLeft + (trialDaysLeft == 1 ? " day left." : " days left."))
                    : "The free launch period is over."));
            card.addView(planBullet("Keep it active", "If your subscription expires you stop receiving new bookings until you pay again."));
        }
        return card;
    }

