    // Dashboard banner that explains the monetization state at a glance and,
    // for expired subscription partners, explains why bookings stopped and
    // funnels them to pay. Returns null when no banner is needed.
    private View subscriptionGateBanner() {
        if (partnerBillingStatus == null) {
            if (!partnerBillingLoading) loadPartnerBillingStatus();
            return null;
        }
        String model = partnerBillingStatus.optString("billingModel",
                partnerBillingStatus.optString("kind", "subscription"));
        boolean active = partnerBillingStatus.optBoolean("active", false);
        boolean withinTrial = partnerBillingStatus.optBoolean("withinTrial", false);
        int trialDaysLeft = partnerBillingStatus.optInt("trialDaysRemaining", 0);

        // Commission (cleaning) partners are never gated. Surface the plan at
        // the top of home at all times: a green free-period note during the
        // trial, and a steady commission note afterwards.
        if ("commission".equals(model)) {
            int percent = partnerBillingStatus.optInt("cleaningCommissionPercent",
                    (int) Math.round(partnerBillingStatus.optDouble("cleaningCommissionRate", 0.25) * 100));
            LinearLayout note = vertical();
            note.setPadding(dp(16), dp(14), dp(16), dp(14));
            if (withinTrial) {
                note.setBackground(stroke(Color.rgb(240, 251, 244), Color.rgb(190, 227, 203), dp(16)));
                note.addView(text("Free launch period · " + trialDaysLeft + (trialDaysLeft == 1 ? " day left" : " days left"), 13, GREEN, true));
                note.addView(text("Enjoy 0% platform fee for now. After the free period a " + percent + "% fee applies per completed job. No subscription needed.", 12, MUTED, false), margin(-1, -2, 0, 4, 0, 0));
            } else {
                note.setBackground(stroke(Color.rgb(248, 250, 252), Color.rgb(216, 223, 232), dp(16)));
                note.addView(text("Commission plan active", 13, GREEN, true));
                note.addView(text("No monthly subscription. The platform fee is " + percent + "% per completed job and you always keep receiving bookings.", 12, MUTED, false), margin(-1, -2, 0, 4, 0, 0));
            }
            return note;
        }

        // Subscription partners.
        double subscriptionAmount = partnerBillingStatus.optDouble("subscriptionAmount",
                partnerBillingStatus.optDouble("amount", 299));
        if (withinTrial) {
            LinearLayout note = vertical();
            note.setPadding(dp(16), dp(14), dp(16), dp(14));
            note.setBackground(stroke(Color.rgb(240, 251, 244), Color.rgb(190, 227, 203), dp(16)));
            note.addView(text("Free launch period · " + trialDaysLeft + (trialDaysLeft == 1 ? " day left" : " days left"), 13, GREEN, true));
            note.addView(text("You are receiving bookings free of charge. After this, a " + money(subscriptionAmount) + "/month subscription keeps your bookings active.", 12, MUTED, false), margin(-1, -2, 0, 4, 0, 0));
            return note;
        }
        if (active) {
            // Keep the plan visible at the top with a calm "active" status
            // instead of hiding it entirely.
            String expiresLabel = formatBillingDate(partnerBillingStatus.optString("subscriptionExpiresAt", ""));
            LinearLayout note = vertical();
            note.setPadding(dp(16), dp(14), dp(16), dp(14));
            note.setBackground(stroke(Color.rgb(240, 251, 244), Color.rgb(190, 227, 203), dp(16)));
            note.addView(text(TextUtils.isEmpty(expiresLabel) ? "Subscription active" : "Subscription active until " + expiresLabel, 13, GREEN, true));
            note.addView(text(money(subscriptionAmount) + "/month keeps your bookings flowing.", 12, MUTED, false), margin(-1, -2, 0, 4, 0, 0));
            return note;
        }

        // Expired subscription — this is the important gate banner.
        LinearLayout banner = vertical();
        banner.setPadding(dp(16), dp(16), dp(16), dp(16));
        banner.setBackground(stroke(ROSE_SOFT, Color.rgb(240, 180, 196), dp(16)));
        banner.addView(text("You're not receiving new bookings", 14, ROSE_DARK, true));
        banner.addView(text("Your subscription has expired. Pay " + money(subscriptionAmount) + " to reactivate it for the next month and start getting booking requests again.", 12, MUTED, false), margin(-1, -2, 0, 5, 0, 0));
        TextView pay = roseButton("Pay " + money(subscriptionAmount) + " with Cashfree");
        pay.setOnClickListener(view -> startCashfreeSubscriptionPayment(pay));
        banner.addView(pay, margin(-1, dp(48), 0, 12, 0, 0));
        return banner;
    }

    private View partnerBillingCard() {
        LinearLayout card = vertical();
        card.setPadding(dp(18), dp(16), dp(18), dp(16));
        card.setBackground(stroke(Color.WHITE, Color.rgb(235, 215, 220), dp(18)));
        card.addView(text("Partner Billing", 17, BLACK, true));
        if (partnerBillingStatus == null) {
            card.addView(text(partnerBillingLoading ? "Loading billing status..." : "Billing status unavailable", 12, MUTED, false), margin(-1, -2, 0, 6, 0, 0));
            return card;
        }

        // New monetization fields from GET /partners/billing/status.
        String model = partnerBillingStatus.optString("billingModel",
                partnerBillingStatus.optString("kind", "subscription"));
        boolean active = partnerBillingStatus.optBoolean("active", false);
        boolean withinTrial = partnerBillingStatus.optBoolean("withinTrial", false);
        int trialDaysLeft = partnerBillingStatus.optInt("trialDaysRemaining", 0);
        double amount = partnerBillingStatus.optDouble("amount",
                partnerBillingStatus.optDouble("subscriptionAmount", 0));

        if ("commission".equals(model)) {
            buildCleaningBillingCard(card, withinTrial, trialDaysLeft);
        } else {
            buildSubscriptionBillingCard(card, active, withinTrial, trialDaysLeft, amount);
        }
        return card;
    }

    // Cleaning partners: 25% commission model, free for the first launch days.
    private void buildCleaningBillingCard(LinearLayout card, boolean withinTrial, int trialDaysLeft) {
        int percent = partnerBillingStatus.optInt("cleaningCommissionPercent",
                (int) Math.round(partnerBillingStatus.optDouble("cleaningCommissionRate", 0.25) * 100));
        card.addView(text("Commission plan", 14, BLACK, true), margin(-1, -2, 0, 10, 0, 2));
        if (withinTrial) {
            card.addView(text("Free launch period · " + trialDaysLeft + (trialDaysLeft == 1 ? " day left" : " days left"), 12, GREEN, true), margin(-1, -2, 0, 2, 0, 2));
            card.addView(text("You keep 100% of your earnings during the free period. After it ends, the platform fee is " + percent + "% per completed job. No monthly subscription.", 12, MUTED, false));
        } else {
            card.addView(text("Platform fee: " + percent + "% per completed job. No monthly subscription — you only pay a commission on jobs you complete.", 12, MUTED, false));
        }

        JSONObject summary = partnerBillingStatus.optJSONObject("commissionSummary");
        if (summary != null) {
            long jobs = summary.optLong("jobs", 0);
            double gross = summary.optDouble("grossAmount", 0);
            double commission = summary.optDouble("commissionAmount", 0);
            double net = summary.optDouble("netPayable", 0);
            LinearLayout box = vertical();
            box.setPadding(dp(12), dp(10), dp(12), dp(10));
            box.setBackground(stroke(Color.rgb(255, 249, 250), Color.rgb(240, 222, 227), dp(12)));
            box.addView(text("Earnings summary", 12, BLACK, true));
            box.addView(text(jobs + (jobs == 1 ? " completed job" : " completed jobs"), 11, MUTED, false), margin(-1, -2, 0, 4, 0, 0));
            box.addView(text("Gross: " + money(gross) + "  ·  Platform fee: " + money(commission), 11, MUTED, false), margin(-1, -2, 0, 2, 0, 0));
            box.addView(text("Your net: " + money(net), 12, GREEN, true), margin(-1, -2, 0, 2, 0, 0));
            card.addView(box, margin(-1, -2, 0, 12, 0, 0));
        }
    }

    // Subscription partners: flat monthly fee, trial-aware with a Cashfree pay
    // button when expired. Uses the NEW Cashfree checkout, not Razorpay.
    private void buildSubscriptionBillingCard(LinearLayout card, boolean active, boolean withinTrial, int trialDaysLeft, double amount) {
        double subscriptionAmount = partnerBillingStatus.optDouble("subscriptionAmount", amount > 0 ? amount : 299);
        String expiresLabel = formatBillingDate(partnerBillingStatus.optString("subscriptionExpiresAt", ""));
        card.addView(text("Monthly subscription", 14, BLACK, true), margin(-1, -2, 0, 10, 0, 2));

        if (withinTrial) {
            card.addView(text("Free launch period · " + trialDaysLeft + (trialDaysLeft == 1 ? " day left" : " days left"), 12, GREEN, true), margin(-1, -2, 0, 2, 0, 2));
            card.addView(text("You are receiving bookings free of charge. After the free period, keep your subscription active for " + money(subscriptionAmount) + "/month to continue receiving booking requests.", 12, MUTED, false));
        } else if (active) {
            card.addView(text(TextUtils.isEmpty(expiresLabel) ? "Subscription active" : "Subscription active until " + expiresLabel, 12, GREEN, true), margin(-1, -2, 0, 2, 0, 2));
            card.addView(text(money(subscriptionAmount) + " per month keeps your bookings flowing.", 12, MUTED, false));
        } else {
            card.addView(text("Subscription expired", 12, ROSE_DARK, true), margin(-1, -2, 0, 2, 0, 2));
            card.addView(text("You are not receiving new bookings. Pay " + money(subscriptionAmount) + " to reactivate your subscription for the next month and start getting booking requests again.", 12, MUTED, false));
        }

        // Pay button appears whenever a subscription payment is due (expired).
        if (!active && !withinTrial) {
            TextView pay = roseButton("Pay " + money(subscriptionAmount) + " with Cashfree");
            pay.setOnClickListener(view -> startCashfreeSubscriptionPayment(pay));
            card.addView(pay, margin(-1, dp(48), 0, 14, 0, 0));
        }
    }

    private String money(double value) {
        if (value == Math.rint(value)) return "₹" + (long) value;
        return "₹" + String.format(Locale.ENGLISH, "%.2f", value);
    }

    // Formats an ISO date (e.g. subscriptionExpiresAt) as "12 Nov 2026" in IST.
    private String formatBillingDate(String iso) {
        if (TextUtils.isEmpty(iso)) return "";
        try {
            java.text.SimpleDateFormat parser = new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss", Locale.ENGLISH);
            parser.setTimeZone(java.util.TimeZone.getTimeZone("UTC"));
            java.util.Date date = parser.parse(iso.length() >= 19 ? iso.substring(0, 19) : iso);
            java.text.SimpleDateFormat out = new java.text.SimpleDateFormat("d MMM yyyy", Locale.ENGLISH);
            out.setTimeZone(java.util.TimeZone.getTimeZone("Asia/Kolkata"));
            return date == null ? "" : out.format(date);
        } catch (Exception error) {
            return "";
        }
    }

    private void loadPartnerBillingStatus() {
        partnerBillingLoading = true;
        backendClient.fetchBillingStatus(new BackendClient.JsonCallback() {
            @Override public void onSuccess(JSONObject object) {
                partnerBillingLoading = false;
                partnerBillingStatus = object;
                if ("earnings".equals(activeTab)) showEarnings();
            }
            @Override public void onError(String message) {
                partnerBillingLoading = false;
                if ("earnings".equals(activeTab)) Toast.makeText(MainActivity.this, "Billing status could not be loaded", Toast.LENGTH_SHORT).show();
            }
        });
    }

    // ── NEW: Cashfree subscription payment. Fully separate from the Razorpay
    //        startPartnerBillingPayment()/onPaymentSuccess() flow below, which
    //        is left unchanged. ──────────────────────────────────────────────
    private void startCashfreeSubscriptionPayment(TextView button) {
        button.setEnabled(false);
        button.setText("Preparing secure payment...");
        backendClient.createCashfreeSubscriptionOrder(new BackendClient.JsonCallback() {
            @Override public void onSuccess(JSONObject object) {
                button.setEnabled(true);
                button.setText("Pay with Cashfree");
                JSONObject order = object.optJSONObject("order");
                String sessionId = order == null ? "" : order.optString("paymentSessionId", "");
                String orderId = order == null ? "" : order.optString("orderId", "");
                String env = object.optString("env", "SANDBOX");
                if (order == null || TextUtils.isEmpty(sessionId) || TextUtils.isEmpty(orderId)) {
                    Toast.makeText(MainActivity.this, "Invalid payment response", Toast.LENGTH_LONG).show();
                    return;
                }
                pendingCashfreeOrderId = orderId;
                try {
                    Intent intent = new Intent(MainActivity.this, CashfreeCheckoutActivity.class);
                    intent.putExtra(CashfreeCheckoutActivity.EXTRA_PAYMENT_SESSION_ID, sessionId);
                    intent.putExtra(CashfreeCheckoutActivity.EXTRA_ENV, env);
                    intent.putExtra(CashfreeCheckoutActivity.EXTRA_ORDER_ID, orderId);
                    startActivityForResult(intent, REQ_CASHFREE_CHECKOUT);
                } catch (Exception error) {
                    pendingCashfreeOrderId = "";
                    Toast.makeText(MainActivity.this, "Unable to open payment checkout", Toast.LENGTH_LONG).show();
                }
            }
            @Override public void onError(String message) {
                button.setEnabled(true);
                button.setText("Try payment again");
                Toast.makeText(MainActivity.this, safeUserError(message), Toast.LENGTH_LONG).show();
            }
        });
    }

    private void verifyCashfreeSubscription(String orderId) {
        if (TextUtils.isEmpty(orderId)) return;
        backendClient.verifyCashfreeSubscription(orderId, new BackendClient.JsonCallback() {
            @Override public void onSuccess(JSONObject object) {
                JSONObject billing = object.optJSONObject("billing");
                if (billing != null) partnerBillingStatus = billing;
                Toast.makeText(MainActivity.this, "Subscription activated. You will keep receiving bookings.", Toast.LENGTH_LONG).show();
                if ("earnings".equals(activeTab)) showEarnings();
                else if ("home".equals(activeTab)) showDashboard();
            }
            @Override public void onError(String message) {
                // Payment may still be settling via webhook; refresh status.
                Toast.makeText(MainActivity.this, "Payment is being confirmed. This can take a moment.", Toast.LENGTH_LONG).show();
                loadPartnerBillingStatus();
            }
        });
    }

    private void startPartnerBillingPayment(TextView button) {
        button.setEnabled(false);
        button.setText("Preparing secure payment...");
        backendClient.createBillingOrder(new BackendClient.JsonCallback() {
            @Override public void onSuccess(JSONObject object) {
                button.setEnabled(true);
                JSONObject order = object.optJSONObject("order");
                String keyId = object.optString("keyId", "");
                if (order == null || TextUtils.isEmpty(keyId) || TextUtils.isEmpty(order.optString("id"))) {
                    Toast.makeText(MainActivity.this, "Invalid payment response", Toast.LENGTH_LONG).show();
                    return;
                }
                activeBillingOrderId = order.optString("id");
                try {
                    Checkout checkout = new Checkout();
                    checkout.setKeyID(keyId);
                    checkout.setImage(R.mipmap.ic_launcher);
                    JSONObject options = new JSONObject();
                    options.put("name", "ApnaServo Partner");
                    options.put("description", "Partner billing payment");
                    options.put("order_id", activeBillingOrderId);
                    options.put("currency", order.optString("currency", "INR"));
                    options.put("amount", order.optLong("amount"));
                    JSONObject retry = new JSONObject(); retry.put("enabled", true); retry.put("max_count", 4); options.put("retry", retry);
                    JSONObject theme = new JSONObject(); theme.put("color", "#E12A53"); options.put("theme", theme);
                    checkout.open(MainActivity.this, options);
                } catch (Exception error) {
                    activeBillingOrderId = "";
                    Toast.makeText(MainActivity.this, "Unable to open payment checkout", Toast.LENGTH_LONG).show();
                }
            }
            @Override public void onError(String message) {
                button.setEnabled(true);
                button.setText("Try payment again");
                Toast.makeText(MainActivity.this, safeUserError(message), Toast.LENGTH_LONG).show();
            }
        });
    }

    @Override public void onPaymentSuccess(String paymentId, PaymentData data) {
        String orderId = data == null ? activeBillingOrderId : data.getOrderId();
        String signature = data == null ? "" : data.getSignature();
        if (TextUtils.isEmpty(orderId) || TextUtils.isEmpty(paymentId) || TextUtils.isEmpty(signature)) {
            Toast.makeText(this, "Payment received but verification data is missing. Contact support.", Toast.LENGTH_LONG).show();
            return;
        }
        backendClient.verifyBillingPayment(orderId, paymentId, signature, new BackendClient.JsonCallback() {
            @Override public void onSuccess(JSONObject object) {
                activeBillingOrderId = "";
                partnerBillingStatus = object.optJSONObject("billing");
                Toast.makeText(MainActivity.this, "Payment verified successfully", Toast.LENGTH_LONG).show();
                showEarnings();
            }
            @Override public void onError(String message) {
                Toast.makeText(MainActivity.this, "Payment verification pending. Do not pay again; contact support.", Toast.LENGTH_LONG).show();
            }
        });
    }

    @Override public void onPaymentError(int code, String response, PaymentData data) {
        activeBillingOrderId = "";
        Toast.makeText(this, "Payment was not completed. You can try again.", Toast.LENGTH_LONG).show();
    }

