    private void shareReferralCode(String code) {
        if (TextUtils.isEmpty(code)) {
            Toast.makeText(this, "Referral code is not available yet", Toast.LENGTH_SHORT).show();
            return;
        }
        String message = "Join ApnaServo as a partner and start earning! Use my referral code " + code
                + " when you register. Download: https://apnaservo.com/partner";
        Intent share = new Intent(Intent.ACTION_SEND);
        share.setType("text/plain");
        share.putExtra(Intent.EXTRA_TEXT, message);
        startActivity(Intent.createChooser(share, "Share referral code"));
    }

    private void loadReferralData(LinearLayout listHolder) {
        referralLoading = true;
        backendClient.fetchReferrals(new BackendClient.JsonCallback() {
            @Override
            public void onSuccess(JSONObject object) {
                referralLoading = false;
                referralData = object;
                if ("referral".equals(currentNavState != null ? currentNavState.screen : "")) {
                    listHolder.removeAllViews();
                    renderReferralList(listHolder);
                }
            }
            @Override
            public void onError(String message) {
                referralLoading = false;
                listHolder.removeAllViews();
                listHolder.addView(referralEmptyState("Could not load referrals", "Check your network and try again."));
            }
        });
    }

    private void renderReferralList(LinearLayout container) {
        if (referralData == null) return;

        JSONObject summary = referralData.optJSONObject("summary");
        JSONArray items = referralData.optJSONArray("referrals");

        // Summary card
        container.addView(referralSummaryCard(summary), margin(-1, -2, 0, 0, 0, 14));

        // List header
        TextView listHeading = text("Your Referrals", 15, BLACK, true);
        container.addView(listHeading, margin(-1, -2, 0, 0, 0, 10));

        if (items == null || items.length() == 0) {
            container.addView(referralEmptyState("No referrals yet", "Share your code with other service partners to get started."));
            return;
        }

        LinearLayout listCard = vertical();
        listCard.setPadding(dp(18), dp(8), dp(18), dp(8));
        listCard.setBackground(stroke(Color.WHITE, Color.rgb(248, 224, 230), dp(22)));
        listCard.setElevation(dp(7));

        for (int i = 0; i < items.length(); i++) {
            JSONObject item = items.optJSONObject(i);
            if (item == null) continue;
            if (i > 0) listCard.addView(profileDivider(), margin(-1, 1, 58, 4, 0, 4));
            listCard.addView(referralRow(item));
        }
        container.addView(listCard);
    }

