        row.addView(initial, new LinearLayout.LayoutParams(dp(52), dp(52)));

        LinearLayout copy = vertical();
        copy.setPadding(dp(14), 0, dp(8), 0);
        copy.addView(text(name, 15, BLACK, true));
        copy.addView(referralProgressLabel(status, jobCount, threshold), margin(-1, -2, 0, 5, 0, 0));
