    private TextView referralProgressLabel(String status, int jobCount, int threshold) {
        String label;
        int color;
        if ("eligible".equals(status)) {
            label = "Completed " + threshold + "/" + threshold + " jobs";
            color = GREEN;
        } else if ("in_progress".equals(status)) {
            label = jobCount + "/" + threshold + " jobs completed";
            color = Color.rgb(200, 110, 20);
        } else {
            label = "Registered · awaiting first job";
            color = MUTED;
        }
        return text(label, 12, color, false);
    }

    private TextView referralStatusChip(String status, int jobCount, int threshold) {
        String label;
        int textColor;
        int bgColor;
        if ("eligible".equals(status)) {
            label = "Eligible";
            textColor = GREEN;
            bgColor = Color.rgb(226, 249, 234);
        } else if ("in_progress".equals(status)) {
            label = jobCount + "/" + threshold;
            textColor = Color.rgb(180, 90, 10);
            bgColor = Color.rgb(255, 242, 224);
        } else {
            label = "Pending";
            textColor = Color.rgb(100, 100, 112);
            bgColor = Color.rgb(242, 242, 246);
        }
        TextView chip = text(label, 11, textColor, true);
        chip.setGravity(Gravity.CENTER);
        chip.setPadding(dp(10), dp(5), dp(10), dp(5));
        chip.setBackground(round(bgColor, dp(12)));
        return chip;
    }

