    private void resetMainScroll() {
        if (mainScroll != null) {
            mainScroll.post(() -> mainScroll.smoothScrollTo(0, 0));
        }
    }

    private void clearContentForScreen(String screenKey) {
        if (content == null) {
            return;
        }
        boolean directory = "laundry_partners".equals(screenKey);
        if (bottomNavigation != null) bottomNavigation.setVisibility(directory ? View.GONE : View.VISIBLE);
        if (mainScroll != null) mainScroll.setPadding(0, 0, 0, directory ? dp(12) : dp(76));
        content.setPadding(dp(16), directory ? dp(18) : dp(20), dp(16), directory ? dp(24) : dp(8));
        removeServiceStatusActionDock();
        removeServiceStatusSnackbar();
        boolean animate = shouldAnimateScreen(screenKey);
        int animationGeneration = ++contentAnimationGeneration;
        content.animate().cancel();
        content.setLayerType(animate ? View.LAYER_TYPE_HARDWARE : View.LAYER_TYPE_NONE, null);
        content.setAlpha(animate ? 0f : 1f);
        content.setTranslationY(animate ? dp(8) : 0f);
        content.removeAllViews();
        if (animate) {
            content.post(() -> {
                if (content == null || animationGeneration != contentAnimationGeneration) {
                    return;
                }
                content.animate()
                        .alpha(1f)
                        .translationY(0f)
                        .setDuration(180)
                        .setInterpolator(new DecelerateInterpolator(1.35f))
                        .withEndAction(() -> {
                            if (content != null) {
                                content.setLayerType(View.LAYER_TYPE_NONE, null);
                            }
                        })
                        .start();
                animateVisibleChildren();
            });
        }
    }

    private boolean shouldAnimateScreen(String screenKey) {
        long now = System.currentTimeMillis();
        String key = TextUtils.isEmpty(screenKey) ? "screen" : screenKey;
        boolean changed = !key.equals(lastRenderedScreen);
        lastRenderedScreen = key;
        if (!changed || now - lastContentAnimationAt < 140) {
            return false;
        }
        lastContentAnimationAt = now;
        return true;
    }

    private void animateVisibleChildren() {
        int count = Math.min(content.getChildCount(), 8);
        for (int index = 0; index < count; index++) {
            View child = content.getChildAt(index);
            child.animate().cancel();
            child.setAlpha(0f);
            child.setTranslationY(dp(7 + Math.min(index, 3) * 2));
            child.animate()
                    .alpha(1f)
                    .translationY(0f)
                    .setStartDelay(index * 14L)
                    .setDuration(190)
                    .setInterpolator(new DecelerateInterpolator(1.45f))
                    .start();
        }
    }

    private void setDefaultScrollPadding() {
        if (mainScroll != null) {
            mainScroll.setPadding(0, 0, 0, dp(76));
        }
    }

    private void setSupportChatScrollPadding() {
        if (mainScroll != null) {
            mainScroll.setPadding(0, 0, 0, dp(158));
        }
    }

    private void installPartnerKeyboardLift() {
        View root = findViewById(android.R.id.content);
        if (root == null || keyboardLiftRoot == root) {
            return;
        }
        keyboardLiftRoot = root;
        root.getViewTreeObserver().addOnGlobalLayoutListener(() -> {
            if (partnerSupportInputDock == null || mainScroll == null || currentNavState == null
                    || (!"support_chat".equals(currentNavState.screen) && !"booking_chat".equals(currentNavState.screen))) {
                if (partnerSupportInputDock != null) {
                    partnerSupportInputDock.setTranslationY(0f);
                }
                return;
            }

            Rect visibleFrame = new Rect();
            root.getWindowVisibleDisplayFrame(visibleFrame);
            int rootHeight = root.getRootView().getHeight();
            int keyboardHeight = rootHeight - visibleFrame.bottom;
            boolean keyboardOpen = keyboardHeight > dp(140);

            if (keyboardOpen) {
                int dockBottom = partnerSupportInputDock.getBottom();
                int lift = Math.max(0, dockBottom - visibleFrame.bottom + dp(10));
                partnerSupportInputDock.setTranslationY(-lift);
                mainScroll.setPadding(0, 0, 0, lift + partnerSupportInputDock.getHeight() + dp(104));
                if (content != null) {
                    mainScroll.post(() -> mainScroll.smoothScrollTo(0, content.getBottom()));
                }
            } else {
                partnerSupportInputDock.setTranslationY(0f);
                setSupportChatScrollPadding();
            }
        });
    }

    private void removePartnerSupportInputDock() {
        if (appRoot != null && partnerSupportInputDock != null) {
            partnerSupportInputDock.setTranslationY(0f);
            appRoot.removeView(partnerSupportInputDock);
        }
        partnerSupportInputDock = null;
        supportChatInput = null;
        supportChatMessages = null;
        supportStatusViews.clear();
        setDefaultScrollPadding();
    }

    private void removeServiceStatusActionDock() {
        if (appRoot != null && serviceStatusActionDock != null) {
            serviceStatusActionDock.animate().cancel();
            serviceStatusActionDock.setTranslationY(0f);
            appRoot.removeView(serviceStatusActionDock);
        }
        serviceStatusActionDock = null;
        setDefaultScrollPadding();
    }

    private void removeServiceStatusSnackbar() {
        if (appRoot != null && serviceStatusSnackbar != null) {
            serviceStatusSnackbar.animate().cancel();
            appRoot.removeView(serviceStatusSnackbar);
        }
        serviceStatusSnackbar = null;
    }

