    private View notificationsCard() {
        LinearLayout card = vertical();
        int shown = 0;
        for (PartnerBooking booking : bookings) {
            if (isPending(booking) && shown < 8) {
                card.addView(notificationRow(R.drawable.ic_partner_dash_bell, "New request available", bookingTitle(booking) + " â€¢ " + bookingSlot(booking), ROSE, ROSE_SOFT, () -> showNewRequest(booking)));
                shown++;
            } else if (isActive(booking) && shown < 8) {
                card.addView(notificationRow(R.drawable.ic_partner_stat_briefcase, "Booking in progress", bookingTitle(booking) + " â€¢ " + statusPillText(booking), GREEN, Color.rgb(231, 249, 237), () -> showOrderDetail(booking)));
                shown++;
            }
        }
        if (shown == 0) {
            card.addView(notificationEmptyState());
        }
        return card;
    }

    private void renderPartnerNotifications(LinearLayout list, JSONArray notifications, boolean append, int page, int total) {
        View previousLoadMore = list.findViewWithTag("notification_load_more");
        if (previousLoadMore != null) {
            list.removeView(previousLoadMore);
        }
        if (!append) {
            list.removeAllViews();
        }
        if (notifications == null || notifications.length() == 0) {
            if (!append) {
                list.addView(notificationEmptyState());
            }
            return;
        }
        for (int i = 0; i < notifications.length(); i++) {
            JSONObject item = notifications.optJSONObject(i);
            if (item == null) {
                continue;
            }
            list.addView(partnerNotificationRow(item), margin(-1, -2, 0, 0, 0, 10));
        }
        if (page * NOTIFICATION_PAGE_SIZE < total) {
            TextView loadMore = text("Load more", 13, ROSE, true);
            loadMore.setTag("notification_load_more");
            loadMore.setGravity(Gravity.CENTER);
            loadMore.setBackground(stroke(Color.WHITE, LINE, dp(14)));
            loadMore.setOnClickListener(view -> {
                loadMore.setEnabled(false);
                loadMore.setText("Loading...");
                loadPartnerNotifications(list, page + 1, true);
            });
            list.addView(loadMore, margin(-1, 46, 0, 4, 0, 12));
        }
    }

    private View partnerNotificationRow(JSONObject item) {
        String title = item.optString("title", "System update");
        String body = item.optString("body", "");
        String category = item.optString("category", "");
        int accent = "booking_request".equals(category) ? ROSE : "payment".equals(category) ? GREEN : ROSE;
        int bg = accent == GREEN ? Color.rgb(231, 249, 237) : ROSE_SOFT;
        return notificationRow(R.drawable.ic_partner_dash_bell, title, body + " â€¢ " + shortNotificationDate(item.optString("createdAt", "")), accent, bg, () -> {
            backendClient.markNotificationRead(item.optString("id", ""));
            partnerNotificationUnreadCount = Math.max(0, partnerNotificationUnreadCount - 1);
            JSONObject data = item.optJSONObject("data");
            String actionType = notificationJsonString(item, data,
                    "actionType", "action_type", "push_action_type", "click_action", "screen", "route");
            String actionId = notificationJsonString(item, data,
                    "actionId", "action_id", "push_action_id", "targetId", "target_id");
            String bookingId = notificationJsonString(item, data,
                    "bookingId", "booking_id", "bookingCode", "booking_code");
            String rawType = notificationJsonString(item, data,
                    "type", "event", "category", "notificationType", "notification_type");
            String status = notificationJsonString(item, data,
                    "status", "bookingStatus", "booking_status");
            actionType = normalizePartnerDeepLinkAction(actionType, rawType, status, bookingId, actionId);
            if (TextUtils.isEmpty(actionId) && isPartnerBookingDeepLink(actionType)) {
                actionId = bookingId;
            }
            if (TextUtils.isEmpty(bookingId) && isPartnerBookingDeepLink(actionType)) {
                bookingId = actionId;
            }
            if ("OPEN_NOTIFICATIONS".equalsIgnoreCase(actionType)) {
                showNotifications();
                return;
            }
            if ("OPEN_PARTNER_HOME".equalsIgnoreCase(actionType)
                    || "OPEN_HOME".equalsIgnoreCase(actionType)
                    || "OPEN_OFFERS".equalsIgnoreCase(actionType)) {
                showDashboard();
                return;
            }
            if ("OPEN_SUPPORT".equalsIgnoreCase(actionType)) {
                showSupportTool();
                return;
            }
            boolean openChat = "OPEN_BOOKING_CHAT".equalsIgnoreCase(actionType);
            if (!"OPEN_PARTNER_BOOKING".equalsIgnoreCase(actionType)
                    && !"OPEN_BOOKING".equalsIgnoreCase(actionType)
                    && !"OPEN_PAYMENT".equalsIgnoreCase(actionType)
                    && !openChat) {
                return;
            }
            bookingId = TextUtils.isEmpty(actionId) ? bookingId : actionId;
            openPartnerBookingDestination(bookingId, openChat);
        });
    }

    private String notificationJsonString(JSONObject item, JSONObject data, String... keys) {
        if (keys == null) return "";
        for (String key : keys) {
            String value = item == null ? "" : item.optString(key, "");
            if (TextUtils.isEmpty(value) && data != null) {
                value = data.optString(key, "");
            }
            if (!TextUtils.isEmpty(value)) {
                return value.trim();
            }
        }
        return "";
    }

