    private boolean matchesBookingFilter(PartnerBooking booking) {
        if ("all".equals(bookingFilter)) {
            return isBookingHistoryVisible(booking);
        }
        if ("ongoing".equals(bookingFilter)) {
            return isBookingHistoryVisible(booking) && isActive(booking);
        }
        if ("completed".equals(bookingFilter)) {
            return isBookingHistoryVisible(booking) && isFinishedForPartner(booking);
        }
        return isBookingHistoryVisible(booking)
                && (cancelledIds.contains(booking.id) || "cancelled".equalsIgnoreCase(booking.status));
    }

    private boolean isBookingHistoryVisible(PartnerBooking booking) {
        if (booking == null || TextUtils.isEmpty(booking.id) || isPending(booking)) return false;
        String status = normalizedStatus(booking);
        return acceptedIds.contains(booking.id)
                || completedIds.contains(booking.id)
                || "accepted".equals(status)
                || "on_the_way".equals(status)
                || "arrived".equals(status)
                || "started".equals(status)
                || "amount_pending".equals(status)
                || "completed".equals(status);
    }

