    private void pickStatementDate(Calendar target, TextView targetView, String label) {
        DatePickerDialog picker = new DatePickerDialog(
                this,
                (view, year, month, dayOfMonth) -> {
                    target.set(Calendar.YEAR, year);
                    target.set(Calendar.MONTH, month);
                    target.set(Calendar.DAY_OF_MONTH, dayOfMonth);
                    targetView.setText(label + "\n" + formatApiDate(target));
                },
                target.get(Calendar.YEAR),
                target.get(Calendar.MONTH),
                target.get(Calendar.DAY_OF_MONTH)
        );
        showDialogSafely(picker);
    }

    private String formatApiDate(Calendar calendar) {
        return new SimpleDateFormat("yyyy-MM-dd", Locale.US).format(calendar.getTime());
    }

    private void downloadJobStatement(String fromDate, String toDate) {
        Toast.makeText(this, "Preparing job statement...", Toast.LENGTH_SHORT).show();
        backendClient.downloadStatement(fromDate, toDate, new BackendClient.PdfCallback() {
            @Override
            public void onSuccess(byte[] bytes, String fileName) {
                if (!isValidPdf(bytes)) {
                    Toast.makeText(MainActivity.this, "Server did not return a valid PDF statement", Toast.LENGTH_LONG).show();
                    return;
                }
                try {
                    File dir = getExternalFilesDir(Environment.DIRECTORY_DOWNLOADS);
                    if (dir == null) {
                        dir = getCacheDir();
                    }
                    if (!dir.exists()) {
                        dir.mkdirs();
                    }
                    String safeName = TextUtils.isEmpty(fileName) ? "apnaservo-job-statement.pdf" : fileName.trim();
                    if (!safeName.toLowerCase(Locale.US).endsWith(".pdf")) safeName += ".pdf";
                    safeName = safeName.replaceAll("[^a-zA-Z0-9._-]", "-");
                    File output = new File(dir, safeName);
                    try (FileOutputStream stream = new FileOutputStream(output)) {
                        stream.write(bytes);
                    }
                    Toast.makeText(MainActivity.this, "Statement downloaded", Toast.LENGTH_SHORT).show();
                    openStatementPdf(output);
                } catch (Exception error) {
                    Toast.makeText(MainActivity.this, "Could not save PDF", Toast.LENGTH_SHORT).show();
                }
            }

            @Override
            public void onError(String message) {
                Toast.makeText(MainActivity.this, TextUtils.isEmpty(message) ? "Statement download failed" : message, Toast.LENGTH_LONG).show();
            }
        });
    }

    private boolean isValidPdf(byte[] bytes) {
        return bytes != null && bytes.length >= 5
                && bytes[0] == '%' && bytes[1] == 'P' && bytes[2] == 'D'
                && bytes[3] == 'F' && bytes[4] == '-';
    }

    private void openStatementPdf(File file) {
        try {
            Uri uri = FileProvider.getUriForFile(this, getPackageName() + ".fileprovider", file);
            Intent intent = new Intent(Intent.ACTION_VIEW);
            intent.setDataAndType(uri, "application/pdf");
            intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
            startActivity(Intent.createChooser(intent, "Open Job Statement"));
        } catch (Exception error) {
            Toast.makeText(this, "PDF saved. Install a PDF viewer to open it.", Toast.LENGTH_LONG).show();
        }
    }

