    private String bookingTitle(PartnerBooking booking) {
        String service = booking.service == null ? "" : booking.service.toLowerCase(Locale.ROOT);
        if (isLaundryText(service)) {
            return "Laundry";
        }
        if (isRoText(service)) {
            return "RO Service";
        }
        if (service.contains("ac")) {
            String acType = customerSelectedDetail(booking);
            return TextUtils.isEmpty(acType) ? "AC Repair & Service" : acType;
        }
        if (service.contains("clean")) {
            // Show exactly what the customer picked, e.g. "Bathroom Cleaning",
            // "Sofa Cleaning", "Full Home Deep Cleaning". Falls back to a generic
            // label only when the customer left it unspecified.
            String cleaningType = customerSelectedDetail(booking);
            return TextUtils.isEmpty(cleaningType) ? "Cleaning Service" : cleaningType;
        }
        if (service.contains("appliance")) {
            String applianceType = customerSelectedDetail(booking);
            return TextUtils.isEmpty(applianceType) ? "Appliance Service" : applianceType;
        }
        String otherDetail = customerSelectedDetail(booking);
        return TextUtils.isEmpty(otherDetail) ? booking.service : otherDetail;
    }

    /**
     * Pulls the specific thing the customer selected out of {@code booking.issue}.
     * The customer app sends the chosen sub-type inside the issue text, usually
     * prefixed with "Service request - " (e.g. "Service request - Bathroom
     * Cleaning"). This strips that prefix and ignores the generic placeholder
     * the backend writes when nothing specific was chosen
     * ("Customer requested ... inspection"). Returns "" when there is no useful
     * detail.
     */
    private String customerSelectedDetail(PartnerBooking booking) {
        String issue = booking == null || booking.issue == null ? "" : booking.issue.trim();
        if (TextUtils.isEmpty(issue)) return "";
        String lower = issue.toLowerCase(Locale.ROOT);
        if (lower.startsWith("customer requested") || "service request".equals(lower)) {
            return "";
        }
        // Strip the "Service request - " / "Service request-" prefix the customer
        // app prepends for non-appliance services.
        String cleaned = issue.replaceFirst("(?i)^service request\\s*-\\s*", "").trim();
        return cleaned;
    }

    private String bookingDate(PartnerBooking booking) {
        String slot = booking.time == null ? "" : booking.time.trim();
        if (slot.contains(",")) {
            return slot.substring(0, slot.indexOf(',')).trim();
        }
        if (slot.toLowerCase(Locale.ROOT).contains("may") || slot.toLowerCase(Locale.ROOT).contains("jun")) {
            return slot;
        }
        if ("yesterday".equalsIgnoreCase(slot)) {
            return "Yesterday";
        }
        return "16 May 2026";
    }

    private String bookingSlot(PartnerBooking booking) {
        String slot = booking.time == null ? "" : booking.time.trim();
        if (slot.contains(",")) {
            return slot.substring(slot.indexOf(',') + 1).trim();
        }
        if (slot.toUpperCase(Locale.ROOT).contains("AM") || slot.toUpperCase(Locale.ROOT).contains("PM")) {
            return slot;
        }
        return "10:00 AM - 12:00 PM";
    }

    private String serviceShort(String service) {
        String value = service == null ? "" : service.toLowerCase(Locale.ROOT);
        if (isLaundryText(value)) return "LD";
        if (isRoText(value)) return "RO";
        if (value.contains("electric")) return "EL";
        if (value.contains("plumb")) return "PL";
        if (value.contains("clean")) return "CL";
        if (value.contains("paint")) return "PT";
        if (value.contains("carp")) return "CP";
        if (value.contains("road")) return "RA";
        if (value.contains("interior")) return "ID";
        if (value.contains("pest")) return "PC";
        if (value.contains("appliance")) return "AP";
        return "AC";
    }

    private int serviceAccent(String service) {
        String value = service == null ? "" : service.toLowerCase(Locale.ROOT);
        if (isLaundryText(value)) return Color.rgb(22, 147, 150);
        if (isRoText(value)) return Color.rgb(37, 111, 236);
        if (value.contains("electric")) return Color.rgb(225, 143, 31);
        if (value.contains("plumb")) return Color.rgb(33, 128, 202);
        if (value.contains("clean")) return GREEN;
        if (value.contains("pest")) return ROSE_DARK;
        if (value.contains("appliance")) return Color.rgb(137, 91, 219);
        return Color.rgb(32, 126, 226);
    }

    private int serviceBg(String service) {
        String value = service == null ? "" : service.toLowerCase(Locale.ROOT);
        if (isLaundryText(value)) return Color.rgb(229, 250, 249);
        if (isRoText(value)) return Color.rgb(232, 241, 255);
        if (value.contains("electric")) return Color.rgb(255, 249, 232);
        if (value.contains("plumb")) return Color.rgb(232, 244, 255);
        if (value.contains("clean")) return Color.rgb(229, 249, 237);
        if (value.contains("pest")) return Color.rgb(255, 236, 242);
        if (value.contains("appliance")) return Color.rgb(246, 236, 255);
        return Color.rgb(232, 243, 255);
    }

