    private View drawerIconBadge(String label) {
        int iconRes;
        if (label.contains("Dashboard")) iconRes = R.drawable.ic_partner_nav_home;
        else if (label.contains("Booking") || label.contains("Jobs")) iconRes = R.drawable.ic_partner_nav_bookings;
        else if (label.contains("Earning")) iconRes = R.drawable.ic_partner_nav_earnings;
        else if (label.contains("Plan")) iconRes = R.drawable.ic_partner_stat_shield;
        else if (label.contains("Service")) iconRes = R.drawable.ic_partner_stat_briefcase;
        else if (label.contains("Profile")) iconRes = R.drawable.ic_partner_nav_profile;
        else if (label.contains("Document")) iconRes = R.drawable.ic_partner_doc_upload;
        else if (label.contains("Refer")) iconRes = R.drawable.ic_partner_earn_gift;
        else if (label.contains("Support")) iconRes = R.drawable.ic_partner_support_headset;
        else if (label.contains("Setting")) iconRes = R.drawable.ic_partner_settings_sliders;
        else iconRes = R.drawable.ic_partner_nav_profile;
        return coloredIconBadge(iconRes, drawerIconTint(label, true), drawerIconTint(label, false), 48, 12);
    }

