    private String drawerSubtitle(String label) {
        if (label.contains("Dashboard")) return "Overview & performance";
        if (label.contains("Booking") || label.contains("Jobs")) return "Manage your bookings";
        if (label.contains("Earning")) return "Track income & payments";
        if (label.contains("Plan")) return "Subscription & free trial";
        if (label.contains("Service")) return "Manage your services";
        if (label.contains("Profile")) return "View & edit your profile";
        if (label.contains("Document")) return "Verification & documents";
        if (label.contains("Refer")) return "Invite partners, track rewards";
        if (label.contains("Support")) return "Help & support center";
        return "App & account settings";
    }

    // Per-item accent + soft background for the drawer icon badges, matching
    // the colourful treatment used on the Profile screen so each row reads at
    // a glance instead of a flat wall of rose.
    private int drawerIconTint(String label, boolean background) {
        int accent;
        int bg;
        if (label.contains("Dashboard")) { accent = ROSE; bg = ROSE_SOFT; }
        else if (label.contains("Booking") || label.contains("Jobs")) { accent = Color.rgb(37, 160, 210); bg = Color.rgb(224, 243, 251); }
        else if (label.contains("Earning")) { accent = Color.rgb(33, 172, 129); bg = Color.rgb(224, 247, 238); }
        else if (label.contains("Plan")) { accent = Color.rgb(203, 128, 24); bg = Color.rgb(255, 243, 224); }
        else if (label.contains("Service")) { accent = Color.rgb(236, 138, 48); bg = Color.rgb(255, 240, 226); }
        else if (label.contains("Profile")) { accent = Color.rgb(137, 91, 219); bg = Color.rgb(243, 236, 255); }
        else if (label.contains("Document")) { accent = Color.rgb(104, 122, 224); bg = Color.rgb(237, 239, 255); }
        else if (label.contains("Refer")) { accent = Color.rgb(224, 86, 143); bg = Color.rgb(255, 233, 242); }
        else if (label.contains("Support")) { accent = Color.rgb(37, 160, 210); bg = Color.rgb(224, 243, 251); }
        else { accent = Color.rgb(118, 109, 128); bg = Color.rgb(239, 237, 242); }
        return background ? bg : accent;
    }

