    private View profileMetricMini(String iconValue, String value, String label, int accent, int bg) {
        LinearLayout box = vertical();
        box.setGravity(Gravity.CENTER);
        TextView icon = text(iconValue, 13, accent, true);
        icon.setGravity(Gravity.CENTER);
        icon.setBackground(round(bg, dp(14)));
        box.addView(icon, new LinearLayout.LayoutParams(dp(30), dp(30)));
        TextView valueView = text(value, 16, BLACK, true);
        valueView.setGravity(Gravity.CENTER);
        box.addView(valueView, margin(-1, -2, 0, 6, 0, 0));
        TextView labelView = text(label, 10, MUTED, false);
        labelView.setGravity(Gravity.CENTER);
        labelView.setSingleLine(true);
        box.addView(labelView);
        return box;
    }

    private View profileMetricIcon(int iconRes, String value, String label, int accent, int bg, boolean withBg) {
        LinearLayout box = vertical();
        box.setGravity(Gravity.CENTER);
        box.setPadding(dp(2), 0, dp(2), 0);

        FrameLayout iconWrap = new FrameLayout(this);
        if (withBg) {
            iconWrap.setBackground(round(bg, dp(14)));
        }
        ImageView icon = new ImageView(this);
        icon.setImageResource(iconRes);
        icon.setColorFilter(accent);
        icon.setPadding(dp(withBg ? 7 : 3), dp(withBg ? 7 : 3), dp(withBg ? 7 : 3), dp(withBg ? 7 : 3));
        iconWrap.addView(icon, new FrameLayout.LayoutParams(-1, -1));
        box.addView(iconWrap, new LinearLayout.LayoutParams(dp(30), dp(30)));

        TextView valueView = text(value, 16, BLACK, true);
        valueView.setGravity(Gravity.CENTER);
        valueView.setSingleLine(true);
        box.addView(valueView, margin(-1, -2, 0, 6, 0, 0));

        TextView labelView = text(label, 10, MUTED, false);
        labelView.setGravity(Gravity.CENTER);
        labelView.setSingleLine(true);
        box.addView(labelView);
        return box;
    }

