    private View animatedBellIcon() {
        FrameLayout frame = new FrameLayout(this);
        if (!featureEnabled("partner_notifications")) {
            frame.setVisibility(View.INVISIBLE);
            return frame;
        }
        ImageView icon = new ImageView(this);
        icon.setImageResource(R.drawable.ic_partner_dash_bell);
        icon.setColorFilter(BLACK);
        icon.setPadding(dp(8), dp(10), dp(8), dp(10));
        frame.addView(icon, new FrameLayout.LayoutParams(-1, -1));
        int badgeCount = pendingCount() + partnerNotificationUnreadCount;
        if (hasUnreadIncomingRequest || badgeCount > 0) {
            TextView badge = text(badgeCount > 0 ? String.valueOf(Math.min(9, badgeCount)) : "", 8, Color.WHITE, true);
            badge.setGravity(Gravity.CENTER);
            badge.setBackground(round(ROSE, dp(8)));
            FrameLayout.LayoutParams badgeParams = new FrameLayout.LayoutParams(badgeCount > 0 ? dp(16) : dp(9), badgeCount > 0 ? dp(16) : dp(9), Gravity.RIGHT | Gravity.TOP);
            badgeParams.setMargins(0, dp(8), dp(5), 0);
            frame.addView(badge, badgeParams);
        }
        frame.setOnClickListener(view -> {
            hasUnreadIncomingRequest = false;
            stopBellAnimation();
            showNotifications();
        });
        addPressAnimation(frame);
        if (hasUnreadIncomingRequest) {
            startBellIdlePulse(frame);
        }
        return frame;
    }

