    private Bitmap partnerQrBitmap(int sizePx) {
        String role = isStaffSession() ? "Company Staff" : "Service Partner";
        String payload = "ApnaServo Digital ID\n"
                + "ID: " + partnerPublicId() + "\n"
                + "Role: " + role + "\n"
                + "Name: " + identityCardName() + "\n"
                + "Company: " + (isStaffSession() ? staffCompanyName() : "ApnaServo") + "\n"
                + "Service: " + identityCardService() + "\n"
                + "Location: " + identityCardArea() + "\n"
                + "Verification: " + (identityCardVerified() ? "Verified" : "Pending Admin Verification") + "\n"
                + "Verify this ID with ApnaServo before service entry.";
        try {
            BitMatrix matrix = new MultiFormatWriter().encode(payload, BarcodeFormat.QR_CODE, sizePx, sizePx);
            Bitmap bitmap = Bitmap.createBitmap(sizePx, sizePx, Bitmap.Config.ARGB_8888);
            for (int x = 0; x < sizePx; x++) {
                for (int y = 0; y < sizePx; y++) {
                    bitmap.setPixel(x, y, matrix.get(x, y) ? Color.rgb(78, 28, 36) : Color.WHITE);
                }
            }
            return bitmap;
        } catch (Exception ignored) {
            return qrIconBitmap(sizePx, Color.rgb(78, 28, 36));
        }
    }

    private String virtualIdSecurityCode() {
        int hash = Math.abs((partnerPublicId() + "|" + identityCardPhone() + "|" + identityCardName()).hashCode());
        return "AS-" + String.format(Locale.US, "%06d", hash % 1000000);
    }

    private Bitmap qrIconBitmap(int sizePx, int color) {
        Bitmap bitmap = Bitmap.createBitmap(sizePx, sizePx, Bitmap.Config.ARGB_8888);
        Canvas canvas = new Canvas(bitmap);
        canvas.drawColor(Color.TRANSPARENT);
        Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);
        paint.setColor(color);
        paint.setStyle(Paint.Style.STROKE);
        paint.setStrokeWidth(Math.max(2, sizePx / 14f));
        int marker = Math.max(7, sizePx / 4);
        int pad = Math.max(2, sizePx / 10);
        drawQrMarker(canvas, paint, pad, pad, marker);
        drawQrMarker(canvas, paint, sizePx - pad - marker, pad, marker);
        drawQrMarker(canvas, paint, pad, sizePx - pad - marker, marker);
        paint.setStyle(Paint.Style.FILL);
        int dot = Math.max(3, sizePx / 9);
        canvas.drawRect(sizePx / 2f - dot, sizePx / 2f - dot, sizePx / 2f + dot, sizePx / 2f + dot, paint);
        canvas.drawRect(sizePx * 0.66f, sizePx * 0.55f, sizePx * 0.66f + dot, sizePx * 0.55f + dot, paint);
        canvas.drawRect(sizePx * 0.48f, sizePx * 0.72f, sizePx * 0.48f + dot, sizePx * 0.72f + dot, paint);
        canvas.drawRect(sizePx * 0.75f, sizePx * 0.76f, sizePx * 0.75f + dot, sizePx * 0.76f + dot, paint);
        return bitmap;
    }

    private void drawQrMarker(Canvas canvas, Paint paint, int x, int y, int size) {
        canvas.drawRect(x, y, x + size, y + size, paint);
        Paint fill = new Paint(Paint.ANTI_ALIAS_FLAG);
        fill.setColor(paint.getColor());
        fill.setStyle(Paint.Style.FILL);
        int inset = Math.max(2, size / 4);
        canvas.drawRect(x + inset, y + inset, x + size - inset, y + size - inset, fill);
    }

