    private View onlineRadar() {
        FrameLayout radar = new FrameLayout(this);
        radar.setClipChildren(false);
        radar.setClipToPadding(false);
        radar.setBackground(round(Color.rgb(232, 253, 239), dp(25)));
        radar.setElevation(dp(5));
        TextView ring = new TextView(this);
        ring.setBackground(stroke(Color.TRANSPARENT, Color.rgb(174, 244, 196), dp(20)));
        FrameLayout.LayoutParams ringParams = new FrameLayout.LayoutParams(dp(40), dp(40), Gravity.CENTER);
        radar.addView(ring, ringParams);
        TextView dot = new TextView(this);
        dot.setBackground(round(online ? Color.rgb(16, 200, 86) : Color.rgb(168, 168, 168), dp(8)));
        radar.addView(dot, new FrameLayout.LayoutParams(dp(16), dp(16), Gravity.CENTER));
        if (online) {
            startHeartbeatPulse(ring);
        }
        return radar;
    }

    private void startHeartbeatPulse(View ring) {
        ring.setScaleX(0.86f);
        ring.setScaleY(0.86f);
        ring.setAlpha(0.85f);
        ring.animate()
                .scaleX(1.22f)
                .scaleY(1.22f)
                .alpha(0.18f)
                .setDuration(720)
                .withEndAction(() -> {
                    if (online && ring.getWindowToken() != null) {
                        startHeartbeatPulse(ring);
                    }
                })
                .start();
    }

