    private void showApprovalPopupIfNeeded() {
        if (prefs == null || !isPartnerApproved() || prefs.getBoolean(KEY_APPROVAL_POPUP_SHOWN, false)) {
            return;
        }
        AlertDialog dialog = new AlertDialog.Builder(this).create();
        LinearLayout sheet = vertical();
        sheet.setPadding(dp(22), dp(20), dp(22), dp(18));
        sheet.setBackground(stroke(Color.WHITE, Color.rgb(213, 240, 224), dp(22)));
        TextView title = text("Congratulations!", 22, GREEN, true);
        title.setGravity(Gravity.CENTER);
        sheet.addView(title, margin(-1, -2, 0, 0, 0, 10));
        TextView body = text("Your account has been verified successfully. You can now start accepting bookings.", 14, BLACK, true);
        body.setGravity(Gravity.CENTER);
        body.setLineSpacing(dp(3), 1f);
        sheet.addView(body, margin(-1, -2, 0, 0, 0, 18));
        TextView close = roseButton("Start Accepting Bookings");
        close.setOnClickListener(view -> {
            prefs.edit().putBoolean(KEY_APPROVAL_POPUP_SHOWN, true).apply();
            dialog.dismiss();
            showDashboard();
        });
        sheet.addView(close, margin(-1, 50, 0, 0, 0, 0));
        dialog.setView(sheet);
        dialog.setOnCancelListener(ignored -> prefs.edit().putBoolean(KEY_APPROVAL_POPUP_SHOWN, true).apply());
        dialog.setOnShowListener(d -> {
            Window window = dialog.getWindow();
            if (window != null) {
                window.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));
            }
        });
        showDialogSafely(dialog);
    }

