    private String moneyLabel(int amount) {
        return "\u20B9" + String.format(Locale.US, "%,d", amount);
    }

    private int liveJobsCount() {
        return pendingCount() + activeCount() + completedCount();
    }

    private String partnerRatingText() {
        int completed = completedCount();
        float rating = completed == 0 ? 4.8f : Math.min(5.0f, 4.6f + (completed * 0.02f));
        return String.format(Locale.US, "%.1f", rating);
    }

    private int responseRate() {
        if (backendStatsLoaded && !isStaffSession()) return backendResponseRate;
        int handled = activeCount() + completedCount();
        int total = handled + cancelledCount();
        if (total == 0) {
            return 0;
        }
        return Math.max(0, Math.min(100, Math.round((handled * 100f) / total)));
    }

    private String responseRateLabel() {
        int rate = responseRate();
        if (rate >= 90) return "Excellent";
        if (rate >= 75) return "Good";
        if (rate > 0) return "Needs attention";
        return "No responses yet";
    }

