    private View recentRequests() {
        LinearLayout list = vertical();
        list.setClipChildren(false);
        list.setClipToPadding(false);
        list.setPadding(dp(2), 0, dp(2), 0);
        list.addView(recentRequestGuide(), margin(-1, -2, 0, 0, 0, 10));
        int shown = 0;
        for (PartnerBooking booking : bookings) {
            if (isPending(booking)) {
                list.addView(requestMiniCard(booking), margin(-1, -2, 0, 0, 0, 10));
                shown++;
            }
        }
        if (shown == 0) {
            list.addView(emptyRecentRequestCard(), margin(-1, -2, 0, 0, 0, 10));
        }
        return list;
    }

    private View recentRequestGuide() {
        LinearLayout guide = horizontal();
        guide.setGravity(Gravity.CENTER_VERTICAL);
        guide.setPadding(dp(10), dp(8), dp(10), dp(8));
        guide.setBackground(stroke(Color.rgb(255, 246, 248), Color.rgb(249, 224, 230), dp(15)));
        guide.setElevation(dp(5));
        TextView state = text(online ? "ON" : "OFF", 9, online ? GREEN : MUTED, true);
        state.setGravity(Gravity.CENTER);
        state.setBackground(round(online ? Color.rgb(216, 251, 229) : Color.rgb(241, 239, 239), dp(11)));
        guide.addView(state, new LinearLayout.LayoutParams(dp(44), dp(24)));
        String message = online ? "You are visible to customers and receiving new requests" : "Go online to receive new requests";
        TextView copy = text(message, 11, BLACK, false);
        copy.setPadding(dp(12), 0, 0, 0);
        copy.setSingleLine(true);
        guide.addView(copy, new LinearLayout.LayoutParams(0, -2, 1));
        guide.setOnClickListener(view -> {
            if (!requireFeature("partner_availability", "Partner Availability")) return;
            online = !online;
            prefs.edit().putBoolean("online", online).apply();
            if (online) {
                ensurePartnerLocationReady(true);
            }
            syncPartnerStatus(true);
            showDashboard();
            fetchBackendBookings();
        });
        addPressAnimation(guide);
        return guide;
    }

