    private View orderProgress(PartnerBooking booking) {
        FrameLayout wrap = new FrameLayout(this);
        View line = new View(this);
        line.setBackgroundColor(Color.rgb(230, 222, 224));
        FrameLayout.LayoutParams lineParams = new FrameLayout.LayoutParams(-1, dp(2), Gravity.TOP | Gravity.CENTER_HORIZONTAL);
        lineParams.setMargins(dp(54), dp(22), dp(54), 0);
        wrap.addView(line, lineParams);
        LinearLayout row = horizontal();
        row.setGravity(Gravity.CENTER);
        int stage = statusStage(booking);
        row.addView(step("A", "Accept", stage >= 1), new LinearLayout.LayoutParams(0, -2, 1));
        row.addView(step("W", "On the Way", stage >= 2), new LinearLayout.LayoutParams(0, -2, 1));
        row.addView(step("R", "Arrived", stage >= 3), new LinearLayout.LayoutParams(0, -2, 1));
        row.addView(step("C", "Complete", stage >= 4), new LinearLayout.LayoutParams(0, -2, 1));
        wrap.addView(row, new FrameLayout.LayoutParams(-1, -2));
        return wrap;
    }

    private View step(String icon, String label, boolean active) {
        FrameLayout wrap = new FrameLayout(this);
        LinearLayout box = vertical();
        box.setGravity(Gravity.CENTER);
        FrameLayout circleWrap = new FrameLayout(this);
        TextView circle = text(icon, 16, active ? Color.WHITE : MUTED, true);
        circle.setGravity(Gravity.CENTER);
        circle.setBackground(stroke(active ? ROSE : Color.rgb(229, 229, 229), active ? Color.WHITE : Color.rgb(220, 220, 220), dp(20)));
        circle.setElevation(active ? dp(5) : dp(1));
        circleWrap.addView(circle, new FrameLayout.LayoutParams(dp(42), dp(42), Gravity.CENTER));
        if (active) {
            TextView check = text("\u2713", 11, ROSE, true);
            check.setGravity(Gravity.CENTER);
            check.setBackground(round(Color.WHITE, dp(9)));
            FrameLayout.LayoutParams checkParams = new FrameLayout.LayoutParams(dp(18), dp(18), Gravity.RIGHT | Gravity.BOTTOM);
            checkParams.setMargins(0, 0, dp(4), dp(1));
            circleWrap.addView(check, checkParams);
        }
        box.addView(circleWrap, new LinearLayout.LayoutParams(dp(48), dp(46)));
        TextView copy = text(label, 10, active ? BLACK : MUTED, false);
        copy.setGravity(Gravity.CENTER);
        box.addView(copy, margin(-1, -2, 0, 7, 0, 0));
        wrap.addView(box, new FrameLayout.LayoutParams(-1, -2, Gravity.CENTER));
        return wrap;
    }

    private int statusStage(PartnerBooking booking) {
        String status = booking.status == null ? "" : booking.status.toLowerCase(Locale.US);
        if (completedIds.contains(booking.id) || "completed".equals(status)) return 4;
        if ("arrived".equals(status) || "started".equals(status) || "amount_pending".equals(status)) return 3;
        if ("on_the_way".equals(status)) return 2;
        if (acceptedIds.contains(booking.id) || "accepted".equals(status)) return 1;
        return 0;
    }

