    private void showPartnerCancelBookingDialog(PartnerBooking booking) {
        if (booking == null || TextUtils.isEmpty(booking.id)) {
            Toast.makeText(this, "Booking unavailable", Toast.LENGTH_SHORT).show();
            return;
        }
        if (!"accepted".equals(normalizedStatus(booking))) {
            Toast.makeText(this, "Use support chat for active journey cancellations.", Toast.LENGTH_LONG).show();
            showPartnerSupportChat("Booking Cancellation", "I need help cancelling booking " + booking.id + ". ");
            return;
        }
        AlertDialog dialog = new AlertDialog.Builder(this).create();
        LinearLayout sheet = vertical();
        sheet.setPadding(dp(20), dp(18), dp(20), dp(18));
        sheet.setBackground(stroke(Color.WHITE, Color.rgb(250, 214, 224), dp(22)));
        sheet.addView(text("Cancel this booking?", 20, BLACK, true));
        sheet.addView(text("The customer and admin support will be notified. Please enter a clear reason before cancelling.", 12, MUTED, false), margin(-1, -2, 0, 4, 0, 14));

        EditText reason = input("Reason for cancellation", InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_CAP_SENTENCES | InputType.TYPE_TEXT_FLAG_MULTI_LINE);
        reason.setMinLines(3);
        reason.setGravity(Gravity.TOP | Gravity.LEFT);
        reason.setText("I am unable to attend this booking and need support to cancel it.");
        sheet.addView(reason, margin(-1, 96, 0, 0, 0, 14));

        TextView confirm = text("Cancel Booking", 15, Color.WHITE, true);
        confirm.setGravity(Gravity.CENTER);
        confirm.setBackground(gradient(ROSE, ROSE_DARK, dp(16)));
        confirm.setOnClickListener(view -> {
            String message = reason.getText().toString().trim();
            if (TextUtils.isEmpty(message)) {
                Toast.makeText(this, "Please enter a reason.", Toast.LENGTH_SHORT).show();
                return;
            }
            confirm.setEnabled(false);
            confirm.setText("Cancelling...");
            cancelAcceptedBookingViaSupport(booking, message, dialog);
        });
        sheet.addView(confirm, new LinearLayout.LayoutParams(-1, dp(50)));

        TextView keep = text("Keep Booking", 13, MUTED, true);
        keep.setGravity(Gravity.CENTER);
        keep.setOnClickListener(view -> dialog.dismiss());
        sheet.addView(keep, margin(-1, 38, 0, 8, 0, 0));

        dialog.setView(sheet);
        showDialogSafely(dialog);
        Window window = dialog.getWindow();
        if (window != null) {
            window.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));
        }
    }

    private void cancelAcceptedBookingViaSupport(PartnerBooking booking, String reason, AlertDialog dialog) {
        String actionKey = statusActionKey(booking, "cancelled");
        if (statusUpdatingKeys.contains(actionKey)) {
            Toast.makeText(this, "Cancellation already in progress", Toast.LENGTH_SHORT).show();
            return;
        }
        statusUpdatingKeys.add(actionKey);
        if (backendClient != null) {
            backendClient.updateBookingStatus(booking.id, "cancelled", 0, new BackendClient.JsonCallback() {
                @Override
                public void onSuccess(JSONObject object) {
                    statusUpdatingKeys.remove(actionKey);
                    if (dialog != null && dialog.isShowing()) {
                        dialog.dismiss();
                    }
                    dispatchPartnerSupportMessage("Booking Cancellation",
                            "Booking " + booking.id + " cancelled by partner. Reason: " + reason,
                            supportMessageId("PARCAN"), "", false);
                    completeLocalStatusUpdate(booking, "cancelled");
                }

                @Override
                public void onError(String message) {
                    statusUpdatingKeys.remove(actionKey);
                    Toast.makeText(MainActivity.this, "Cancel failed: " + safeUserError(message), Toast.LENGTH_LONG).show();
                }
            });
            return;
        }
        statusUpdatingKeys.remove(actionKey);
        if (dialog != null && dialog.isShowing()) {
            dialog.dismiss();
        }
        dispatchPartnerSupportMessage("Booking Cancellation",
                "Booking " + booking.id + " cancelled by partner. Reason: " + reason,
                supportMessageId("PARCAN"), "", false);
        completeLocalStatusUpdate(booking, "cancelled");
    }

