    private void acceptBooking(PartnerBooking booking) {
        if (!allowOperationalAction()) return;
        if (!isPartnerApproved()) {
            Toast.makeText(this, partnerApprovalMessage(), Toast.LENGTH_LONG).show();
            showDashboard();
            return;
        }
        if (booking == null || TextUtils.isEmpty(booking.id)) {
            Toast.makeText(this, "Booking unavailable", Toast.LENGTH_SHORT).show();
            return;
        }
        if (!online) {
            online = true;
            prefs.edit().putBoolean("online", true).apply();
            syncPartnerStatus(true);
            fetchBackendBookings();
            Toast.makeText(this, "You are online and ready to accept bookings", Toast.LENGTH_SHORT).show();
        }
        if (acceptedIds.contains(booking.id)) {
            Toast.makeText(this, "Booking already accepted", Toast.LENGTH_SHORT).show();
            showOrderDetail(booking);
            return;
        }
        if (acceptingIds.contains(booking.id)) {
            Toast.makeText(this, "Accepting booking...", Toast.LENGTH_SHORT).show();
            return;
        }
        if (!arrivalDialogBookingIds.add(booking.id)) {
            return;
        }
        showArrivalEstimateDialog(booking);
    }

    private void showArrivalEstimateDialog(PartnerBooking booking) {
        if (booking == null || TextUtils.isEmpty(booking.id)) {
            Toast.makeText(this, "Booking unavailable", Toast.LENGTH_SHORT).show();
            return;
        }
        enterScreen("arrival_estimate", booking.id);
        activeTab = "arrival_estimate";
        updateNav();
        clearContentForScreen("arrival_estimate");
        content.setBackgroundColor(Color.rgb(255, 253, 253));
        content.addView(newRequestHeader(booking, true), margin(-1, -2, 0, 0, 0, 20));
        String scheduleText = scheduledPopupText(booking);
        if (!TextUtils.isEmpty(scheduleText)) {
            content.addView(scheduledSlotBanner(scheduleText), margin(-1, -2, 0, 0, 0, 14));
        }
        content.addView(requestAvailabilityNotice(), margin(-1, -2, 0, 0, 0, 16));
        content.addView(thinDivider(), new LinearLayout.LayoutParams(-1, dp(1)));

        LinearLayout intro = horizontal();
        intro.setGravity(Gravity.CENTER_VERTICAL);
        intro.setPadding(dp(8), dp(20), dp(8), dp(18));
        ImageView travel = requestLineIcon(R.drawable.ic_partner_service_location);
        travel.setBackground(round(Color.rgb(255, 241, 245), dp(30)));
        intro.addView(travel, new LinearLayout.LayoutParams(dp(64), dp(64)));
        LinearLayout introCopy = vertical();
        introCopy.setPadding(dp(18), 0, 0, 0);
        introCopy.addView(text("When can you arrive?", 21, BLACK, true));
        TextView introBody = text("Customer will see this arrival estimate\nimmediately after you accept.", 13, MUTED, false);
        introBody.setLineSpacing(dp(3), 1f);
        introCopy.addView(introBody, margin(-1, -2, 0, 5, 0, 0));
        intro.addView(introCopy, new LinearLayout.LayoutParams(0, -2, 1));
        content.addView(intro);

        int[] minutes = {10, 15, 20, 30, 45, 60};
        String[] labels = {"Within 10 minutes", "Within 15 minutes", "Within 20 minutes", "Within 30 minutes", "Within 45 minutes", "Within 1 hour"};
        int[] selected = {3};
        int[] icons = {
                R.drawable.ic_partner_time_clock,
                R.drawable.ic_partner_time_clock,
                R.drawable.ic_partner_time_clock,
                R.drawable.ic_partner_time_clock,
                R.drawable.ic_partner_time_clock,
                R.drawable.ic_partner_time_clock
        };
        List<LinearLayout> rows = new ArrayList<>();
        List<ImageView> rowIcons = new ArrayList<>();
        List<TextView> radios = new ArrayList<>();
        for (int index = 0; index < labels.length; index++) {
            final int option = index;
            LinearLayout row = horizontal();
            row.setGravity(Gravity.CENTER_VERTICAL);
            row.setPadding(dp(14), dp(10), dp(14), dp(10));
            ImageView optionIcon = requestLineIcon(icons[index]);
            optionIcon.setBackground(round(Color.rgb(255, 242, 245), dp(22)));
            row.addView(optionIcon, new LinearLayout.LayoutParams(dp(48), dp(48)));
            TextView label = text(labels[index], 15, BLACK, index == selected[0]);
            label.setPadding(dp(18), 0, 0, 0);
            row.addView(label, new LinearLayout.LayoutParams(0, -2, 1));
            TextView radio = text(index == selected[0] ? "\u25C9" : "\u25CB", 28,
                    index == selected[0] ? ROSE : Color.rgb(190, 184, 185), false);
            radio.setGravity(Gravity.CENTER);
            row.addView(radio, new LinearLayout.LayoutParams(dp(42), dp(48)));
            applyArrivalOptionStyle(row, optionIcon, radio, index == selected[0]);
            row.setOnClickListener(view -> {
                selected[0] = option;
                for (int item = 0; item < rows.size(); item++) {
                    boolean active = item == selected[0];
                    applyArrivalOptionStyle(rows.get(item), rowIcons.get(item), radios.get(item), active);
                    TextView optionLabel = (TextView) rows.get(item).getChildAt(1);
                    optionLabel.setTextColor(active ? ROSE : BLACK);
                    optionLabel.setTypeface(Typeface.DEFAULT, active ? Typeface.BOLD : Typeface.NORMAL);
                }
            });
            addPressAnimation(row);
            rows.add(row);
            rowIcons.add(optionIcon);
            radios.add(radio);
            content.addView(row, margin(-1, 64, 8, 0, 8, 10));
        }

        TextView accept = roseButton("\u2713  Accept Booking");
        accept.setOnClickListener(view -> {
            arrivalDialogBookingIds.remove(booking.id);
            accept.setEnabled(false);
            accept.setText("Accepting...");
            acceptBookingWithArrivalEstimate(booking, minutes[selected[0]], labels[selected[0]]);
        });
        content.addView(accept, margin(-1, 56, 8, 12, 8, 4));

        if (isCleaningOwnerBooking(booking)) {
            content.addView(cleaningHelperCard(booking, true), margin(-1, -2, 8, 0, 8, 8));
        }

        TextView cancel = text("Not now", 14, MUTED, true);
        cancel.setGravity(Gravity.CENTER);
        cancel.setOnClickListener(view -> {
            arrivalDialogBookingIds.remove(booking.id);
            saveRequestForLater(booking);
        });
        content.addView(cancel, margin(-1, 44, 0, 8, 0, 8));
    }

    private void applyArrivalOptionStyle(LinearLayout row, ImageView icon, TextView radio, boolean active) {
        row.setBackground(stroke(active ? Color.rgb(255, 248, 250) : Color.WHITE,
                active ? ROSE : Color.rgb(241, 229, 232), dp(13)));
        row.setElevation(active ? dp(2) : 0f);
        icon.setColorFilter(active ? ROSE : Color.rgb(119, 52, 67));
        radio.setText(active ? "\u25C9" : "\u25CB");
        radio.setTextColor(active ? ROSE : Color.rgb(190, 184, 185));
    }

    private void acceptBookingWithArrivalEstimate(PartnerBooking booking, int arrivalMinutes, String arrivalLabel) {
        if (!allowOperationalAction()) return;
        acceptingIds.add(booking.id);
        hasUnreadIncomingRequest = false;
        stopIncomingRequestAlert();
        if (backendClient != null) {
            backendClient.acceptBooking(booking.id, arrivalMinutes, arrivalLabel, new BackendClient.JsonCallback() {
                @Override
                public void onSuccess(JSONObject object) {
                    JSONObject remote = object.optJSONObject("booking");
                    finishAcceptedBooking(remote == null ? booking : backendBookingFromJson(remote));
                }

                @Override
                public void onError(String message) {
                    acceptingIds.remove(booking.id);
                    if (isBookingUnavailableError(message)) {
                        removeTakenBooking(booking.id, "This booking has been accepted by another partner.");
                        return;
                    }
                    Toast.makeText(MainActivity.this, "Accept failed: " + message, Toast.LENGTH_LONG).show();
                    showDashboard();
                }
            });
            return;
        }
        acceptingIds.remove(booking.id);
        Toast.makeText(this, "Booking service is unavailable. Reconnect and try again.", Toast.LENGTH_LONG).show();
        showDashboard();
    }

    private void acceptBookingTransaction(PartnerBooking booking, int arrivalMinutes, String arrivalLabel) {
        DocumentReference reference = firestore.collection("bookings").document(booking.id);
        long expectedArrivalAtMillis = System.currentTimeMillis() + arrivalMinutes * 60_000L;
        firestore.runTransaction(transaction -> {
            DocumentSnapshot snapshot = transaction.get(reference);
            String status = value(snapshot, "status", "pending").toLowerCase(Locale.US);
            String assignedPartnerId = value(snapshot, "assignedPartnerId", "");
            boolean visible = "pending".equals(status) || "sent_to_partner".equals(status);
            boolean mine = partnerId().equals(assignedPartnerId);
            if (!visible && !mine) {
                throw new FirebaseFirestoreException("Booking already accepted", FirebaseFirestoreException.Code.ABORTED);
            }
            Map<String, Object> update = new HashMap<>();
            update.put("status", "accepted");
            update.put("assignedPartnerId", partnerId());
            update.put("assignedPartner", partnerPayload());
            update.put("acceptedAt", FieldValue.serverTimestamp());
            update.put("assignedAt", FieldValue.serverTimestamp());
            update.put("partnerArrivalEstimateMinutes", arrivalMinutes);
            update.put("partnerArrivalEstimateLabel", arrivalLabel);
            update.put("expectedArrivalAtMillis", expectedArrivalAtMillis);
            transaction.update(reference, update);
            return null;
        }).addOnSuccessListener(unused -> {
            writeRealtimeAcceptMirror(booking, arrivalMinutes, arrivalLabel, expectedArrivalAtMillis);
            finishAcceptedBooking(booking);
        }).addOnFailureListener(error -> {
            acceptBookingRealtimeFallback(booking, arrivalMinutes, arrivalLabel);
        });
    }

    private void acceptBookingRealtimeFallback(PartnerBooking booking, int arrivalMinutes, String arrivalLabel) {
        if (realtimeDatabase == null) {
            acceptingIds.remove(booking.id);
            Toast.makeText(this, "Accept failed. Realtime database not ready.", Toast.LENGTH_LONG).show();
            showDashboard();
            return;
        }
        realtimeDatabase.getReference("bookings").child(booking.id).runTransaction(new Transaction.Handler() {
            @Override
            public Transaction.Result doTransaction(MutableData currentData) {
                if (currentData.getValue() == null) {
                    return Transaction.abort();
                }
                String status = mutableString(currentData, "status", "pending").toLowerCase(Locale.US);
                String assignedPartnerId = mutableString(currentData, "assignedPartnerId", "");
                boolean visible = "pending".equals(status) || "sent_to_partner".equals(status);
                boolean mine = partnerId().equals(assignedPartnerId);
                if (!visible && !mine) {
                    return Transaction.abort();
                }
                currentData.child("status").setValue("accepted");
                currentData.child("assignedPartnerId").setValue(partnerId());
                currentData.child("assignedPartner").setValue(partnerRealtimePayload());
                currentData.child("acceptedAtMillis").setValue(System.currentTimeMillis());
                currentData.child("assignedAtMillis").setValue(System.currentTimeMillis());
                currentData.child("partnerArrivalEstimateMinutes").setValue(arrivalMinutes);
                currentData.child("partnerArrivalEstimateLabel").setValue(arrivalLabel);
                currentData.child("expectedArrivalAtMillis").setValue(System.currentTimeMillis() + arrivalMinutes * 60_000L);
                return Transaction.success(currentData);
            }

            @Override
            public void onComplete(DatabaseError error, boolean committed, DataSnapshot currentData) {
                if (error == null && committed) {
                    finishAcceptedBooking(booking);
                } else {
                    acceptingIds.remove(booking.id);
                    String message = error == null ? "Booking already accepted or unavailable" : error.getMessage();
                    if (isBookingUnavailableError(message)) {
                        removeTakenBooking(booking.id, "This booking has been accepted by another partner.");
                        return;
                    }
                    Toast.makeText(MainActivity.this, "Accept failed: " + message, Toast.LENGTH_LONG).show();
                    showDashboard();
                }
            }
        });
    }

    private void finishAcceptedBooking(PartnerBooking booking) {
        acceptingIds.remove(booking.id);
        hiddenTakenIds.remove(booking.id);
        acceptedIds.add(booking.id);
        cancelledIds.remove(booking.id);
        saveState();
        Toast.makeText(this, "Booking accepted. Let's go!", Toast.LENGTH_SHORT).show();
        PartnerBooking updatedBooking = new PartnerBooking(
                booking.id,
                booking.service,
                booking.issue,
                booking.customer,
                booking.address,
                booking.city,
                booking.time,
                booking.defaultAmount,
                "accepted",
                booking.lat,
                booking.lng,
                booking.createdAtMillis,
                booking.completedAtMillis,
                booking.customerPhone
        );
        replaceLocalBooking(updatedBooking);
        showOrderDetail(updatedBooking);
    }

    private void cancelBooking(PartnerBooking booking) {
        if (!allowOperationalAction()) return;
        if (booking == null || TextUtils.isEmpty(booking.id)) {
            return;
        }
        PartnerBooking current = findBooking(booking.id);
        String status = normalizedStatus(current == null ? booking : current);
        if (acceptedIds.contains(booking.id)
                || acceptingIds.contains(booking.id)
                || !("pending".equals(status) || "sent_to_partner".equals(status))) {
            stopIncomingRequestAlert();
            fetchBackendBookings();
            return;
        }
        hasUnreadIncomingRequest = false;
        stopIncomingRequestAlert();
        cancelledIds.add(booking.id);
        saveState();
        rejectBooking(booking);
        showDashboard();
    }

    private void rejectBooking(PartnerBooking booking) {
        if (booking == null
                || TextUtils.isEmpty(booking.id)
                || acceptedIds.contains(booking.id)
                || acceptingIds.contains(booking.id)) {
            fetchBackendBookings();
            return;
        }
        hasUnreadIncomingRequest = false;
        stopIncomingRequestAlert();
        if (backendClient != null) {
            backendClient.rejectBooking(booking.id, new BackendClient.JsonCallback() {
                @Override
                public void onSuccess(JSONObject object) {
                    cancelledIds.add(booking.id);
                    saveState();
                    for (int index = bookings.size() - 1; index >= 0; index--) {
                        if (bookings.get(index).id.equals(booking.id)) {
                            bookings.remove(index);
                        }
                    }
                    refreshCurrent();
                }

                @Override
                public void onError(String message) {
                    Toast.makeText(MainActivity.this, "Reject failed: " + message, Toast.LENGTH_LONG).show();
                }
            });
            return;
        }
        rejectBookingTransaction(booking);
    }

    private void rejectBookingTransaction(PartnerBooking booking) {
        DocumentReference reference = firestore.collection("bookings").document(booking.id);
        firestore.runTransaction(transaction -> {
            DocumentSnapshot snapshot = transaction.get(reference);
            Map<String, Object> update = new HashMap<>();
            if (partnerId().equals(value(snapshot, "assignedPartnerId", ""))) {
                update.put("status", "rejected");
                update.put("rejectedAt", FieldValue.serverTimestamp());
            }
            update.put("rejectedPartnerIds", FieldValue.arrayUnion(partnerId()));
            transaction.update(reference, update);
            return null;
        }).addOnSuccessListener(unused -> writeRealtimeRejectMirror(booking))
                .addOnFailureListener(error -> rejectBookingRealtimeFallback(booking));
    }

    private void rejectBookingRealtimeFallback(PartnerBooking booking) {
        if (realtimeDatabase == null) {
            Toast.makeText(this, "Reject failed. Realtime database not ready.", Toast.LENGTH_LONG).show();
            return;
        }
        realtimeDatabase.getReference("bookings").child(booking.id).runTransaction(new Transaction.Handler() {
            @Override
            public Transaction.Result doTransaction(MutableData currentData) {
                if (currentData.getValue() == null) {
                    return Transaction.abort();
                }
                if (partnerId().equals(mutableString(currentData, "assignedPartnerId", ""))) {
                    currentData.child("status").setValue("rejected");
                    currentData.child("rejectedAtMillis").setValue(System.currentTimeMillis());
                }
                currentData.child("rejectedPartnerIds").child(partnerId()).setValue(true);
                return Transaction.success(currentData);
            }

            @Override
            public void onComplete(DatabaseError error, boolean committed, DataSnapshot currentData) {
                if (error != null) {
                    Toast.makeText(MainActivity.this, "Reject failed: " + error.getMessage(), Toast.LENGTH_LONG).show();
                }
            }
        });
    }

    private void askFinalAmount(PartnerBooking booking) {
        if (backendClient == null) {
            showFinalAmountDialog(booking, null);
            return;
        }
        backendClient.getServiceChecklist(booking.service, new BackendClient.JsonCallback() {
            @Override public void onSuccess(JSONObject object) {
                showFinalAmountDialog(booking, object == null ? null : object.optJSONObject("checklist"));
            }

            @Override public void onError(String message) {
                showFinalAmountDialog(booking, null);
            }
        });
    }

