    private String serviceStatusUpdatedTime() {
        return new SimpleDateFormat("hh:mm a", Locale.US).format(new Date());
    }

    private String serviceAcceptedTime(PartnerBooking booking) {
        long timestamp = booking == null ? 0L : booking.createdAtMillis;
        if (timestamp <= 0L) {
            return bookingDate(booking) + ", " + bookingSlot(booking);
        }
        return new SimpleDateFormat("dd MMM yyyy, hh:mm a", Locale.US).format(new Date(timestamp));
    }

