    private View serviceTimelineRow(String iconText, String title, String subtitle, int stageRank, int currentRank, boolean hasNext) {
        boolean completed = stageRank == 1 || currentRank > stageRank || currentRank >= 6;
        boolean current = stageRank > 1 && currentRank == stageRank && currentRank < 6;
        int stepColor = serviceTimelineColor(stageRank);
        int circleColor = completed ? GREEN : current ? stepColor : Color.rgb(238, 238, 238);
        int textColor = completed ? GREEN : current ? stepColor : Color.rgb(108, 108, 108);
        int iconColor = completed || current ? Color.WHITE : Color.rgb(130, 130, 130);

        LinearLayout row = horizontal();
        row.setGravity(Gravity.TOP);
        row.setPadding(0, 0, 0, hasNext ? dp(1) : 0);

        FrameLayout rail = new FrameLayout(this);
        if (hasNext) {
            View line = new View(this);
            int lineColor = completed ? Color.rgb(196, 234, 210) : current ? lighten(stepColor, 210) : Color.rgb(230, 230, 230);
            line.setBackgroundColor(lineColor);
            FrameLayout.LayoutParams lineParams = new FrameLayout.LayoutParams(dp(2), dp(52), Gravity.TOP | Gravity.CENTER_HORIZONTAL);
            lineParams.setMargins(0, dp(36), 0, 0);
            rail.addView(line, lineParams);
        }
        TextView circle = text(completed ? "\u2713" : iconText, completed ? 19 : 16, iconColor, true);
        circle.setGravity(Gravity.CENTER);
        circle.setBackground(round(circleColor, dp(23)));
        circle.setElevation(current ? dp(4) : 0);
        FrameLayout.LayoutParams circleParams = new FrameLayout.LayoutParams(dp(40), dp(40), Gravity.TOP | Gravity.CENTER_HORIZONTAL);
        rail.addView(circle, circleParams);
        row.addView(rail, new LinearLayout.LayoutParams(dp(50), hasNext ? dp(72) : dp(48)));

        LinearLayout copy = vertical();
        copy.setPadding(dp(8), dp(3), 0, 0);
        copy.addView(text(title, 15, textColor, true));
        TextView detail = text(subtitle, 11, completed || current ? BLACK : MUTED, false);
        detail.setMaxLines(2);
        detail.setEllipsize(TextUtils.TruncateAt.END);
        copy.addView(detail, margin(-1, -2, 0, 3, 0, 0));
        row.addView(copy, new LinearLayout.LayoutParams(0, -2, 1));

        String pillText = completed ? "Completed" : current ? "In Progress" : "Pending";
        int pillTextColor = completed ? GREEN : current ? stepColor : MUTED;
        int pillBg = completed ? Color.rgb(231, 249, 237) : current ? lighten(stepColor, 236) : Color.rgb(246, 246, 246);
        TextView pill = pill(pillText, pillTextColor, pillBg);
        pill.setTextSize(11);
        row.addView(pill, new LinearLayout.LayoutParams(dp(82), dp(28)));

        if (current) {
            row.setAlpha(0f);
            row.setTranslationY(dp(6));
            row.post(() -> row.animate()
                    .alpha(1f)
                    .translationY(0f)
                    .setDuration(300)
                    .setInterpolator(new DecelerateInterpolator(1.4f))
                    .start());
        }
        return row;
    }

    private String amountPendingLabel(PartnerBooking booking) {
        if (paymentSubmittedByCustomer(booking)) {
            return "Payment submitted";
        }
        if ("amount_pending".equals(normalizedStatus(booking))) {
            return "Waiting for customer payment";
        }
        return "Pending";
    }

    private int serviceTimelineColor(int stageRank) {
        if (stageRank == 3) return Color.rgb(43, 111, 232);
        if (stageRank == 4) return Color.rgb(238, 139, 27);
        if (stageRank >= 6) return GREEN;
        return ROSE;
    }

    private int lighten(int color, int floor) {
        float amount = floor >= 236 ? 0.84f : 0.58f;
        int red = Math.round(Color.red(color) + (255 - Color.red(color)) * amount);
        int green = Math.round(Color.green(color) + (255 - Color.green(color)) * amount);
        int blue = Math.round(Color.blue(color) + (255 - Color.blue(color)) * amount);
        return Color.rgb(red, green, blue);
    }

    private void installServiceStatusActionDock(PartnerBooking booking) {
        removeServiceStatusActionDock();
        if (appRoot == null || mainScroll == null || booking == null) {
            return;
        }
        // Laundry owners can monitor the complete live route, but only the
        // assigned staff member can change a pickup, delivery or payment step.
        if (isReadOnlyLaundryOwnerFor(booking)) {
            setDefaultScrollPadding();
            return;
        }
        ServiceStatusStep step = nextServiceStatusStep(booking);
        if (step == null) {
            setDefaultScrollPadding();
            return;
        }
        mainScroll.setPadding(0, 0, 0, dp(214));

        LinearLayout dock = vertical();
        dock.setPadding(dp(14), dp(11), dp(14), dp(11));
        dock.setMinimumHeight(dp(118));
        dock.setBackground(stroke(Color.WHITE, Color.rgb(241, 229, 231), dp(22)));
        dock.setElevation(dp(7));

        LinearLayout header = horizontal();
        header.setGravity(Gravity.CENTER_VERTICAL);
        LinearLayout copy = vertical();
        copy.addView(text("Update Status", 15, BLACK, true));
        copy.addView(text(serviceActionHint(booking, step), 11, MUTED, false), margin(-1, -2, 0, 2, 0, 0));
        header.addView(copy, new LinearLayout.LayoutParams(0, -2, 1));
        TextView live = pill("\u25CF  Live", GREEN, Color.rgb(231, 249, 237));
        live.setTextSize(12);
        header.addView(live, new LinearLayout.LayoutParams(dp(68), dp(28)));
        dock.addView(header);

        TextView action = text(step.icon + "    " + serviceStatusActionLabel(booking, step), 16, Color.WHITE, true);
        action.setGravity(Gravity.CENTER);
        action.setPadding(dp(12), 0, dp(12), 0);
        action.setBackground(gradient(serviceActionStartColor(step), serviceActionEndColor(step), dp(18)));
        action.setElevation(dp(5));
        action.setOnClickListener(view -> runServiceStatusStep(booking, step, action));
        addPressAnimation(action);
        dock.addView(action, margin(-1, 56, 0, 10, 0, 0));

        FrameLayout.LayoutParams params = new FrameLayout.LayoutParams(-1, -2, Gravity.BOTTOM);
        params.setMargins(dp(14), 0, dp(14), dp(84));
        appRoot.addView(dock, params);
        serviceStatusActionDock = dock;
        dock.setAlpha(0f);
        dock.setTranslationY(dp(18));
        dock.animate()
                .alpha(1f)
                .translationY(0f)
                .setDuration(300)
                .setInterpolator(new DecelerateInterpolator(1.35f))
                .start();
    }

    private ServiceStatusStep nextServiceStatusStep(PartnerBooking booking) {
        String status = normalizedStatus(booking);
        int rank = statusRank(status);
        if (isCleaningStaffJob(booking) && rank < 3) return ServiceStatusStep.ARRIVED;
        if (rank < 2) return ServiceStatusStep.ON_THE_WAY;
        if ("on_the_way".equals(status)) return ServiceStatusStep.ARRIVED;
        if ("arrived".equals(status)) return ServiceStatusStep.STARTED;
        if ("started".equals(status)) return ServiceStatusStep.COMPLETE;
        if ("amount_pending".equals(status) && paymentSubmittedByCustomer(booking)) return ServiceStatusStep.CONFIRM_PAYMENT;
        return null;
    }

    private String serviceActionHint(PartnerBooking booking, ServiceStatusStep step) {
        if (isCleaningStaffJob(booking)) {
            if (step == ServiceStatusStep.ON_THE_WAY || step == ServiceStatusStep.ARRIVED) return "Update when you reach the customer location.";
            if (step == ServiceStatusStep.STARTED) return "Start cleaning. The customer will be notified instantly.";
            if (step == ServiceStatusStep.COMPLETE) return "Complete the job and send the final amount.";
        }
        if (isLaundryBooking(booking)) {
            if (step == ServiceStatusStep.ON_THE_WAY) return "Start the pickup route. The customer will be notified.";
            if (step == ServiceStatusStep.ARRIVED) return "Confirm only after collecting the laundry.";
            if (step == ServiceStatusStep.STARTED) return "Laundry is ready. Start the delivery route.";
            if (step == ServiceStatusStep.COMPLETE) return "Mark delivered, enter the amount, then verify payment.";
            if (step == ServiceStatusStep.CONFIRM_PAYMENT) return "Confirm only after receiving the customer payment.";
        }
        if (step == ServiceStatusStep.COMPLETE) {
            return "Complete the job and send the final amount.";
        }
        if (step == ServiceStatusStep.CONFIRM_PAYMENT) {
            return "Confirm only after receiving customer payment.";
        }
        return "Tap once. The customer will be notified instantly.";
    }

    private String serviceStatusActionLabel(PartnerBooking booking, ServiceStatusStep step) {
        if (isCleaningStaffJob(booking)) {
            if (step == ServiceStatusStep.ON_THE_WAY) return "On the way to customer";
            if (step == ServiceStatusStep.ARRIVED) return "Reached Customer Location";
            if (step == ServiceStatusStep.STARTED) return "Mark as Cleaning in Progress";
            if (step == ServiceStatusStep.COMPLETE) return "Mark Job as Completed";
        }
        if (!isLaundryBooking(booking)) return step.label;
        if (step == ServiceStatusStep.ON_THE_WAY) return "On the way to pickup";
        if (step == ServiceStatusStep.ARRIVED) return "Mark as Picked Up";
        if (step == ServiceStatusStep.STARTED) return "Out for Delivery";
        if (step == ServiceStatusStep.COMPLETE) return "Mark as Delivered";
        if (step == ServiceStatusStep.CONFIRM_PAYMENT) return "Verify Payment & Complete";
        return step.label;
    }

    private int serviceActionStartColor(ServiceStatusStep step) {
        if (step == ServiceStatusStep.ARRIVED) return Color.rgb(43, 111, 232);
        if (step == ServiceStatusStep.STARTED) return Color.rgb(238, 139, 27);
        if (step == ServiceStatusStep.COMPLETE || step == ServiceStatusStep.CONFIRM_PAYMENT) return Color.rgb(0, 164, 78);
        return ROSE;
    }

    private int serviceActionEndColor(ServiceStatusStep step) {
        if (step == ServiceStatusStep.ARRIVED) return Color.rgb(20, 84, 201);
        if (step == ServiceStatusStep.STARTED) return Color.rgb(224, 105, 15);
        if (step == ServiceStatusStep.COMPLETE || step == ServiceStatusStep.CONFIRM_PAYMENT) return Color.rgb(0, 124, 62);
        return ROSE_DARK;
    }

    private void runServiceStatusStep(PartnerBooking booking, ServiceStatusStep step, TextView action) {
        if (booking == null || step == null) {
            Toast.makeText(this, "Booking unavailable", Toast.LENGTH_SHORT).show();
            return;
        }
        if (isReadOnlyLaundryOwnerFor(booking)) {
            Toast.makeText(this, "Laundry status is updated by the assigned staff member.", Toast.LENGTH_LONG).show();
            showCompanyBookingLiveDetail(booking);
            return;
        }
        // Block Start Service for cleaning bookings until helper choice is saved.
        if (step == ServiceStatusStep.STARTED && isCleaningOwnerBooking(booking)
                && !cleaningHelperChosen(booking.id)) {
            Toast.makeText(this,
                    "Choose a helper or select \"No helper\" before starting the job.",
                    Toast.LENGTH_LONG).show();
            showCleaningHelperPicker(booking);
            return;
        }
        action.animate()
                .scaleX(0.985f)
                .scaleY(0.985f)
                .setDuration(90)
                .withEndAction(() -> action.animate().scaleX(1f).scaleY(1f).setDuration(110).start())
                .start();
        if (step == ServiceStatusStep.COMPLETE) {
            askFinalAmount(booking);
            return;
        }
        if (step == ServiceStatusStep.CONFIRM_PAYMENT) {
            action.setEnabled(false);
            action.setText(step.icon + "  Verifying payment...");
            confirmDirectPaymentReceived(booking);
            return;
        }
        String actionKey = statusActionKey(booking, step.targetStatus);
        if (statusUpdatingKeys.contains(actionKey)) {
            Toast.makeText(this, "Update already in progress", Toast.LENGTH_SHORT).show();
            return;
        }
        action.setEnabled(false);
        action.setAlpha(0.86f);
        action.setText(step.icon + "  Updating...");
        updateBookingStatusInApp(booking, step.targetStatus);
    }

    private void showCustomerNotifiedSnackbar() {
        showServiceStatusSnackbar("\u2713 Customer notified successfully.");
    }

    private void showServiceStatusSnackbar(String message) {
        if (appRoot == null || TextUtils.isEmpty(message)) {
            return;
        }
        removeServiceStatusSnackbar();
        TextView snack = text(message, 13, Color.WHITE, true);
        snack.setGravity(Gravity.CENTER);
        snack.setPadding(dp(18), 0, dp(18), 0);
        snack.setBackground(round(Color.rgb(19, 154, 79), dp(22)));
        snack.setElevation(dp(12));
        int bottom = serviceStatusActionDock == null ? dp(98) : dp(214);
        FrameLayout.LayoutParams params = new FrameLayout.LayoutParams(-2, dp(44), Gravity.BOTTOM | Gravity.CENTER_HORIZONTAL);
        params.setMargins(dp(18), 0, dp(18), bottom);
        appRoot.addView(snack, params);
        serviceStatusSnackbar = snack;
        snack.setAlpha(0f);
        snack.setTranslationY(dp(12));
        snack.animate()
                .alpha(1f)
                .translationY(0f)
                .setDuration(220)
                .setInterpolator(new DecelerateInterpolator(1.4f))
                .start();
        snack.postDelayed(() -> {
            if (serviceStatusSnackbar != snack) {
                return;
            }
            snack.animate()
                    .alpha(0f)
                    .translationY(dp(12))
                    .setDuration(180)
                    .withEndAction(() -> {
                        if (serviceStatusSnackbar == snack) {
                            removeServiceStatusSnackbar();
                        }
                    })
                    .start();
        }, 1900);
    }

    private void openNavigationToCustomer(PartnerBooking booking) {
        if (!requireFeature("partner_location", "Partner Location")) return;
        if (booking == null) return;
        try {
            String destination = booking.lat != 0 && booking.lng != 0
                    ? booking.lat + "," + booking.lng
                    : booking.address;
            Uri uri = Uri.parse("google.navigation:q=" + encode(destination));
            Intent intent = new Intent(Intent.ACTION_VIEW, uri);
            intent.setPackage("com.google.android.apps.maps");
            startActivity(intent);
        } catch (Exception error) {
            Toast.makeText(this, "Navigation unavailable", Toast.LENGTH_SHORT).show();
        }
    }

    private int statusRank(String status) {
        if ("accepted".equals(status)) return 1;
        if ("on_the_way".equals(status)) return 2;
        if ("arrived".equals(status)) return 3;
        if ("started".equals(status)) return 4;
        if ("amount_pending".equals(status)) return 5;
        if ("completed".equals(status)) return 6;
        return 0;
    }

    private boolean canReportCustomerNoResponse(PartnerBooking booking) {
        String status = normalizedStatus(booking);
        return "arrived".equals(status) || "started".equals(status);
    }

    private String routePrimaryActionLabel(PartnerBooking booking) {
        String status = normalizedStatus(booking);
        if (isLaundryBooking(booking)) {
            if ("accepted".equals(status)) return "\uD83D\uDE97  On the way to pickup";
            if ("on_the_way".equals(status)) return "\uD83D\uDECD  Mark as Picked Up";
            if ("arrived".equals(status)) return "\uD83D\uDE9A  Out for Delivery";
            if ("started".equals(status)) return "\u2713  Mark as Delivered";
            if ("amount_pending".equals(status) && quoteCountered(booking)) return "\u20B9  Review Counter Offer";
            if ("amount_pending".equals(status) && quoteExpired(booking)) return "\u20B9  Send Fresh Amount";
            if ("amount_pending".equals(status) && paymentSubmittedByCustomer(booking)) return "\u2713  Verify Payment & Complete";
            if ("amount_pending".equals(status)) return "\u23F3  Waiting for Customer Payment";
            if ("completed".equals(status)) return "\u2713  Delivery Completed";
        }
        if ("accepted".equals(status)) return "\uD83D\uDE80  Let's Go";
        if ("on_the_way".equals(status)) return "\uD83D\uDCCD  Mark as Arrived";
        if ("arrived".equals(status)) return "\u25B6  Start Service";
        if ("started".equals(status)) return "\u2713  Mark as Completed";
        if ("amount_pending".equals(status) && quoteCountered(booking)) return "\u20B9  Review Counter Offer";
        if ("amount_pending".equals(status) && quoteExpired(booking)) return "\u20B9  Send Fresh Quote";
        if ("amount_pending".equals(status) && paymentSubmittedByCustomer(booking)) return "\u2713  Confirm Payment Received";
        if ("amount_pending".equals(status)) return "\u23F3  Waiting for Customer Payment";
        if ("customer_no_response".equals(status)) return "\u26A0  Customer No Response";
        if ("completed".equals(status)) return "\u2713  Job Completed";
        return "\uD83D\uDE80  Let's Go";
    }

    private String routeSnackLabel(PartnerBooking booking) {
        String status = normalizedStatus(booking);
        if (isLaundryBooking(booking)) {
            if ("on_the_way".equals(status)) return "Customer notified: heading for pickup";
            if ("arrived".equals(status)) return "Laundry marked as picked up";
            if ("started".equals(status)) return "Customer notified: out for delivery";
            if ("amount_pending".equals(status) && paymentSubmittedByCustomer(booking)) return "Customer marked payment as paid. Verify receipt to complete";
            if ("amount_pending".equals(status)) return "Delivered. Amount sent for customer payment";
            if ("completed".equals(status)) return "Payment verified and laundry order completed";
        }
        if ("amount_pending".equals(status) && quoteCountered(booking)) return "Customer countered Rs " + booking.quoteCounterAmount;
        if ("amount_pending".equals(status) && quoteExpired(booking)) return "Quote expired. Send a fresh quote";
        if ("amount_pending".equals(status) && paymentSubmittedByCustomer(booking)) return "Customer marked payment as paid. Confirm only after receiving it";
        if ("amount_pending".equals(status)) return "Final amount sent. Waiting for customer to tap Pay Partner";
        if ("customer_no_response".equals(status)) return "Customer unavailable report submitted";
        if ("completed".equals(status)) return "Job completed and payment confirmed";
        return readableStatus(status) + " updated";
    }

    private void handleRoutePrimaryAction(PartnerBooking booking) {
        String status = normalizedStatus(booking);
        if ("accepted".equals(status)) {
            updateBookingStatusInApp(booking, "on_the_way");
        } else if ("on_the_way".equals(status)) {
            updateBookingStatusInApp(booking, "arrived");
        } else if ("arrived".equals(status)) {
            updateBookingStatusInApp(booking, "started");
        } else if ("started".equals(status)) {
            askFinalAmount(booking);
        } else if ("amount_pending".equals(status)) {
            if (quoteCountered(booking) || quoteExpired(booking)) {
                askFinalAmount(booking);
                return;
            }
            if (!paymentSubmittedByCustomer(booking)) {
                Toast.makeText(this, "Waiting for customer to tap Pay Partner.", Toast.LENGTH_LONG).show();
                return;
            }
            confirmDirectPaymentReceived(booking);
        } else if ("completed".equals(status)) {
            showBookings();
        } else if ("customer_no_response".equals(status)) {
            showBookings();
        } else {
            updateBookingStatusInApp(booking, "on_the_way");
        }
    }

    private void confirmDirectPaymentReceived(PartnerBooking booking) {
        if (booking == null || TextUtils.isEmpty(booking.id)) {
            Toast.makeText(this, "Booking unavailable", Toast.LENGTH_SHORT).show();
            return;
        }
        int amount = finalAmount(booking);
        if (amount <= 0) {
            Toast.makeText(this, "Final amount missing. Send a fresh quote.", Toast.LENGTH_LONG).show();
            askFinalAmount(booking);
            return;
        }
        String actionKey = statusActionKey(booking, "completed");
        if (statusUpdatingKeys.contains(actionKey)) {
            Toast.makeText(this, "Payment verification already in progress", Toast.LENGTH_SHORT).show();
            return;
        }
        statusUpdatingKeys.add(actionKey);
        if (backendClient != null) {
            backendClient.updateBookingStatus(booking.id, "completed", amount, new BackendClient.JsonCallback() {
                @Override
                public void onSuccess(JSONObject object) {
                    statusUpdatingKeys.remove(actionKey);
                    paidIds.add(booking.id);
                    prefs.edit()
                            .putStringSet(KEY_PAID, new HashSet<>(paidIds))
                            .putInt(amountKey(booking), amount)
                            .apply();
                    completeLocalStatusUpdate(booking, "completed");
                }

                @Override
                public void onError(String message) {
                    statusUpdatingKeys.remove(actionKey);
                    Toast.makeText(MainActivity.this, "Payment verification failed: " + safeUserError(message), Toast.LENGTH_LONG).show();
                }
            });
        } else {
            statusUpdatingKeys.remove(actionKey);
            Toast.makeText(this, "Payment verification needs a secure backend connection. Please reconnect and try again.", Toast.LENGTH_LONG).show();
        }
    }

    private void showNoResponseReportDialog(PartnerBooking booking) {
        AlertDialog dialog = new AlertDialog.Builder(this).create();
        LinearLayout sheet = vertical();
        sheet.setPadding(dp(20), dp(18), dp(20), dp(16));
        sheet.setBackground(stroke(Color.WHITE, Color.rgb(250, 214, 224), dp(22)));
        sheet.addView(text("Customer No Response", 19, BLACK, true));
        sheet.addView(text("Use this only after reaching the service address and trying to contact the customer.", 12, MUTED, false), margin(-1, -2, 0, 4, 0, 12));

        EditText reason = input("Reason, e.g. customer not available / door locked", InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_CAP_SENTENCES | InputType.TYPE_TEXT_FLAG_MULTI_LINE);
        reason.setMinLines(3);
        reason.setGravity(Gravity.TOP | Gravity.LEFT);
        reason.setText("Customer unavailable at address, no response on call.");
        sheet.addView(reason, margin(-1, 92, 0, 0, 0, 14));

        TextView submit = roseButton("Submit No Response Report");
        submit.setOnClickListener(view -> {
            String body = reason.getText().toString().trim();
            if (TextUtils.isEmpty(body)) {
                Toast.makeText(this, "Please enter a reason.", Toast.LENGTH_SHORT).show();
                return;
            }
            submit.setEnabled(false);
            requireFreshGpsForJob(booking, "arrived", location -> {
                BackendClient.LocationPayload payload = locationPayload(location);
                backendClient.reportCustomerNoResponse(booking.id, body, payload, new BackendClient.JsonCallback() {
                    @Override
                    public void onSuccess(JSONObject object) {
                        Toast.makeText(MainActivity.this, "No response report submitted", Toast.LENGTH_SHORT).show();
                        dialog.dismiss();
                        stopJobLocationTracking();
                        showFinishedBookingList(new PartnerBooking(
                                booking.id, booking.service, booking.issue, booking.customer, booking.address, booking.city,
                                booking.time, booking.defaultAmount, "customer_no_response", booking.lat, booking.lng,
                                booking.createdAtMillis, booking.completedAtMillis, booking.customerPhone,
                                booking.quoteStatus, booking.quoteCounterAmount, booking.quoteCounterMessage, booking.quoteExpiresAtMillis
                        ));
                    }

                    @Override
                    public void onError(String message) {
                        submit.setEnabled(true);
                        Toast.makeText(MainActivity.this, "No response report failed: " + message, Toast.LENGTH_LONG).show();
                    }
                });
            });
        });
        sheet.addView(submit, new LinearLayout.LayoutParams(-1, dp(50)));

        TextView cancel = text("Cancel", 13, MUTED, true);
        cancel.setGravity(Gravity.CENTER);
        cancel.setOnClickListener(view -> dialog.dismiss());
        sheet.addView(cancel, margin(-1, 38, 0, 8, 0, 0));

        dialog.setView(sheet);
        showDialogSafely(dialog);
        Window window = dialog.getWindow();
        if (window != null) {
            window.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));
        }
    }

    private void updateBookingStatusInApp(PartnerBooking booking, String status) {
        if (!allowOperationalAction()) return;
        if (isReadOnlyLaundryOwnerFor(booking)) {
            Toast.makeText(this, "Laundry owners can monitor this order. Assigned staff updates its live status.", Toast.LENGTH_LONG).show();
            showCompanyBookingLiveDetail(booking);
            return;
        }
        if (booking == null || TextUtils.isEmpty(booking.id)) {
            Toast.makeText(this, "Booking unavailable", Toast.LENGTH_SHORT).show();
            return;
        }
        String actionKey = statusActionKey(booking, status);
        if (statusUpdatingKeys.contains(actionKey)) {
            Toast.makeText(this, "Update already in progress", Toast.LENGTH_SHORT).show();
            return;
        }
        if ("started".equals(status) && !isLaundryBooking(booking)) {
            playStartServiceVoice();
        }
        statusUpdatingKeys.add(actionKey);
        updateBookingStatusWithGps(booking, status, null);
    }

    private void playStartServiceVoice() {
        try {
            releaseStartServiceVoicePlayer();
            startServiceVoicePlayer = MediaPlayer.create(this, R.raw.start_service_voice);
            if (startServiceVoicePlayer == null) {
                return;
            }
            startServiceVoicePlayer.setOnCompletionListener(player -> {
                if (startServiceVoicePlayer == player) {
                    startServiceVoicePlayer = null;
                }
                player.release();
            });
            startServiceVoicePlayer.setOnErrorListener((player, what, extra) -> {
                if (startServiceVoicePlayer == player) {
                    startServiceVoicePlayer = null;
                }
                player.release();
                return true;
            });
            startServiceVoicePlayer.start();
        } catch (Exception ignored) {
            releaseStartServiceVoicePlayer();
        }
    }

    private void releaseStartServiceVoicePlayer() {
        if (startServiceVoicePlayer == null) {
            return;
        }
        try {
            startServiceVoicePlayer.release();
        } catch (Exception ignored) {
        }
        startServiceVoicePlayer = null;
    }

    private void updateBookingStatusWithGps(PartnerBooking booking, String status, Location location) {
        BackendClient.LocationPayload payload = location == null ? null : locationPayload(location);
        if (backendClient != null) {
            BackendClient.JsonCallback callback = new BackendClient.JsonCallback() {
                @Override
                public void onSuccess(JSONObject object) {
                    statusUpdatingKeys.remove(statusActionKey(booking, status));
                    if (location != null) {
                        sendPartnerLocation(booking, location, false);
                    }
                    PartnerBooking serverBooking = null;
                    if (object != null) {
                        JSONObject bookingObject = object.optJSONObject("booking");
                        if (bookingObject != null) {
                            serverBooking = backendBookingFromJson(bookingObject);
                        }
                    }
                    PartnerBooking appliedBooking = serverBooking != null && booking.id.equals(serverBooking.id)
                            ? serverBooking
                            : booking;
                    completeLocalStatusUpdate(appliedBooking, serverBooking == null ? status : normalizedStatus(serverBooking));
                }

                @Override
                public void onError(String message) {
                    statusUpdatingKeys.remove(statusActionKey(booking, status));
                    Toast.makeText(MainActivity.this, "Status update failed: " + safeUserError(message), Toast.LENGTH_LONG).show();
                    if ("map".equals(activeTab) && activeMapBooking != null && booking.id.equals(activeMapBooking.id)) {
                        showInAppMap(booking);
                    } else {
                        refreshCurrent();
                    }
                }
            };
            if (isStaffSession()) {
                backendClient.updateStaffBookingStatus(booking.id, status, 0, payload, callback);
            } else {
                backendClient.updateBookingStatus(booking.id, status, 0, payload, callback);
            }
        } else {
            statusUpdatingKeys.remove(statusActionKey(booking, status));
            Toast.makeText(this, "Status update needs a secure backend connection. Please reconnect and try again.", Toast.LENGTH_LONG).show();
            refreshCurrent();
        }
    }

    private String statusActionKey(PartnerBooking booking, String status) {
        String bookingId = booking == null ? "" : booking.id;
        return bookingId + ":" + (status == null ? "" : status);
    }

    private void completeLocalStatusUpdate(PartnerBooking booking, String status) {
        if ("amount_pending".equals(status)) {
            stopJobLocationTracking();
            PartnerBooking updatedBooking = new PartnerBooking(
                    booking.id, booking.service, booking.issue, booking.customer, booking.address, booking.city,
                    booking.time, booking.defaultAmount, status, booking.lat, booking.lng,
                    booking.createdAtMillis, booking.completedAtMillis, booking.customerPhone,
                    booking.quoteStatus, booking.quoteCounterAmount, booking.quoteCounterMessage, booking.quoteExpiresAtMillis
            );
            replaceLocalBooking(updatedBooking);
            bookingFilter = "ongoing";
            showInAppMap(updatedBooking);
            showCustomerNotifiedSnackbar();
            return;
        }
        if ("completed".equals(status) || "customer_no_response".equals(status) || "cancelled".equals(status) || "rejected".equals(status)) {
            stopJobLocationTracking();
            PartnerBooking updatedBooking = new PartnerBooking(
                    booking.id, booking.service, booking.issue, booking.customer, booking.address, booking.city,
                    booking.time, booking.defaultAmount, status, booking.lat, booking.lng,
                    booking.createdAtMillis, booking.completedAtMillis, booking.customerPhone,
                    booking.quoteStatus, booking.quoteCounterAmount, booking.quoteCounterMessage, booking.quoteExpiresAtMillis
            );
            replaceLocalBooking(updatedBooking);
            showFinishedBookingList(updatedBooking);
            showCustomerNotifiedSnackbar();
            return;
        }
        PartnerBooking updatedBooking = new PartnerBooking(
                booking.id, booking.service, booking.issue, booking.customer, booking.address, booking.city,
                booking.time, booking.defaultAmount, status, booking.lat, booking.lng,
                booking.createdAtMillis, booking.completedAtMillis, booking.customerPhone,
                booking.quoteStatus, booking.quoteCounterAmount, booking.quoteCounterMessage, booking.quoteExpiresAtMillis
        );
        replaceLocalBooking(updatedBooking);
        showInAppMap(updatedBooking);
        showCustomerNotifiedSnackbar();
    }

    private void replaceLocalBooking(PartnerBooking updatedBooking) {
        if (updatedBooking == null || TextUtils.isEmpty(updatedBooking.id)) {
            return;
        }
        boolean replaced = false;
        for (int index = 0; index < bookings.size(); index++) {
            if (updatedBooking.id.equals(bookings.get(index).id)) {
                bookings.set(index, updatedBooking);
                replaced = true;
                break;
            }
        }
        if (!replaced) {
            bookings.add(0, updatedBooking);
        }
        savePartnerBookingCache();
    }

