    private boolean hasLocationPermission() {
        return Build.VERSION.SDK_INT < Build.VERSION_CODES.M
                || checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION) == PackageManager.PERMISSION_GRANTED
                || checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION) == PackageManager.PERMISSION_GRANTED;
    }

    private boolean gpsProviderEnabled() {
        if (locationManager == null) {
            locationManager = (LocationManager) getSystemService(LOCATION_SERVICE);
        }
        try {
            return locationManager != null && locationManager.isProviderEnabled(LocationManager.GPS_PROVIDER);
        } catch (Exception ignored) {
            return false;
        }
    }

    private boolean anyLocationProviderEnabled() {
        if (locationManager == null) {
            locationManager = (LocationManager) getSystemService(LOCATION_SERVICE);
        }
        try {
            return locationManager != null
                    && (locationManager.isProviderEnabled(LocationManager.GPS_PROVIDER)
                    || locationManager.isProviderEnabled(LocationManager.NETWORK_PROVIDER));
        } catch (Exception ignored) {
            return false;
        }
    }

    private void requestJobLocationPermission() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
            boolean requestedBefore = prefs != null && prefs.getBoolean(KEY_LOCATION_PERMISSION_REQUESTED, false);
            boolean canAskAgain = !requestedBefore
                    || shouldShowRequestPermissionRationale(Manifest.permission.ACCESS_FINE_LOCATION)
                    || shouldShowRequestPermissionRationale(Manifest.permission.ACCESS_COARSE_LOCATION);
            if (!canAskAgain) {
                showPartnerLocationPermissionSettingsDialog();
                return;
            }
            if (prefs != null) {
                prefs.edit().putBoolean(KEY_LOCATION_PERMISSION_REQUESTED, true).apply();
            }
            requestPermissions(
                    new String[]{Manifest.permission.ACCESS_FINE_LOCATION, Manifest.permission.ACCESS_COARSE_LOCATION},
                    LOCATION_PERMISSION_REQUEST
            );
        }
    }

    private boolean requestInitialPartnerLocationPermission() {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.M || hasLocationPermission()) {
            return false;
        }
        boolean requestedBefore = prefs != null && prefs.getBoolean(KEY_LOCATION_PERMISSION_REQUESTED, false);
        boolean canAskAgain = !requestedBefore
                || shouldShowRequestPermissionRationale(Manifest.permission.ACCESS_FINE_LOCATION)
                || shouldShowRequestPermissionRationale(Manifest.permission.ACCESS_COARSE_LOCATION);
        if (!canAskAgain) {
            return false;
        }
        requestJobLocationPermission();
        return true;
    }

    private boolean ensurePartnerLocationReady(boolean userInitiated) {
        if (!hasLocationPermission()) {
            if (userInitiated) {
                requestJobLocationPermission();
            } else {
                boolean started = requestInitialPartnerLocationPermission();
                if (!started && !hasLocationPermission()) {
                    showPartnerLocationPermissionSettingsDialog();
                }
            }
            return false;
        }
        if (!anyLocationProviderEnabled()) {
            showPartnerLocationSettingsDialog(userInitiated);
            return false;
        }
        syncCurrentPartnerLocation();
        if (online && !isStaffSession()) {
            startAvailabilityLocationTracking();
        }
        return true;
    }

