    private String firestoreListenErrorMessage(Exception error) {
        String message = error == null || error.getMessage() == null ? "unknown" : error.getMessage();
        if (error instanceof FirebaseFirestoreException) {
            FirebaseFirestoreException firestoreError = (FirebaseFirestoreException) error;
            if (firestoreError.getCode() == FirebaseFirestoreException.Code.PERMISSION_DENIED) {
                if (firebaseAuth.getCurrentUser() == null) {
                    return "Firebase setup issue: Auth or API key is blocked. Enable the Identity Toolkit API and Anonymous Auth.";
                }
                return "Firestore rules blocked booking read access. Allow authenticated access for bookings and partners.";
            }
        }
        return "Firestore request listen failed: " + message;
    }

