    private List<PartnerBooking> parseBackendBookings(JSONObject root) {
        List<PartnerBooking> result = new ArrayList<>();
        JSONArray array = root == null ? null : root.optJSONArray("bookings");
        if (array == null) {
            return result;
        }
        for (int index = 0; index < array.length(); index++) {
            JSONObject object = array.optJSONObject(index);
            if (object == null) {
                continue;
            }
            PartnerBooking booking = backendBookingFromJson(object);
            JSONObject assignment = object.optJSONObject("laundryAssignment");
            if (assignment != null && !TextUtils.isEmpty(booking.id)) {
                prefs.edit()
                        .putString(KEY_LAUNDRY_ASSIGNMENT_PREFIX + booking.id, assignment.optString("staffName", ""))
                        .putString(KEY_LAUNDRY_TASK_STATUS_PREFIX + booking.id, assignment.optString("taskStatus", "assigned"))
                        .apply();
            }
            if (shouldShowBackendApiBooking(booking, object)) {
                result.add(booking);
            }
        }
        return result;
    }

    private PartnerBooking backendBookingFromJson(JSONObject object) {
        if (object == null) {
            return null;
        }
        String id = jsonString(object, "canonicalBookingId", jsonString(object, "publicId", jsonString(object, "bookingCode", jsonString(object, "_id", jsonString(object, "bookingId", "")))));
        String service = jsonString(object, "serviceName", skillLabel(jsonString(object, "serviceCategory", "service")));
        String issue = jsonString(object, "issue", "Service request");
        String customer = jsonString(object, "userName", jsonString(object, "customerName", "Customer"));
        String address = jsonString(object, "address", jsonString(object, "location", "Customer address"));
        String city = jsonString(object, "city", "Guwahati");
        String time = jsonString(object, "slot", jsonString(object, "time", "Partner provides arrival ETA"));
        if (TextUtils.isEmpty(time)) time = "Partner provides arrival ETA";
        int amount = jsonInt(object, "quoteAmount", jsonInt(object, "finalAmount", jsonInt(object, "price", jsonInt(object, "defaultAmount", 0))));
        String status = jsonString(object, "status", "pending");
        double lat = jsonDouble(object, "lat", 0);
        double lng = jsonDouble(object, "lng", 0);
        long created = jsonCreatedAtMillis(object, System.currentTimeMillis());
        String phone = jsonString(object, "customerPhone", jsonString(object, "userPhone", jsonString(object, "phone", jsonString(object, "customerPhoneMasked", ""))));
        if (!TextUtils.isEmpty(id)) {
            bookingAlternatePhoneCache.put(id, jsonString(object, "alternatePhone", ""));
            JSONObject locationChange = object.optJSONObject("locationChange");
            bookingLocationChangeStateCache.put(id, locationChange == null ? "none" : locationChange.optString("state", "none"));
            bookingLocationVersionCache.put(id, Math.max(1, object.optInt("locationVersion", 1)));
        }
        PartnerBooking parsed = new PartnerBooking(
                id, service, issue, customer, address, city, time, amount, status, lat, lng, created,
                jsonCompletedAtMillis(object), phone,
                jsonString(object, "quoteStatus", ""),
                jsonInt(object, "quoteCounterAmount", 0),
                jsonString(object, "quoteCounterMessage", ""),
                jsonLong(object, "quoteExpiresAtMillis", 0)
        );
        parsed.serviceId = ServiceRouting.canonicalServiceId(jsonString(object, "serviceId",
                jsonString(object, "serviceType", jsonString(object, "serviceCategory", service))));
        if (TextUtils.isEmpty(parsed.serviceId)) parsed.serviceId = ServiceRouting.canonicalServiceId(service);
        // Scheduling fields (sent by backend serializer / FCM data)
        parsed.bookingType = jsonString(object, "bookingType", "instant");
        parsed.scheduledDate = jsonString(object, "scheduledDate", "");
        parsed.scheduledSlot = jsonString(object, "scheduledSlot", "");
        parsed.scheduledSlotLabel = jsonString(object, "scheduledSlotLabel", "");
        return parsed;
    }

    private boolean shouldShowBackendBooking(PartnerBooking booking, JSONObject object) {
        if (hiddenTakenIds.contains(booking.id) && !acceptedIds.contains(booking.id)) {
            return false;
        }
        String status = booking.status == null ? "" : booking.status.toLowerCase(Locale.US);
        String assignedPartnerId = jsonString(object, "partnerId", jsonString(object, "assignedPartnerId", ""));
        boolean assignedToThisPartner = !TextUtils.isEmpty(assignedPartnerId) && (assignedPartnerId.equals(partnerId()) || acceptedIds.contains(booking.id));
        boolean activeForThisPartner = assignedToThisPartner && ("accepted".equals(status)
                || "on_the_way".equals(status)
                || "arrived".equals(status)
                || "started".equals(status)
                || "amount_pending".equals(status)
                || "customer_no_response".equals(status)
                || "completed".equals(status)
                || "cancelled".equals(status)
                || "rejected".equals(status));
        boolean openForThisPartner = online
                && ("pending".equals(status) || "sent_to_partner".equals(status))
                && backendBookingMatchesPartnerSkill(booking, object)
                && partnerMatchesBooking(booking);
        if (openForThisPartner) {
            clearLocalBlocksForServerPending(booking.id);
        }
        return activeForThisPartner || openForThisPartner;
    }

    private boolean shouldShowBackendApiBooking(PartnerBooking booking, JSONObject object) {
        if (hiddenTakenIds.contains(booking.id) && !acceptedIds.contains(booking.id)) {
            return false;
        }
        String status = booking.status == null ? "" : booking.status.toLowerCase(Locale.US);
        String assignedPartnerId = jsonString(object, "partnerId", jsonString(object, "assignedPartnerId", ""));
        boolean assignedByBackend = !TextUtils.isEmpty(assignedPartnerId);
        boolean activeFromBackend = assignedByBackend && ("accepted".equals(status)
                || "on_the_way".equals(status)
                || "arrived".equals(status)
                || "started".equals(status)
                || "amount_pending".equals(status)
                || "customer_no_response".equals(status)
                || "completed".equals(status)
                || "cancelled".equals(status)
                || "rejected".equals(status));
        // The authenticated backend has already filtered this feed for the current
        // partner. Keep requested jobs visible while offline for later acceptance.
        boolean openFromBackend = ("pending".equals(status) || "sent_to_partner".equals(status))
                && bookingMatchesAssignedService(booking)
                && !jsonHasRejectedPartner(object);
        if (openFromBackend) {
            clearLocalBlocksForServerPending(booking.id);
        }
        return activeFromBackend || openFromBackend || shouldShowBackendBooking(booking, object);
    }

    private boolean backendBookingMatchesPartnerSkill(PartnerBooking booking, JSONObject object) {
        if (!bookingMatchesAssignedService(booking)) return false;
        String rawType = jsonString(object, "serviceCategory", jsonString(object, "serviceType", ""));
        String rawName = jsonString(object, "serviceName", booking.service);
        String combined = (rawType + " " + rawName).trim().toLowerCase(Locale.ROOT);
        if (TextUtils.isEmpty(combined.trim())) {
            return true;
        }
        String normalizedType = normalizeSkill(combined);
        for (String skill : partnerSkills()) {
            if (serviceTextMatchesSkill(combined, normalizedType, skill)) {
                return true;
            }
        }
        return false;
    }

