    private List<PartnerBooking> parseRealtimeRestBookings(JSONObject root) {
        List<PartnerBooking> result = new ArrayList<>();
        java.util.Iterator<String> keys = root.keys();
        while (keys.hasNext()) {
            String key = keys.next();
            JSONObject object = root.optJSONObject(key);
            if (object == null) {
                continue;
            }
            PartnerBooking booking = new PartnerBooking(
                    key,
                    jsonString(object, "serviceName", jsonString(object, "service", "Service")),
                    jsonString(object, "issue", "Service request"),
                    jsonString(object, "customerName", jsonString(object, "userName", "Customer")),
                    jsonString(object, "address", jsonString(object, "location", "Customer address")),
                    jsonString(object, "city", "Guwahati, Assam"),
                    jsonString(object, "slot", jsonString(object, "time", "Partner provides arrival ETA")),
                    jsonInt(object, "finalAmount", jsonInt(object, "defaultAmount", jsonInt(object, "price", 0))),
                    jsonString(object, "status", "pending"),
                    jsonDouble(object, "lat", jsonDouble(object, "locationLat", 0)),
                    jsonDouble(object, "lng", jsonDouble(object, "locationLng", 0)),
                    jsonCreatedAtMillis(object, 0),
                    jsonLong(object, "completedAtMillis", 0),
                    jsonString(object, "customerPhone", jsonString(object, "userPhone", jsonString(object, "phone", jsonString(object, "customerPhoneMasked", ""))))
            );
            booking.serviceId = ServiceRouting.canonicalServiceId(jsonString(object, "serviceId",
                    jsonString(object, "serviceType", jsonString(object, "serviceCategory", booking.service))));
            if (shouldShowRealtimeRestBooking(booking, object)) {
                result.add(booking);
            }
        }
        return result;
    }

    private void applyLiveBookings(List<PartnerBooking> live, boolean fromRestPoll) {
        if (!isStaffSession() && !isPartnerApproved()) {
            bookings = new ArrayList<>();
            hasUnreadIncomingRequest = false;
            stopIncomingRequestAlert();
            backendConnected = true;
            loadingBookings = false;
            refreshCurrent();
            return;
        }
        List<PartnerBooking> visibleLive = new ArrayList<>();
        for (PartnerBooking booking : live) {
            if (!hiddenTakenIds.contains(booking.id) || acceptedIds.contains(booking.id)) {
                visibleLive.add(booking);
            }
        }
        live = visibleLive;
        Collections.sort(live, (left, right) -> Long.compare(right.createdAtMillis, left.createdAtMillis));
        if (!isStaffSession()) pruneAlertedPendingIds(live);
        PartnerBooking freshRequest = isStaffSession() ? null : freshPendingRequest(live);
        bookings = live;
        if (!isStaffSession()) syncLocalPaymentState(live);
        savePartnerBookingCache();
        boolean alertStarted = false;
        if (freshRequest != null && online) {
            hasUnreadIncomingRequest = true;
            startBellShake();
            startIncomingRequestAlert(freshRequest);
            alertStarted = true;
        }
        backendConnected = true;
        loadingBookings = false;
        if (!isStaffSession() && !alertStarted && online) {
            refreshHandler.postDelayed(MainActivity.this::showPendingRequestIfAvailable, fromRestPoll ? 80 : 250);
        }
        if ("company_booking".equals(activeTab) && activeDetailBooking != null) {
            PartnerBooking updated = findBooking(activeDetailBooking.id);
            if (updated != null) {
                runOnUiThread(() -> showCompanyBookingLiveDetail(updated));
                return;
            }
        }
        if (!alertStarted || isSafeToRefreshBehindAlert()) {
            refreshCurrent();
        }
    }

    private void syncLocalPaymentState(List<PartnerBooking> live) {
        boolean changed = false;
        SharedPreferences.Editor editor = prefs.edit();
        for (PartnerBooking booking : live) {
            String status = normalizedStatus(booking);
            if (booking.defaultAmount > 0 && ("amount_pending".equals(status) || "completed".equals(status))) {
                editor.putInt(amountKey(booking), booking.defaultAmount);
            }
            if ("completed".equals(status)) {
                if (completedIds.add(booking.id)) {
                    changed = true;
                }
                if (paidIds.add(booking.id)) {
                    changed = true;
                }
            }
        }
        editor.apply();
        if (changed) {
            saveState();
        }
    }

