    private void clearLocalBlocksForServerPending(String bookingId) {
        boolean changed = false;
        if (cancelledIds.remove(bookingId)) {
            changed = true;
        }
        if (completedIds.remove(bookingId)) {
            changed = true;
        }
        if (changed) {
            saveState();
        }
    }

    private boolean shouldAllowDebugVisiblePending(PartnerBooking booking) {
        if (TextUtils.isEmpty(booking.service) || "Service".equalsIgnoreCase(booking.service)) {
            return true;
        }
        return partnerSkills().size() > 1;
    }

    private boolean realtimeBookingMatchesPartnerSkill(PartnerBooking booking, DataSnapshot snapshot) {
        if (!bookingMatchesAssignedService(booking)) return false;
        String rawType = realtimeValue(snapshot, "serviceType", realtimeValue(snapshot, "serviceId", ""));
        String rawName = realtimeValue(snapshot, "serviceName", realtimeValue(snapshot, "service", booking.service));
        String combined = (rawType + " " + rawName).trim().toLowerCase(Locale.ROOT);
        if (!TextUtils.isEmpty(combined.trim())) {
            String normalizedType = normalizeSkill(combined);
            for (String skill : partnerSkills()) {
                if (serviceTextMatchesSkill(combined, normalizedType, skill)) {
                    return true;
                }
            }
            return false;
        }
        return true;
    }

