    private boolean bookingMatchesPartnerSkill(PartnerBooking booking, DocumentSnapshot snapshot) {
        if (!bookingMatchesAssignedService(booking)) return false;
        String rawType = value(snapshot, "serviceType", value(snapshot, "serviceId", ""));
        String rawName = value(snapshot, "serviceName", value(snapshot, "service", booking.service));
        String combined = (rawType + " " + rawName).trim().toLowerCase(Locale.ROOT);
        if (!TextUtils.isEmpty(combined.trim())) {
            String normalizedType = normalizeSkill(combined);
            for (String skill : partnerSkills()) {
                if (serviceTextMatchesSkill(combined, normalizedType, skill)) {
                    return true;
                }
            }
            return false;
        }
        if ("Service".equalsIgnoreCase(booking.service)) {
            return true;
        }
        String normalizedBooking = normalizeSkill(booking.service);
        for (String skill : partnerSkills()) {
            if (normalizeSkill(skill).equals(normalizedBooking)) {
                return true;
            }
        }
        return false;
    }

    private boolean serviceTextMatchesSkill(String combined, String normalizedType, String skill) {
        String textValue = combined == null ? "" : combined.toLowerCase(Locale.ROOT);
        String normalizedSkill = normalizeSkill(skill);
        if (normalizedSkill.equals(normalizedType)) {
            return true;
        }
        if ("ro".equals(normalizedSkill)) {
            return isRoText(textValue);
        }
        if ("laundry".equals(normalizedSkill)) {
            return isLaundryText(textValue);
        }
        String label = skillLabel(normalizedSkill).toLowerCase(Locale.ROOT);
        return textValue.contains(normalizedSkill)
                || textValue.contains(label)
                || label.contains(textValue);
    }

    private boolean bookingMatchesAssignedService(PartnerBooking booking) {
        if (booking == null) return false;
        String bookingServiceId = ServiceRouting.canonicalServiceId(booking.serviceId);
        if (TextUtils.isEmpty(bookingServiceId)) bookingServiceId = ServiceRouting.canonicalServiceId(booking.service);
        String accountServiceId = currentServiceId();
        boolean matches = ServiceRouting.matchesAssignment(accountServiceId, bookingServiceId);
        if (!matches) {
            android.util.Log.w("ServiceRouting", "Blocked cross-service booking " + booking.id
                    + " account=" + accountServiceId + " booking=" + bookingServiceId);
        }
        return matches;
    }

    private boolean hasRejectedPartner(DocumentSnapshot snapshot) {
        Object rejected = snapshot.get("rejectedPartnerIds");
        return rejected instanceof List && ((List<?>) rejected).contains(partnerId());
    }

    private boolean partnerMatchesBooking(PartnerBooking booking) {
        if (booking == null) return false;
        Location partnerLocation = bestCachedLocation();
        if (partnerLocation == null) return false;
        double radiusKm = Math.max(25, serviceRadiusKm());
        if (NearbyBookingMatcher.matches(partnerLocation.getLatitude(), partnerLocation.getLongitude(),
                booking.lat, booking.lng, radiusKm)) {
            return true;
        }
        String city = booking.city == null ? "" : booking.city.toLowerCase(Locale.US);
        return city.contains("guwahati") && NearbyBookingMatcher.matches(
                partnerLocation.getLatitude(), partnerLocation.getLongitude(),
                booking.lat, booking.lng, Math.max(radiusKm, 60));
    }

