    private boolean realtimeHasRejectedPartner(DataSnapshot snapshot) {
        Object rejected = snapshot.child("rejectedPartnerIds").getValue();
        if (rejected instanceof List) {
            return ((List<?>) rejected).contains(partnerId());
        }
        if (rejected instanceof Map) {
            Map<?, ?> rejectedMap = (Map<?, ?>) rejected;
            if (rejectedMap.containsKey(partnerId())) {
                Object value = rejectedMap.get(partnerId());
                return !(value instanceof Boolean) || (Boolean) value;
            }
            return rejectedMap.containsValue(partnerId());
        }
        return false;
    }

    private String jsonString(JSONObject object, String key, String fallback) {
        if (object == null || !object.has(key) || object.isNull(key)) {
            return fallback;
        }
        String value = object.optString(key, fallback);
        return TextUtils.isEmpty(value) ? fallback : value;
    }

    private int jsonInt(JSONObject object, String key, int fallback) {
        if (object == null || !object.has(key) || object.isNull(key)) {
            return fallback;
        }
        try {
            return object.getInt(key);
        } catch (Exception ignored) {
            try {
                return Integer.parseInt(object.optString(key, String.valueOf(fallback)));
            } catch (Exception ignoredAgain) {
                return fallback;
            }
        }
    }

    private double jsonDouble(JSONObject object, String key, double fallback) {
        if (object == null || !object.has(key) || object.isNull(key)) {
            return fallback;
        }
        try {
            return object.getDouble(key);
        } catch (Exception ignored) {
            try {
                return Double.parseDouble(object.optString(key, String.valueOf(fallback)));
            } catch (Exception ignoredAgain) {
                return fallback;
            }
        }
    }

    private long jsonLong(JSONObject object, String key, long fallback) {
        if (object == null || !object.has(key) || object.isNull(key)) {
            return fallback;
        }
        try {
            return object.getLong(key);
        } catch (Exception ignored) {
            try {
                return Long.parseLong(object.optString(key, String.valueOf(fallback)));
            } catch (Exception ignoredAgain) {
                return fallback;
            }
        }
    }

    private long jsonCreatedAtMillis(JSONObject object, long fallback) {
        long direct = jsonLong(object, "createdAtMillis", -1L);
        if (direct > 0L) {
            return direct;
        }
        long parsed = parseIsoMillis(jsonString(object, "createdAt", ""));
        return parsed > 0L ? parsed : fallback;
    }

    private long jsonCompletedAtMillis(JSONObject object) {
        long direct = jsonLong(object, "completedAtMillis", -1L);
        if (direct > 0L) return direct;
        long parsed = parseIsoMillis(jsonString(object, "completedAt", ""));
        if (parsed > 0L) return parsed;
        JSONObject accounting = object == null ? null : object.optJSONObject("completionAccounting");
        return parseIsoMillis(jsonString(accounting, "creditedAt", ""));
    }

    private long parseIsoMillis(String raw) {
        if (TextUtils.isEmpty(raw)) {
            return 0L;
        }
        String normalized = raw.trim();
        String[] patterns = new String[]{
                "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'",
                "yyyy-MM-dd'T'HH:mm:ss'Z'",
                "yyyy-MM-dd'T'HH:mm:ss.SSSXXX",
                "yyyy-MM-dd'T'HH:mm:ssXXX"
        };
        for (String pattern : patterns) {
            try {
                SimpleDateFormat format = new SimpleDateFormat(pattern, Locale.US);
                if (pattern.endsWith("'Z'")) {
                    format.setTimeZone(TimeZone.getTimeZone("UTC"));
                }
                Date date = format.parse(normalized);
                if (date != null) {
                    return date.getTime();
                }
            } catch (Exception ignored) {
            }
        }
        return 0L;
    }

    private boolean jsonHasRejectedPartner(JSONObject object) {
        JSONObject rejected = object == null ? null : object.optJSONObject("rejectedPartnerIds");
        if (rejected == null) {
            return false;
        }
        if (!rejected.has(partnerId())) {
            return false;
        }
        Object value = rejected.opt(partnerId());
        return !(value instanceof Boolean) || (Boolean) value;
    }

    private String mutableString(MutableData data, String key, String fallback) {
        Object value = data.child(key).getValue();
        return value == null ? fallback : String.valueOf(value);
    }

    private double distanceKm(double lat1, double lng1, double lat2, double lng2) {
        double dLat = Math.toRadians(lat2 - lat1);
        double dLng = Math.toRadians(lng2 - lng1);
        double a = Math.sin(dLat / 2) * Math.sin(dLat / 2)
                + Math.cos(Math.toRadians(lat1)) * Math.cos(Math.toRadians(lat2))
                * Math.sin(dLng / 2) * Math.sin(dLng / 2);
        return 6371 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    }

    private void refreshCurrent() {
        if (content == null) {
            return;
        }
        if (currentNavState != null
                && ("booking_chat".equals(currentNavState.screen) || "support_chat".equals(currentNavState.screen))) {
            return;
        }
        if ("home".equals(activeTab)) {
            showDashboard();
        } else if ("bookings".equals(activeTab)) {
            showBookings();
        } else if ("earnings".equals(activeTab)) {
            showEarnings();
        } else if ("detail".equals(activeTab) && activeDetailBooking != null) {
            PartnerBooking updated = findBooking(activeDetailBooking.id);
            PartnerBooking booking = updated == null ? activeDetailBooking : updated;
            if (isFinishedForPartner(booking)) {
                showFinishedBookingList(booking);
            } else {
                showOrderDetail(booking);
            }
        } else if ("map".equals(activeTab) && activeMapBooking != null) {
            PartnerBooking updated = findBooking(activeMapBooking.id);
            PartnerBooking booking = updated == null ? activeMapBooking : updated;
            if (isFinishedForPartner(booking)) {
                showFinishedBookingList(booking);
            } else {
                showInAppMap(booking);
            }
        }
    }

    private PartnerBooking findBooking(String bookingId) {
        for (PartnerBooking booking : bookings) {
            if (booking.id.equals(bookingId)) {
                return booking;
            }
        }
        return null;
    }

    private PartnerBooking freshPendingRequest(List<PartnerBooking> live) {
        if (isIncomingDialogShowing()) {
            return null;
        }
        for (PartnerBooking booking : live) {
            if (isPendingForIncomingAlert(booking)
                    && isRecentRequestAvailable(booking)
                    && !alertedPendingIds.contains(booking.id)) {
                alertedPendingIds.add(booking.id);
                persistAlertedPendingIds();
                return booking;
            }
        }
        return null;
    }

    private void showPendingRequestIfAvailable() {
        if (!online || !isPartnerApproved() || isIncomingDialogShowing()) {
            return;
        }
        for (PartnerBooking booking : bookings) {
            if (isPendingForIncomingAlert(booking)
                    && isRecentRequestAvailable(booking)
                    && !alertedPendingIds.contains(booking.id)) {
                hasUnreadIncomingRequest = true;
                alertedPendingIds.add(booking.id);
                persistAlertedPendingIds();
                startBellShake();
                startIncomingRequestAlert(booking);
                return;
            }
        }
    }

    private boolean isIncomingDialogShowing() {
        return incomingRequestDialog != null && incomingRequestDialog.isShowing();
    }

    private void pruneAlertedPendingIds(List<PartnerBooking> live) {
        Set<String> pendingIds = new HashSet<>();
        for (PartnerBooking booking : live) {
            if (isPendingForIncomingAlert(booking)) {
                pendingIds.add(booking.id);
            }
        }
        if (alertedPendingIds.retainAll(pendingIds)) {
            persistAlertedPendingIds();
        }
    }

    private boolean isPendingForIncomingAlert(PartnerBooking booking) {
        if (!isPartnerApproved() || booking == null || TextUtils.isEmpty(booking.id)) {
            return false;
        }
        String status = booking.status == null ? "" : booking.status.toLowerCase(Locale.US);
        return ("pending".equals(status) || "sent_to_partner".equals(status))
                && isRecentRequestAvailable(booking);
    }

    private boolean isRecentRequestAvailable(PartnerBooking booking) {
        // Open requests stay available until accepted, rejected, or cancelled.
        // Their visibility must never depend on local time, night hours, or age.
        return booking != null && !TextUtils.isEmpty(booking.id);
    }

    private void showBookingNotification(PartnerBooking booking) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU
                && checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS) != PackageManager.PERMISSION_GRANTED) {
            return;
        }
        NotificationManager manager = (NotificationManager) getSystemService(NOTIFICATION_SERVICE);
        if (manager == null) {
            return;
        }
        ensureBookingNotificationChannel();
        Intent intent = new Intent(this, MainActivity.class);
        intent.setFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP | Intent.FLAG_ACTIVITY_CLEAR_TOP);
        intent.putExtra(KEY_PUSH_ACTION_TYPE, "OPEN_PARTNER_BOOKING");
        intent.putExtra(KEY_PUSH_ACTION_ID, booking.id);
        int flags = PendingIntent.FLAG_UPDATE_CURRENT;
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
            flags |= PendingIntent.FLAG_IMMUTABLE;
        }
        int notificationId = Math.abs(booking.id.hashCode());
        PendingIntent pendingIntent = PendingIntent.getActivity(this, notificationId, intent, flags);
        Notification.Builder builder = Build.VERSION.SDK_INT >= Build.VERSION_CODES.O
                ? new Notification.Builder(this, CHANNEL_BOOKING_REQUESTS)
                : new Notification.Builder(this);
        String distance = distanceLabel(booking);
        String body = bookingTitle(booking) + "\n" + (TextUtils.isEmpty(distance) ? "Nearby service request" : distance);
        builder.setSmallIcon(R.drawable.ic_partner_dash_bell)
                .setContentTitle("New Booking Received")
                .setContentText(bookingTitle(booking) + " - " + (TextUtils.isEmpty(distance) ? "Nearby" : distance))
                .setStyle(new Notification.BigTextStyle().bigText(body))
                .setDefaults(Notification.DEFAULT_VIBRATE)
                .setOnlyAlertOnce(true)
                .setCategory(Notification.CATEGORY_MESSAGE)
                .setVisibility(Notification.VISIBILITY_PUBLIC)
                .setPriority(Notification.PRIORITY_MAX)
                .setAutoCancel(true)
                .setContentIntent(pendingIntent)
                .addAction(android.R.drawable.ic_menu_close_clear_cancel, "Reject", bookingActionPendingIntent(booking.id, false, notificationId + 11))
                .addAction(android.R.drawable.ic_menu_send, "Accept", bookingActionPendingIntent(booking.id, true, notificationId + 12));
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) {
            builder.setSound(Uri.parse("android.resource://" + getPackageName() + "/" + R.raw.incoming_booking_alert));
        }
        manager.notify(notificationId, builder.build());
    }

    private PendingIntent bookingActionPendingIntent(String bookingId, boolean accept, int requestCode) {
        Intent actionIntent = new Intent(this, PartnerBookingActionReceiver.class);
        actionIntent.setAction(accept ? PartnerBookingActionReceiver.ACTION_ACCEPT_BOOKING : PartnerBookingActionReceiver.ACTION_REJECT_BOOKING);
        actionIntent.putExtra(PartnerBookingActionReceiver.EXTRA_BOOKING_ID, bookingId);
        int flags = PendingIntent.FLAG_UPDATE_CURRENT;
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
            flags |= PendingIntent.FLAG_IMMUTABLE;
        }
        return PendingIntent.getBroadcast(this, requestCode, actionIntent, flags);
    }

    private void startIncomingRequestAlert(PartnerBooking booking) {
        if (!appInForeground) {
            hasUnreadIncomingRequest = true;
            showBookingNotification(booking);
            return;
        }
        if (isIncomingDialogShowing() && booking.id.equals(incomingRequestDialogBookingId)) {
            return;
        }
        stopIncomingRequestAlert();
        showIncomingBookingPopup(booking);
        startIncomingCountdown();
        stopIncomingAlertRunnable = () -> expireIncomingRequest(booking);
        refreshHandler.postDelayed(stopIncomingAlertRunnable, 20000);
    }

    private void showIncomingBookingPopup(PartnerBooking booking) {
        if (incomingRequestDialog != null && incomingRequestDialog.isShowing()
                && booking.id.equals(incomingRequestDialogBookingId)) {
            return;
        }
        dismissIncomingBookingPopup();
        incomingRequestDialogBookingId = booking.id;
        incomingRequestDialog = new AlertDialog.Builder(this).create();
        incomingRequestDialog.setView(incomingRequestPopupViewV2(booking));
        incomingRequestDialog.setOnCancelListener(dialog -> {
            if (!dismissingIncomingDialog) {
                stopIncomingRequestAlert();
            }
        });
        if (!showDialogSafely(incomingRequestDialog)) {
            incomingRequestDialog = null;
            incomingRequestDialogBookingId = "";
            return;
        }
        Window window = incomingRequestDialog.getWindow();
        if (window != null) {
            window.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));
            window.setDimAmount(0.58f);
            window.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);
            window.setLayout((int) (getResources().getDisplayMetrics().widthPixels * 0.94f), WindowManager.LayoutParams.WRAP_CONTENT);
        }
    }

    /**
     * Returns a short human label for a scheduled booking's slot, or "" for an
     * instant booking. Prefers the backend-provided label; otherwise builds one
     * from the raw slot key.
     */
    private String scheduledPopupText(PartnerBooking booking) {
        if (booking == null || !"scheduled".equalsIgnoreCase(booking.bookingType)) return "";
        // Backend usually sends a ready label like "Tomorrow Afternoon (12pm – 5pm)".
        if (!TextUtils.isEmpty(booking.scheduledSlotLabel)) return booking.scheduledSlotLabel;
        // Otherwise build one ourselves from the date + slot so the partner still
        // sees exactly when the customer wants the service (never a blank).
        String slot = booking.scheduledSlot == null ? "" : booking.scheduledSlot.toLowerCase(Locale.US);
        String slotLabel = "";
        if ("morning".equals(slot)) slotLabel = "Morning (6am – 12pm)";
        else if ("afternoon".equals(slot)) slotLabel = "Afternoon (12pm – 5pm)";
        else if ("evening".equals(slot)) slotLabel = "Evening (5pm – 10pm)";
        String dayLabel = scheduledDayLabel(booking.scheduledDate);
        if (!TextUtils.isEmpty(dayLabel) && !TextUtils.isEmpty(slotLabel)) return dayLabel + " " + slotLabel;
        if (!TextUtils.isEmpty(dayLabel)) return dayLabel;
        return slotLabel;
    }

    /**
     * Converts a backend "yyyy-MM-dd" (IST) scheduled date into a friendly day
     * label: "Today", "Tomorrow", or e.g. "16 May". Returns "" if unparseable.
     */
    private String scheduledDayLabel(String isoDate) {
        if (TextUtils.isEmpty(isoDate)) return "";
        String raw = isoDate.trim();
        try {
            java.util.TimeZone ist = java.util.TimeZone.getTimeZone("Asia/Kolkata");
            SimpleDateFormat parser = new SimpleDateFormat("yyyy-MM-dd", Locale.US);
            parser.setTimeZone(ist);
            Calendar target = Calendar.getInstance(ist);
            target.setTime(parser.parse(raw));
            Calendar today = Calendar.getInstance(ist);
            Calendar tomorrow = Calendar.getInstance(ist);
            tomorrow.add(Calendar.DAY_OF_MONTH, 1);
            if (sameDay(target, today)) return "Today";
            if (sameDay(target, tomorrow)) return "Tomorrow";
            SimpleDateFormat pretty = new SimpleDateFormat("d MMM", Locale.US);
            pretty.setTimeZone(ist);
            return pretty.format(target.getTime());
        } catch (Exception ignored) {
            return raw;
        }
    }

    private boolean sameDay(Calendar a, Calendar b) {
        return a.get(Calendar.YEAR) == b.get(Calendar.YEAR)
                && a.get(Calendar.DAY_OF_YEAR) == b.get(Calendar.DAY_OF_YEAR);
    }

    /**
     * The "when does the customer want the service" text shown on the incoming
     * booking popup. Scheduled bookings show their slot label; everything else
     * falls back to the customer-provided date/time in {@code booking.time}.
     * Returns "" only when no useful information is available.
     */
    private String requestedWhenText(PartnerBooking booking) {
        if (booking == null) return "";
        String scheduled = scheduledPopupText(booking);
        if (!TextUtils.isEmpty(scheduled)) {
            return scheduled;
        }
        String raw = booking.time == null ? "" : booking.time.trim();
        // Skip the generic placeholder that means "no specific time requested".
        if (TextUtils.isEmpty(raw) || raw.equalsIgnoreCase("Partner provides arrival ETA")) {
            return "As soon as possible";
        }
        return raw;
    }

