        card.addView(details, margin(-1, -2, 0, 0, 0, 8));

        LinearLayout timerRow = horizontal();
        timerRow.setGravity(Gravity.CENTER_VERTICAL);
        TextView clock = text("\u25CB", 14, ROSE, true);
        clock.setGravity(Gravity.CENTER);
        clock.setBackground(round(Color.rgb(255, 237, 242), dp(14)));
        timerRow.addView(clock, new LinearLayout.LayoutParams(dp(28), dp(28)));
        timerRow.addView(text("  Saved to Recent Requests in", 12, BLACK, false), new LinearLayout.LayoutParams(0, -2, 1));
        TextView timer = text("20\nsec", 14, BLACK, true);
        timer.setGravity(Gravity.CENTER);
