    private String customerDisplay(PartnerBooking booking) {
        if (TextUtils.isEmpty(booking.customerPhone)) {
            return booking.customer;
        }
        return booking.customer + "\n" + maskedCustomerPhone(booking) + "\nProtected calling only";
    }

    private String customerCallLabel(String value) {
        if (TextUtils.isEmpty(value)) {
            return "customer";
        }
        String[] lines = value.split("\\n");
        return lines.length > 1 ? lines[1].trim() : "customer";
    }

    private String maskedCustomerPhone(PartnerBooking booking) {
        if (booking == null || TextUtils.isEmpty(booking.customerPhone)) {
            return "Number protected";
        }
        String phone = booking.customerPhone.trim();
        if (phone.contains("*") || phone.toLowerCase(Locale.US).contains("protected")) {
            return phone;
        }
        String digits = phone.replaceAll("\\D", "");
        if (digits.length() < 4) {
            return "Number protected";
        }
        String last = digits.substring(digits.length() - 4);
        String prefix = digits.length() > 10 ? "+" + digits.substring(0, digits.length() - 10) + " " : "";
        return prefix + "******" + last;
    }

    private String maskedPhoneValue(String phone) {
        if (TextUtils.isEmpty(phone)) return "Number protected";
        String digits = phone.replaceAll("\\D", "");
        if (digits.length() < 4) return "Number protected";
        return "+91 ******" + digits.substring(digits.length() - 4);
    }

    private boolean isCallablePhoneNumber(String value) {
        if (TextUtils.isEmpty(value)) {
            return false;
        }
        String clean = value.trim();
        String lower = clean.toLowerCase(Locale.US);
        return !clean.contains("*")
                && !lower.contains("protected")
                && clean.replaceAll("\\D", "").length() >= 6;
    }

    private String callableCustomerPhone(PartnerBooking booking) {
        if (booking == null || !isCallablePhoneNumber(booking.customerPhone)) {
            return "";
        }
        return booking.customerPhone.trim();
    }

    private void showProtectedCallSheet(PartnerBooking booking) {
        if (booking == null || TextUtils.isEmpty(booking.id)) {
            Toast.makeText(this, "Booking not available", Toast.LENGTH_SHORT).show();
            return;
        }
        if (statusStage(booking) < 1) {
            Toast.makeText(this, "Accept booking first. Customer number is protected.", Toast.LENGTH_LONG).show();
            return;
        }
        AlertDialog dialog = new AlertDialog.Builder(this).create();
        LinearLayout sheet = vertical();
        sheet.setPadding(dp(20), dp(18), dp(20), dp(16));
        sheet.setBackground(stroke(Color.WHITE, Color.rgb(250, 214, 224), dp(22)));
        sheet.addView(text("Protected Calling", 19, BLACK, true));
        sheet.addView(text("Primary: " + maskedCustomerPhone(booking), 13, MUTED, false), margin(-1, -2, 0, 5, 0, 4));
        String alternatePhone = bookingAlternatePhoneCache.get(booking.id);
        if (!TextUtils.isEmpty(alternatePhone)) {
            sheet.addView(text("Alternate: " + maskedPhoneValue(alternatePhone), 13, MUTED, false), margin(-1, -2, 0, 2, 0, 8));
        }
        sheet.addView(text("Call ApnaServo virtual number. The customer real number stays hidden and this call is logged.", 12, MUTED, false), margin(-1, -2, 0, 0, 0, 14));

        TextView call = roseButton("\u260E  Call Primary via ApnaServo");
        call.setOnClickListener(view -> {
            dialog.dismiss();
            startVirtualCustomerCall(booking, "primary");
        });
        sheet.addView(call, new LinearLayout.LayoutParams(-1, dp(50)));

        if (!TextUtils.isEmpty(alternatePhone)) {
            TextView alternateCall = outlineButton("\u260E  Call Alternate Number");
            alternateCall.setTextSize(13);
            alternateCall.setOnClickListener(view -> {
                dialog.dismiss();
                startVirtualCustomerCall(booking, "alternate");
            });
            sheet.addView(alternateCall, margin(-1, 48, 0, 10, 0, 0));
        }

        TextView report = outlineButton("Report spam / call issue");
        report.setTextSize(13);
        report.setOnClickListener(view -> {
            dialog.dismiss();
            showCallReportDialog(booking);
        });
        sheet.addView(report, margin(-1, 48, 0, 10, 0, 0));

        TextView cancel = text("Cancel", 13, MUTED, true);
        cancel.setGravity(Gravity.CENTER);
        cancel.setOnClickListener(view -> dialog.dismiss());
        sheet.addView(cancel, margin(-1, 38, 0, 2, 0, 0));

        dialog.setView(sheet);
        showDialogSafely(dialog);
        Window window = dialog.getWindow();
        if (window != null) {
            window.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));
        }
    }

    private void startVirtualCustomerCall(PartnerBooking booking) {
        startVirtualCustomerCall(booking, "primary");
    }

    private void startVirtualCustomerCall(PartnerBooking booking, String contactType) {
        Toast.makeText(this, "Creating protected call log...", Toast.LENGTH_SHORT).show();
        String alternate = bookingAlternatePhoneCache.get(booking.id);
        String fallbackPhone = "alternate".equals(contactType) && isCallablePhoneNumber(alternate) ? alternate : callableCustomerPhone(booking);
        backendClient.createCallLog(booking.id, "start", "", contactType, new BackendClient.JsonCallback() {
            @Override
            public void onSuccess(JSONObject object) {
                String phoneNumber = object.optString("phoneNumber", object.optString("virtualNumber", fallbackPhone));
                if (!isCallablePhoneNumber(phoneNumber)) {
                    phoneNumber = fallbackPhone;
                }
                if (!isCallablePhoneNumber(phoneNumber)) {
                    Toast.makeText(MainActivity.this, "Customer phone number unavailable", Toast.LENGTH_LONG).show();
                    return;
                }
                dialVirtualNumber(phoneNumber);
            }

            @Override
            public void onError(String message) {
                if (!TextUtils.isEmpty(fallbackPhone)) {
                    dialVirtualNumber(fallbackPhone);
                    return;
                }
                Toast.makeText(MainActivity.this, "Protected call failed to start: " + message, Toast.LENGTH_LONG).show();
            }
        });
    }

    private void dialVirtualNumber(String virtualNumber) {
        String clean = virtualNumber == null ? "" : virtualNumber.trim();
        if (TextUtils.isEmpty(clean)) {
            Toast.makeText(this, "Virtual number missing", Toast.LENGTH_SHORT).show();
            return;
        }
        Intent intent = new Intent(Intent.ACTION_DIAL, Uri.parse("tel:" + Uri.encode(clean)));
        try {
            startActivity(intent);
        } catch (Exception error) {
            Toast.makeText(this, "Unable to open the dialer.", Toast.LENGTH_SHORT).show();
        }
    }

