    private View slideToAcceptControl(PartnerBooking booking) {
        FrameLayout slider = new FrameLayout(this);
        slider.setPadding(dp(6), dp(6), dp(6), dp(6));
        slider.setClipChildren(false);
        slider.setClipToPadding(false);
        slider.setBackground(gradient(Color.rgb(0, 180, 82), Color.rgb(0, 214, 96), dp(30)));
        slider.setElevation(dp(12));

        View progress = new View(this);
        progress.setBackground(gradient(Color.rgb(48, 232, 135), Color.rgb(132, 255, 183), dp(28)));
        progress.setAlpha(0.42f);
        progress.setPivotX(0f);
        progress.setScaleX(0.12f);
        slider.addView(progress, new FrameLayout.LayoutParams(-1, -1));

        View motionTrail = new SlideSpeedLinesView(this);
        motionTrail.setAlpha(0.42f);
        FrameLayout.LayoutParams trailParams = new FrameLayout.LayoutParams(-1, -1);
        trailParams.setMargins(dp(76), 0, dp(72), 0);
        slider.addView(motionTrail, trailParams);

        TextView label = text("Accept Booking\nSlide right to accept", 16, Color.WHITE, true);
        label.setGravity(Gravity.CENTER_VERTICAL);
        label.setLineSpacing(dp(2), 0.96f);
        FrameLayout.LayoutParams labelParams = new FrameLayout.LayoutParams(-1, -1);
        labelParams.setMargins(dp(82), 0, dp(70), 0);
        slider.addView(label, labelParams);

        FrameLayout target = new FrameLayout(this);
        target.setBackground(round(Color.argb(28, 255, 255, 255), dp(27)));
        target.addView(new SlideChevronView(this, Color.argb(128, 255, 255, 255), 2), new FrameLayout.LayoutParams(dp(25), dp(25), Gravity.CENTER));
        FrameLayout.LayoutParams targetParams = new FrameLayout.LayoutParams(dp(54), dp(54), Gravity.RIGHT | Gravity.CENTER_VERTICAL);
        targetParams.setMargins(0, 0, dp(5), 0);
        slider.addView(target, targetParams);
        startSlideArrowPulse(target);

        FrameLayout thumb = new FrameLayout(this);
        thumb.setBackground(stroke(Color.WHITE, Color.rgb(219, 244, 227), dp(29)));
        thumb.setElevation(dp(8));
        View thumbChevrons = new SlideChevronView(this, Color.rgb(0, 184, 82), 2);
        thumb.addView(thumbChevrons, new FrameLayout.LayoutParams(dp(26), dp(26), Gravity.CENTER));
        TextView thumbCheck = text("\u2713", 25, Color.rgb(0, 184, 82), true);
        thumbCheck.setGravity(Gravity.CENTER);
        thumbCheck.setVisibility(View.GONE);
        thumb.addView(thumbCheck, new FrameLayout.LayoutParams(-1, -1));
        FrameLayout.LayoutParams thumbParams = new FrameLayout.LayoutParams(dp(58), dp(58), Gravity.LEFT | Gravity.CENTER_VERTICAL);
        thumbParams.setMargins(dp(5), 0, 0, 0);
        slider.addView(thumb, thumbParams);

        final float[] startTouchX = {0f};
        final float[] startThumbX = {0f};
        final boolean[] accepting = {false};
        final boolean[] dragging = {false};
        slider.setOnTouchListener((view, event) -> {
            if (accepting[0]) {
                return true;
            }
            int maxTravel = Math.max(1, slider.getWidth() - thumb.getWidth() - dp(10));
            if (event.getActionMasked() == MotionEvent.ACTION_DOWN) {
                float thumbLeft = thumb.getLeft() + thumb.getTranslationX() - dp(12);
                float thumbRight = thumb.getRight() + thumb.getTranslationX() + dp(18);
                if (event.getX() < thumbLeft || event.getX() > thumbRight) {
                    dragging[0] = false;
                    return false;
                }
                dragging[0] = true;
                startTouchX[0] = event.getX();
                startThumbX[0] = thumb.getTranslationX();
                slider.animate().scaleX(0.985f).scaleY(0.985f).setDuration(70).start();
                return true;
            }
            if (!dragging[0]) {
                return false;
            }
            if (event.getActionMasked() == MotionEvent.ACTION_MOVE) {
                float next = Math.max(0f, Math.min(maxTravel, startThumbX[0] + event.getX() - startTouchX[0]));
                float percent = next / maxTravel;
                updateSlideAcceptProgress(thumb, progress, label, target, next, percent);
                return true;
            }
            if (event.getActionMasked() == MotionEvent.ACTION_UP) {
                dragging[0] = false;
                slider.animate().scaleX(1f).scaleY(1f).setDuration(120).start();
                float percent = thumb.getTranslationX() / maxTravel;
                if (percent >= 0.72f) {
                    accepting[0] = true;
                    pauseIncomingRequestAlert();
                    label.setText("Booking Accepted!\nOpening details...");
                    thumbChevrons.setVisibility(View.GONE);
                    thumbCheck.setVisibility(View.VISIBLE);
                    target.animate().alpha(0f).setDuration(100).start();
                    updateSlideAcceptProgress(thumb, progress, label, target, maxTravel, 1f);
                    label.setAlpha(1f);
                    thumb.animate().translationX(maxTravel).setDuration(120).setInterpolator(new AccelerateDecelerateInterpolator()).start();
                    progress.animate().scaleX(1f).setDuration(120).start();
                    refreshHandler.postDelayed(() -> {
                        if (!isCurrentPendingIncomingBooking(booking)) {
                            stopIncomingRequestAlert();
                            return;
                        }
                        hasUnreadIncomingRequest = false;
                        stopIncomingRequestAlert();
                        PartnerBooking current = findBooking(booking.id);
                        acceptBooking(current == null ? booking : current);
                    }, 320);
                } else {
                    resetSlideAcceptControl(thumb, progress, label, target);
                }
                return true;
            }
            if (event.getActionMasked() == MotionEvent.ACTION_CANCEL) {
                dragging[0] = false;
                slider.animate().scaleX(1f).scaleY(1f).setDuration(120).start();
                resetSlideAcceptControl(thumb, progress, label, target);
                return true;
            }
            return true;
        });
        return slider;
    }

    private void updateSlideAcceptProgress(View thumb, View progress, View label, View target, float thumbX, float percent) {
        thumb.setTranslationX(thumbX);
        progress.setScaleX(0.12f + (0.88f * percent));
        label.setAlpha(1f - (0.35f * percent));
        target.setScaleX(1f + (0.08f * percent));
        target.setScaleY(1f + (0.08f * percent));
    }

    private void resetSlideAcceptControl(View thumb, View progress, View label, View target) {
        thumb.animate().translationX(0f).setDuration(220).setInterpolator(new AccelerateDecelerateInterpolator()).start();
        progress.animate().scaleX(0.12f).setDuration(220).setInterpolator(new AccelerateDecelerateInterpolator()).start();
        label.animate().alpha(1f).setDuration(180).start();
        target.animate().scaleX(1f).scaleY(1f).setDuration(180).start();
    }

    private void startSlideArrowPulse(View target) {
        ObjectAnimator pulse = ObjectAnimator.ofFloat(target, "translationX", 0f, dp(5), 0f);
        pulse.setDuration(950);
        pulse.setRepeatCount(ObjectAnimator.INFINITE);
        pulse.setInterpolator(new AccelerateDecelerateInterpolator());
        pulse.start();
    }

    private String customerInitials(String name) {
        if (TextUtils.isEmpty(name)) {
            return "AS";
        }
        String[] parts = name.trim().split("\\s+");
        if (parts.length == 1) {
            return parts[0].substring(0, Math.min(1, parts[0].length())).toUpperCase(Locale.ROOT);
        }
        return (parts[0].substring(0, 1) + parts[parts.length - 1].substring(0, 1)).toUpperCase(Locale.ROOT);
    }

    private void expireIncomingRequest(PartnerBooking booking) {
        if (!isCurrentPendingIncomingBooking(booking)) {
            return;
        }
        saveRequestForLater(booking);
    }

    private void saveRequestForLater(PartnerBooking booking) {
        hasUnreadIncomingRequest = false;
        stopIncomingRequestAlert();
        if (booking != null && !TextUtils.isEmpty(booking.id)) {
            alertedPendingIds.add(booking.id);
            persistAlertedPendingIds();
        }
        savePartnerBookingCache();
        if (appInForeground) {
            Toast.makeText(this, "Request saved in Recent Requests", Toast.LENGTH_SHORT).show();
            if ("request".equals(activeTab) || "arrival_estimate".equals(activeTab)) {
                showDashboard();
            } else {
                refreshCurrent();
            }
        }
    }

    private void declineIncomingBooking(PartnerBooking booking) {
        if (!isCurrentPendingIncomingBooking(booking)) {
            stopIncomingRequestAlert();
            return;
        }
        hasUnreadIncomingRequest = false;
        stopIncomingRequestAlert();
        PartnerBooking current = findBooking(booking.id);
        cancelBooking(current == null ? booking : current);
    }

    private boolean isCurrentPendingIncomingBooking(PartnerBooking booking) {
        if (booking == null
                || TextUtils.isEmpty(booking.id)
                || !booking.id.equals(incomingRequestDialogBookingId)
                || !isIncomingDialogShowing()) {
            return false;
        }
        PartnerBooking current = findBooking(booking.id);
        return current != null && isPendingForIncomingAlert(current);
    }

    private void startIncomingCountdown() {
        incomingSecondsRemaining = 20;
        updateIncomingCountdownText();
        incomingTimerRunnable = new Runnable() {
            @Override
            public void run() {
                incomingSecondsRemaining = Math.max(0, incomingSecondsRemaining - 1);
                updateIncomingCountdownText();
                if (incomingSecondsRemaining > 0 && incomingTimerView != null) {
                    refreshHandler.postDelayed(this, 1000);
                }
            }
        };
        refreshHandler.postDelayed(incomingTimerRunnable, 1000);
    }

    private void updateIncomingCountdownText() {
        if (incomingTimerView != null) {
            incomingTimerView.setText(incomingSecondsRemaining + "\nsec");
        }
    }

    private void dismissIncomingBookingPopup() {
        if (incomingRequestDialog != null) {
            try {
                if (incomingRequestDialog.isShowing()) {
                    dismissingIncomingDialog = true;
                    incomingRequestDialog.dismiss();
                    dismissingIncomingDialog = false;
                }
            } catch (Exception ignored) {
                dismissingIncomingDialog = false;
            }
            incomingRequestDialog = null;
            incomingRequestDialogBookingId = "";
        }
    }

    private void startSmallBellAnimation(View bell) {
        ObjectAnimator shake = ObjectAnimator.ofFloat(bell, "rotation", 0f, -12f, 12f, -8f, 8f, 0f);
        shake.setDuration(650);
        shake.setInterpolator(new AccelerateDecelerateInterpolator());
        shake.start();
    }

    private void startBellShake() {
        if (dashboardBellView == null) {
            return;
        }
        ObjectAnimator shake = ObjectAnimator.ofFloat(dashboardBellView, "rotation", 0f, -14f, 14f, -10f, 10f, 0f);
        shake.setDuration(760);
        shake.setInterpolator(new AccelerateDecelerateInterpolator());
        shake.start();
        startBellIdlePulse(dashboardBellView);
    }

    private void startBellIdlePulse(View bell) {
        bell.animate().cancel();
        bell.animate()
                .scaleX(1.08f)
                .scaleY(1.08f)
                .setDuration(420)
                .withEndAction(() -> {
                    if (hasUnreadIncomingRequest && dashboardBellView != null) {
                        dashboardBellView.animate().scaleX(1f).scaleY(1f).setDuration(420).withEndAction(() -> {
                            if (hasUnreadIncomingRequest && dashboardBellView != null) {
                                startBellIdlePulse(dashboardBellView);
                            }
                        }).start();
                    }
                })
                .start();
    }

    private void stopBellAnimation() {
        if (dashboardBellView != null) {
            dashboardBellView.animate().cancel();
            dashboardBellView.setScaleX(1f);
            dashboardBellView.setScaleY(1f);
            dashboardBellView.setRotation(0f);
        }
    }

    private void stopIncomingRequestAlert() {
        pauseIncomingRequestAlert();
        dismissIncomingBookingPopup();
    }

    private void pauseIncomingRequestAlert() {
        if (stopIncomingAlertRunnable != null) {
            refreshHandler.removeCallbacks(stopIncomingAlertRunnable);
            stopIncomingAlertRunnable = null;
        }
        if (incomingTimerRunnable != null) {
            refreshHandler.removeCallbacks(incomingTimerRunnable);
            incomingTimerRunnable = null;
        }
        incomingTimerView = null;
        Vibrator vibrator = (Vibrator) getSystemService(VIBRATOR_SERVICE);
        if (vibrator != null) {
            vibrator.cancel();
        }
    }

    private void saveState() {
        prefs.edit()
                .putStringSet(KEY_ACCEPTED, new HashSet<>(acceptedIds))
                .putStringSet(KEY_COMPLETED, new HashSet<>(completedIds))
                .putStringSet(KEY_CANCELLED, new HashSet<>(cancelledIds))
                .putStringSet(KEY_PAID, new HashSet<>(paidIds))
                .apply();
    }

    private void persistAlertedPendingIds() {
        if (prefs != null) {
            prefs.edit().putStringSet(KEY_ALERTED_PENDING, new HashSet<>(alertedPendingIds)).apply();
        }
    }

    private List<PartnerBooking> loadCachedPartnerBookings() {
        List<PartnerBooking> cached = new ArrayList<>();
        String raw = prefs.getString(KEY_BOOKING_CACHE, "[]");
        try {
            JSONArray array = new JSONArray(raw);
            for (int index = 0; index < array.length(); index++) {
                JSONObject object = array.optJSONObject(index);
                if (object == null) {
                    continue;
                }
                PartnerBooking booking = partnerBookingFromCacheJson(object);
                if (booking != null && !TextUtils.isEmpty(booking.id)) {
                    cached.add(booking);
                }
            }
        } catch (Exception ignored) {
            prefs.edit().remove(KEY_BOOKING_CACHE).apply();
        }
        Collections.sort(cached, (left, right) -> Long.compare(right.createdAtMillis, left.createdAtMillis));
        return cached;
    }

    private void savePartnerBookingCache() {
        if (prefs == null || bookings == null) {
            return;
        }
        JSONArray array = new JSONArray();
        int saved = 0;
        for (PartnerBooking booking : bookings) {
            if (booking == null || TextUtils.isEmpty(booking.id)) {
                continue;
            }
            array.put(partnerBookingToJson(booking));
            saved++;
            if (saved >= 150) {
                break;
            }
        }
        prefs.edit().putString(KEY_BOOKING_CACHE, array.toString()).apply();
    }

    private JSONObject partnerBookingToJson(PartnerBooking booking) {
        JSONObject object = new JSONObject();
        try {
            object.put("id", booking.id);
            object.put("service", booking.service);
            object.put("issue", booking.issue);
            object.put("customer", booking.customer);
            object.put("address", booking.address);
            object.put("city", booking.city);
            object.put("time", booking.time);
            object.put("defaultAmount", booking.defaultAmount);
            object.put("status", booking.status);
            object.put("lat", booking.lat);
            object.put("lng", booking.lng);
            object.put("createdAtMillis", booking.createdAtMillis);
            object.put("completedAtMillis", booking.completedAtMillis);
            object.put("customerPhone", booking.customerPhone);
            object.put("quoteStatus", booking.quoteStatus);
            object.put("quoteCounterAmount", booking.quoteCounterAmount);
            object.put("quoteCounterMessage", booking.quoteCounterMessage);
            object.put("quoteExpiresAtMillis", booking.quoteExpiresAtMillis);
        } catch (Exception ignored) {
        }
        return object;
    }

    private PartnerBooking partnerBookingFromCacheJson(JSONObject object) {
        if (object == null) {
            return null;
        }
        return new PartnerBooking(
                object.optString("id", ""),
                object.optString("service", "Service"),
                object.optString("issue", "Service request"),
                object.optString("customer", "Customer"),
                object.optString("address", "Customer address"),
                object.optString("city", "Guwahati"),
                object.optString("time", "10:30 AM"),
                object.optInt("defaultAmount", 0),
                object.optString("status", "pending"),
                object.optDouble("lat", 0),
                object.optDouble("lng", 0),
                object.optLong("createdAtMillis", System.currentTimeMillis()),
                object.optLong("completedAtMillis", 0),
                object.optString("customerPhone", ""),
                object.optString("quoteStatus", ""),
                object.optInt("quoteCounterAmount", 0),
                object.optString("quoteCounterMessage", ""),
                object.optLong("quoteExpiresAtMillis", 0)
        );
    }

    private void hydrateLocalStateFromCachedBookings(List<PartnerBooking> cached) {
        if (cached == null) {
            return;
        }
        boolean changed = false;
        for (PartnerBooking booking : cached) {
            if (booking == null || TextUtils.isEmpty(booking.id)) {
                continue;
            }
            String status = normalizedStatus(booking);
            if ("accepted".equals(status)
                    || "on_the_way".equals(status)
                    || "arrived".equals(status)
                    || "started".equals(status)
                    || "amount_pending".equals(status)) {
                changed |= acceptedIds.add(booking.id);
            }
            if ("completed".equals(status)) {
                changed |= completedIds.add(booking.id);
                changed |= paidIds.add(booking.id);
            }
            if ("cancelled".equals(status) || "rejected".equals(status)) {
                changed |= cancelledIds.add(booking.id);
            }
        }
        if (changed) {
            saveState();
        }
    }

    private boolean isPending(PartnerBooking booking) {
        return ("pending".equalsIgnoreCase(booking.status) || "sent_to_partner".equalsIgnoreCase(booking.status))
                && isRecentRequestAvailable(booking)
                && !acceptedIds.contains(booking.id)
                && !completedIds.contains(booking.id)
                && !cancelledIds.contains(booking.id)
                && !hiddenTakenIds.contains(booking.id);
    }

    private boolean isActive(PartnerBooking booking) {
        String status = booking.status == null ? "" : booking.status.toLowerCase(Locale.US);
        return (acceptedIds.contains(booking.id)
                || "accepted".equals(status)
                || "on_the_way".equals(status)
                || "arrived".equals(status)
                || "started".equals(status)
                || "amount_pending".equals(status))
                && !completedIds.contains(booking.id)
                && !cancelledIds.contains(booking.id);
    }

    private int pendingCount() {
        int count = 0;
        for (PartnerBooking booking : bookings) {
            if (isPending(booking)) count++;
        }
        return count;
    }

    private int activeCount() {
        if (backendStatsLoaded && !isStaffSession()) return backendActiveJobs;
        int count = 0;
        for (PartnerBooking booking : bookings) {
            if (isActive(booking)) count++;
        }
        return count;
    }

    private int completedCount() {
        if (backendStatsLoaded && !isStaffSession()) return backendCompletedJobs;
        int count = 0;
        for (PartnerBooking booking : bookings) {
            if ("completed".equalsIgnoreCase(booking.status)) {
                count++;
            }
        }
        return count;
    }

    private int cancelledCount() {
        int count = cancelledIds.size();
        for (PartnerBooking booking : bookings) {
            if (("cancelled".equalsIgnoreCase(booking.status) || "rejected".equalsIgnoreCase(booking.status))
                    && !cancelledIds.contains(booking.id)) {
                count++;
            }
        }
        return count;
    }

    private int todayEarnings() {
        if (backendStatsLoaded && !isStaffSession()) return backendTodayEarnings;
        return earningsForPeriod("today");
    }

    private int totalEarnings() {
        if (backendStatsLoaded && !isStaffSession()) return backendTotalEarnings;
        int total = 0;
        for (PartnerBooking booking : bookings) {
            if (paidIds.contains(booking.id) || "completed".equalsIgnoreCase(booking.status)) {
                total += finalAmount(booking);
            }
        }
        return total;
    }

    private int selectedEarnings() {
        if ("payouts".equals(earningsPeriod)) {
            return totalEarnings();
        }
        return earningsForPeriod(earningsPeriod);
    }

    private int earningsForPeriod(String period) {
        if (backendStatsLoaded && !isStaffSession()) {
            if ("today".equals(period)) return backendTodayEarnings;
            if ("week".equals(period)) return backendWeekEarnings;
            if ("month".equals(period)) return backendMonthEarnings;
            return backendTotalEarnings;
        }
        int total = 0;
        for (PartnerBooking booking : bookings) {
            if ((paidIds.contains(booking.id) || "completed".equalsIgnoreCase(booking.status))
                    && isWithinEarningsPeriod(booking, period)) {
                total += finalAmount(booking);
            }
        }
        return total;
    }

    private int serviceEarnings() {
        return Math.max(0, selectedEarnings() - incentives() - tips());
    }

    private int incentives() {
        return 0;
    }

    private int tips() {
        return 0;
    }

    private int selectedCompletedCount() {
        int count = 0;
        for (PartnerBooking booking : bookings) {
            if ((paidIds.contains(booking.id) || "completed".equalsIgnoreCase(booking.status))
                    && ("payouts".equals(earningsPeriod) || isWithinEarningsPeriod(booking, earningsPeriod))) {
                count++;
            }
        }
        return count;
    }

    private boolean isWithinEarningsPeriod(PartnerBooking booking, String period) {
        long time = booking.completedAtMillis > 0 ? booking.completedAtMillis : booking.createdAtMillis;
        if (time <= 0) {
            return false;
        }
        Calendar bookingDate = Calendar.getInstance();
        bookingDate.setTimeInMillis(time);
        Calendar now = Calendar.getInstance();
        if ("today".equals(period)) {
            return bookingDate.get(Calendar.YEAR) == now.get(Calendar.YEAR)
                    && bookingDate.get(Calendar.DAY_OF_YEAR) == now.get(Calendar.DAY_OF_YEAR);
        }
        if ("month".equals(period)) {
            return bookingDate.get(Calendar.YEAR) == now.get(Calendar.YEAR)
                    && bookingDate.get(Calendar.MONTH) == now.get(Calendar.MONTH);
        }
        if ("week".equals(period)) {
            return bookingDate.get(Calendar.YEAR) == now.get(Calendar.YEAR)
                    && bookingDate.get(Calendar.WEEK_OF_YEAR) == now.get(Calendar.WEEK_OF_YEAR);
        }
        return true;
    }

    private String earningsPeriodLabel() {
        if ("today".equals(earningsPeriod)) return "Today's Earnings";
        if ("month".equals(earningsPeriod)) return "Monthly Earnings";
        if ("payouts".equals(earningsPeriod)) return "Verified Payouts";
        return "Weekly Earnings";
    }

    private String earningsPeriodSubtitle() {
        if ("payouts".equals(earningsPeriod)) {
            return "All completed jobs ready for payout";
        }
        return selectedCompletedCount() + " completed jobs in this period";
    }

    private int finalAmount(PartnerBooking booking) {
        int saved = prefs.getInt(amountKey(booking), 0);
        return saved > 0 ? saved : booking.defaultAmount;
    }

    private String quoteStatus(PartnerBooking booking) {
        if (booking == null || TextUtils.isEmpty(booking.quoteStatus) || "none".equals(booking.quoteStatus)) {
            return booking != null && "amount_pending".equals(normalizedStatus(booking)) ? "pending" : "none";
        }
        return booking.quoteStatus.trim().toLowerCase(Locale.US);
    }

    private boolean quoteCountered(PartnerBooking booking) {
        return "countered".equals(quoteStatus(booking)) && booking.quoteCounterAmount > 0;
    }

    private boolean quoteExpired(PartnerBooking booking) {
        return "expired".equals(quoteStatus(booking))
                || ("pending".equals(quoteStatus(booking)) && booking.quoteExpiresAtMillis > 0 && booking.quoteExpiresAtMillis <= System.currentTimeMillis());
    }

    private boolean paymentSubmittedByCustomer(PartnerBooking booking) {
        return "payment_submitted".equals(quoteStatus(booking));
    }

    private String amountLabel(PartnerBooking booking) {
        if (isPending(booking)) {
            return "Set after work";
        }
        if (quoteCountered(booking)) {
            return "Customer offered Rs " + booking.quoteCounterAmount;
        }
        if (quoteExpired(booking)) {
            return "Quote expired. Send fresh quote";
        }
        if ("amount_pending".equals(normalizedStatus(booking))) {
            return paymentSubmittedByCustomer(booking)
                    ? "Rs " + finalAmount(booking) + " marked paid"
                    : "Rs " + finalAmount(booking) + " awaiting customer payment";
        }
        return "Rs " + finalAmount(booking);
    }

    private String requestAmountLabel(PartnerBooking booking) {
        int amount = finalAmount(booking);
        return amount > 0 ? "Rs" + amount : "New";
    }

    private String amountKey(PartnerBooking booking) {
        return "amount_" + booking.id;
    }

    private PartnerBooking findBookingById(String bookingId) {
        if (TextUtils.isEmpty(bookingId) || bookings == null) {
            return null;
        }
        for (PartnerBooking booking : bookings) {
            if (booking != null && bookingId.equals(booking.id)) {
                return booking;
            }
        }
        return null;
    }

    private String encode(String value) {
        try {
            return URLEncoder.encode(value, "UTF-8");
        } catch (Exception ignored) {
            return value.replace(" ", "+");
        }
    }

    private TextView statusPill(PartnerBooking booking) {
        String status = booking.status == null ? "" : booking.status.toLowerCase(Locale.US);
        if (completedIds.contains(booking.id) || "completed".equalsIgnoreCase(booking.status)) {
            return pill("Completed", GREEN, Color.rgb(230, 249, 236));
        }
        if ("amount_pending".equals(status) && quoteCountered(booking)) {
            return pill("Counter offered", ROSE, ROSE_SOFT);
        }
        if ("amount_pending".equals(status) && quoteExpired(booking)) {
            return pill("Expired", ROSE_DARK, ROSE_SOFT);
        }
        if ("amount_pending".equals(status)) {
            return pill("Awaiting approval", Color.rgb(168, 118, 23), Color.rgb(255, 247, 224));
        }
        if ("customer_no_response".equals(status)) {
            return pill("No response", ROSE_DARK, ROSE_SOFT);
        }
        if (cancelledIds.contains(booking.id)) {
            return pill("Cancelled", ROSE_DARK, ROSE_SOFT);
        }
        if ("arrived".equals(status)) {
            return pill("Arrived", ROSE, ROSE_SOFT);
        }
        if ("started".equals(status)) {
            return pill("Started", ROSE, ROSE_SOFT);
        }
        if ("on_the_way".equals(status)) {
            return pill("On Way", Color.rgb(168, 118, 23), Color.rgb(255, 247, 224));
        }
        if (acceptedIds.contains(booking.id) || "accepted".equals(status)) {
            return pill("Ongoing", Color.rgb(168, 118, 23), Color.rgb(255, 247, 224));
        }
        return pill("New", ROSE_DARK, ROSE_SOFT);
    }

