    private void styleTab(TextView item, boolean selected, int iconRes) {
        if (item == null) return;
        int color = selected ? ROSE : Color.rgb(92, 86, 86);
        item.setTextColor(color);
        item.setTypeface(Typeface.DEFAULT, selected ? Typeface.BOLD : Typeface.NORMAL);
        item.setBackground(null);
        item.setAlpha(selected ? 1f : 0.72f);
        item.setTextSize(10.5f);
        Drawable icon = getDrawable(iconRes);
        if (icon != null) {
            icon = icon.mutate();
            icon.setTint(color);
            icon.setBounds(0, 0, dp(selected ? 24 : 22), dp(selected ? 24 : 22));
            item.setCompoundDrawables(null, icon, null, null);
        }
        float targetY = selected ? -dp(5) : 0f;
        if (Math.abs(item.getTranslationY() - targetY) > 0.5f) {
            item.animate()
                    .translationY(targetY)
                    .setDuration(170)
                    .setInterpolator(new DecelerateInterpolator(1.4f))
                    .start();
        } else {
            item.setTranslationY(targetY);
        }
    }

