    private String partnerId() {
        String phone = partnerPhone();
        if (!TextUtils.isEmpty(phone)) {
            return "partner-" + phone;
        }
        return "partner-" + partnerName().toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+", "-");
    }

    private String partnerPublicId() {
        String publicId = prefs == null ? "" : prefs.getString(KEY_PUBLIC_ID, "");
        if (!TextUtils.isEmpty(publicId)) return publicId;
        if (isStaffSession()) {
            try {
                JSONObject staff = new JSONObject(prefs.getString(KEY_STAFF_PROFILE_JSON, "{}"));
                String staffCode = staff.optString("staffCode", "").trim();
                if (!TextUtils.isEmpty(staffCode)) return staffCode;
            } catch (Exception ignored) {
            }
        }
        return "ID PENDING";
    }

    private String partnerSkill() {
        return firstPartnerSkill();
    }

    private Set<String> partnerSkills() {
        if (selectedSkills == null || selectedSkills.isEmpty()) {
            selectedSkills = skillsFromPrefs();
        }
        return selectedSkills;
    }

    private Set<String> skillsFromPrefs() {
        Set<String> skills = new LinkedHashSet<>();
        String saved = prefs == null ? "" : prefs.getString(KEY_SKILL, "");
        if (TextUtils.isEmpty(saved)) {
            return skills;
        }
        String[] parts = saved.split(",");
        for (String part : parts) {
            String normalized = normalizeSkill(part);
            if (!TextUtils.isEmpty(normalized)) {
                skills.add(normalized);
                break;
            }
        }
        return skills;
    }

    private String firstPartnerSkill() {
        Set<String> skills = partnerSkills();
        if (skills.contains(selectedSkill)) {
            return selectedSkill;
        }
        for (String skill : skills) {
            return skill;
        }
        return "service";
    }

    private String skillsCsv(Set<String> skills) {
        if (skills == null || skills.isEmpty()) {
            return "";
        }
        StringBuilder builder = new StringBuilder();
        for (String skill : skills) {
            if (builder.length() > 0) {
                builder.append(",");
            }
            builder.append(normalizeSkill(skill));
        }
        return builder.toString();
    }

    private String skillsLabel() {
        StringBuilder builder = new StringBuilder();
        for (String skill : partnerSkills()) {
            if (builder.length() > 0) {
                builder.append(", ");
            }
            builder.append(skillLabel(skill));
        }
        return builder.length() == 0 ? skillLabel(partnerSkill()) : builder.toString();
    }

    private String normalizePhone(String rawPhone) {
        String digits = rawPhone == null ? "" : rawPhone.replaceAll("[^0-9]", "");
        if (digits.startsWith("91") && digits.length() > 10) {
            digits = digits.substring(2);
        }
        if (digits.length() > 10) {
            digits = digits.substring(digits.length() - 10);
        }
        return digits;
    }

    private String normalizeSkill(String skill) {
        if (TextUtils.isEmpty(skill)) {
            return "";
        }
        String value = skill.trim().toLowerCase(Locale.ROOT);
        if ("ac".equals(value) || "ac_repair".equals(value) || value.contains("ac repair") || value.contains("air")) return "ac";
        if ("plumbing".equals(value) || value.contains("plumb")) return "plumbing";
        if ("electrician".equals(value) || value.contains("electric")) return "electrician";
        if ("carpenter".equals(value) || value.contains("carpent")) return "carpenter";
        if (isLaundryText(value)) return "laundry";
        if (isRoText(value)) return "ro";
        if ("cleaning".equals(value) || value.contains("clean")) return "cleaning";
        if ("painting".equals(value) || value.contains("paint")) return "painting";
        if ("interior".equals(value) || value.contains("interior")) return "interior";
        if ("roadside".equals(value) || value.contains("road")) return "roadside";
        if ("appliances".equals(value) || value.contains("appliance")) return "appliances";
        if ("pest".equals(value) || value.contains("pest")) return "pest";
        return value;
    }

    private String skillLabel(String skill) {
        if ("ac".equals(skill)) return "AC Repair";
        if ("plumbing".equals(skill)) return "Plumber";
        if ("electrician".equals(skill)) return "Electrician";
        if ("carpenter".equals(skill)) return "Carpenter";
        if ("cleaning".equals(skill)) return "Cleaning";
        if ("laundry".equals(skill)) return "Laundry";
        if ("painting".equals(skill)) return "Painting";
        if ("interior".equals(skill)) return "Interior";
        if ("roadside".equals(skill)) return "Roadside";
        if ("ro".equals(skill)) return "RO Service";
        if ("appliances".equals(skill)) return "Appliances";
        if ("pest".equals(skill)) return "Pest Control";
        return "Service";
    }

    private boolean isLaundryText(String value) {
        if (value == null) {
            return false;
        }
        String compact = value.replaceAll("[^a-z0-9]+", "");
        return value.contains("laundry")
                || compact.contains("dryclean")
                || value.contains("cloth")
                || value.contains("iron")
                || value.contains("dry clean")
                || value.contains("washing service");
    }

    private boolean isRoText(String value) {
        if (value == null) {
            return false;
        }
        String cleaned = value.replaceAll("[^a-z0-9]+", " ").trim();
        String compact = cleaned.replace(" ", "");
        return "ro".equals(cleaned)
                || cleaned.startsWith("ro ")
                || cleaned.endsWith(" ro")
                || cleaned.contains(" ro ")
                || compact.contains("roservice")
                || compact.contains("waterpurifier")
                || value.contains("ro service")
                || value.contains("water purifier")
                || value.contains("purifier")
                || value.contains("water filter")
                || value.contains("filter change");
    }

    private ImageView profilePhotoView(int sizeDp) {
        ImageView image = new ImageView(this);
        image.setScaleType(ImageView.ScaleType.CENTER_CROP);
        image.setBackground(gradient(ROSE_DARK, ROSE, dp(sizeDp / 2)));
        image.setClipToOutline(true);
        String photo = prefs.getString(KEY_PHOTO, "");
        if (!TextUtils.isEmpty(photo)) {
            setImageUriSafely(image, Uri.parse(photo));
        } else {
            image.setImageResource(android.R.drawable.sym_def_app_icon);
        }
        return image;
    }

    private void showProfileTool(String title, String subtitle) {
        if (title.contains("Personal")) {
            showPersonalInformationTool();
            return;
        }
        if (title.contains("Support")) {
            showSupportTool();
            return;
        }
        if (title.contains("Document")) {
            showDocumentsTool();
            return;
        }
        if (title.contains("My Services")) {
            showMyServicesTool();
            return;
        }
        if (title.contains("Setting")) {
            showSettingsTool();
            return;
        }
        if (title.contains("Legal")) {
            showPartnerLegalInformationTool();
            return;
        }
        enterScreen("profile_tool", title, subtitle);
        activeTab = "profile";
        updateNav();
        clearContentForScreen("profile_tool:" + title);
        content.addView(profileSubHeader(title), margin(-1, -2, 0, 0, 0, 14));
        content.addView(profileToolCard(title, subtitle), margin(-1, -2, 0, 0, 0, 14));
        content.addView(profileToolActions(title), margin(-1, -2, 0, 0, 0, 12));
    }

