    private void showPartnerFieldEditor(String title, String key, String current, int inputType) {
        if (KEY_NAME.equals(key)) {
            Toast.makeText(this, "Partner name is verified and cannot be edited.", Toast.LENGTH_SHORT).show();
            return;
        }
        LinearLayout sheet = vertical();
        sheet.setPadding(dp(18), dp(18), dp(18), dp(14));
        sheet.setBackground(stroke(Color.WHITE, Color.rgb(250, 216, 225), dp(22)));
        sheet.addView(text("Edit " + title, 18, BLACK, true), margin(-1, -2, 0, 0, 0, 12));
        EditText edit = input(title, inputType);
        if (KEY_PHONE.equals(key)) {
            edit.setFilters(new InputFilter[]{new InputFilter.LengthFilter(10)});
        } else if (KEY_NAME.equals(key)) {
            edit.setFilters(new InputFilter[]{new InputFilter.LengthFilter(80)});
        }
        edit.setText(current);
        edit.setSelectAllOnFocus(true);
        sheet.addView(edit, margin(-1, 54, 0, 0, 0, 14));
        LinearLayout actions = horizontal();
        TextView cancel = outlineButton("Cancel");
        TextView save = roseButton("Save");
        actions.addView(cancel, new LinearLayout.LayoutParams(0, dp(48), 1));
        LinearLayout.LayoutParams saveParams = new LinearLayout.LayoutParams(0, dp(48), 1);
        saveParams.setMargins(dp(10), 0, 0, 0);
        actions.addView(save, saveParams);
        sheet.addView(actions);

        AlertDialog dialog = new AlertDialog.Builder(this).create();
        dialog.setView(sheet);
        cancel.setOnClickListener(view -> dialog.dismiss());
        save.setOnClickListener(view -> {
            String value = edit.getText().toString().trim();
            if (TextUtils.isEmpty(value)) {
                Toast.makeText(this, title + " required", Toast.LENGTH_SHORT).show();
                return;
            }
            if (KEY_PHONE.equals(key)) {
                value = value.replaceAll("\\D", "");
                if (!isValidIndianPhone(value)) {
                    Toast.makeText(this, "Please enter a valid phone number.", Toast.LENGTH_SHORT).show();
                    return;
                }
            } else if (KEY_NAME.equals(key) && !isValidPartnerName(value)) {
                Toast.makeText(this, "Please enter a valid partner name.", Toast.LENGTH_SHORT).show();
                return;
            }
            prefs.edit().putString(key, value).apply();
            syncPartnerStatus();
            dialog.dismiss();
            showPersonalInformationTool();
        });
        showDialogSafely(dialog);
        Window window = dialog.getWindow();
        if (window != null) {
            window.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));
        }
    }

