    private PartnerBooking partnerSupportCancellableBooking() {
        if (activeDetailBooking != null && "accepted".equals(normalizedStatus(activeDetailBooking))) {
            return activeDetailBooking;
        }
        if (activeMapBooking != null && "accepted".equals(normalizedStatus(activeMapBooking))) {
            return activeMapBooking;
        }
        if (bookings != null) {
            for (PartnerBooking booking : bookings) {
                if ("accepted".equals(normalizedStatus(booking))) {
                    return booking;
                }
            }
        }
        return null;
    }

