    private void showCustomerBookingChat(PartnerBooking booking) {
        if (booking == null || TextUtils.isEmpty(booking.id)) {
            Toast.makeText(this, "Booking not found", Toast.LENGTH_SHORT).show();
            return;
        }
        if (statusStage(booking) < 1) {
            Toast.makeText(this, "Accept booking first to chat with the customer.", Toast.LENGTH_LONG).show();
            return;
        }
        activeDetailBooking = booking;
        activeBookingChatId = booking.id;
        activeBookingChatCustomer = TextUtils.isEmpty(booking.customer) ? "Customer" : booking.customer;
        enterScreen("booking_chat", booking.id);
        activeTab = "bookings";
        updateNav();
        clearContentForScreen("booking_chat:" + booking.id);
        content.addView(partnerBookingChatTopBar("Customer Chat"), margin(-1, -2, 0, 0, 0, 10));
        content.addView(partnerBookingChatPeerCard(booking), margin(-1, -2, 0, 0, 0, 18));

        supportChatMessages = vertical();
        supportStatusViews.clear();
        bookingChatRendered.clear();
        supportChatMessages.addView(partnerSupportDatePill(), margin(-1, -2, 0, 0, 0, 14));
        supportChatMessages.addView(partnerBookingChatEmptyState(), margin(-1, -2, 0, 18, 0, 18));
        content.addView(supportChatMessages, margin(-1, -2, 0, 0, 0, 12));

        loadBookingChatMessages(activeBookingChatId);
        restoreQueuedBookingChatMessages(activeBookingChatId);
        schedulePartnerBookingChatPolling();
        showBookingChatInputDock();
        if (backendClient != null) {
            backendClient.markBookingChatSeen(activeBookingChatId);
        }
        setSupportChatScrollPadding();
        if (mainScroll != null) {
            mainScroll.post(() -> mainScroll.smoothScrollTo(0, content.getBottom()));
        }
    }

