    private void removePartnerBookingChatEmptyState() {
        if (supportChatMessages == null) {
            return;
        }
        for (int index = supportChatMessages.getChildCount() - 1; index >= 0; index--) {
            View child = supportChatMessages.getChildAt(index);
            if ("booking_chat_empty_state".equals(child.getTag())) {
                supportChatMessages.removeViewAt(index);
            }
        }
    }

    private void schedulePartnerBookingChatPolling() {
        if (bookingChatPollRunnable != null) {
            refreshHandler.removeCallbacks(bookingChatPollRunnable);
        }
        bookingChatPollRunnable = new Runnable() {
            @Override
            public void run() {
                if (currentNavState == null || !"booking_chat".equals(currentNavState.screen)
                        || TextUtils.isEmpty(activeBookingChatId) || backendClient == null) {
                    return;
                }
                backendClient.fetchBookingChatMessages(activeBookingChatId, new BackendClient.JsonCallback() {
                    final String requestedBookingId = activeBookingChatId;
                    @Override
                    public void onSuccess(JSONObject object) {
                        JSONArray messages = object.optJSONArray("messages");
                        if (messages != null && currentNavState != null && "booking_chat".equals(currentNavState.screen)
                                && requestedBookingId.equals(activeBookingChatId)) {
                            for (int index = 0; index < messages.length(); index++) {
                                addBookingChatMessage(messages.optJSONObject(index), true);
                            }
                            backendClient.markBookingChatSeen(activeBookingChatId);
                        }
                    }

                    @Override
                    public void onError(String message) {
                    }
                });
                refreshHandler.postDelayed(this, 3000L);
            }
        };
        refreshHandler.postDelayed(bookingChatPollRunnable, 3000L);
    }

