    private void loadBookingChatMessages(String bookingId) {
        if (backendClient == null || TextUtils.isEmpty(bookingId)) {
            return;
        }
        backendClient.fetchBookingChatMessages(bookingId, new BackendClient.JsonCallback() {
            @Override
            public void onSuccess(JSONObject object) {
                if (currentNavState == null || !"booking_chat".equals(currentNavState.screen) || !bookingIdMatchesActive(object.optString("bookingId", bookingId), object.optString("bookingCode", ""))) {
                    return;
                }
                JSONArray messages = object.optJSONArray("messages");
                if (messages == null || messages.length() == 0) {
                    return;
                }
                for (int index = 0; index < messages.length(); index++) {
                    addBookingChatMessage(messages.optJSONObject(index));
                }
                backendClient.markBookingChatSeen(bookingId);
            }

            @Override
            public void onError(String message) {
                addBookingChatSystemMessage("Unable to load chat. It will retry when the internet connection is available.");
            }
        });
    }

    private void sendBookingChatMessage() {
        if (supportChatInput == null) {
            return;
        }
        String message = supportChatInput.getText().toString().trim();
        if (TextUtils.isEmpty(message)) {
            Toast.makeText(this, "Please type a message", Toast.LENGTH_SHORT).show();
            return;
        }
        if (message.length() > MAX_CHAT_MESSAGE_LENGTH) {
            Toast.makeText(this, "Message too long. Keep it under 1000 characters.", Toast.LENGTH_LONG).show();
            return;
        }
        if (TextUtils.isEmpty(activeBookingChatId)) {
            Toast.makeText(this, "Booking chat unavailable", Toast.LENGTH_SHORT).show();
            return;
        }
        supportChatInput.setText("");
        String messageId = supportMessageId("PARCHAT");
        addBookingChatBubble(message, true, messageId, isNetworkOnline() ? "Sending" : "Queued");
        dispatchBookingChatMessage(activeBookingChatId, message, messageId, false);
    }

    private void dispatchBookingChatMessage(String bookingId, String message, String messageId, boolean fromQueue) {
        if (TextUtils.isEmpty(bookingId) || TextUtils.isEmpty(message)) {
            return;
        }
        if (TextUtils.isEmpty(messageId)) {
            messageId = supportMessageId("PARCHAT");
        }
        if (!isNetworkOnline() || backendClient == null) {
            queueBookingChatMessage(bookingId, message, messageId);
            updateBookingChatMessageStatus(messageId, "Queued");
            return;
        }
        String finalMessageId = messageId;
        backendClient.sendBookingChatMessage(bookingId, message, finalMessageId, new BackendClient.JsonCallback() {
            @Override
            public void onSuccess(JSONObject object) {
                removeQueuedBookingChatMessage(finalMessageId);
                updateBookingChatMessageStatus(finalMessageId, "Sent");
            }

            @Override
            public void onError(String error) {
                queueBookingChatMessage(bookingId, message, finalMessageId);
                updateBookingChatMessageStatus(finalMessageId, fromQueue ? "Failed - tap retry" : "Failed - tap retry");
            }
        });
    }

    private void addBookingChatMessage(JSONObject object) {
        addBookingChatMessage(object, false);
    }

    private boolean addBookingChatMessage(JSONObject object, boolean alertIncoming) {
        if (object == null) {
            return false;
        }
        String messageId = object.optString("id", object.optString("clientMessageId", ""));
        if (!TextUtils.isEmpty(messageId) && bookingChatRendered.containsKey(messageId)) {
            return false;
        }
        boolean fromPartner = "partner".equalsIgnoreCase(object.optString("senderRole", ""));
        addBookingChatBubble(object.optString("message", ""), fromPartner, fromPartner ? object.optString("clientMessageId", messageId) : messageId, object.optString("deliveryStatus", ""));
        if (!TextUtils.isEmpty(messageId)) {
            bookingChatRendered.put(messageId, true);
        }
        if (alertIncoming && !fromPartner) {
            vibrateIncomingChatMessage();
        }
        return true;
    }

    private void addBookingChatSystemMessage(String message) {
        if (supportChatMessages == null || TextUtils.isEmpty(message)) {
            return;
        }
        TextView note = text(message, 11, MUTED, false);
        note.setGravity(Gravity.CENTER);
        note.setPadding(dp(12), dp(8), dp(12), dp(8));
        note.setBackground(round(Color.rgb(255, 244, 246), dp(14)));
        supportChatMessages.addView(note, margin(-1, -2, 12, 0, 12, 12));
    }

    private void addBookingChatBubble(String message, boolean fromPartner, String messageId, String status) {
        if (supportChatMessages == null || TextUtils.isEmpty(message)) {
            return;
        }
        removePartnerBookingChatEmptyState();
        LinearLayout row = horizontal();
        row.setGravity(fromPartner ? Gravity.RIGHT : Gravity.LEFT | Gravity.TOP);
        if (!fromPartner) {
            row.addView(customerChatIcon(), new LinearLayout.LayoutParams(dp(30), dp(30)));
        }
        LinearLayout stack = vertical();
        TextView bubble = text(message, 13, BLACK, false);
        bubble.setPadding(dp(13), dp(11), dp(13), dp(11));
        bubble.setMaxLines(10);
        bubble.setBackground(fromPartner
                ? gradient(Color.rgb(255, 238, 243), Color.rgb(255, 224, 233), dp(18))
                : stroke(Color.WHITE, Color.rgb(246, 220, 227), dp(18)));
        bubble.setElevation(dp(2));
        stack.addView(bubble, new LinearLayout.LayoutParams(dp(fromPartner ? 252 : 266), -2));
        TextView time = text(partnerSupportTimeLabel(), 10, Color.rgb(145, 135, 135), false);
        time.setGravity(fromPartner ? Gravity.RIGHT : Gravity.LEFT);
        if (fromPartner && !TextUtils.isEmpty(status)) {
            time.setText(supportStatusText(status));
        }
        if (fromPartner && !TextUtils.isEmpty(messageId)) {
            supportStatusViews.put(messageId, time);
            bookingChatRendered.put(messageId, true);
            time.setOnClickListener(view -> retryQueuedBookingChatMessage(messageId));
        }
        stack.addView(time, margin(-1, -2, 0, 2, 0, 0));
        LinearLayout.LayoutParams stackParams = new LinearLayout.LayoutParams(-2, -2);
        if (!fromPartner) {
            stackParams.setMargins(dp(8), 0, 0, 0);
        }
        row.addView(stack, stackParams);
        supportChatMessages.addView(row, margin(-1, -2, 0, 0, 0, 12));
        if (mainScroll != null && content != null) {
            mainScroll.post(() -> mainScroll.smoothScrollTo(0, content.getBottom()));
        }
    }

