        TextView icon = text(customerInitials(activeBookingChatCustomer), 12, Color.WHITE, true);
        icon.setGravity(Gravity.CENTER);
        icon.setIncludeFontPadding(false);
        icon.setBackground(gradient(ROSE_DARK, ROSE, dp(15)));
        icon.setElevation(dp(2));
