    private void updateBookingChatMessageStatus(String messageId, String status) {
        if (TextUtils.isEmpty(messageId)) {
            return;
        }
        TextView view = supportStatusViews.get(messageId);
        if (view != null) {
            view.setText(supportStatusText(status));
            int color = "Seen".equalsIgnoreCase(status) || "Delivered".equalsIgnoreCase(status) || "Sent".equalsIgnoreCase(status)
                    ? GREEN
                    : ("Queued".equalsIgnoreCase(status) ? Color.rgb(218, 126, 33) : Color.rgb(215, 51, 70));
            view.setTextColor(color);
        }
    }

    private boolean bookingIdMatchesActive(String bookingId, String bookingCode) {
        if (TextUtils.isEmpty(activeBookingChatId)) {
            return false;
        }
        return activeBookingChatId.equals(bookingId) || activeBookingChatId.equals(bookingCode);
    }

    private void handleIncomingBookingChatMessage(JSONObject object) {
        if (object == null || "partner".equalsIgnoreCase(object.optString("senderRole", ""))) {
            return;
        }
        String bookingId = object.optString("bookingId", "");
        String bookingCode = object.optString("bookingCode", "");
        PartnerBooking booking = findBookingById(TextUtils.isEmpty(bookingId) ? bookingCode : bookingId);
        boolean matchesActive = bookingIdMatchesActive(bookingId, bookingCode);
        if (currentNavState != null && "booking_chat".equals(currentNavState.screen) && matchesActive) {
            addBookingChatMessage(object, true);
            if (backendClient != null) {
                backendClient.markBookingChatSeen(activeBookingChatId);
            }
        } else if (booking != null || (activeDetailBooking != null && (activeDetailBooking.id.equals(bookingId) || activeDetailBooking.id.equals(bookingCode)))) {
            Toast.makeText(this, "Customer sent a message", Toast.LENGTH_SHORT).show();
        }
    }

    private void vibrateIncomingChatMessage() {
        Vibrator vibrator = (Vibrator) getSystemService(VIBRATOR_SERVICE);
        if (vibrator == null || !vibrator.hasVibrator()) {
            return;
        }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            vibrator.vibrate(VibrationEffect.createOneShot(35, VibrationEffect.DEFAULT_AMPLITUDE));
        } else {
            vibrator.vibrate(35);
        }
    }

    private void handleBookingChatSeen(JSONObject object) {
        if (currentNavState == null || !"booking_chat".equals(currentNavState.screen) || object == null) {
            return;
        }
        if (!"user".equalsIgnoreCase(object.optString("seenByRole", ""))) {
            return;
        }
        if (!bookingIdMatchesActive(object.optString("bookingId", ""), object.optString("bookingCode", ""))) {
            return;
        }
        for (String key : new ArrayList<>(supportStatusViews.keySet())) {
            updateBookingChatMessageStatus(key, "Seen");
        }
    }

    private JSONArray pendingBookingChatQueue() {
        try {
            return new JSONArray(prefs.getString(KEY_PENDING_BOOKING_CHAT_QUEUE, "[]"));
        } catch (Exception ignored) {
            return new JSONArray();
        }
    }

    private void restoreQueuedBookingChatMessages(String bookingId) {
        if (TextUtils.isEmpty(bookingId)) {
            return;
        }
        JSONArray queue = pendingBookingChatQueue();
        for (int index = 0; index < queue.length(); index++) {
            JSONObject item = queue.optJSONObject(index);
            if (item == null || !bookingId.equals(item.optString("bookingId", ""))) {
                continue;
            }
            String messageId = item.optString("id", "");
            if (!TextUtils.isEmpty(messageId) && bookingChatRendered.containsKey(messageId)) {
                continue;
            }
            addBookingChatBubble(item.optString("message", ""), true, messageId, "Queued");
        }
    }

    private void queueBookingChatMessage(String bookingId, String message, String messageId) {
        try {
            JSONArray queue = pendingBookingChatQueue();
            JSONArray updated = new JSONArray();
            boolean replaced = false;
            for (int index = 0; index < queue.length(); index++) {
                JSONObject item = queue.optJSONObject(index);
                if (item == null) {
                    continue;
                }
                if (messageId.equals(item.optString("id"))) {
                    item.put("attempts", item.optInt("attempts", 0) + 1);
                    updated.put(item);
                    replaced = true;
                } else {
                    updated.put(item);
                }
            }
            if (!replaced) {
                JSONObject item = new JSONObject();
                item.put("id", messageId);
                item.put("bookingId", bookingId);
                item.put("message", message);
                item.put("attempts", 0);
                item.put("createdAtMillis", System.currentTimeMillis());
                updated.put(item);
            }
            prefs.edit().putString(KEY_PENDING_BOOKING_CHAT_QUEUE, trimQueue(updated).toString()).apply();
        } catch (Exception ignored) {
        }
    }

    private JSONArray trimQueue(JSONArray queue) {
        if (queue == null || queue.length() <= MAX_PENDING_QUEUE_ITEMS) {
            return queue == null ? new JSONArray() : queue;
        }
        JSONArray trimmed = new JSONArray();
        int start = Math.max(0, queue.length() - MAX_PENDING_QUEUE_ITEMS);
        for (int index = start; index < queue.length(); index++) {
            JSONObject item = queue.optJSONObject(index);
            if (item != null) {
                trimmed.put(item);
            }
        }
        return trimmed;
    }

    private void removeQueuedBookingChatMessage(String messageId) {
        try {
            JSONArray queue = pendingBookingChatQueue();
            JSONArray updated = new JSONArray();
            for (int index = 0; index < queue.length(); index++) {
                JSONObject item = queue.optJSONObject(index);
                if (item != null && !messageId.equals(item.optString("id"))) {
                    updated.put(item);
                }
            }
            prefs.edit().putString(KEY_PENDING_BOOKING_CHAT_QUEUE, updated.toString()).apply();
        } catch (Exception ignored) {
        }
    }

    private void retryQueuedBookingChatMessage(String messageId) {
        JSONArray queue = pendingBookingChatQueue();
        for (int index = 0; index < queue.length(); index++) {
            JSONObject item = queue.optJSONObject(index);
            if (item != null && messageId.equals(item.optString("id"))) {
                updateBookingChatMessageStatus(messageId, isNetworkOnline() ? "Retrying" : "Queued");
                dispatchBookingChatMessage(item.optString("bookingId", ""), item.optString("message", ""), messageId, true);
                return;
            }
        }
    }

    private void flushQueuedBookingChatMessages() {
        if (!isNetworkOnline() || backendClient == null || prefs == null) {
            return;
        }
        JSONArray queue = pendingBookingChatQueue();
        for (int index = 0; index < queue.length(); index++) {
            JSONObject item = queue.optJSONObject(index);
            if (item == null) {
                continue;
            }
            String id = item.optString("id", "");
            updateBookingChatMessageStatus(id, "Retrying");
            dispatchBookingChatMessage(item.optString("bookingId", ""), item.optString("message", ""), id, true);
        }
    }

    private void showPartnerSupportChat(String supportType, String draftMessage) {
        String type = TextUtils.isEmpty(supportType) ? "Chat" : supportType;
        enterScreen("support_chat", type, draftMessage == null ? "" : draftMessage);
        activeTab = "profile";
        updateNav();
        clearContentForScreen("support_chat:" + type);
        content.addView(partnerSupportHeader(), margin(-1, -2, 0, 0, 0, 18));
        content.addView(partnerSupportHeroCard(type), margin(-1, -2, 0, 0, 0, 14));

        supportChatMessages = vertical();
        supportStatusViews.clear();
        supportChatMessages.addView(partnerSupportDatePill(), margin(-1, -2, 0, 0, 0, 14));
        content.addView(supportChatMessages, margin(-1, -2, 0, 0, 0, 12));

        if (!restorePartnerSupportHistory()) {
            addSupportBubble(partnerSupportGreeting(type), false);
            if ("Track Issue".equals(type)) {
                addSupportBubble("Share the support request ID, booking ID, or issue details. I will check the status and guide you through the next step.", false);
            } else if ("Complaint".equals(type)) {
                addSupportBubble("For a complaint, type the booking ID, customer name, and issue details. The ticket will be saved in real time.", false);
            } else {
                addSupportBubble("Partner app ke bookings, payout, documents, service area, online status ya customer issue ke baare me puch sakte ho.", false);
            }
        }

        showPartnerSupportInputDock(type);
        if (!TextUtils.isEmpty(draftMessage) && supportChatInput != null) {
            supportChatInput.setText(draftMessage);
            supportChatInput.setSelection(supportChatInput.length());
        }
        setSupportChatScrollPadding();
        if (mainScroll != null) {
            mainScroll.post(() -> mainScroll.smoothScrollTo(0, content.getBottom()));
        }
    }

