    private void focusSupportComposer(String seed) {
        if (supportChatInput != null) {
            if (TextUtils.isEmpty(supportChatInput.getText().toString())) {
                supportChatInput.setText(seed);
                supportChatInput.setSelection(supportChatInput.length());
            }
            supportChatInput.requestFocus();
        } else {
            Toast.makeText(this, "Message box niche available hai", Toast.LENGTH_SHORT).show();
        }
    }

    private void sendSupportComposerMessage() {
        if (supportChatInput == null) {
            return;
        }
        String message = supportChatInput.getText().toString().trim();
        if (TextUtils.isEmpty(message)) {
            Toast.makeText(this, "Please write your message first", Toast.LENGTH_SHORT).show();
            return;
        }
        if (message.length() > MAX_CHAT_MESSAGE_LENGTH) {
            Toast.makeText(this, "Message too long. Keep it under 1000 characters.", Toast.LENGTH_LONG).show();
            return;
        }
        supportChatInput.setText("");
        sendSupportRequest("Support", message);
    }

