    private void sendAiSupportMessage(String supportType) {
        if (supportChatInput == null) {
            return;
        }
        String message = supportChatInput.getText().toString().trim();
        if (TextUtils.isEmpty(message)) {
            Toast.makeText(this, "Please write your issue first", Toast.LENGTH_SHORT).show();
            return;
        }
        if (message.length() > MAX_CHAT_MESSAGE_LENGTH) {
            Toast.makeText(this, "Message too long. Keep it under 1000 characters.", Toast.LENGTH_LONG).show();
            return;
        }
        supportChatInput.setText("");
        String messageId = supportMessageId("PARMSG");
        addSupportBubble(message, true, messageId, isNetworkOnline() ? "Sending" : "Queued");
        String reply = aiSupportReply(message);
        refreshHandler.postDelayed(() -> {
            addSupportBubble(reply, false);
            updateSupportMessageStatus(messageId, "Seen");
        }, 500);
        dispatchPartnerSupportMessage(supportType, message, messageId, "", false);
    }

    private void addSupportBubble(String message, boolean fromPartner) {
        addSupportBubble(message, fromPartner, "", "");
    }

    private void addSupportBubble(String message, boolean fromPartner, String messageId, String status) {
        addSupportBubble(message, fromPartner, messageId, status, partnerSupportTimeLabel(), true);
    }

    private void addSupportBubble(String message, boolean fromPartner, String messageId, String status, String timeLabel, boolean persist) {
        if (supportChatMessages == null) {
            return;
        }
        LinearLayout row = horizontal();
        row.setGravity(fromPartner ? Gravity.RIGHT : Gravity.LEFT | Gravity.TOP);
        if (!fromPartner) {
            row.addView(partnerSupportBotIcon(), new LinearLayout.LayoutParams(dp(30), dp(30)));
        }
        LinearLayout stack = vertical();
        TextView bubble = text(message, 13, BLACK, false);
        bubble.setPadding(dp(13), dp(11), dp(13), dp(11));
        bubble.setMaxLines(10);
        bubble.setBackground(fromPartner
                ? round(Color.rgb(255, 240, 245), dp(16))
                : stroke(Color.WHITE, Color.rgb(235, 226, 226), dp(16)));
        stack.addView(bubble, new LinearLayout.LayoutParams(dp(fromPartner ? 252 : 266), -2));
        TextView time = text(TextUtils.isEmpty(timeLabel) ? partnerSupportTimeLabel() : timeLabel, 10, Color.rgb(145, 135, 135), false);
        time.setGravity(fromPartner ? Gravity.RIGHT : Gravity.LEFT);
        if (fromPartner && !TextUtils.isEmpty(status)) {
            time.setText((TextUtils.isEmpty(timeLabel) ? partnerSupportTimeLabel() : timeLabel) + " - " + status);
        }
        if (fromPartner && !TextUtils.isEmpty(messageId)) {
            supportStatusViews.put(messageId, time);
            time.setOnClickListener(view -> retryQueuedPartnerSupportMessage(messageId));
        }
        stack.addView(time, margin(-1, -2, 0, 2, 0, 0));
        LinearLayout.LayoutParams stackParams = new LinearLayout.LayoutParams(-2, -2);
        if (!fromPartner) {
            stackParams.setMargins(dp(8), 0, 0, 0);
        }
        row.addView(stack, stackParams);
        supportChatMessages.addView(row, margin(-1, -2, 0, 0, 0, 12));
        if (persist) {
            persistPartnerSupportMessage(message, fromPartner, messageId, status,
                    TextUtils.isEmpty(timeLabel) ? partnerSupportTimeLabel() : timeLabel);
        }
        if (mainScroll != null && content != null) {
            mainScroll.post(() -> mainScroll.smoothScrollTo(0, content.getBottom()));
        }
    }

    private boolean restorePartnerSupportHistory() {
        if (prefs == null) {
            return false;
        }
        try {
            JSONArray history = new JSONArray(prefs.getString(KEY_PARTNER_SUPPORT_HISTORY, "[]"));
            if (history.length() == 0) {
                return false;
            }
            for (int index = 0; index < history.length(); index++) {
                JSONObject item = history.optJSONObject(index);
                if (item == null || TextUtils.isEmpty(item.optString("message"))) {
                    continue;
                }
                addSupportBubble(
                        item.optString("message"),
                        item.optBoolean("fromPartner", false),
                        item.optString("messageId", ""),
                        item.optString("status", ""),
                        item.optString("time", ""),
                        false
                );
            }
            return supportChatMessages != null && supportChatMessages.getChildCount() > 1;
        } catch (Exception ignored) {
            return false;
        }
    }

    private void persistPartnerSupportMessage(String message, boolean fromPartner, String messageId, String status, String timeLabel) {
        if (prefs == null || TextUtils.isEmpty(message)) {
            return;
        }
        try {
            JSONArray current = new JSONArray(prefs.getString(KEY_PARTNER_SUPPORT_HISTORY, "[]"));
            JSONArray updated = new JSONArray();
            int start = Math.max(0, current.length() - 99);
            for (int index = start; index < current.length(); index++) {
                JSONObject saved = current.optJSONObject(index);
                if (saved != null) {
                    updated.put(saved);
                }
            }
            JSONObject item = new JSONObject();
            item.put("message", message);
            item.put("fromPartner", fromPartner);
            item.put("messageId", messageId == null ? "" : messageId);
            item.put("status", status == null ? "" : status);
            item.put("time", timeLabel == null ? partnerSupportTimeLabel() : timeLabel);
            item.put("savedAt", System.currentTimeMillis());
            updated.put(item);
            prefs.edit().putString(KEY_PARTNER_SUPPORT_HISTORY, updated.toString()).apply();
        } catch (Exception ignored) {
        }
    }

    private void updatePersistedPartnerSupportStatus(String messageId, String status) {
        if (prefs == null || TextUtils.isEmpty(messageId)) {
            return;
        }
        try {
            JSONArray history = new JSONArray(prefs.getString(KEY_PARTNER_SUPPORT_HISTORY, "[]"));
            boolean changed = false;
            for (int index = 0; index < history.length(); index++) {
                JSONObject item = history.optJSONObject(index);
                if (item != null && messageId.equals(item.optString("messageId"))) {
                    item.put("status", status == null ? "" : status);
                    changed = true;
                }
            }
            if (changed) {
                prefs.edit().putString(KEY_PARTNER_SUPPORT_HISTORY, history.toString()).apply();
            }
        } catch (Exception ignored) {
        }
    }

