    private String partnerSupportTimeLabel() {
        Calendar calendar = Calendar.getInstance();
        int hour = calendar.get(Calendar.HOUR);
        if (hour == 0) {
            hour = 12;
        }
        return String.format(Locale.US, "%d:%02d %s",
                hour,
                calendar.get(Calendar.MINUTE),
                calendar.get(Calendar.AM_PM) == Calendar.AM ? "AM" : "PM");
    }

    private String supportStatusText(String status) {
        return partnerSupportTimeLabel() + " - " + status;
    }

    private void updateSupportMessageStatus(String messageId, String status) {
        if (TextUtils.isEmpty(messageId)) {
            return;
        }
        TextView view = supportStatusViews.get(messageId);
        if (view != null) {
            view.setText(supportStatusText(status));
            int color = "Seen".equalsIgnoreCase(status) || "Delivered".equalsIgnoreCase(status) || "Sent".equalsIgnoreCase(status)
                    ? GREEN
                    : ("Queued".equalsIgnoreCase(status) ? Color.rgb(218, 126, 33) : Color.rgb(215, 51, 70));
            view.setTextColor(color);
        }
        updatePersistedPartnerSupportStatus(messageId, status);
        persistPartnerSupportDeliveryStatus(messageId, status);
    }

    private void persistPartnerSupportDeliveryStatus(String messageId, String status) {
        if (TextUtils.isEmpty(messageId) || status == null || firestore == null) {
            return;
        }
        String normalized = status.toLowerCase(Locale.US);
        if (!normalized.contains("sent") && !normalized.contains("delivered") && !normalized.contains("seen")) {
            return;
        }
        Map<String, Object> update = new HashMap<>();
        update.put("deliveryStatus", normalized);
        update.put("deliveryStatusAtMillis", System.currentTimeMillis());
        if (realtimeDatabase != null) {
            realtimeDatabase.getReference("partner_support_messages").child(messageId).updateChildren(new HashMap<>(update));
        }
        firestore.collection("partner_support_messages")
                .document(messageId)
                .set(update, SetOptions.merge())
                .addOnFailureListener(error -> {});
    }

    private String supportMessageId(String prefix) {
        return prefix + System.currentTimeMillis() + String.valueOf(Math.abs((int) (Math.random() * 9000)) + 1000);
    }

    private void startPartnerSupportPhotoCapture(String supportType) {
        pendingSupportCaptureType = TextUtils.isEmpty(supportType) ? "Chat" : supportType;
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M
                && checkSelfPermission(Manifest.permission.CAMERA) != PackageManager.PERMISSION_GRANTED) {
            requestPermissions(new String[]{Manifest.permission.CAMERA}, SUPPORT_CAMERA_PERMISSION_REQUEST);
            return;
        }
        launchPartnerSupportCamera();
    }

    private void launchPartnerSupportCamera() {
        try {
            Intent intent = new Intent(MediaStore.ACTION_IMAGE_CAPTURE);
            startActivityForResult(intent, SUPPORT_CAMERA_REQUEST);
        } catch (Exception error) {
            Toast.makeText(this, "Unable to open the camera.", Toast.LENGTH_SHORT).show();
        }
    }

    private void handlePartnerSupportCameraResult(Intent data) {
        if (data == null || data.getExtras() == null) {
            Toast.makeText(this, "Photo capture failed", Toast.LENGTH_SHORT).show();
            return;
        }
        Object bitmap = data.getExtras().get("data");
        if (!(bitmap instanceof Bitmap)) {
            Toast.makeText(this, "Photo capture failed", Toast.LENGTH_SHORT).show();
            return;
        }
        File file = savePartnerSupportBitmap((Bitmap) bitmap);
        if (file == null) {
            Toast.makeText(this, "Unable to save the photo.", Toast.LENGTH_SHORT).show();
            return;
        }
        String messageId = supportMessageId("PARPHOTO");
        String message = "Photo attachment";
        addSupportBubble(message, true, messageId, isNetworkOnline() ? "Uploading" : "Queued");
        dispatchPartnerSupportMessage(pendingSupportCaptureType, message, messageId, file.getAbsolutePath(), false);
    }

    private File savePartnerSupportBitmap(Bitmap bitmap) {
        try {
            File dir = new File(getFilesDir(), "support_uploads");
            if (!dir.exists() && !dir.mkdirs()) {
                return null;
            }
            File file = new File(dir, "partner_support_" + System.currentTimeMillis() + ".jpg");
            FileOutputStream output = new FileOutputStream(file);
            bitmap.compress(Bitmap.CompressFormat.JPEG, 88, output);
            output.flush();
            output.close();
            return file;
        } catch (Exception ignored) {
            return null;
        }
    }

    private void dispatchPartnerSupportMessage(String type, String message, String messageId, String attachmentPath, boolean fromQueue) {
        if (TextUtils.isEmpty(messageId)) {
            messageId = supportMessageId("PARMSG");
        }
        if (!isNetworkOnline()) {
            queuePartnerSupportMessage(type, message, messageId, attachmentPath);
            updateSupportMessageStatus(messageId, "Queued");
            return;
        }
        String finalMessageId = messageId;
        ensureFirebaseReady(() -> writePartnerSupportMessage(type, message, finalMessageId, attachmentPath));
    }

    private void writePartnerSupportMessage(String type, String message, String messageId, String attachmentPath) {
        if (!TextUtils.isEmpty(attachmentPath)) {
            uploadPartnerSupportAttachment(type, message, messageId, attachmentPath, url ->
                    writePartnerSupportMessageDocument(type, message, messageId, url, true, attachmentPath)
            );
            return;
        }
        writePartnerSupportMessageDocument(type, message, messageId, "", false, "");
    }

    private void uploadPartnerSupportAttachment(String type, String message, String messageId, String attachmentPath, SupportUploadCallback callback) {
        File file = new File(attachmentPath);
        if (!file.exists()) {
            updateSupportMessageStatus(messageId, "Failed - tap retry");
            return;
        }
        if (firebaseStorage == null) {
            firebaseStorage = FirebaseStorage.getInstance();
        }
        updateSupportMessageStatus(messageId, "Uploading");
        StorageReference ref = firebaseStorage.getReference().child("support_uploads/partner/" + supportOwnerUid() + "/" + messageId + ".jpg");
        StorageMetadata metadata = new StorageMetadata.Builder().setContentType("image/jpeg").build();
        ref.putFile(Uri.fromFile(file), metadata)
                .addOnSuccessListener(snapshot -> ref.getDownloadUrl()
                        .addOnSuccessListener(uri -> callback.onUploaded(uri.toString()))
                        .addOnFailureListener(error -> {
                            queuePartnerSupportMessage(type, message, messageId, attachmentPath);
                            updateSupportMessageStatus(messageId, "Failed - tap retry");
                        }))
                .addOnFailureListener(error -> {
                    queuePartnerSupportMessage(type, message, messageId, attachmentPath);
                    updateSupportMessageStatus(messageId, "Failed - tap retry");
                });
    }

    private void writePartnerSupportMessageDocument(String type, String message, String messageId, String attachmentUrl, boolean hasAttachment, String attachmentPath) {
        Map<String, Object> payload = new HashMap<>();
        payload.put("clientMessageId", messageId);
        payload.put("type", TextUtils.isEmpty(type) ? "Chat" : type);
        payload.put("message", message);
        payload.put("senderRole", "partner");
        payload.put("ownerUid", supportOwnerUid());
        payload.put("partnerId", partnerId());
        payload.put("partnerName", partnerName());
        payload.put("deliveryStatus", "sent");
        payload.put("status", "open");
        payload.put("createdAtMillis", System.currentTimeMillis());
        payload.put("sentAtMillis", System.currentTimeMillis());
        payload.put("hasAttachment", hasAttachment);
        payload.put("attachmentUrl", attachmentUrl == null ? "" : attachmentUrl);
        monitorPartnerSupportFraud(message, messageId);

        if (realtimeDatabase != null) {
            realtimeDatabase.getReference("partner_support_messages").child(messageId).updateChildren(new HashMap<>(payload));
        }
        Map<String, Object> firestorePayload = new HashMap<>(payload);
        firestorePayload.put("createdAt", FieldValue.serverTimestamp());
        firestore.collection("partner_support_messages")
                .document(messageId)
                .set(firestorePayload, SetOptions.merge())
                .addOnSuccessListener(ref -> {
                    removeQueuedPartnerSupportMessage(messageId);
                    updateSupportMessageStatus(messageId, "Sent");
                    refreshHandler.postDelayed(() -> updateSupportMessageStatus(messageId, "Delivered"), 500);
                    writePartnerSupportRequest(type, message, messageId, attachmentUrl);
                })
                .addOnFailureListener(error -> {
                    queuePartnerSupportMessage(type, message, messageId, hasAttachment ? attachmentPath : "");
                    updateSupportMessageStatus(messageId, "Failed - tap retry");
                });
    }

    private void monitorPartnerSupportFraud(String message, String messageId) {
        if (backendClient == null || TextUtils.isEmpty(message)) {
            return;
        }
        String bookingId = currentBookingIdForFraudMonitor();
        if (!TextUtils.isEmpty(bookingId)) {
            backendClient.monitorBookingChat(bookingId, message, messageId);
        }
    }

    private String currentBookingIdForFraudMonitor() {
        if (activeMapBooking != null && !TextUtils.isEmpty(activeMapBooking.id)) {
            return activeMapBooking.id;
        }
        if (activeDetailBooking != null && !TextUtils.isEmpty(activeDetailBooking.id)) {
            return activeDetailBooking.id;
        }
        if (bookings != null && !bookings.isEmpty() && !TextUtils.isEmpty(bookings.get(0).id)) {
            return bookings.get(0).id;
        }
        return "";
    }

    private void writePartnerSupportRequest(String type, String message, String messageId, String attachmentUrl) {
        Map<String, Object> request = new HashMap<>();
        String category = supportCategoryForType(type);
        request.put("partnerId", partnerId());
        request.put("ownerUid", supportOwnerUid());
        request.put("partnerName", partnerName());
        request.put("type", TextUtils.isEmpty(type) ? "Chat" : type);
        request.put("category", category);
        request.put("message", message);
        request.put("lastMessageId", messageId);
        request.put("deliveryStatus", "sent");
        request.put("status", "open");
        request.put("attachmentUrl", attachmentUrl == null ? "" : attachmentUrl);
        request.put("createdAtMillis", System.currentTimeMillis());
        if (realtimeDatabase != null) {
            realtimeDatabase.getReference("partner_support_requests").child(messageId).updateChildren(new HashMap<>(request));
        }
        request.put("createdAt", FieldValue.serverTimestamp());
        firestore.collection("partner_support_requests")
                .document(messageId)
                .set(request, SetOptions.merge())
                .addOnFailureListener(error -> {});
        if (backendClient != null) {
            backendClient.createPartnerSupportTicket(category, message, messageId, attachmentUrl, new BackendClient.JsonCallback() {
                @Override public void onSuccess(JSONObject object) { }
                @Override public void onError(String message) { }
            });
        }
    }

    private String supportCategoryForType(String type) {
        String value = String.valueOf(type == null ? "" : type).toLowerCase(Locale.US);
        if (value.contains("verification") || value.contains("kyc") || value.contains("login") || value.contains("registration")) {
            return "Partner Verification Support";
        }
        if (value.contains("complaint")) {
            return "Partner Complaint";
        }
        return TextUtils.isEmpty(type) ? "Partner Support" : type;
    }

    private void queuePartnerSupportMessage(String type, String message, String messageId, String attachmentPath) {
        try {
            JSONArray queue = pendingPartnerSupportQueue();
            JSONArray updated = new JSONArray();
            boolean replaced = false;
            for (int index = 0; index < queue.length(); index++) {
                JSONObject item = queue.optJSONObject(index);
                if (item == null) {
                    continue;
                }
                if (messageId.equals(item.optString("id"))) {
                    updated.put(partnerSupportQueueItem(type, message, messageId, attachmentPath, item.optInt("attempts", 0) + 1));
                    replaced = true;
                } else {
                    updated.put(item);
                }
            }
            if (!replaced) {
                updated.put(partnerSupportQueueItem(type, message, messageId, attachmentPath, 0));
            }
            prefs.edit().putString(KEY_PENDING_SUPPORT_QUEUE, trimQueue(updated).toString()).apply();
        } catch (Exception ignored) {
        }
    }

    private JSONObject partnerSupportQueueItem(String type, String message, String messageId, String attachmentPath, int attempts) {
        JSONObject item = new JSONObject();
        try {
            item.put("id", messageId);
            item.put("type", TextUtils.isEmpty(type) ? "Chat" : type);
            item.put("message", message == null ? "" : message);
            item.put("attachmentPath", attachmentPath == null ? "" : attachmentPath);
            item.put("attempts", attempts);
            item.put("createdAtMillis", System.currentTimeMillis());
        } catch (Exception ignored) {
        }
        return item;
    }

    private String supportOwnerUid() {
        return firebaseAuth != null && firebaseAuth.getCurrentUser() != null
                ? firebaseAuth.getCurrentUser().getUid()
                : "";
    }

    private JSONArray pendingPartnerSupportQueue() {
        if (prefs == null) {
            return new JSONArray();
        }
        try {
            return new JSONArray(prefs.getString(KEY_PENDING_SUPPORT_QUEUE, "[]"));
        } catch (Exception ignored) {
            return new JSONArray();
        }
    }

    private void removeQueuedPartnerSupportMessage(String messageId) {
        if (prefs == null) {
            return;
        }
        try {
            JSONArray queue = pendingPartnerSupportQueue();
            JSONArray updated = new JSONArray();
            for (int index = 0; index < queue.length(); index++) {
                JSONObject item = queue.optJSONObject(index);
                if (item != null && !messageId.equals(item.optString("id"))) {
                    updated.put(item);
                }
            }
            prefs.edit().putString(KEY_PENDING_SUPPORT_QUEUE, updated.toString()).apply();
        } catch (Exception ignored) {
        }
    }

    private void retryQueuedPartnerSupportMessage(String messageId) {
        JSONArray queue = pendingPartnerSupportQueue();
        for (int index = 0; index < queue.length(); index++) {
            JSONObject item = queue.optJSONObject(index);
            if (item != null && messageId.equals(item.optString("id"))) {
                updateSupportMessageStatus(messageId, isNetworkOnline() ? "Retrying" : "Queued");
                dispatchPartnerSupportMessage(
                        item.optString("type", "Chat"),
                        item.optString("message", ""),
                        messageId,
                        item.optString("attachmentPath", ""),
                        true
                );
                return;
            }
        }
    }

    private void flushQueuedPartnerSupportMessages() {
        if (supportQueueSyncing || !isNetworkOnline()) {
            return;
        }
        JSONArray queue = pendingPartnerSupportQueue();
        if (queue.length() == 0) {
            return;
        }
        supportQueueSyncing = true;
        for (int index = 0; index < queue.length(); index++) {
            JSONObject item = queue.optJSONObject(index);
            if (item == null) {
                continue;
            }
            String id = item.optString("id");
            updateSupportMessageStatus(id, "Retrying");
            dispatchPartnerSupportMessage(
                    item.optString("type", "Chat"),
                    item.optString("message", ""),
                    id,
                    item.optString("attachmentPath", ""),
                    true
            );
        }
        refreshHandler.postDelayed(() -> supportQueueSyncing = false, 2200L);
    }

