    private void sendSupportRequest(String type, String message) {
        if (TextUtils.isEmpty(message)) {
            Toast.makeText(this, "Please write your issue first", Toast.LENGTH_SHORT).show();
            return;
        }
        if (message.length() > MAX_CHAT_MESSAGE_LENGTH) {
            Toast.makeText(this, "Message too long. Keep it under 1000 characters.", Toast.LENGTH_LONG).show();
            return;
        }
        String messageId = supportMessageId("PARMSG");
        dispatchPartnerSupportMessage(type, message, messageId, "", false);
        Toast.makeText(this, isNetworkOnline() ? "Support request sending" : "Support request queued", Toast.LENGTH_SHORT).show();
    }

    private void writeSupportRequest(String type, String message) {
        Map<String, Object> request = new HashMap<>();
        request.put("partnerId", partnerId());
        request.put("partnerName", partnerName());
        request.put("type", type);
        request.put("message", message);
        request.put("status", "open");
        request.put("createdAtMillis", System.currentTimeMillis());
        if (realtimeDatabase != null) {
            realtimeDatabase.getReference("partner_support_requests").push().updateChildren(new HashMap<>(request));
        }
        request.put("createdAt", FieldValue.serverTimestamp());
        firestore.collection("partner_support_requests")
                .add(request)
                .addOnSuccessListener(ref -> Toast.makeText(this, "Support request submitted", Toast.LENGTH_SHORT).show())
                .addOnFailureListener(error -> Toast.makeText(this, "Support request saved locally/realtime", Toast.LENGTH_SHORT).show());
    }

