    private boolean documentUploaded(String title) {
        return !TextUtils.isEmpty(prefs.getString(documentPrefKey(title), ""));
    }

    private String documentStatusLabel(String title, String fallback) {
        String status = prefs.getString(documentPrefKey(title) + "_status", "");
        if (!TextUtils.isEmpty(status)) {
            return status;
        }
        return documentUploaded(title) ? "Uploaded" : fallback;
    }

    private boolean documentStatusVerified(String title, boolean fallback) {
        String status = prefs.getString(documentPrefKey(title) + "_status", "");
        if (!TextUtils.isEmpty(status)) {
            return "Uploaded".equalsIgnoreCase(status);
        }
        return documentUploaded(title) || fallback;
    }

    private void showDocumentUploadOptions(String title) {
        Dialog dialog = new Dialog(this);
        dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);
        LinearLayout sheet = vertical();
        sheet.setPadding(dp(18), dp(18), dp(18), dp(14));
        sheet.setBackground(stroke(Color.WHITE, Color.rgb(250, 216, 225), dp(24)));

        sheet.addView(text(title, 18, BLACK, true), margin(-1, -2, 0, 0, 0, 6));
        sheet.addView(text("Upload a clear JPG, PNG, or PDF document.", 12, MUTED, false), margin(-1, -2, 0, 0, 0, 14));
        sheet.addView(documentUploadChoice(android.R.drawable.ic_menu_camera, "Open camera", "Take a clear document photo", () -> {
            dialog.dismiss();
            openDocumentCamera(title);
        }));
        sheet.addView(documentUploadChoice(android.R.drawable.ic_menu_upload, "Choose from files", "Select an existing image or PDF", () -> {
            dialog.dismiss();
            pickDocumentFile(title);
        }));
        TextView cancel = outlineButton("Cancel");
        cancel.setOnClickListener(view -> dialog.dismiss());
        sheet.addView(cancel, margin(-1, 48, 0, 14, 0, 0));

        dialog.setContentView(sheet);
        dialog.setOnShowListener(d -> {
            Window window = dialog.getWindow();
            if (window != null) {
                window.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));
                window.setGravity(Gravity.BOTTOM);
                WindowManager.LayoutParams params = new WindowManager.LayoutParams();
                params.copyFrom(window.getAttributes());
                params.width = WindowManager.LayoutParams.MATCH_PARENT;
                params.height = WindowManager.LayoutParams.WRAP_CONTENT;
                params.dimAmount = 0.22f;
                window.setAttributes(params);
                window.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);
            }
        });
        showDialogSafely(dialog);
    }

