    private void showChoiceSheet(String title, String subtitle, String[] labels, int selectedIndex, ChoiceHandler handler) {
        AlertDialog dialog = new AlertDialog.Builder(this).create();
        LinearLayout sheet = vertical();
        sheet.setPadding(dp(18), dp(18), dp(18), dp(12));
        sheet.setBackground(stroke(Color.WHITE, Color.rgb(250, 216, 225), dp(24)));
        sheet.addView(text(title, 19, BLACK, true));
        if (!TextUtils.isEmpty(subtitle)) {
            sheet.addView(text(subtitle, 12, MUTED, false), margin(-1, -2, 0, 4, 0, 14));
        }
        for (int i = 0; i < labels.length; i++) {
            boolean selected = i == selectedIndex;
            TextView option = text(labels[i], 14, selected ? Color.WHITE : BLACK, true);
            option.setGravity(Gravity.CENTER_VERTICAL);
            option.setPadding(dp(14), 0, dp(14), 0);
            option.setBackground(selected ? gradient(ROSE, Color.rgb(218, 75, 88), dp(15)) : stroke(Color.WHITE, Color.rgb(248, 230, 232), dp(15)));
            int choice = i;
            option.setOnClickListener(view -> {
                dialog.dismiss();
                handler.onChoice(choice);
            });
            addPressAnimation(option);
            sheet.addView(option, margin(-1, 48, 0, 0, 0, 9));
        }
        TextView cancel = outlineButton("Cancel");
        cancel.setOnClickListener(view -> dialog.dismiss());
        sheet.addView(cancel, margin(-1, 48, 0, 8, 0, 0));
        dialog.setView(sheet);
        showDialogSafely(dialog);
        Window window = dialog.getWindow();
        if (window != null) {
            window.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));
        }
    }

